        public static void SetText(object t,string s){if(t==null)return;
            /* L10n chokepoint: translate BEFORE the glyph registration and the
             * bold wrap — the catalogue keys are the raw English source, and
             * the fallback atlas must learn the TRANSLATED glyphs. Unknown
             * strings pass through untouched (I18n.Tr is identity for en). */
            s=I18n.Tr(s);
            /* Make sure any non-ASCII glyph in this string exists in the runtime fallback atlas before TMP lays it out, else it renders as a box (Sid: "several players have boxes for their names"). No-ops for pure-ASCII text. */try{UnicodeFallback.EnsureCharacters(s);}catch{}pTmpText?.SetValue(t,_BoldWrap(s??""));}
        /* Codex v1.36 client find 15: USER-AUTHORED values (display names,
         * item names) must never pass through I18n.Tr — a player literally
         * named "Done." would render as "Hecho." in Spanish. Same glyph
         * registration and bold wrap as SetText, no catalogue lookup. Any
         * site whose whole payload is a raw user string uses this. */
        public static void SetTextRaw(object t,string s){if(t==null)return;
            try{UnicodeFallback.EnsureCharacters(s);}catch{}pTmpText?.SetValue(t,_BoldWrap(s??""));}
        public static void SetColor(object t,Color c){if(t!=null)pTmpColor?.SetValue(t,c);}
        public static void SetBold(object t,bool b){if(t==null)return;try{var tp=pTmpFontStyle?.PropertyType;if(tp!=null)pTmpFontStyle.SetValue(t,Enum.ToObject(tp,b?1:0));}catch{}}
        public static void SetWordWrap(object t,bool on){if(t==null||tTMP==null)return;try{var p=tTMP.GetProperty("enableWordWrapping",BindingFlags.Public|BindingFlags.Instance);p?.SetValue(t,on);}catch{}}
        // Release a text element's fixed preferred height so its OWN TMP-reported
        // (content-driven) height feeds the layout instead. CreateText always adds a
        // LayoutElement with prefH = sizeDelta.y (priority 1), which OVERRIDES TMP's
        // ILayoutElement (priority 0) — so any growing text inside a ScrollView+CSF
        // stays locked at sizeDelta.y and never scrolls. Setting the LE's preferred
        // dims to -1 makes the layout fall through to TMP's computed values; minH is
        // an optional floor. This is the missing piece behind "the panel won't scroll".
        public static void SetTextAutoHeight(object tmp,float minH=0f){if(tmp==null||tLE==null)return;try{var go=((Component)tmp).gameObject;var le=go.GetComponent(tLE);if(le==null)le=go.AddComponent(tLE);tLE.GetProperty("preferredHeight",BindingFlags.Public|BindingFlags.Instance)?.SetValue(le,-1f);tLE.GetProperty("preferredWidth",BindingFlags.Public|BindingFlags.Instance)?.SetValue(le,-1f);if(minH>0f)tLE.GetProperty("minHeight",BindingFlags.Public|BindingFlags.Instance)?.SetValue(le,minH);}catch{}}
        public static void SetOverflowMode(object t,int mode){if(t==null||pTmpOverflow==null)return;try{pTmpOverflow.SetValue(t,Enum.ToObject(pTmpOverflow.PropertyType,mode));}catch{}}
        /* Aug-3 item 7c (#297 family). A ONE-LINE cell whose box is under ~1.4x its
         * font size fits a pure-Gravity line but NOT a line whose glyphs come from
         * the runtime OS fallback atlas (Cyrillic/Greek — #110): the fallback face
         * has taller ascender+descender metrics at the same point size, so the
         * global Truncate default drops the WHOLE line and the cell renders blank
         * while its English sibling shows. Overflow + no-wrap guarantees exactly
         * one painted line; the couple of px of vertical bleed stay inside the
         * row's own padding. Only for single-line cells — never for a wrapped body.
         *
         * CALLER OBLIGATION (Aug-3 review find F5). Overflow removes the HORIZONTAL
         * bound too: nothing clips the tail any more, so a cell with a sibling to
         * its right in the same layout row will paint straight over it once the
         * content outgrows the cell. Before calling this, either (a) confirm the
         * element's right-hand space is empty — a flexW:1 spacer, its own row in a
         * VLG, a scroll viewport whose RectMask2D edge is the next thing over, or a
         * free-floating chart label — or (b) bound the rendered STRING to the cell
         * (Trunc / FitTwoParts). Do NOT reach for a per-cell RectMask2D on pooled
         * row cells: that is the per-frame cost #162 says to keep out of this menu.
         * Audited at introduction: bounded via string caps = the history opponent +
         * series-head cells and the shop name cell; verified safe as-is = every
         * header/status line that owns its row or is followed by a flex spacer, the
         * chart/graph labels (they float over the plot by design), the single-glyph
         * tier button, and the mode-leaderboard rows (their overflow is eaten by
         * their own ScrollView mask before it reaches the next column). */
        /// <summary>Shorten <paramref name="text"/> until TMP measures it at or
        /// under <paramref name="maxPx"/>, appending ".." when it had to cut.
        ///
        /// Codex Aug-4 r2 find 3: a CHARACTER budget is not a pixel budget.
        /// `FitOneLine` gives a cell unbounded overflow so a translated line can
        /// never be dropped whole (#297), but that also means anything too WIDE
        /// paints straight over its neighbour — an 18-character name of wide
        /// glyphs ("WWWWWWWWWWWWWWWWWW") fits the character cap and still
        /// overruns a 240px cell into the FPS column.
        ///
        /// Measured with TMP's GetPreferredValues, which sizes a candidate
        /// string WITHOUT assigning it, so this costs no layout passes. Binary
        /// search rather than a per-character walk keeps it ~6 measurements for
        /// any realistic name. Runs at row-fill rate (a handful of rows per
        /// refresh), never per frame (#162).
        ///
        /// Falls back to returning the text unchanged if the measurement API is
        /// unavailable — the old behaviour, not a blank cell.</summary>
        public static string FitToWidth(object tmp, string text, float maxPx)
        {
            if (tmp == null || string.IsNullOrEmpty(text) || maxPx <= 0f) return text;
            try
            {
                if (mTmpPreferredValues == null)
                    mTmpPreferredValues = tTMP.GetMethod("GetPreferredValues",
                        BindingFlags.Public | BindingFlags.Instance,
                        null, new Type[] { typeof(string) }, null);
                if (mTmpPreferredValues == null) return text;
                Func<string, float> width = candidate =>
                {
                    var v = mTmpPreferredValues.Invoke(tmp, new object[] { candidate });
                    return v is Vector2 ? ((Vector2)v).x : 0f;
                };
                if (width(text) <= maxPx) return text;
                // Longest prefix that fits with the marker appended.
                int lo = 0, hi = text.Length;
                while (lo < hi)
                {
                    int mid = (lo + hi + 1) / 2;
                    if (width(text.Substring(0, mid) + "..") <= maxPx) lo = mid; else hi = mid - 1;
                }
                return lo <= 0 ? ".." : text.Substring(0, lo).TrimEnd() + "..";
            }
            catch { return text; }
        }

        /// <summary>TMP's own preferred WIDTH for <paramref name="text"/>, measured
        /// without assigning it (the same GetPreferredValues(string) call FitToWidth
        /// uses, so it costs no layout pass and is parsed with this component's real
        /// font/size/richText settings).
        ///
        /// Returns 0 when the measurement API is unavailable. Callers must treat 0 as
        /// "unknown" and fall back to a conservative estimate — never as "empty", or a
        /// missing reflection target silently becomes a zero-width control.</summary>
        public static float MeasureTextWidth(object tmp,string text)
        {
            if(tmp==null||string.IsNullOrEmpty(text))return 0f;
            try
            {
                if(mTmpPreferredValues==null)
                    mTmpPreferredValues=tTMP.GetMethod("GetPreferredValues",
                        BindingFlags.Public|BindingFlags.Instance,
                        null,new Type[]{typeof(string)},null);
                if(mTmpPreferredValues==null)return 0f;
                var v=mTmpPreferredValues.Invoke(tmp,new object[]{text});
                return v is Vector2?((Vector2)v).x:0f;
            }
            catch{return 0f;}
        }

        public static void FitOneLine(object t){SetOverflowMode(t,0);SetWordWrap(t,false);}
        public static void SetCharSpacing(object t,float spacing){if(t!=null)pTmpCharSpacing?.SetValue(t,spacing);}
        public static void SetImageColor(GameObject go,Color c){if(go==null)return;var img=go.GetComponent(tImage);if(img!=null)pImgColor?.SetValue(img,c);}
        public static object GetButtonText(GameObject btn){if(btn==null)return null;foreach(Transform ch in btn.transform)foreach(var co in ch.GetComponents<Component>())if(co.GetType().Name=="TextMeshProUGUI")return co;return null;}
        public const int AlignTopLeft=257,AlignTopCenter=258,AlignTopRight=260,AlignMidLeft=513,AlignMidCenter=514,AlignMidRight=516;
    }

    // ClickHandler - camera-aware click detection for ROUNDS' ScreenSpaceCamera Canvas
    public class ClickHandler : MonoBehaviour
    {
        public System.Action onClick;
        private RectTransform rt;
        private Camera canvasCamera;
        private bool cameraResolved;
        private void Awake(){rt=GetComponent<RectTransform>();}
        private void ResolveCamera()
        {
            cameraResolved=true;canvasCamera=null;Transform t=transform;
            while(t!=null){var cc=t.GetComponent(UIFactory.tCanvas);if(cc!=null){try{var bf=BindingFlags.Public|BindingFlags.Instance;int rm=(int)UIFactory.tCanvas.GetProperty("renderMode",bf).GetValue(cc);if(rm!=0){canvasCamera=UIFactory.tCanvas.GetProperty("worldCamera",bf)?.GetValue(cc) as Camera;if(canvasCamera==null)canvasCamera=Camera.main;}}catch{}break;}t=t.parent;}
        }
        // When true, ClickHandlers ignore clicks — an IMGUI modal owns the screen.
        // Bug #75: the uGUI click-blocker only stops EventSystem raycasts, but
        // ClickHandler polls Input.GetMouseButtonDown directly and does its own
        // hit test, bypassing the blocker entirely — so shop/artist buttons behind
        // the artist price/stock modal still fired ("clickable through the menu").
        // CompetitiveUI sets this whenever any IMGUI modal is open, the same
        // condition that drives the uGUI blocker.
        public static bool ModalBlockInput;
        // Set on handlers that belong to the CURRENT modal itself (e.g. the
        // info-popup's click-anywhere-to-close backdrop) so they keep working
        // while ModalBlockInput suppresses every handler BEHIND the modal.
        public bool bypassModalBlock;
        private bool ContainsScreenPoint(RectTransform target, Vector3 point)
        {
            if (target == null) return false;
            Vector3[] corners = new Vector3[4];
            target.GetWorldCorners(corners);
            float minX = float.PositiveInfinity, minY = float.PositiveInfinity;
            float maxX = float.NegativeInfinity, maxY = float.NegativeInfinity;
            for (int i = 0; i < corners.Length; i++)
            {
                Vector3 c = canvasCamera != null
                    ? canvasCamera.WorldToScreenPoint(corners[i])
                    : corners[i];
                minX = Mathf.Min(minX, c.x);
                minY = Mathf.Min(minY, c.y);
                maxX = Mathf.Max(maxX, c.x);
                maxY = Mathf.Max(maxY, c.y);
            }
            return point.x >= minX && point.x <= maxX
                && point.y >= minY && point.y <= maxY;
        }
        private bool IsInsideAncestorMasks(Vector3 point)
        {
            // Unity's EventSystem respects a ScrollView Mask when raycasting,
            // but this component polls Input directly. Enforce every ancestor
            // mask here too so clipped rows cannot be clicked through panels
            // that visually cover them.
            // Both clip types matter: scroll viewports now use RectMask2D (the
            // stencil Mask was the drag-scroll cost), and some panels still use
            // Mask. Missing either would let a clipped row be clicked through
            // the panel covering it (learning #185).
            if (UIFactory.tMask == null && UIFactory.tRectMask2D == null) return true;
            Transform cursor = transform.parent;
            while (cursor != null)
            {
                try
                {
                    bool clips = (UIFactory.tMask != null && cursor.GetComponent(UIFactory.tMask) != null)
                              || (UIFactory.tRectMask2D != null && cursor.GetComponent(UIFactory.tRectMask2D) != null);
                    if (clips && !ContainsScreenPoint(cursor as RectTransform, point))
                        return false;
                }
                catch { }
                cursor = cursor.parent;
            }
            return true;
        }
        private void Update()
        {
            if(rt==null||onClick==null||!gameObject.activeInHierarchy)return;
            if(ModalBlockInput&&!bypassModalBlock)return;
            if(!Input.GetMouseButtonDown(0))return;
            if(!cameraResolved)ResolveCamera();
            Vector3 mp=Input.mousePosition;
            if(ContainsScreenPoint(rt,mp)&&IsInsideAncestorMasks(mp))onClick.Invoke();
        }
    }

