        public static void MaybeRefreshLiveSeries()
        {
            if (currentTab != 1) return;
            // Pulse tick (every ~2.5s): flip the header dot so it blinks visibly.
            // Decoupled from the server fetch so it doesn't have to wait 10s between blinks.
            if (Time.unscaledTime >= liveHeaderNextPulseAt)
            {
                liveHeaderNextPulseAt = Time.unscaledTime + LIVE_HEADER_PULSE_INTERVAL;
                liveHeaderPulseFilled = !liveHeaderPulseFilled;
                dirty = true;
            }
            // Fetch tick (every 5s): do the actual network poll for live series + bets.
            // Halved from 10s because the bet window between series-create and first-2-points
            // is tight (~30-60s) and spectators were missing half their chance to bet before
            // the series locked. 5s is still cheap on the server (single indexed query).
            if (Time.unscaledTime < liveSeriesAutoRefreshAt) return;
            liveSeriesAutoRefreshAt = Time.unscaledTime + 5f;
            ApiClient.FetchActiveSeries();
            ApiClient.FetchActiveTeamSeries();
            // Spectatable-games list (10s self-throttle inside) — feeds the
            // WATCH buttons on the live-series headers.
            ApiClient.MaybeFetchSpectateGames();
            var sid = MatchTracker.LocalSteamId;
            // FFA betting moved into this column (item 4), so it rides the same
            // 5s tick rather than needing a ticker of its own (#62).
            ApiClient.FetchFfaBettable(sid);
            if (!string.IsNullOrEmpty(sid) && sid != "unknown") ApiClient.FetchMyBets(sid);
        }
        /* Aug-3 item 13. SentUtc is the SERVER's created_at (or, for a local echo,
         * the moment we sent) parsed out of the wire "timestamp" field; AddedUtc is
         * local RECEIPT time and stays separate on purpose — CompetitiveUI's in-game
         * overlay ages lines by AddedUtc for its 25s/35s fade, and sorting that by
         * server time would make backfilled scrollback flash as "new" mid-match.
         * SentUtc exists so the merged (all-channels) pane can be time-ORDERED
         * across channels instead of ordered by arrival. */
        /* Seq gives a rendered row a STABLE IDENTITY. r4 find 5: matching an
          * echo by its rendered TEXT is wrong — two different messages can
          * render identical text (same sender, two over-limit messages sharing
          * a retained prefix), so the wrong line could satisfy the "is my echo
          * still on screen" test and the real canonical row would be dropped
          * for good. A monotonic id cannot be confused that way. */
        /* ChatId (Aug 6 item 5): the SERVER row id, so a moderator
         * retraction frame can locate and drop an already-rendered
         * line. 0 = local echo / system line / pre-id row, which a
         * retraction can never target. */
        // Source is client-internal (never on the wire out): it lets the
        // mute-from-message picker say WHICH platform a row came from, since
        // the rendered Line has already baked the tag into rich text.
        public struct ChatEntry { public string Line; public DateTime AddedUtc; public DateTime SentUtc; public string Channel; public long Seq; public int ChatId; public string Source; }
        private static long chatSeqNext = 1;
        /* Newest server-issued timestamp observed this session, kept even after
         * the row itself is evicted or filtered away. It is the anchor a
         * locally-generated line uses when the pane is empty (r7 find 1).
         *
         * RESIDUAL, accepted: a session that has never received ANY server row
         * — scrollback empty or its fetch failing — has genuinely nothing to
         * anchor to, so a local line falls back to this machine's clock and a
         * later row that truly preceded it can sort above it. Closing that
         * needs a trustworthy clock, and four rounds of clock-based attempts
         * each produced worse defects than the one they fixed. */
        private static DateTime lastServerStampSeen = DateTime.MinValue;
        private static List<ChatEntry> chatLines = new List<ChatEntry>();
        private static readonly object chatLinesLock = new object();
        private const int CHAT_LOG_MAX = 60;

        /// <summary>Thread-safe snapshot of the most recent chat lines for the in-game overlay.</summary>
        public static ChatEntry[] SnapshotChat(int tail)
        {
            lock (chatLinesLock)
            {
                int start = Math.Max(0, chatLines.Count - tail);
                var arr = new ChatEntry[chatLines.Count - start];
                for (int i = 0; i < arr.Length; i++) arr[i] = chatLines[start + i];
                return arr;
            }
        }

        /// <summary>Copy recent chat into caller-owned storage without allocating
        /// an array every OnGUI repaint.</summary>
        public static void CopyChatTail(List<ChatEntry> destination, int tail)
        {
            if (destination == null) return;
            lock (chatLinesLock)
            {
                destination.Clear();
                int start = Math.Max(0, chatLines.Count - tail);
                for (int i = start; i < chatLines.Count; i++) destination.Add(chatLines[i]);
            }
        }
