        public static void Open()
        {
            if(!UIFactory.Ready){UIFactory.InitTypes();UIFactory.InitFont();}if(!UIFactory.Ready)return;
            /* Bug #46: use IsInOnlineRoom, not IsInRoom — Photon's OfflineMode (Sandbox)
             * counts as "in a room" and lingers at the main menu after leaving Sandbox,
             * which kept inGameMode=true and hid the ranked Disable button until relaunch. */
            bool inRoom=GameStateWatcher.IsInOnlineRoom;
            inGameMode=inRoom;
            // Always use our own overlay canvas - guarantees we render on top of all ROUNDS UI
            EnsureOverlayCanvas();
            bool builtThisOpen=false;
            if(!pageBuilt||pageGO==null||pageGO.transform.parent!=overlayCanvasGO.transform){if(pageGO!=null)UnityEngine.Object.Destroy(pageGO);pageBuilt=false;BuildPage(overlayCanvasGO.transform);if(!pageBuilt)return;builtThisOpen=true;}
            pageGO.SetActive(true);
            // ForceUpdateCanvases is a synchronous whole-canvas layout rebuild — one of the
            // F5-open hitches (v1.29). Only needed right after a fresh BuildPage; a plain
            // SetActive(true) re-open lays out through Unity's normal end-of-frame pass.
            if(builtThisOpen)
                try{UIFactory.tCanvas?.GetMethod("ForceUpdateCanvases",BindingFlags.Public|BindingFlags.Static)?.Invoke(null,null);}catch{}
            isOpen=true;dirty=true;RefreshData();ApiClient.ResetQueueCountTimer();Plugin.Log.LogInfo($"[NATIVE] Opened competitive page (inGame={inGameMode})");
            // L10n D2 ask-once: fires only while ModLanguage is the unset
            // sentinel; any choice writes the config and it never asks again.
            try { MaybeShowLanguagePrompt(); } catch { }
        }

        /// <summary>EVERY overlay surface that outlives pageGO (they parent
        /// to the PERSISTENT overlay canvas), plus the modal statics, plus
        /// the blocker/fade. ONE list, shared by Close() and Tick()'s
        /// page-null recovery (Codex tournament r7 find 2 — the recovery
        /// re-listed a subset by hand and drifted: card preview and cursor
        /// trail survived a host destruction). Add every future persistent-
        /// canvas surface HERE, never to one caller. Gold-bearing surfaces
        /// first (r5 finds 1+2: the bets popup's controls carry
        /// bypassModalBlock and the IMGUI amount prompt renders independent
        /// of IsOpen — either surviving a close can stake real gold over
        /// live combat).</summary>
        private static void TeardownOverlaySurfaces(){try{HideTournamentBetsPopup();}catch{}try{HideRecentTournamentsPopup();}catch{}try{CancelCustomBet();}catch{}try{TrailPreview.Stop();}catch{}try{PlayerEffectCosmetic.StopPreview();}catch{}try{HideInfoPopup();}catch{}try{HideCardPreview();}catch{}/* Aug 6 review find 3: an Escape with the picker dropdown open left a full-screen raycast-blocking dim over live gameplay and PickerOpen stuck true forever. */try{HidePicker();}catch{}SetClickBlocker(false);SetMenuFade(false);/* fade must never survive a close (Sid2 in-game bleed hunt) */}

        public static void Close(){if(pageGO!=null)pageGO.SetActive(false);isOpen=false;TeardownOverlaySurfaces();Plugin.Log.LogInfo("[NATIVE] Closed competitive page");}

        /// <summary>Sid2's screenshot shows the page title/footer over live
        /// gameplay on his 16:10 monitor while 16:9 machines never see it.
        /// The mechanism is still unproven, so log the full layer state at
        /// every match start until his next report pins it (page active?
        /// fade alpha? canvas size vs window?).</summary>
        public static void LogOverlayState(string context)
        {
            try
            {
                bool pageActive = pageGO != null && pageGO.activeInHierarchy;
                float alpha = -1f;
                try
                {
                    var aProp = menuFadeCG?.GetType().GetProperty("alpha", BindingFlags.Public | BindingFlags.Instance);
                    if (aProp != null) alpha = (float)aProp.GetValue(menuFadeCG);
                }
                catch { }
                Vector2 canvasSize = Vector2.zero;
                try
                {
                    var crt = overlayCanvasGO?.GetComponent<RectTransform>();
                    if (crt != null) canvasSize = crt.rect.size;
                }
                catch { }
                Plugin.Log.LogInfo($"[OVERLAY-DIAG] {context}: window={Screen.width}x{Screen.height} " +
                                   $"canvas={canvasSize.x:0}x{canvasSize.y:0} pageActive={pageActive} " +
                                   $"isOpen={isOpen} fadeAlpha={alpha:0.00} fullscreen={Screen.fullScreen}");
            }
            catch { }
        }

        // Bug batch item 6: while a player-effect preview runs, the aura is a WORLD
        // particle system, and a ScreenSpaceOverlay canvas composites above ALL
        // world renderers regardless of sortingOrder — the old "sortingOrder
        // 30500" attempt could never draw it in front. Instead fade the page to
        // near-transparent while previewing: the aura (following the cursor) is
        // fully visible and the buttons stay clickable through the CanvasGroup.
        private static object menuFadeCG;
        public static void SetMenuFade(bool on)
        {
            try
            {
                if (pageGO == null) return;
                if (menuFadeCG == null)
                {
                    var tCG = UIFactory.tCanvasGroup;
                    if (tCG == null) return;
                    menuFadeCG = pageGO.GetComponent(tCG) ?? pageGO.AddComponent(tCG);
                }
                var aProp = menuFadeCG.GetType().GetProperty("alpha", BindingFlags.Public | BindingFlags.Instance);
                aProp?.SetValue(menuFadeCG, on ? 0.16f : 1f);
            }
            catch { }
        }

        // Full-screen uGUI raycast blocker for IMGUI modals (bug report form, log/admin
        // viewers). The IMGUI backdrop those draw blocks NOTHING in uGUI — they're separate
        // input paths — so clicks on the form also hit the F5 buttons behind it (lopi #14).
        // A transparent raycastTarget Image as the TOP child of the overlay canvas intercepts
        // every uGUI raycast while a modal is up; the IMGUI form still works (separate path).
        private static GameObject clickBlocker;
        public static void SetClickBlocker(bool on)
        {
            try
            {
                if (clickBlocker == null)
                {
                    if (overlayCanvasGO == null) return;
                    clickBlocker = new GameObject("CR_ClickBlocker");
                    clickBlocker.transform.SetParent(overlayCanvasGO.transform, false);
                    var rt = clickBlocker.AddComponent<RectTransform>();
                    rt.anchorMin = Vector2.zero; rt.anchorMax = Vector2.one; rt.offsetMin = Vector2.zero; rt.offsetMax = Vector2.zero;
                    var img = clickBlocker.AddComponent(UIFactory.tImage);
                    UIFactory.tImage.GetProperty("color", BindingFlags.Public | BindingFlags.Instance)?.SetValue(img, new Color(0, 0, 0, 0.001f));
                    UIFactory.tImage.GetProperty("raycastTarget", BindingFlags.Public | BindingFlags.Instance)?.SetValue(img, true);
                    clickBlocker.SetActive(false);
                }
                if (on) clickBlocker.transform.SetAsLastSibling();
                if (clickBlocker.activeSelf != on) clickBlocker.SetActive(on);
            }
            catch { }
        }

        private static float dataCheckTimer;private static int lastMatchCount=-1,lastLBCount=-1,lastCardCount=-1;
        /* Codex Aug-4 r2 find 8: a server pack can correct text WITHOUT the
         * locale changing, and MarkDirty() only re-runs the per-tab data
         * refresh — every STATIC label built once in BuildPage keeps its old
         * wording until the page is rebuilt. I18n's repaint request sets this;
         * Tick consumes it at a safe moment.
         *
         * Deferred to Tick rather than rebuilt inside the event: the pack can
         * land from inside SetLocale, i.e. mid-build, and tearing the page down
         * underneath its own construction is how #9's page-navigation
         * corruption happened. Tick runs only when the page is open and fully
         * built, which is exactly when a rebuild is safe. */
        internal static void RequestCatalogueRebuild() { catalogueRebuildPending = true; }
        private static bool catalogueRebuildPending;

        /// <summary>Frame stamp of the Escape press that closed the F5 menu.
        /// Tick runs in Update, BEFORE any OnGUI consumer sees the same key
        /// event — the spectator leave-menu reads this so one Esc press never
        /// both closes the menu AND opens the leave dialog (Aug 10 review
        /// find 13; NativeUI.IsOpen is already false by OnGUI time).</summary>
        public static int EscConsumedFrame { get; private set; } = -1;

        public static void Tick()
        {
            if(!isOpen||!pageBuilt)return;
            if(pageGO==null)
            {
                // Page host destroyed under us (scene change / UI-host
                // respawn, e.g. the tournament-room watchdog's
                // NetworkRestart). Codex tournament r6 find 1: a bare flag
                // reset here bypassed Close()'s teardown, so the STATIC
                // CustomBetPromptOpen (and the bets popup, its own GO gone
                // but its flags live) survived host destruction — the IMGUI
                // amount prompt kept rendering and its next Enter could
                // submit the stale wager mid-game. r7 find 2: ONE shared
                // teardown, never a hand-copied subset.
                isOpen=false;pageBuilt=false;
                TeardownOverlaySurfaces();
                return;
            }
            if(Input.GetKeyDown(KeyCode.Escape)){EscConsumedFrame=Time.frameCount;Close();return;}
            // r8 find 1: a bet-row refresh deferred by the mid-click guard
            // lands here on the first fully-released frame.
            if(tournBetsFillPending&&!Input.GetMouseButton(0)&&!Input.GetMouseButtonUp(0)){try{RefreshTournamentBets();}catch{}}
            if(catalogueRebuildPending)
            {
                catalogueRebuildPending=false;
                // Same PUBLIC page path the language switch uses (§2.3):
                // Close -> destroy -> pageBuilt=false -> Open, never a bare
                // pageBuilt flip (Tick's early-return would strand Escape).
                int backTo=currentTab;
                Close();
                if(pageGO!=null)UnityEngine.Object.Destroy(pageGO);
                pageBuilt=false;
                Open();
                SwitchTab(backTo);
                return;
            }
            dataCheckTimer+=Time.deltaTime;if(dataCheckTimer>=0.3f){dataCheckTimer=0f;int mc=ApiClient.CachedMatchHistory?.Count??0,lc=ApiClient.CachedLeaderboard?.entries?.Length??0,cc=ApiClient.CachedCardStats?.Count??0;if(mc!=lastMatchCount||lc!=lastLBCount||cc!=lastCardCount){lastMatchCount=mc;lastLBCount=lc;lastCardCount=cc;dirty=true;}}
            // Bug 263: debounced server-side history search — 0.6s after the
            // last keystroke, fetch the name-filtered slice (the instant
            // client-side filter has been rendering meanwhile).
            if(histSearchChangedAt>=0f&&Time.realtimeSinceStartup-histSearchChangedAt>=0.6f)
            {
                histSearchChangedAt=-1f;
                string q=histSearch?.Trim()??"";
                if(q.Length>0){try{ApiClient.FetchMatchHistorySearch(MatchTracker.LocalSteamId,q,append:false);}catch{}}
            }
            // Info tab: cross-ref link clicks are a raw Input poll (edge
            // trigger, so it must live on this per-frame path — #120).
            if (currentTab == TAB_INFO) TickInfoLinkClicks();
            // Codex r1 f16: timed alerts expire LOCALLY — when the soonest
            // expiry passes, drop it and repaint so the banner clears within
            // seconds. Throttled; no server calls.
            if(Time.unscaledTime>=alertExpiryCheckAt)
            {
                alertExpiryCheckAt=Time.unscaledTime+2f;
                if(ApiClient.PruneExpiredAlerts())dirty=true;
            }
            if(dirty){dirty=false;RefreshCurrentTab();}
            MaybeRefreshTournament();
            MaybeRefreshTeamTab();
            MaybeRefreshLeaderboardTab();
            MaybeRefreshOvtTab();
            MaybeRefreshFfaTab();
            MaybeRefreshHomeTab();
            MaybeRefreshCompareRecords();
            TickAnimatedThumbnails();
            TickCardPreviewUpgrade();
        }

        /* Aug-3 item 6. The card preview binds its sprite once at construction
         * (see cardPreviewName) and the native capture lands ~0.92s later, so
         * without this the FIRST open of any card is always the PNG and only a
         * re-click gets the native render — "about 50/50" is literally whether
         * the next click lands before or after the capture.
         * REBUILD, not swap-in-place: ShowCardPreview picks between two totally
         * different layouts on `cardSprite != null` (380x600 image vs 440x360
         * text), so a card with no PNG has no Image component to swap into —
         * precisely the cards that need the native render most. One rebuild per
         * card per session is free; the popup holds no scroll or input state.
         * Probing the cache is the same read the seam itself does, so it cannot
         * disagree with it — unlike a completion callback, which would have to
         * replicate CaptureOne's six-outcome decision table. */
        private static void TickCardPreviewUpgrade()
        {
            if (cardPreviewGO == null || string.IsNullOrEmpty(cardPreviewName)) return;
            try
            {
                if (!CardSnapshot.TryGetSprite(cardPreviewName, out var snap) || snap == null) return;
                if (ReferenceEquals(snap, cardPreviewBoundSprite)) return;
                string nm = cardPreviewName;
                Plugin.Log.LogInfo($"[CARD-PREVIEW] native snapshot landed for '{nm}' — rebuilding popup");
                ShowCardPreview(nm);   // re-stamps cardPreviewName/BoundSprite
            }
            catch (Exception ex) { Plugin.Log.LogWarning($"[CARD-PREVIEW] upgrade tick: {ex.Message}"); }
        }

        // Bug #74: animated cosmetics were static in the shop. Registry of shop-row
        // Image components showing an animated sku; the sprite property is re-set at
        // the item's own fps from Tick. Entries are (re)assigned per ApplyShopRow
        // fill (rows are pooled) and cleared when the row shows a static item.
        private static readonly Dictionary<object, (Sprite[] frames, float fps)> _animThumbs =
            new Dictionary<object, (Sprite[], float)>();
        private static PropertyInfo _pImgSprite;
        // Last frame index actually assigned per Image — at 3.6-6 fps the frame
        // only changes every 10+ rendered frames, so skipping same-index sets
        // avoids ~94% of the per-frame reflection SetValue + Canvas dirtying
        // (the Home pool doubled to 12 rows in item 4, making this worth it).
        private static readonly Dictionary<object, int> _animThumbLastIdx = new Dictionary<object, int>();
        public static void TrackAnimatedThumb(object img, Sprite[] frames, float fps)
        {
            if (img == null) return;
            if (frames == null || frames.Length < 2 || fps <= 0f) { _animThumbs.Remove(img); _animThumbLastIdx.Remove(img); return; }
            _animThumbs[img] = (frames, fps);
            _animThumbLastIdx.Remove(img);  // force a fresh set on the next tick
        }
        private static void TickAnimatedThumbnails()
        {
            // Shop tab (4) AND Home tab (newest-cosmetics art, v1.33). Both use
            // distinct Image objects, so _animThumbs entries never collide.
            if (_animThumbs.Count == 0 || (currentTab != 4 && currentTab != TAB_HOME)) return;
            try
            {
                if (_pImgSprite == null && UIFactory.tImage != null)
                    _pImgSprite = UIFactory.tImage.GetProperty("sprite", BindingFlags.Public | BindingFlags.Instance);
                if (_pImgSprite == null) return;
                // v1.32 item 8: static-cosmetics mode pins shop thumbnails to frame 1.
                bool _static = Plugin.AnimatedCosmetics != null && !Plugin.AnimatedCosmetics.Value;
                foreach (var kv in _animThumbs)
                {
                    var (frames, fps) = kv.Value;
                    int idx = _static ? 0 : (int)(Time.unscaledTime * fps) % frames.Length;
                    int last;
                    if (_animThumbLastIdx.TryGetValue(kv.Key, out last) && last == idx) continue;
                    _pImgSprite.SetValue(kv.Key, frames[idx]);
                    _animThumbLastIdx[kv.Key] = idx;
                }
            }
            catch { }
        }

        // The Leaderboard tab was session-stale: SwitchTab used to fetch only when
        // the cache was NULL, and RefreshData only refetches it if the menu happens
        // to be OPENED on tab 1 — so ratings from series played mid-session never
        // showed up without a manual Refresh ("leaderboard tab hasn't been updating").
        // Same shape as MaybeRefreshTeamTab (learning #62): throttled ticker while
        // the tab is open. 30s — a 500-row board doesn't need the 2s queue cadence.
        private static float lbTabRefreshAt;
        private static void MaybeRefreshLeaderboardTab()
        {
            if (currentTab != 1) return;
            TickPodiumSparkle();
            if (Time.unscaledTime < lbTabRefreshAt) return;
            lbTabRefreshAt = Time.unscaledTime + 30f;
            ApiClient.FetchLeaderboard();
            ApiClient.FetchRecentSeries();
            ApiClient.FetchRecentMultimodeSeries();
        }

        // ── Podium title sparkle (v1.32 item 4) ────────────────────────────
        // The server resolves sku 'title_podium' to "1st Place"/"2nd Place"/
        // "3rd Place" (gold/silver/bronze). The client adds a per-character
        // glitter; on the 1v1 leaderboard the glitter ANIMATES by rewriting
        // only the (at most 3) podium rows' name text on a slow tick — never
        // a full-board repaint (F5 perf, learning #109). Detection is by exact
        // title text: the server never issues another title with these names.
        // Aug 12 item 2d: the 2v2 and FFA ladders now have their own podium
        // skus, and the server renders those with a mode prefix — main.py's
        // PODIUM_TITLES / PODIUM_TITLES_2V2 / PODIUM_TITLES_FFA tables, whose
        // strings are reproduced EXACTLY here (grepped from that source, not
        // guessed — a mismatched literal is a silent no-sparkle, #152).
        // Deliberately an exact-match set rather than an EndsWith("1st Place"):
        // a future purchasable title that happens to end in those words must
        // not inherit the podium glitter.
        internal static bool IsPodiumTitle(string t)
        {
            if (string.IsNullOrEmpty(t)) return false;
            return t == "1st Place"     || t == "2nd Place"     || t == "3rd Place"
                || t == "2v2 1st Place" || t == "2v2 2nd Place" || t == "2v2 3rd Place"
                || t == "FFA 1st Place" || t == "FFA 2nd Place" || t == "FFA 3rd Place";
        }
        /// <summary>Drop a podium title's ladder prefix when it is being drawn
        /// ON that ladder's own board. The server ships "2v2 1st Place" /
        /// "FFA 1st Place" so the title stays unambiguous on mixed surfaces
        /// (chat, Home, the 1v1 board), but on the 2v2 board itself the prefix
        /// says nothing and costs 4 characters in a 200px name cell that
        /// already truncates — i.e. it would eat the "]" and part of the place
        /// (#292). A title from a DIFFERENT ladder keeps its prefix, which is
        /// the whole reason the prefix exists.</summary>
        private static string PodiumTitleOnOwnBoard(string title, string ladderPrefix)
            => (!string.IsNullOrEmpty(title) && title.StartsWith(ladderPrefix + " ", StringComparison.Ordinal))
               ? title.Substring(ladderPrefix.Length + 1) : title;
        private static uint _podiumTick = 0;
        private static float _podiumTickAt = 0f;
        // Entries: [0]=txtName object, [1]=base name (no title), [2]=title, [3]=color hex
        private static readonly List<object[]> _podiumLbRows = new List<object[]>();
        // Aug 12 item 2c: the 2v2 and FFA boards get the same ANIMATED glitter
        // (they had a static tick-0 span). One list per board because each is
        // repopulated by its own refresh; the tick walks all three, which costs
        // nothing — only one board is on screen at a time, and rewriting a
        // pooled row that is currently inactive is harmless.
        private static readonly List<object[]> _podiumTeamRows = new List<object[]>();
        private static readonly List<object[]> _podiumFfaRows = new List<object[]>();
        // Dark SDF outline on podium rows' cells so text stays readable over the
        // gold/silver/bronze tints (Sid: "Stan's elo is hard to read"). Original
        // materials keyed by label; one outline clone per base material.
        private static readonly Dictionary<object, Material> _lbOutlineOrig = new Dictionary<object, Material>();
        private static readonly Dictionary<Material, Material> _lbOutlineCache = new Dictionary<Material, Material>();
        private static void SetLbRowOutline(LBRow row, bool on)
        {
