        // The 1v1 podium tints, verbatim (alphas already halved once — 0.22
        // "read too strong behind text"). Shared so the three boards cannot
        // drift into three slightly different golds.
        private static Color PodiumRowTint(int rank)
            => rank == 1 ? new Color(1f, 0.84f, 0f, 0.11f)
             : rank == 2 ? new Color(0.75f, 0.75f, 0.78f, 0.10f)
             : rank == 3 ? new Color(0.8f, 0.5f, 0.2f, 0.10f)
             : new Color(0.15f, 0.15f, 0.2f, 0.01f);
        /// <summary>Give a pooled board row the background Image the tint is
        /// written to. Painted on the row ROOT rather than an inserted wrapper
        /// object: the root already carries the row's HLG and padding, so this
        /// changes no layout at all (an Image is not an ILayoutElement) and
        /// covers the full row width including the padding. raycastTarget is
        /// FALSE — unlike the 1v1 board these rows are not clickable, and a new
        /// raycast target under the cursor is not a change worth making for a
        /// decoration.</summary>
        private static void AddRowBackground(GameObject root)
        {
            if (root == null || UIFactory.tImage == null) return;
            try
            {
                var img = root.AddComponent(UIFactory.tImage);
                var bf = BindingFlags.Public | BindingFlags.Instance;
                UIFactory.tImage.GetProperty("color", bf)?.SetValue(img, PodiumRowTint(0));
                UIFactory.tImage.GetProperty("raycastTarget", bf)?.SetValue(img, false);
            }
            catch { }
        }
        internal static string PodiumSparkleSpan(string title, string hex, uint tick)
        {
            // Brackets carry the title color too — bare brackets inherit the row's
            // BASE color (green on the local player's row), which read as a bug
            // (Sid feedback, v1.32 round 2).
            var sb = new System.Text.StringBuilder(title.Length * 24 + 40);
            sb.Append("<b><color=").Append(hex).Append(">[</color>");
            for (int i = 0; i < title.Length; i++)
            {
                bool glint = ((i + (int)tick) % 3) == 0;
                sb.Append("<color=").Append(glint ? "#FFFFFF" : hex).Append(">")
                  .Append(title[i]).Append("</color>");
            }
            sb.Append("<color=").Append(hex).Append(">]</color></b>");
            return sb.ToString();
        }
        private static void TickPodiumSparkle()
        {
            if (_podiumLbRows.Count == 0 && _podiumTeamRows.Count == 0 && _podiumFfaRows.Count == 0) return;
            if (Time.unscaledTime < _podiumTickAt) return;
            _podiumTickAt = Time.unscaledTime + 0.7f;
            _podiumTick++;
            RepaintPodiumRows(_podiumLbRows);
            RepaintPodiumRows(_podiumTeamRows);
            RepaintPodiumRows(_podiumFfaRows);
        }
        private static void RepaintPodiumRows(List<object[]> rows)
        {
            foreach (var r in rows)
            {
                if (r == null || r.Length < 4 || r[0] == null) continue;
                UIFactory.SetTextRaw(r[0],
                    $"{(string)r[1]} {PodiumSparkleSpan((string)r[2], (string)r[3], _podiumTick)}");
            }
        }

        // Pulled out of RefreshTeamTab so the queue lists keep updating while
        // the tab is open even when nothing else flips the dirty bit. Without
        // this the Random Queue / Custom Lobbies panels stay frozen until the
        // user navigates away and back. Throttled to 2s to match the existing
        // /team/queue/list cadence in ApiClient.
        private static float teamTabRefreshAt;
        private static float teamSeriesRefreshAt;
        public static int teamSeriesPageReq = 0;
        public static void MaybeRefreshTeamTab()
        {
            if (currentTab != 8) return;
            // Aug 12 item 2c: BEFORE the throttle, exactly like the 1v1 tab's
            // ticker — a 0.7s glitter cannot live behind a 2s gate.
            TickPodiumSparkle();
            if (Time.unscaledTime < teamTabRefreshAt) return;
            teamTabRefreshAt = Time.unscaledTime + 2f;
            // v1.37 host lobbies: one-shot membership rediscovery + the
            // browser fetch. The state HEARTBEAT itself runs from
            // TickLeaveRecovery, not from this tab ticker.
            ApiClient.TeamLobby.ProbeServerState();
            ApiClient.TeamLobby.FetchLobbies(false);   // internally 3s-throttled
            ApiClient.UpdateTeamQueueList(force: true);
            // Header count auto-refreshes via its own internal 10s timer.
            ApiClient.UpdateTeamQueueCount();
            // Live 2v2 strip — pull the active team series feed every 5s so
            // the inline panel inside the 2v2 tab stays current without
            // requiring the user to switch to the leaderboard tab.
            ApiClient.FetchActiveTeamSeries();
            // Aug 7 item 13: WATCH buttons on the live strip need the spectate
            // eligibility feed; its own 10s global throttle dedupes traffic.
            ApiClient.MaybeFetchSpectateGames();
            // Recent 2v2 Series (paged) — refresh every 10s. Page state lives
            // in teamSeriesPageReq so prev/next buttons can change it.
            if (Time.unscaledTime >= teamSeriesRefreshAt)
            {
                teamSeriesRefreshAt = Time.unscaledTime + 10f;
                ApiClient.FetchAllSeriesPaged(teamSeriesPageReq, 10);
            }
        }

        private static void FindMainMenuGroup(){
            // QuitButton COMPONENT anchor first (locale-independent — the
            // text=="QUIT" match fails on every non-English ROUNDS install
            // because the game localizes the label; same fix as
            // MainMenuInjector). Text match kept only as a fallback.
            var all=UnityEngine.Object.FindObjectsOfType<ListMenuButton>();
            foreach(var b in all){try{if(b!=null&&b.GetComponent<QuitButton>()!=null){mainMenuGroup=b.transform.parent.gameObject;Plugin.Log.LogInfo($"[NATIVE] Found main menu group (component anchor): {mainMenuGroup.name}");return;}}catch{}}
            Type tt=null;PropertyInfo tp=null;foreach(var a in AppDomain.CurrentDomain.GetAssemblies()){tt=a.GetType("TMPro.TMP_Text");if(tt!=null)break;}if(tt!=null)tp=tt.GetProperty("text",BindingFlags.Public|BindingFlags.Instance);
            foreach(var b in all){if(tp==null)break;try{var tc=b.GetComponentInChildren(tt,true);if(tc==null)continue;if((tp.GetValue(tc)as string??"").Trim().ToUpper()=="QUIT"){mainMenuGroup=b.transform.parent.gameObject;Plugin.Log.LogInfo($"[NATIVE] Found main menu group: {mainMenuGroup.name}");return;}}catch{}}
            Plugin.Log.LogWarning("[NATIVE] Could not find QUIT button");}
        private static Transform FindCanvasAbove(Transform from){Transform c=from;while(c!=null){if(UIFactory.tCanvas!=null&&c.GetComponent(UIFactory.tCanvas)!=null){Plugin.Log.LogInfo($"[NATIVE] Found Canvas: {c.gameObject.name}");return c;}c=c.parent;}return from.parent??from;}
        private static void EnsureOverlayCanvas(){if(overlayCanvasGO!=null)return;overlayCanvasGO=new GameObject("CR_OverlayCanvas");overlayCanvasGO.hideFlags=HideFlags.HideAndDontSave;UnityEngine.Object.DontDestroyOnLoad(overlayCanvasGO);if(UIFactory.tCanvas!=null){var cv=overlayCanvasGO.AddComponent(UIFactory.tCanvas);var bf=BindingFlags.Public|BindingFlags.Instance;UIFactory.tCanvas.GetProperty("renderMode",bf)?.SetValue(cv,Enum.ToObject(UIFactory.tCanvas.GetProperty("renderMode",bf).PropertyType,0));UIFactory.tCanvas.GetProperty("sortingOrder",bf)?.SetValue(cv,30000);}if(UIFactory.tCanvasScaler!=null){var sc=overlayCanvasGO.AddComponent(UIFactory.tCanvasScaler);var bf=BindingFlags.Public|BindingFlags.Instance;var smp=UIFactory.tCanvasScaler.GetProperty("uiScaleMode",bf);if(smp!=null)smp.SetValue(sc,Enum.ToObject(smp.PropertyType,1));UIFactory.tCanvasScaler.GetProperty("referenceResolution",bf)?.SetValue(sc,new Vector2(1920,1080));}if(UIFactory.tGR!=null)overlayCanvasGO.AddComponent(UIFactory.tGR);Plugin.Log.LogInfo("[NATIVE] Created persistent overlay Canvas");}

        private static void BuildPage(Transform canvasParent)
        {
            try{rankedRows.Clear();casualRows.Clear();lbRows.Clear();cardRows.Clear();sessionOppTexts.Clear();ovtSoloLbRows.Clear();ovtDuoLbRows.Clear();ovtRecentRows.Clear();ovtRecentHoverBodies.Clear();ffaLbRows.Clear();ffaRecentRows.Clear();ffaRecentCasRows.Clear();
            /* Bugs #147/#149/#150: EVERY pool below holds rows parented to the
             * OLD pageGO and is re-Add()ed by a Build*Tab under the new one.
             * Miss one and a SECOND BuildPage — which the language switch and
             * the first-run language prompt both trigger — leaves destroyed
             * rows at indices 0..N-1; the next refresh throws
             * MissingReferenceException into Plugin.Update's empty catch, so
             * the tab renders blank with NO log line at all. Parallel
             * index-mapped lists MUST clear alongside their row pool.
             * Deliberately NOT cleared: chatLines (chat history, not views),
             * compareSelected (the user's picks, not views), _lblParts/
