        private static Color FfaPlayerColor(int slot)
        {
            int n=FFA_SLOT_PALETTE.Length;
            return FFA_SLOT_PALETTE[((slot%n)+n)%n];
        }

        private static string FfaSafeRich(string value)
        {
            if(string.IsNullOrEmpty(value))return "";
            // Control characters flatten to spaces (Codex Jul-29 find 9): a
            // card/display name carrying raw line breaks would explode the
            // one-line height estimates and the hover tooltip's CalcHeight.
            // C0 AND C1 (U+0085 NEL!) AND the U+2028/U+2029 separators — all
            // of which TMP treats as line control (round-2 find 5).
            var sb=new StringBuilder(value.Length);
            foreach(char ch in value)
                sb.Append(ch<' '||(ch>=(char)0x7F&&ch<=(char)0x9F)
                          ||ch==(char)0x2028||ch==(char)0x2029?' ':ch);
            return sb.ToString().Replace("&","&amp;").Replace("<","&lt;").Replace(">","&gt;");
        }

        private static string FfaTitleHex(string value)
        {
            if(string.IsNullOrEmpty(value))return "#FFD94D";
            try
            {
                if(ColorUtility.TryParseHtmlString(value,out Color parsed))
                    return "#"+ColorUtility.ToHtmlStringRGB(parsed);
            }
            catch{}
            return "#FFD94D";
        }

        private static int FfaGameNumber(string room)
        {
            if(string.IsNullOrEmpty(room))return -1;
            int marker=room.LastIndexOf("_r",StringComparison.Ordinal);
            if(marker<0||marker+2>=room.Length)return -1;
            if(int.TryParse(room.Substring(marker+2),System.Globalization.NumberStyles.None,
                System.Globalization.CultureInfo.InvariantCulture,out int game)&&game>0)return game;
            return -1;
        }

        // The inline line shows only the FINAL HAND (the cards still held at
        // game end) — the full mixed-color stream wrapped 2-3 lines per player
        // in long games and read badly (Sid, July 29 item 1). Replaced
        // ("rolled") picks collapse into a red "+N replaced" chip; hovering
        // the line shows the complete chronological list in a tooltip
        // (hoverText, drawn by DrawFfaRecentHoverGraph's IMGUI pass).
        private static string BuildFfaCardsText(ApiClient.FfaRecentPlayer player,out string hoverText)
        {
            hoverText=null;
            if(player==null)return "";
            /* Round-2 HIGH, FFA sibling (#279 — the same defect the 1v1 and 2v2
             * halves were reported for, in the mode whose "(hover for build)"
             * wording the other two now copy). This used to return "" on an
             * empty card list, BEFORE the build was even decoded, so a
             * participant who never picked a card had their stored build
             * dropped and their cards line hidden entirely — no surface at all.
             * The build is therefore decoded FIRST and a card-less player still
             * gets a line, because the line is what the hover scan hit-tests
             * (cardsGO must be active and non-empty for the region to exist). */
            string buildOnly=BuildStatsTipBlock(player.end_stats,BUILD_TIP_WIDE_COLS);
            if(player.cards==null||player.cards.Count==0)
            {
                if(buildOnly.Length==0)return "";
                hoverText=buildOnly;
                return "    <color=#667788>"+I18n.Tr("Cards:")+"</color> "
                      +I18n.Tr("<color=#667788>none</color>  <color=#556270>(hover for build)</color>");
            }
            int rolled=0;
            var sb=new StringBuilder("    <color=#667788>"+I18n.Tr("Cards:")+"</color> ");
            bool firstHeld=true;
            for(int i=0;i<player.cards.Count;i++)
            {
                var card=player.cards[i];
                if(card!=null&&card.rolled){rolled++;continue;}
                if(!firstHeld)sb.Append("<color=#667788>, </color>");
                firstHeld=false;
                sb.Append("<color=#8FA0B0>").Append(FfaSafeRich(card?.name??"?")).Append("</color>");
            }
            if(firstHeld)sb.Append(I18n.Tr("<color=#667788>none held</color>"));
            // Aug 12 item 1: the FFA tab draws its own 470px tooltip
            // (DrawFfaCardsTooltip) which measures with CalcHeight, so it takes
            // the WIDE column budget. Decoded above the empty-hand branch
            // because whether a build exists decides which affordance the line
            // needs — a tooltip nobody is told about is a tooltip nobody opens.
            string build=buildOnly;
            var hv=new StringBuilder();
            if(rolled>0)
            {
                sb.Append("  ").Append(I18n.TrF("<color=#FF6666>+{0} replaced</color> <color=#556270>(hover)</color>",rolled));
                hv.Append(I18n.Tr("All picks (oldest first) - red = replaced:")).Append('\n');
                int onLine=0;
                for(int i=0;i<player.cards.Count;i++)
                {
                    var card=player.cards[i];
                    if(onLine>0)hv.Append(", ");
                    string color=card!=null&&card.rolled?"#FF7777":"#DDDDDD";
                    hv.Append("<color=").Append(color).Append(">")
                      .Append(FfaSafeRich(card?.name??"?")).Append("</color>");
                    if(++onLine>=4&&i<player.cards.Count-1){hv.Append('\n');onLine=0;}
                }
            }
            else if(build.Length>0)
            {
                sb.Append("  ").Append(I18n.Tr("<color=#556270>(hover for build)</color>"));
            }
            if(build.Length>0)
            {
                if(hv.Length>0)hv.Append('\n');
                hv.Append(build);
            }
            if(hv.Length>0)hoverText=hv.ToString();
            return sb.ToString();
        }

        private static void FillFfaDotPool(List<GameObject> pool,GameObject group,int count,Sprite sprite,Color color,string prefix)
        {
            count=Math.Max(0,count);
            while(pool.Count<count)pool.Add(CreateFfaDot(group.transform,prefix+pool.Count,sprite));
            for(int i=0;i<pool.Count;i++)
            {
                bool show=i<count;
                pool[i].SetActive(show);
                if(show)UIFactory.SetImageColor(pool[i],color);
            }
            float width=count>0?count*10f+(count-1)*2f:0f;
            SetFfaLayoutWidth(group,width,0f);
        }

        private static FfaTimelineGraph ParseFfaTimeline(ApiClient.FfaRecentMatch match,List<ApiClient.FfaRecentPlayer> players)
        {
            if(match==null||string.IsNullOrEmpty(match.timeline)||players==null||players.Count==0)return null;
            string[] tokens=match.timeline.Split(',');
            int n=players.Count;
            var graph=new FfaTimelineGraph
            {
                names=new string[n],
                colors=new Color[n],
                values=new float[n][],
            };
            var fullPoints=new int[n];
            var liveHalves=new int[n];
            for(int i=0;i<n;i++)
            {
                graph.names[i]=Trunc(players[i]?.display_name??"?",18);
                // A missing slot serialises as -1, which would land every such
                // player on the same palette entry — fall back to row index.
                int slotForColor=players[i]!=null?players[i].slot:-1;
                if(slotForColor<0)slotForColor=i;
                graph.colors[i]=FfaPlayerColor(slotForColor);
                // Aug 8 (Sid, round 2): when the row carries the match-time
                // body-colour stamp, the graph line adopts it — the SAME
                // resolution the score dots use (BuildFfaRecentRowText), so
                // the dots/graph stay a matched pair; slot palette otherwise.
                // Resolved here, at graph-build/fill time (#265).
                string gHex=SafeHexColor(players[i]?.color_hex);
                if(gHex!=null&&ColorUtility.TryParseHtmlString(gHex,out Color gStamp))graph.colors[i]=gStamp;
                graph.values[i]=new float[tokens.Length+1];
            }
            int eventIndex=0;
            for(int t=0;t<tokens.Length;t++)
            {
                string token=tokens[t];
                int pos=0;
                while(pos<token.Length&&(token[pos]==' '||token[pos]=='\t'))pos++;
                int digitStart=pos;
                int slot=0;
                while(pos<token.Length&&char.IsDigit(token[pos]))
                {
                    slot=slot*10+(token[pos]-'0');
                    pos++;
                }
                if(pos==digitStart)continue;
                int line=-1;
                for(int i=0;i<n;i++)if(players[i]!=null&&players[i].slot==slot){line=i;break;}
                if(line<0)continue;
                bool converted=false;
                for(int i=pos;i<token.Length;i++)if(token[i]=='R'){converted=true;break;}
                liveHalves[line]++;
                if(converted)
                {
                    fullPoints[line]++;
                    Array.Clear(liveHalves,0,liveHalves.Length);
                }
                eventIndex++;
                for(int i=0;i<n;i++)
                {
                    float score=fullPoints[i]+liveHalves[i]*0.5f;
                    graph.values[i][eventIndex]=score;
                    if(score>graph.maxScore)graph.maxScore=score;
                }
            }
            if(eventIndex==0)return null;
            graph.eventCount=eventIndex;
            graph.maxScore=Mathf.Max(1f,Mathf.Ceil(graph.maxScore*2f)*0.5f);
            int game=FfaGameNumber(match.photon_room_id);
            graph.title=game>0?I18n.TrF("Game {0} score progression",game):I18n.Tr("Score progression");
            graph.eventLabel=I18n.TrF("{0} half-point events",eventIndex);
            graph.maxLabel=graph.maxScore.ToString("0.#",System.Globalization.CultureInfo.InvariantCulture);
            return graph;
        }

        /// <summary>Compact "what was this game set to" tail for an FFA history
        /// header (Sid, Aug 3). Deliberately shows only what DIFFERS from the
        /// defaults — a header that repeats "to 5, cap 5, 1 pick" on every row
        /// is noise, and the row is width-constrained. Empty string for
        /// pre-config matches, whose stored values were never actually
        /// used.</summary>
        private static string FfaSettingsSummary(ApiClient.FfaRecentMatch m)
        {
            if(m==null||!m.has_settings)return "";
            var bits=new List<string>(4);
            // "to N"/"cap N" stay literal: 2-letter connectors can never be
            // harvestable keys (#295c) and fold poorly into a template here.
            if(m.score_target>0&&m.score_target!=5)bits.Add($"to {m.score_target}");
            if(m.card_candidates>0&&m.card_candidates!=5)bits.Add(I18n.TrF("{0}-card draw",m.card_candidates));
            if(m.card_cap>0&&m.card_cap!=5)bits.Add($"cap {m.card_cap}");
            if(m.initial_picks>1)bits.Add(I18n.TrF("{0} opening picks",m.initial_picks));
            if(m.same_card_rule)bits.Add(I18n.Tr("same-card"));
            if(bits.Count==0)return "";
            return $" <color=#777>-</color> <color=#C48CFF>{string.Join(", ",bits.ToArray())}</color>";
        }

        private static void BuildFfaRecentRowText(ApiClient.FfaRecentMatch match,FfaRecentMatchRow row)
        {
            if(match==null||row==null)return;
            row.currentMatchId=match.match_id;
            if(row.btnId!=null)row.btnId.SetActive(!string.IsNullOrEmpty(match.match_id));
            string date="";
            if(!string.IsNullOrEmpty(match.ended_at)&&DateTime.TryParse(match.ended_at,
                System.Globalization.CultureInfo.InvariantCulture,
                System.Globalization.DateTimeStyles.AssumeUniversal,out DateTime parsed))
                date=DateFmt.Short(parsed);
            string duration=match.duration_seconds>0
                ?$"{match.duration_seconds/60}m{match.duration_seconds%60:00}s":"?";
            int game=FfaGameNumber(match.photon_room_id);
            int playerCount=match.player_count>0?match.player_count:(match.players?.Count??0);
            string gameText=game>0?I18n.TrF("Game {0}",game):I18n.Tr("Game ?");
            string hover=!string.IsNullOrEmpty(match.timeline)
                ?"  "+I18n.Tr("<color=#777>(hover for score graph)</color>"):"";
            UIFactory.SetTextRaw(row.txtHeader,
                I18n.TrF("<color=#DDDDDD>{0}</color> <color=#777>-</color> {1} players <color=#777>-</color> <color=#8FA3B8>{2}</color> <color=#777>-</color> {3}",
                    date,playerCount,duration,gameText)
                +FfaSettingsSummary(match)+hover);

            var players=new List<ApiClient.FfaRecentPlayer>(match.players??new List<ApiClient.FfaRecentPlayer>());
            players.Sort((a,b)=>(a?.placement>0?a.placement:99).CompareTo(b?.placement>0?b.placement:99));
            while(row.players.Count<players.Count)
                row.players.Add(CreateFfaRecentPlayerRow(row.root.transform,"Player"+row.players.Count));
            EnsureFfaDotSprites();
            for(int i=0;i<row.players.Count;i++)
            {
                var ui=row.players[i];
                if(i>=players.Count){ui.root.SetActive(false);continue;}
                var player=players[i];
                if(player==null){ui.root.SetActive(false);continue;}
                int placement=player.placement;
                bool winner=(!string.IsNullOrEmpty(match.winner_steam_id)&&player.steam_id==match.winner_steam_id)
                            ||(string.IsNullOrEmpty(match.winner_steam_id)&&placement==1);
                // Aug 8 (Sid, round 2): the match-time body-colour stamp now
                // drives the score DOTS too (not just the points text below) —
                // and ParseFfaTimeline applies the same stamp to that player's
                // graph line, so the dots/graph stay a matched pair. Pre-stamp
                // rows (empty color_hex) keep the slot palette exactly as
                // before. SafeHexColor validates the server hex (#156 family).
                string stampHex=SafeHexColor(player.color_hex);
                Color dotColor=FfaPlayerColor(player.slot);
                if(stampHex!=null&&ColorUtility.TryParseHtmlString(stampHex,out Color stamped))dotColor=stamped;
                // Aug 11 review find: dots keep the RAW stamp (graph/dot
                // identity match), but TEXT gets the lightness floor —
                // Charcoal/Obsidian stamps were near-invisible as text.
                string stampTextHex=stampHex!=null?ReadableNameColor(stampHex):null;
                UIFactory.SetText(ui.txtPlacement,placement>0?$"#{placement}":"#?");
                // Name first, THEN the title — every other surface renders
                // "name [title]" (leaderboards, chat); this row was the one
                // place with the order flipped (Sid, July 29 item 1).
                string title=string.IsNullOrEmpty(player.title)?""
                    :$" <color={FfaTitleHex(player.title_color)}>[{FfaSafeRich(Trunc(player.title,14))}]</color>";
                string nameColor=winner?"#FFD700":"#FFFFFF";
                /* Leading space INSIDE the key: a spaceless "(left)" token fails the
                   extractor's single-token rule and could never be harvested. */
                string left=player.left_early?I18n.Tr(" <color=#888888>(left)</color>"):"";
                UIFactory.SetTextRaw(ui.txtIdentity,
                    $"<color={nameColor}>{FfaSafeRich(Trunc(player.display_name??"?",18))}</color>{title}{left}");

                int points=Math.Max(0,player.rounds_won);
                int leftover=Math.Max(0,player.points_total-points*2);
                int shownHalves=Math.Min(FFA_HALF_DOT_CAP,leftover);
                FillFfaDotPool(ui.fullDots,ui.fullDotsGO,points,ffaFullDotSprite,dotColor,"P");
                FillFfaDotPool(ui.halfDots,ui.halfDotsGO,shownHalves,ffaHalfDotSprite,dotColor,"H");
                // Aug 8 (Sid): the stamp also tints the points/score readout
                // (stampHex computed above, beside the dot colour).
                UIFactory.SetText(ui.txtPoints,stampTextHex!=null?$"<color={stampTextHex}>{points}(P)</color>":$"{points}(P)");
                int hiddenHalves=leftover-shownHalves;
                if(ui.halfOverflowGO!=null)ui.halfOverflowGO.SetActive(hiddenHalves>0);
                if(hiddenHalves>0)UIFactory.SetText(ui.txtHalfOverflow,stampTextHex!=null?$"<color={stampTextHex}>+{hiddenHalves}</color>":$"+{hiddenHalves}");
                UIFactory.SetText(ui.txtHalves,stampTextHex!=null?$"<color={stampTextHex}>{leftover}(H)</color>":$"{leftover}(H)");
                UIFactory.SetText(ui.txtKills,$"{Math.Max(0,player.kills)}k");
                UIFactory.SetText(ui.txtRewards,player.xp_gained==0&&player.gold_gained==0?""
                    :$"+{player.xp_gained}xp <color=#FFD94D>+{player.gold_gained}g</color>");
                if(player.has_rating_change)
                {
                    string elo=RatingDeltaText(player.rating_change);
                    UIFactory.SetText(ui.txtElo,$"<color={(player.rating_change>=0?"#00FF00":"#FF6666")}>{elo}</color>");
                }
                else UIFactory.SetText(ui.txtElo,"");

                // Telemetry line. Rows predating the FFA telemetry migration
                // carry nothing, so the whole line hides rather than showing a
                // row of dashes.
                bool hasCombat=player.bullets_fired>0||player.blocks_activated>0;
                bool hasConn=player.fps_avg>0||player.ping_avg>0;
                // Aug 7 review find 4: damage stands on its own. A melee, body-
                // damage or trap build deals real damage with zero shots and zero
                // blocks, so hasCombat alone would hide its DPS. RECORD_NONE is
                // the "not recorded" sentinel; 0 is a legitimate value (#257).
                bool hasDamage=player.damage_dealt>=0;
                if(ui.statsGO!=null)ui.statsGO.SetActive(hasCombat||hasConn||hasDamage);
                if(hasCombat||hasConn||hasDamage)
                {
                    string hitTxt="",blkTxt="",fpsTxt="",pingTxt="";
                    var inv=System.Globalization.CultureInfo.InvariantCulture;
                    /* These two colour the LABEL and leave the value in the cell's
                     * own colour, so the tag closes mid-message and the markup
                     * cannot be hoisted out of the literal the way every other
                     * telemetry string here was: the close tag would have to land
                     * at a word boundary only the translation knows. "Block {0}%"
                     * therefore stays a second key alongside the whole-wrapped one
                     * the 1v1 history row uses. Wrapping the WHOLE string to merge
                     * them would tint the number too — a silent restyle. */
                    if(player.bullets_fired>0)
                        hitTxt=I18n.TrF("<color=#FF9988>Hit</color> {0}%",(100f*player.bullets_hit/player.bullets_fired).ToString("F0",inv));
                    if(player.blocks_activated>0)
                        /* Colour hoisted out of the literal so the key is the plain "Block {0}%",
                         * matching the sibling call sites that already use it. The tag
                         * used to close after the word, leaving the percentage
                         * uncoloured; it is now tinted like every other Block cell in
                         * the mod, which is the small deliberate visual change this
                         * key collapse costs. */
                        blkTxt="<color=#99CCFF>"+I18n.TrF("Block {0}%",(100f*player.blocks_successful/player.blocks_activated).ToString("F0",inv))+"</color>";
                    if(player.fps_avg>0)fpsTxt=I18n.TrF("<color=#8FA3B8>{0} fps</color>",player.fps_avg);
                    if(player.ping_avg>0)pingTxt=I18n.TrF("<color=#8FA3B8>{0} ms</color>",player.ping_avg);
                    /* Aug 6 item 4 — avg DPS over the whole game. A NULL damage
                     * column (every game before the telemetry clients) renders a
                     * DASH, never "0.0" — 0 is a legitimate value here (#257).
                     * The dash still needs hasCombat: it exists so a row that
                     * ALREADY shows telemetry doesn't lose a column, whereas a
                     * recorded damage value earns the cell on its own. */
                    string dpsTxt="";
                    if(hasDamage||hasCombat)
                        dpsTxt="<color=#C9A6E8>"+I18n.TrF("{0} dps",
                            hasDamage&&match.duration_seconds>0
                                ?(player.damage_dealt/(float)match.duration_seconds).ToString("F1",inv):"-")+"</color>";
                    UIFactory.SetTextRaw(ui.txtHit,hitTxt);
                    UIFactory.SetTextRaw(ui.txtBlock,blkTxt);
                    UIFactory.SetTextRaw(ui.txtFps,fpsTxt);
                    UIFactory.SetTextRaw(ui.txtPing,pingTxt);
                    UIFactory.SetTextRaw(ui.txtDps,dpsTxt);
                    // Only register a region when the cell actually rendered
                    // text: an EMPTY element has preferredWidth 0, which the
                    // hover resolver treats as "no fraction" = a FULL-width
                    // invisible hover trap across the row (1v1 review [8]).
                    // F9: also pass the whole-tab OUTER viewport so the hit
                    // test clips against BOTH masks live (the cards/header
                    // path already double-clips via TryGetFfaViewportClippedRect).
                    // F13: pass this participant's name — the popup titles the
                    // series with it instead of claiming the series is "you".
                    string subjectName=FfaSafeRich(Trunc(player.display_name??"?",18));
                    if(!string.IsNullOrEmpty(hitTxt))
                        RegisterPairGraphRectFor(ui.txtHit,player.hit_timeline,false,false,null,match.timeline,ffaTabOuterViewport,subjectName,match.duration_seconds);
                    if(!string.IsNullOrEmpty(blkTxt))
                        RegisterPairGraphRectFor(ui.txtBlock,player.block_timeline,true,false,null,match.timeline,ffaTabOuterViewport,subjectName,match.duration_seconds);
                    if(!string.IsNullOrEmpty(fpsTxt))
                        RegisterTeleGraphRectFor(ui.txtFps,player.fps_timeline,null,false,null,match.timeline,outerClip:ffaTabOuterViewport,subjectLabel:subjectName,durationSeconds:match.duration_seconds);
                    if(!string.IsNullOrEmpty(pingTxt))
                        RegisterTeleGraphRectFor(ui.txtPing,player.ping_timeline,null,true,null,match.timeline,outerClip:ffaTabOuterViewport,subjectLabel:subjectName,durationSeconds:match.duration_seconds);
                    /* Aug 7 item 3d: per-second damage line. FFA samples every
                     * participant on the one 3s telemetry tick, so unlike 1v1
                     * there is a single cadence for the whole match. A row
                     * predating the damage columns has no timeline, so the
                     * converter returns an EMPTY series and nothing is registered
                     * even though the cell renders its dash.
                     * F7 (Codex r3): decimated timelines have variable stride —
                     * derive the interval from the row's real duration
                     * (DpsStepFor), falling back to the 3s tick. */
                    if(!string.IsNullOrEmpty(dpsTxt))
                    {
                        float ffaDpsStep=DpsStepFor(player.damage_timeline,match.duration_seconds,DPS_STEP_FFA);
                        RegisterDpsGraphRectFor(ui.txtDps,CumulativeToDps(player.damage_timeline,ffaDpsStep),null,null,match.timeline,ffaDpsStep,ffaTabOuterViewport,subjectName,match.duration_seconds);
                    }
                }

                string cards=BuildFfaCardsText(player,out string cardsHover);
                ui.cardsHoverText=cardsHover;
                if(ui.cardsGO!=null)ui.cardsGO.SetActive(!string.IsNullOrEmpty(cards));
                if(!string.IsNullOrEmpty(cards))UIFactory.SetText(ui.txtCards,cards);
                ui.root.SetActive(true);
            }
            if(row.timelineMatchId!=match.match_id||row.timelineSource!=match.timeline)
            {
                row.timelineMatchId=match.match_id;
                row.timelineSource=match.timeline;
                row.graph=ParseFfaTimeline(match,players);
            }
            row.root.SetActive(true);
        }

        private static float EstimateFfaRecentHeight(ApiClient.FfaRecentMatch match)
        {
            float height=38f;
            if(match?.players==null)return height;
            foreach(var player in match.players)
            {
                height+=27f;
                // The telemetry line only renders when the row actually has
                // telemetry, so the estimate must use the same condition or
                // the inner scroll is sized for content that is not there.
                if(player!=null&&(player.bullets_fired>0||player.blocks_activated>0
                                  ||player.fps_avg>0||player.ping_avg>0))
                    height+=19f;
                if(player==null)continue;
                if(player.cards==null||player.cards.Count==0)
                {
                    // Round-2 HIGH sibling: a card-less player with a stored
                    // build now DOES render a cards line ("none (hover for
                    // build)"), so the estimate has to count it or the inner
                    // scroll is sized for content that is there (#199 in the
                    // direction the old `continue` got away with). Presence,
                    // not a decode: an undecodable wire over-counts by 20px,
                    // which costs a sliver of scroll and never overpaints.
                    if(!string.IsNullOrEmpty(player.end_stats))height+=20f;
                    continue;
                }
                // Inline line = held cards only (rolled ones collapse into a
                // "+N replaced" chip) — count what actually renders.
                int chars=11;
                int rolled=0;
                foreach(var card in player.cards)
                {
                    if(card!=null&&card.rolled){rolled++;continue;}
                    chars+=(card?.name?.Length??1)+2;
                }
                if(rolled>0)chars+=22;
                height+=Math.Max(1,(chars+89)/90)*20f;
            }
            return height+8f;
        }

        private static void EnsureFfaWorldToScreenPoint()
        {
            if(ffaWorldToScreenPointResolved)return;
            ffaWorldToScreenPointResolved=true;
            try
            {
                foreach(var asm in AppDomain.CurrentDomain.GetAssemblies())
                {
                    var type=asm.GetType("UnityEngine.RectTransformUtility");
                    if(type==null)continue;
                    var method=type.GetMethod("WorldToScreenPoint",BindingFlags.Public|BindingFlags.Static,
                        null,new Type[]{typeof(Camera),typeof(Vector3)},null);
                    if(method==null)continue;
                    ffaWorldToScreenPoint=(Func<Camera,Vector3,Vector2>)Delegate.CreateDelegate(
                        typeof(Func<Camera,Vector3,Vector2>),method);
                    break;
                }
            }
            catch{ffaWorldToScreenPoint=null;}
        }

        private static bool TryGetFfaScreenRect(RectTransform target,out Rect rect)
        {
            rect=default(Rect);
            if(target==null||!target.gameObject.activeInHierarchy)return false;
            target.GetWorldCorners(ffaHoverCorners);
            float minX=float.PositiveInfinity,minY=float.PositiveInfinity;
            float maxX=float.NegativeInfinity,maxY=float.NegativeInfinity;
            for(int i=0;i<4;i++)
            {
                Vector2 point=ffaWorldToScreenPoint!=null
                    ?ffaWorldToScreenPoint(null,ffaHoverCorners[i])
                    :new Vector2(ffaHoverCorners[i].x,ffaHoverCorners[i].y);
                minX=Mathf.Min(minX,point.x);maxX=Mathf.Max(maxX,point.x);
                minY=Mathf.Min(minY,point.y);maxY=Mathf.Max(maxY,point.y);
            }
            if(maxX<=minX||maxY<=minY)return false;
            rect=new Rect(minX,Screen.height-maxY,maxX-minX,maxY-minY);
            return true;
        }

        /// <summary>Screen rect of `target` clipped to BOTH scroll masks that
        /// can hide it — the Recent-FFAs list viewport AND the whole-tab outer
        /// viewport. Rows scrolled out of view must not keep live hover
        /// regions (#185: raw rect tests ignore mask clipping).</summary>
        private static bool TryGetFfaViewportClippedRect(RectTransform target,out Rect rect)
        {
            return TryGetFfaViewportClippedRect(target,ffaRecentViewport,out rect);
        }
        // Per-section variant (item 6): casual rows must clip against THEIR
        // list mask, not the ranked one — callers pass row.ownerViewport.
        private static bool TryGetFfaViewportClippedRect(RectTransform target,RectTransform listViewport,out Rect rect)
            => TryGetMaskedScreenRect(target,listViewport,ffaTabOuterViewport,out rect);

        /// <summary>Screen rect of `target` clipped to the two scroll masks
        /// that can hide it: its own list viewport and the whole-tab outer
        /// viewport. Both are parameters because the 1v2 tab has the identical
        /// two-mask nesting and had no clipping helper of its own — a raw rect
        /// test ignores mask clipping entirely (#185), so a row scrolled under
        /// either edge would keep a live hover region over whatever is drawn
        /// there.</summary>
        private static bool TryGetMaskedScreenRect(RectTransform target,RectTransform listViewport,
                                                   RectTransform outerViewport,out Rect rect)
        {
            rect=default(Rect);
            if(!TryGetFfaScreenRect(target,out Rect raw))return false;
            if(listViewport!=null&&TryGetFfaScreenRect(listViewport,out Rect clip))
            {
                float xMin=Mathf.Max(raw.xMin,clip.xMin);
                float xMax=Mathf.Min(raw.xMax,clip.xMax);
                float yMin=Mathf.Max(raw.yMin,clip.yMin);
                float yMax=Mathf.Min(raw.yMax,clip.yMax);
                if(xMax<=xMin||yMax<=yMin)return false;
                raw=new Rect(xMin,yMin,xMax-xMin,yMax-yMin);
            }
            if(outerViewport!=null&&TryGetFfaScreenRect(outerViewport,out Rect oclip))
            {
                float xMin=Mathf.Max(raw.xMin,oclip.xMin);
                float xMax=Mathf.Min(raw.xMax,oclip.xMax);
                float yMin=Mathf.Max(raw.yMin,oclip.yMin);
                float yMax=Mathf.Min(raw.yMax,oclip.yMax);
                if(xMax<=xMin||yMax<=yMin)return false;
                raw=new Rect(xMin,yMin,xMax-xMin,yMax-yMin);
            }
            rect=raw;
            return true;
        }

        private static bool TryGetFfaHeaderHoverRect(FfaRecentMatchRow row,out Rect rect)
        {
            rect=default(Rect);
            if(row==null||row.graph==null)return false;
            return TryGetFfaViewportClippedRect(row.headerRect,row.ownerViewport??ffaRecentViewport,out rect);
        }

        private static void EnsureFfaGraphStyles()
        {
            if(ffaGraphTitleStyle!=null)return;
            ffaGraphTitleStyle=new GUIStyle(GUI.skin.label)
            {
                fontSize=15,fontStyle=FontStyle.Bold,alignment=TextAnchor.MiddleLeft,
                clipping=TextClipping.Overflow
            };
            ffaGraphTitleStyle.normal.textColor=Color.white;
            ffaGraphLegendStyle=new GUIStyle(GUI.skin.label)
            {
                fontSize=12,fontStyle=FontStyle.Bold,alignment=TextAnchor.MiddleLeft,
                clipping=TextClipping.Overflow
            };
            ffaGraphLegendStyle.normal.textColor=Color.white;
            ffaGraphAxisStyle=new GUIStyle(GUI.skin.label)
            {
                fontSize=11,fontStyle=FontStyle.Bold,alignment=TextAnchor.MiddleLeft,
                clipping=TextClipping.Overflow
            };
            ffaGraphAxisStyle.normal.textColor=new Color(0.65f,0.68f,0.74f);
        }

        private static void DrawFfaGraphSegment(Vector2 start,Vector2 end,Color color,float thickness)
        {
            float dx=end.x-start.x,dy=end.y-start.y;
            float length=Mathf.Sqrt(dx*dx+dy*dy);
            if(length<0.1f)return;
            Matrix4x4 previous=GUI.matrix;
            Color previousColor=GUI.color;
            GUI.color=color;
            GUIUtility.RotateAroundPivot(Mathf.Atan2(dy,dx)*Mathf.Rad2Deg,start);
            GUI.DrawTexture(new Rect(start.x,start.y-thickness*0.5f,length,thickness),Texture2D.whiteTexture);
            GUI.matrix=previous;
            GUI.color=previousColor;
        }

        private static void DrawFfaTimelineGraph(FfaTimelineGraph graph,Vector2 mouse)
        {
            if(graph==null||graph.eventCount<=0||graph.values==null)return;
            EnsureFfaGraphStyles();
            int legendRows=(graph.names.Length+1)/2;
            float width=470f,height=218f+legendRows*18f;
            float x=mouse.x+18f,y=mouse.y+18f;
            if(x+width>Screen.width-6f)x=mouse.x-width-18f;
            if(y+height>Screen.height-6f)y=mouse.y-height-18f;
            x=Mathf.Clamp(x,6f,Mathf.Max(6f,Screen.width-width-6f));
            y=Mathf.Clamp(y,6f,Mathf.Max(6f,Screen.height-height-6f));
            var panel=new Rect(x,y,width,height);
            GUI.DrawTexture(panel,Texture2D.whiteTexture,ScaleMode.StretchToFill,true,0,
                new Color(0.025f,0.03f,0.045f,0.97f),0,0);
            GUI.Label(new Rect(x+14f,y+8f,width-28f,24f),graph.title,ffaGraphTitleStyle);

            var plot=new Rect(x+42f,y+38f,width-60f,142f);
            Color grid=new Color(0.35f,0.38f,0.45f,0.42f);
            DrawFfaGraphSegment(new Vector2(plot.x,plot.y),new Vector2(plot.x,plot.yMax),grid,1f);
            DrawFfaGraphSegment(new Vector2(plot.x,plot.yMax),new Vector2(plot.xMax,plot.yMax),grid,1f);
            DrawFfaGraphSegment(new Vector2(plot.x,plot.y+plot.height*0.5f),new Vector2(plot.xMax,plot.y+plot.height*0.5f),grid,1f);
            GUI.Label(new Rect(x+8f,plot.y-8f,32f,22f),graph.maxLabel,ffaGraphAxisStyle);
            GUI.Label(new Rect(x+22f,plot.yMax-12f,18f,22f),"0",ffaGraphAxisStyle);
            GUI.Label(new Rect(plot.x,plot.yMax+3f,plot.width,20f),graph.eventLabel,ffaGraphAxisStyle);

            float xStep=graph.eventCount>0?plot.width/graph.eventCount:plot.width;
            for(int line=0;line<graph.values.Length;line++)
            {
                float[] values=graph.values[line];
                if(values==null)continue;
                Color color=graph.colors[line];
                for(int e=0;e<graph.eventCount;e++)
                {
                    float v1=values[e],v2=values[e+1];
                    Vector2 p1=new Vector2(plot.x+e*xStep,plot.yMax-v1/graph.maxScore*plot.height);
                    Vector2 p2=new Vector2(plot.x+(e+1)*xStep,plot.yMax-v2/graph.maxScore*plot.height);
                    DrawFfaGraphSegment(p1,p2,color,2f);
                }
            }

            float legendY=plot.yMax+28f;
            float legendW=(width-28f)*0.5f;
            for(int i=0;i<graph.names.Length;i++)
            {
                int col=i&1,row=i/2;
                float lx=x+14f+col*legendW;
                float ly=legendY+row*18f;
                GUI.DrawTexture(new Rect(lx,ly+7f,20f,3f),Texture2D.whiteTexture,
                    ScaleMode.StretchToFill,true,0,graph.colors[i],0,0);
                GUI.Label(new Rect(lx+26f,ly,legendW-30f,19f),graph.names[i],ffaGraphLegendStyle);
            }
        }

        private static void DrawFfaRecentHoverGraph()
        {
            try
            {
                if(Event.current==null||Event.current.type!=EventType.Repaint)return;
                if(!isOpen||currentTab!=12)return;
                Vector2 mouse=Event.current.mousePosition;
                // Cards-line tooltips first (a cards line is more specific
                // than its row's header; the rects never overlap). Both row
                // pools (ranked + casual, item 6) are scanned; each row clips
                // against its OWN list viewport.
                string cardsTip=null;
                FfaTimelineGraph hit=null;
                void ScanPool(List<FfaRecentMatchRow> pool)
                {
                    for(int i=0;i<pool.Count&&cardsTip==null;i++)
                    {
                        var row=pool[i];
                        if(row?.root==null||!row.root.activeInHierarchy)continue;
                        for(int p=0;p<row.players.Count;p++)
                        {
                            var pu=row.players[p];
                            if(pu?.cardsGO==null||!pu.cardsGO.activeInHierarchy)continue;
                            if(string.IsNullOrEmpty(pu.cardsHoverText))continue;
                            var cardsRt=pu.cardsGO.GetComponent<RectTransform>();
                            if(cardsRt==null)continue;
                            if(TryGetFfaViewportClippedRect(cardsRt,row.ownerViewport??ffaRecentViewport,out Rect cr)&&cr.Contains(mouse))
                            {
                                cardsTip=pu.cardsHoverText;
                                break;
                            }
                        }
                        if(cardsTip==null&&hit==null
                           &&TryGetFfaHeaderHoverRect(row,out Rect hover)&&hover.Contains(mouse))
                            hit=row.graph;
                    }
                }
                ScanPool(ffaRecentRows);
                if(cardsTip==null&&hit==null)ScanPool(ffaRecentCasRows);
                if(cardsTip==null&&hit==null)return;
                int previousDepth=GUI.depth;
                try
                {
                    GUI.depth=-20000;
                    if(cardsTip!=null)DrawFfaCardsTooltip(cardsTip,mouse);
                    else DrawFfaTimelineGraph(hit,mouse);
                }
                finally{GUI.depth=previousDepth;}
            }
            catch{}
        }

        private static GUIStyle ffaCardsTipStyle;
        private static string ffaCardsTipCachedText;
        private static float ffaCardsTipCachedHeight;
        private static string ffaCardsTipCachedDrawn;
        private static int ffaCardsTipCachedScreenH;
        private static void DrawFfaCardsTooltip(string tip,Vector2 mouse)
            => DrawWideTooltip(tip,mouse,470f);

        /// <summary>The FFA-style measured tooltip, shared with the 1v2 recent
        /// panel. Fixed width, height MEASURED with CalcHeight rather than
        /// modelled from a line count (#237: a wrapped or localised line breaks
        /// any row model), memoised on (content, screen height) so the
        /// per-Repaint cost is one reference compare and one int compare
        /// (#162).
        ///
        /// A body taller than the screen is ELIDED from the end with a visible
        /// "+N more lines" marker rather than drawn off the bottom. The old
        /// version clamped the box's Y to >= 8 and stopped there, which keeps
        /// the TOP on screen and silently loses the tail — the exact shape
        /// #351/#245 warn about, and reachable here because a 1v2 series can
        /// carry three games x three players of build lines.</summary>
        private static void DrawWideTooltip(string tip,Vector2 mouse,float width)
        {
            if(string.IsNullOrEmpty(tip))return;
            if(ffaCardsTipStyle==null)
            {
                ffaCardsTipStyle=new GUIStyle(GUI.skin.label)
                {
                    fontSize=13,fontStyle=FontStyle.Bold,alignment=TextAnchor.UpperLeft,
                    richText=true,wordWrap=true,clipping=TextClipping.Overflow
                };
                ffaCardsTipStyle.normal.textColor=Color.white;
            }
            const float pad=10f;
            float maxH=Mathf.Max(80f,Screen.height-16f-pad*2f);
            // Only one tooltip can be hovered at a time, so a single slot
            // suffices. Screen height is part of the key because it bounds the
            // elision — a window resize must re-measure.
            if(!ReferenceEquals(tip,ffaCardsTipCachedText)||ffaCardsTipCachedScreenH!=Screen.height)
            {
                ffaCardsTipCachedText=tip;
                ffaCardsTipCachedScreenH=Screen.height;
                ffaCardsTipCachedDrawn=tip;
                ffaCardsTipCachedHeight=ffaCardsTipStyle.CalcHeight(new GUIContent(tip),width-pad*2f);
                if(ffaCardsTipCachedHeight>maxH)
                {
                    // Bounded shrink: drop trailing lines until it fits, then
                    // say how many went. Halving the search would be faster and
                    // is not worth it — this runs once per hovered row, and the
                    // marker line must be measured WITH the body it labels.
                    var all=tip.Split('\n');
                    var lines=new List<string>(all);
                    while(lines.Count>1&&ffaCardsTipCachedHeight>maxH)
                    {
                        int drop=Mathf.Max(1,lines.Count/12);
                        int cut=Mathf.Min(drop,lines.Count-1);
                        lines.RemoveRange(lines.Count-cut,cut);
                        int hidden=all.Length-lines.Count;
                        ffaCardsTipCachedDrawn=string.Join("\n",lines.ToArray())
                            +"\n<color=#8FA3B8>"+I18n.TrF("+{0} more lines",hidden)+"</color>";
                        ffaCardsTipCachedHeight=ffaCardsTipStyle.CalcHeight(
                            new GUIContent(ffaCardsTipCachedDrawn),width-pad*2f);
                    }
                }
            }
            string drawn=ffaCardsTipCachedDrawn??tip;
            float h=ffaCardsTipCachedHeight+pad*2f;
            // Clamp BOTH edges: the Min alone would place a tall box at
            // negative Y (Codex Jul-29 find 9). With the elision above the box
            // now also FITS, so the clamp is no longer load-bearing for
            // legibility — it is the belt to the elision's braces.
            float x=Mathf.Max(8f,Mathf.Min(mouse.x+18f,Screen.width-width-8f));
            float y=Mathf.Max(8f,Mathf.Min(mouse.y+14f,Screen.height-h-8f));
            var box=new Rect(x,y,width,h);
            var prev=GUI.color;
            GUI.color=new Color(0.07f,0.08f,0.10f,0.96f);
            GUI.DrawTexture(box,Texture2D.whiteTexture);
            GUI.color=prev;
            GUI.Label(new Rect(box.x+pad,box.y+pad,width-pad*2f,ffaCardsTipCachedHeight),drawn,ffaCardsTipStyle);
        }

        // 2s queue traffic rides the internal throttles; recent + bets 10s,
        // board 30s.
        private static float ffaLbRefreshAt, ffaRecentRefreshAt, ffaBetRefreshAt;
        private static void MaybeRefreshFfaTab()
        {
            if(currentTab!=12)return;
            // Aug 12 item 2c: podium glitter on the FFA board (0.7s internal tick).
            TickPodiumSparkle();
            // One-shot membership discovery on first tab visit (design review
            // find 6): a relaunched client whose server row survived must
            // find it before offering Create.
            ApiClient.FfaProbeServerState();
            ApiClient.UpdateFfaQueuePoll(false);   // internally 2s-throttled; no-op when not polling
            ApiClient.FetchFfaLobbies(false);      // internally 3s-throttled (browser panel)
            if(Time.unscaledTime>=ffaRecentRefreshAt)
            {
                ffaRecentRefreshAt=Time.unscaledTime+10f;
                ApiClient.FetchFfaRecent(ffaRecentPageReq,5);
                ApiClient.FetchFfaRecent(ffaRecentCasPageReq,5,false);
            }
            if(Time.unscaledTime>=ffaBetRefreshAt)
            {
                ffaBetRefreshAt=Time.unscaledTime+10f;
                ApiClient.FetchFfaBettable(MatchTracker.LocalSteamId);
                // Aug 7 item 13: WATCH on live FFA lobbies (10s global throttle inside).
                ApiClient.MaybeFetchSpectateGames();
            }
            if(Time.unscaledTime>=ffaLbRefreshAt)
            {
                ffaLbRefreshAt=Time.unscaledTime+30f;
                ApiClient.FetchFfaLeaderboard(200,ffaLbSortReq);
            }
            // 1s dirty ticker while the settings-lock countdown is live, or
            // the "Start in Ns" label freezes between polls (#62's class).
            if(ApiClient.FfaLobbyLockRemaining>0f&&Time.unscaledTime>=ffaCfgTickAt)
            {
                ffaCfgTickAt=Time.unscaledTime+1f;
                dirty=true;
            }
        }

        /// <summary>Item 7: widen/narrow the FFA Start button to whatever label it
        /// is currently showing. The three labels differ by ~35 characters
        /// ("Start Game (5/10)" vs uk's 51-char "Start unlocks in 60s (settings
        /// changed)"), so no single constant can serve both without either
        /// clipping the countdown or leaving a comically wide button at rest.
        ///
        /// Measurement, not a character budget: TMP is asked for the width of the
        /// exact string it will lay out — same font, same size, same rich-text
        /// parsing, and (crucially) the same OS-fallback atlas for Cyrillic, whose
        /// advances differ from Gravity's (#110/#297). A character estimate is the
        /// fallback ONLY if the reflection target is missing, and it is deliberately
        /// pessimistic (10 px/char at 16 pt) so the fallback errs wide.
        ///
        /// Safe by construction on both sides: the row's children in this state are
        /// Start + Leave = ~320 px inside ~1824 px, so growth is free (learning
        /// #245's budget check), and the cap stops a bad translation from pushing
        /// Leave off-row.</summary>
        private static void SizeFfaStartButton(object startTxt,string label)
        {
            if(ffaStartBtn==null)return;
            // SetText/SetTextRaw wrap in <b>, and rich text is on, so measure the
            // wrapped form — the tags are parsed, not measured, but the bold face
            // they select is wider than the regular one.
            float w=UIFactory.MeasureTextWidth(startTxt,"<b>"+label+"</b>");
            if(w<=0f)w=(label??"").Length*10f;
            UIFactory.SetPrefW(ffaStartBtn,Mathf.Clamp(w+24f,FFA_START_BTN_W,FFA_START_BTN_MAX));
        }

        private static void RefreshFfaTab()
        {
            bool polling=ApiClient.IsFfaQueuePolling;
            string st=ApiClient.FfaQueueStatus;
            bool inLobby=!string.IsNullOrEmpty(ApiClient.OpenFfaLobbyId);
            // Locked = a lock landed even though polling stopped: Create stays
            // hidden, Leave stays visible (only escape from a husk lock).
            // Inside an actual ffa_ room everything hides (mirrors 1v2).
            bool ffaLocked=Plugin.PendingFfaSlot>=0;
            bool inFfaRoom=false;
            try{inFfaRoom=PhotonNetwork.InRoom&&(PhotonNetwork.CurrentRoom?.Name??"").StartsWith("ffa_");}catch{}
            if(ffaJoinBtn!=null)ffaJoinBtn.SetActive(!polling&&!ffaLocked&&!inFfaRoom&&!inLobby&&st!="leaving");
            if(ffaCreatePrivBtn!=null)ffaCreatePrivBtn.SetActive(!polling&&!ffaLocked&&!inFfaRoom&&!inLobby&&st!="leaving");
            if(ffaStartBtn!=null)
            {
                bool showStart=inLobby&&ApiClient.FfaLobbyIsHost&&!ffaLocked&&!inFfaRoom&&st!="leaving";
                ffaStartBtn.SetActive(showStart);
                if(showStart)
                {
                    float lockS=ApiClient.FfaLobbyLockRemaining;
                    // Bug 163: "Start in {0}s" read as an AUTO-start countdown; it
                    // is actually the settings-change lockout re-arming the 60s
                    // start gate. Name the mechanism so hosts don't panic-wait.
                    string startLbl=
                        lockS>0.5f?I18n.TrF("Start unlocks in {0}s (settings changed)",Mathf.CeilToInt(lockS))
                        :ApiClient.FfaLobbyCanStart
                        ?I18n.TrF("Start Game ({0}/{1})",ApiClient.FfaLobbyMemberCount,ApiClient.FfaLobbyMaxPlayers)
                        :I18n.TrF("Start (need {0}+)",ApiClient.FfaLobbyMinPlayers);
                    object startTxt=ffaStartBtnTxt??UIFactory.GetButtonText(ffaStartBtn);
                    // Raw: the three branches are already translated by TrF, and
                    // a formatted string can never match a catalogue key anyway.
                    UIFactory.SetTextRaw(startTxt,startLbl);
                    SizeFfaStartButton(startTxt,startLbl);
                }
            }
            // v1.36 settings row: values for everyone, controls host-only.
            // The server check is the real gate (§7b) — this is decoration.
            if(ffaSettingsRow!=null)
            {
                bool showCfg=inLobby&&!ffaLocked&&!inFfaRoom&&st!="leaving";
                ffaSettingsRow.SetActive(showCfg);
                if(showCfg)
                {
                    UIFactory.SetText(txtFfaCfgTarget,ApiClient.FfaLobbyCfgTarget.ToString());
                    UIFactory.SetText(txtFfaCfgCand,ApiClient.FfaLobbyCfgCand.ToString());
                    UIFactory.SetText(txtFfaCfgPicks,ApiClient.FfaLobbyCfgPicks.ToString());
                    UIFactory.SetText(txtFfaCfgCap,ApiClient.FfaLobbyCfgCap.ToString());
                    UIFactory.SetText(UIFactory.GetButtonText(ffaCfgSameBtn),
                        ApiClient.FfaLobbyCfgSame?"Same cards: ON":"Same cards: OFF");
                    UIFactory.SetText(UIFactory.GetButtonText(ffaCfgRankedBtn),
                        ApiClient.FfaLobbyCfgRanked?"Ranked":"Casual");
                    bool host=ApiClient.FfaLobbyIsHost;
                    foreach(var b in ffaCfgHostBtns)if(b!=null)b.SetActive(host);
                }
            }
            if(ffaLeaveBtn!=null)ffaLeaveBtn.SetActive((polling||ffaLocked||inLobby)&&!inFfaRoom);
            if(txtFfaStatus!=null)
            {
                string msg;
                if(inFfaRoom)msg=I18n.Tr("<color=#66DD66>In FFA match.</color>");
                else if(st=="leaving")msg=I18n.Tr("<color=#888>Leaving...</color>");
                else if(st=="ready_join"||ffaLocked)
                {
                    int slot=Plugin.PendingFfaSlot>=0?Plugin.PendingFfaSlot:ApiClient.FfaMySlot;
                    int cnt=Math.Max(ApiClient.FfaLobbyPlayerCount,slot+1);
                    msg=I18n.TrF("<color=#66DD66>Game starting! Joining as player {0} of {1}...</color>",slot+1,cnt);
                }
                else if(inLobby)
                {
                    if(ApiClient.FfaLobbyIsHost)
                        msg=ApiClient.FfaLobbyCanStart
                            ?I18n.TrF("<color=#66DD66>Your lobby is ready.</color> {0} in - press Start, or wait for more (up to {1}).",ApiClient.FfaLobbyMemberCount,ApiClient.FfaLobbyMaxPlayers)
                            :I18n.TrF("<color=#FFCC44>You are the host.</color> Waiting for players - {0}/{1} needed to start.",ApiClient.FfaLobbyMemberCount,ApiClient.FfaLobbyMinPlayers);
                    else
                    {
                        string hostName=null;
                        try{hostName=ApiClient.FfaLobbyMembers?.Find(m=>m.is_host)?.display_name;}catch{}
                        msg=I18n.TrF("<color=#FFCC44>In {0}'s lobby</color> - waiting for the host to start ({1} in).",FfaSafeRich(Trunc(hostName??I18n.Tr("the host"),16)),ApiClient.FfaLobbyMemberCount);
                    }
                }
                else msg=I18n.Tr("Browse open lobbies below, or create your own.");
                UIFactory.SetTextRaw(txtFfaStatus,msg);
            }
            RenderFfaLobbySection();
            RenderFfaBettingSection();

            // Leaderboard — active-sort header highlight + pooled rows.
            var lb=ApiClient.CachedFfaLeaderboard??new List<ApiClient.FfaLeaderboardEntry>();
            if(ffaLbSortKeys!=null&&ffaLbHeaderTexts!=null&&ffaLbSortBtns!=null)
            {
                // Item 1 fix family: translate the base label, THEN append the
                // arrow, and write via SetTextRaw so the composed string is
                // never re-looked-up (a "Gold v" key can't exist).
                string[] baseLabels=new[]{I18n.Tr("#"),I18n.Tr("Player"),I18n.Tr("Rating"),I18n.Tr("Games"),I18n.Tr("Wins"),I18n.Tr("Top3"),I18n.Tr("AvgPl"),I18n.Tr("WR")};
                for(int hi=0;hi<ffaLbSortKeys.Length&&hi<baseLabels.Length;hi++)
                {
                    bool active=ffaLbSortKeys[hi]!=null&&ffaLbSortKeys[hi]==ffaLbSortReq;
                    UIFactory.SetTextRaw(ffaLbHeaderTexts[hi],active?baseLabels[hi]+" v":baseLabels[hi]);
                    UIFactory.SetColor(ffaLbHeaderTexts[hi],active?C_GOLD:C_LABEL);
                    if(ffaLbSortBtns[hi]!=null)
                        UIFactory.SetImageColor(ffaLbSortBtns[hi],active?new Color(0.38f,0.30f,0.10f,0.98f):new Color(0.18f,0.20f,0.24f,0.85f));
                }
            }
            // Aug 12 item 2c: rebuilt every fill, like the 1v1 board's.
            _podiumFfaRows.Clear();
            for(int i=0;i<ffaLbRows.Count;i++)
            {
                var row=ffaLbRows[i];
                if(i>=lb.Count){row.root.SetActive(false);continue;}
                var e=lb[i];
                bool me=e.steam_id==MatchTracker.LocalSteamId;
                UIFactory.SetText(row.txtRank,$"#{e.rank}");
                UIFactory.SetColor(row.txtRank,
                    e.rank==1?new Color(1f,0.84f,0f):
                    e.rank==2?new Color(0.75f,0.75f,0.75f):
                    e.rank==3?new Color(0.8f,0.5f,0.2f):C_GOLD);
                string nameDisplay=Trunc(e.display_name,14);
                if(!string.IsNullOrEmpty(e.title))
                {
                    string col=string.IsNullOrEmpty(e.title_color)?"#FFD94D":e.title_color;
                    if(IsPodiumTitle(e.title))
                    {
                        // Aug 12 item 2c: animated tick, not frozen at 0; and
                        // the tick entry stores the same de-prefixed text.
                        string ttl=PodiumTitleOnOwnBoard(e.title,"FFA");
                        _podiumFfaRows.Add(new object[]{row.txtName,nameDisplay,ttl,col});
                        nameDisplay=$"{nameDisplay} {PodiumSparkleSpan(ttl,col,_podiumTick)}";
                    }
                    else nameDisplay=$"{nameDisplay} <color={col}>[{Trunc(e.title,12)}]</color>";
                }
                UIFactory.SetTextRaw(row.txtName,nameDisplay);
                UIFactory.SetColor(row.txtName,me?C_GREEN:C_WHITE);
                if(e.rd>0)UIFactory.SetText(row.txtRating,$"{e.rating} <size=72%><color=#9AA0A6>~{e.rd}</color></size>");
                else UIFactory.SetText(row.txtRating,$"{e.rating}");
                UIFactory.SetText(row.txtGames,$"{e.games_played}");
                UIFactory.SetText(row.txtWins,$"{e.wins}");
                UIFactory.SetText(row.txtTop3,$"{e.top3}");
                UIFactory.SetText(row.txtAvgPl,e.avg_placement>0f?$"{e.avg_placement:F1}":"-");
                UIFactory.SetText(row.txtWR,$"{e.win_rate*100f:F0}%");
                // Aug 12 item 2c: podium tint + readability outline.
                UIFactory.SetImageColor(row.root,PodiumRowTint(e.rank));
                SetFfaLbRowOutline(row,e.rank<=3);
                row.root.SetActive(true);
            }
            if(txtFfaLbHeader!=null)
                UIFactory.SetTextRaw(txtFfaLbHeader,lb.Count==0
                    ?I18n.Tr("<b>FFA Leaderboard</b>  <color=#888>- no ranked FFAs yet</color>")
                    :I18n.TrF("<b>FFA Leaderboard</b>  <color=#888>({0} ranked)</color>",lb.Count));
            // 30f -> 23f: this estimate is (CreateFfaLBRow's prefH) + (the LB
            // ScrollView's spacing of 1), and item 15 took the row 29 -> 22. Left
            // stale it would over-report content height and keep the inner
            // ScrollRect enabled on a list that fits, stealing the wheel from the
            // outer tab scroll (bug #76's mechanism).
            ToggleInnerScroll(ffaLbScrollRect,Math.Min(lb.Count,ffaLbRows.Count)*23f);

            // F2: the recent rows below RE-REGISTER their Hit/Block/FPS/ping
            // hover regions on every dirty refresh, and the region lists were
            // only cleared on tab CHANGE — an open FFA tab accumulated
            // thousands of entries (and stale page-1 regions kept firing
            // after paging). Clear once before BOTH pools re-register,
            // mirroring RefreshHistory (tab 0) / RefreshTeamTab (tab 8).
            // RefreshFfaTab only runs while currentTab==12, so this can't
            // wipe another tab's live regions.
            CompetitiveUI.ClearCardHoverRegions();
            // Recent ranked FFAs: one pooled container per match, with pooled
            // player rows and procedural score-dot Images.
            if(ffaRecentContainer!=null)
            {
                var rec=ApiClient.CachedFfaRecent??new List<ApiClient.FfaRecentMatch>();
                while(ffaRecentRows.Count<Math.Min(rec.Count,10))
                    ffaRecentRows.Add(CreateFfaRecentMatchRow(ffaRecentContainer.transform,$"FfaRR{ffaRecentRows.Count}",ffaRecentViewport));
                float recTotalH=0f;
                for(int i=0;i<ffaRecentRows.Count;i++)
                {
                    var row=ffaRecentRows[i];
                    if(i>=rec.Count){row.root.SetActive(false);continue;}
                    BuildFfaRecentRowText(rec[i],row);
                    recTotalH+=EstimateFfaRecentHeight(rec[i])+2f;
                }
                ToggleInnerScroll(ffaRecentScrollRect,recTotalH);
                if(txtFfaRecentHeader!=null)
                    UIFactory.SetTextRaw(txtFfaRecentHeader,ApiClient.CachedFfaRecentTotal==0
                        ?I18n.Tr("<b>Recent Ranked FFAs</b>  <color=#888>- none yet</color>")
                        :I18n.TrF("<b>Recent Ranked FFAs</b>  <color=#888>({0} total)</color>",ApiClient.CachedFfaRecentTotal));
                int pages=Math.Max(1,ApiClient.CachedFfaRecentPages);
                if(txtFfaRecentPage!=null)UIFactory.SetText(txtFfaRecentPage,$"{ffaRecentPageReq+1}/{pages}");
                if(ffaRecentPrevBtn!=null)ffaRecentPrevBtn.SetActive(ffaRecentPageReq>0);
                if(ffaRecentNextBtn!=null)ffaRecentNextBtn.SetActive(ffaRecentPageReq+1<pages);
            }

            // Recent CASUAL FFAs (item 6): identical render against the
            // separate casual caches.
            if(ffaRecentCasContainer!=null)
            {
                var rec=ApiClient.CachedFfaRecentCasual??new List<ApiClient.FfaRecentMatch>();
                while(ffaRecentCasRows.Count<Math.Min(rec.Count,10))
                    ffaRecentCasRows.Add(CreateFfaRecentMatchRow(ffaRecentCasContainer.transform,$"FfaCR{ffaRecentCasRows.Count}",ffaRecentCasViewport));
                float recTotalH=0f;
                for(int i=0;i<ffaRecentCasRows.Count;i++)
                {
                    var row=ffaRecentCasRows[i];
                    if(i>=rec.Count){row.root.SetActive(false);continue;}
                    BuildFfaRecentRowText(rec[i],row);
                    recTotalH+=EstimateFfaRecentHeight(rec[i])+2f;
                }
                ToggleInnerScroll(ffaRecentCasScrollRect,recTotalH);
                if(txtFfaRecentCasHeader!=null)
                    UIFactory.SetTextRaw(txtFfaRecentCasHeader,ApiClient.CachedFfaRecentCasualTotal==0
                        ?I18n.Tr("<b>Recent Casual FFAs</b>  <color=#888>- none yet</color>")
                        :I18n.TrF("<b>Recent Casual FFAs</b>  <color=#888>({0} total)</color>",ApiClient.CachedFfaRecentCasualTotal));
                int pages=Math.Max(1,ApiClient.CachedFfaRecentCasualPages);
                if(txtFfaRecentCasPage!=null)UIFactory.SetText(txtFfaRecentCasPage,$"{ffaRecentCasPageReq+1}/{pages}");
                if(ffaRecentCasPrevBtn!=null)ffaRecentCasPrevBtn.SetActive(ffaRecentCasPageReq>0);
                if(ffaRecentCasNextBtn!=null)ffaRecentCasNextBtn.SetActive(ffaRecentCasPageReq+1<pages);
            }
        }

        private static void RenderFfaBettingSection()
        {
            if(ffaBetPanel==null||ffaBetContainer==null)return;
            var lobbies=ApiClient.CachedFfaBettable;
            bool show=lobbies!=null&&lobbies.Count>0;
            ffaBetPanel.SetActive(show);
            if(!show)
            {
                for(int i=0;i<ffaBetLobbyRows.Count;i++)ffaBetLobbyRows[i].root.SetActive(false);
                return;
            }
            while(ffaBetLobbyRows.Count<lobbies.Count)
                ffaBetLobbyRows.Add(CreateFfaBetLobbyRow(
                    ffaBetContainer.transform,$"FfaBetLobby{ffaBetLobbyRows.Count}"));
            for(int i=0;i<ffaBetLobbyRows.Count;i++)
            {
                var ui=ffaBetLobbyRows[i];
                if(i>=lobbies.Count){ui.root.SetActive(false);continue;}
                var lobby=lobbies[i];
                var players=lobby.players;
                int playerRows=players!=null?players.Count:0;
                int count=lobby.player_count>0?lobby.player_count:playerRows;
                string note=lobby.is_member
                    ?"  "+I18n.Tr("<color=#777>(your lobby)</color>")
                    :lobby.already_bet?"  "+I18n.Tr("<color=#777>(bet placed)</color>"):"";
                UIFactory.SetTextRaw(ui.txtHeader,I18n.TrF("Game {0} - {1} players",lobby.game_number,count)+note);
                // Aug 7 item 13: WATCH — /ffa/bettable's lobby_id IS the
                // spectate feed's ffa source_ref (both are ffa_lobbies.id).
                var specG=FindSpectateGame("ffa",lobby.lobby_id);
                bool canWatch=specG!=null&&!lobby.is_member&&!LocalInSpectateRoster(specG);
                ui.watchGameId=canWatch?specG.game_id:null;
                if(ui.watchBtn!=null)ui.watchBtn.SetActive(canWatch);
                while(ui.players.Count<playerRows)
                    ui.players.Add(CreateFfaBetPlayerRow(ui.root.transform,$"Player{ui.players.Count}"));
                for(int p=0;p<ui.players.Count;p++)
                {
                    var playerUi=ui.players[p];
                    if(p>=playerRows){playerUi.root.SetActive(false);continue;}
                    var player=players[p];
                    playerUi.lobbyId=lobby.lobby_id;
                    playerUi.steamId=player.steam_id;
                    playerUi.displayName=player.display_name??"Player";
                    playerUi.gameNumber=lobby.game_number;
                    UIFactory.SetTextRaw(playerUi.txtName,FfaSafeRich(Trunc(playerUi.displayName,28)));
                    UIFactory.SetText(playerUi.txtRating,$"{player.rating}");
                    UIFactory.SetText(playerUi.txtOdds,"x"+player.odds_multiplier.ToString(
                        "0.00",System.Globalization.CultureInfo.InvariantCulture));
                    UIFactory.SetColor(playerUi.txtOdds,player.bettable?C_GOLD:C_DIM);
                    playerUi.betBtn.SetActive(player.bettable&&!lobby.is_member&&!lobby.already_bet);
                    playerUi.root.SetActive(true);
                }
                SetFfaBetLobbyHeight(ui,playerRows);
                ui.root.SetActive(true);
            }
        }

        private static FfaBrowserRow CreateFfaBrowserRow(Transform parent,string name)
        {
            var row=new FfaBrowserRow();
            row.root=new GameObject(name);
            row.root.transform.SetParent(parent,false);
            row.root.AddComponent<RectTransform>();
            UIFactory.AddHLG(row.root,spacing:8,padL:6,padR:6,forceExpandH:false);
            /* minH ONLY, deliberately no prefH. The row height is now DERIVED
             * from content: the member summary sizes itself (below), the info
             * column sums to it, and the HLG reports that upward. A prefH here
             * would be a LayoutElement value at priority 1 and would override
             * the group-derived height, pinning every row to one size again.
             * AddLE only writes values >= 0, so preferredHeight stays at
             * LayoutElement's -1 default and LayoutUtility skips it; minH
             * remains a pure floor, so an empty pooled row is still 31px. */
            UIFactory.AddLE(row.root,minH:31,flexH:0);
            /* The header and the member summary are SEPARATE elements in a
             * column, not one element holding a "\n"-joined two-line string.
             * The reason is WRAPPING, and wrapping is per-element: the roster
             * must wrap to show a full lobby (~200 visible chars against a
             * ~1612px cell), while the header must NOT wrap or a long one would
             * push the roster out of a fixed box. One element cannot be both,
             * so the old shared cell had to pick -- it picked no-wrap, which is
             * why the roster clipped at the cell edge and lost its trailing
             * "+N more" in exactly the full-lobby case that counter exists for.
             * (Note for anyone reading the history: an earlier draft justified
             * this split by the HEADER wrapping and eating the roster's line.
             * That was wrong -- wrap was already off on the shared cell, so the
             * header could not wrap. The roster's clipping is the real defect.) */
            var infoCol=new GameObject("InfoCol");infoCol.transform.SetParent(row.root.transform,false);
            infoCol.AddComponent<RectTransform>();
            UIFactory.AddVLG(infoCol,spacing:1);
            /* prefW is LOAD-BEARING, not decoration. SetTextAutoHeight below
             * sets preferredWidth to -1, so the member element reports its
             * UNWRAPPED width (~1600px for a full roster) upward, and a layout
             * group derives its own preferred/flexible width from max(children)
             * (#132). This pin, at LayoutElement priority 1, overrides that.
             * flexW:1 + minW:300 reproduce what txtInfo itself used to carry,
             * so the column still stretches exactly as the cell did. */
            UIFactory.AddLE(infoCol,prefW:760,minW:300,flexW:1);
            row.txtInfo=UIFactory.CreateText("Info",infoCol.transform,"",17f,C_WHITE,
                UIFactory.AlignMidLeft,sizeDelta:new Vector2(760,28));
            UIFactory.SetOverflowMode(row.txtInfo,3);
            /* Wrap off: this cell holds ONLY the header now, and it must stay
             * one line so a long header cannot push the roster below it down.
             * The box is 28px at 17pt = 1.65x, deliberately roomier than the
             * 25px it used to carry: 25/17 = 1.47 sits just above the 1.41
             * this same file calls "exactly the #297 edge", and the old
             * shared cell was resized to 48px whenever a roster was present,
             * so the header had slack here that the split takes away.
             * Truncate rather than FitOneLine, because Overflow would let a
             * tall translated header paint over the roster underneath. */
            UIFactory.SetWordWrap(row.txtInfo,false);
            /* The roster element. sizeDelta X of 0 is deliberate: CreateText
             * only bakes a LayoutElement when BOTH dimensions are > 0, so this
             * skips the baked prefH/minH that pinned the old shared cell, and
             * SetTextAutoHeight then installs a clean one with prefH/prefW -1.
             * TMP therefore reports its own WRAPPED height and the row grows to
             * fit the real roster -- one line for most lobbies, more only when
             * the text genuinely needs it. Exactly the shape already shipping on
             * CreateFfaRecentPlayerRow's txtCards. The whole tab is inside
             * FfaScroll, so a taller row is absorbed by the scroll (#199).
             * minH 22 is the anti-collapse floor. TMP can report 0 for one
             * frame before layout has run (#143) and the floor is what it
             * falls back to -- so the floor must fit a real line of the WIDEST
             * metrics this element can receive, not a Latin one. 22 is this
             * file's house value for 13pt (1.69x -- the 48x22 and 90x22 cells);
             * 16 would have been 1.23x and a Cyrillic roster would have been
             * hidden for that frame. */
            row.txtMembers=UIFactory.CreateText("Members",infoCol.transform,"",13f,C_WHITE,
                UIFactory.AlignTopLeft,sizeDelta:new Vector2(0,16));
            UIFactory.SetWordWrap(row.txtMembers,true);
            UIFactory.SetTextAutoHeight(row.txtMembers,22);
            row.membersGO=(row.txtMembers as Component)?.gameObject;
            if(row.membersGO!=null)row.membersGO.SetActive(false);
            row.joinBtn=UIFactory.CreateButton("Join",row.root.transform,"Join",16f,C_WHITE,
                new Color(0.25f,0.42f,0.20f,0.95f),
                ()=>{
                    if(string.IsNullOrEmpty(row.lobbyId))return;
                    // Capture NOW (#265): the pooled row is rebound on refresh,
                    // and the password modal outlives this click.
                    string id=row.lobbyId;
                    if(row.hasPassword)
                        CompetitiveUI.OpenArtistInput(I18n.Tr("Private FFA lobby"),I18n.Tr("Password"),"",
                            pw=>{ApiClient.FfaJoinLobby(id,pw);dirty=true;});
                    else ApiClient.FfaJoinLobby(id);
                    dirty=true;
                },
                sizeDelta:new Vector2(88,26));
            SetFfaLayoutWidth(row.joinBtn,88f,0f,88f);
            row.betBtn=UIFactory.CreateButton("Bet",row.root.transform,"Bet",16f,C_WHITE,
                new Color(0.35f,0.28f,0.10f,0.95f),
                // CreateButton already claims the per-control guard — a Claim
                // in here would be a same-frame no-op (#158).
                ()=>{ClickLobbyBet("ffa",row.lobbyId,row.betTargets,row.betAmount);dirty=true;},
                sizeDelta:new Vector2(76,26));
            SetFfaLayoutWidth(row.betBtn,76f,0f,76f);
            row.betBtn.SetActive(false);
            row.root.SetActive(false);
            return row;
        }

        // Lobby panel body (July 29 redesign). Two modes:
        //   idle      -> browser: open lobbies with Join buttons (pooled rows)
        //   in lobby  -> member list text (from the poll's members payload)
        private static void RenderFfaLobbySection()
        {
            if(txtFfaLobbyHeader==null||txtFfaLobbyBody==null)return;
            bool inLobby=!string.IsNullOrEmpty(ApiClient.OpenFfaLobbyId);
            int newH;
            if(inLobby)
            {
                for(int i=0;i<ffaBrowserRows.Count;i++)ffaBrowserRows[i].root.SetActive(false);
                // Aug 8 (Sid): pooled member ROWS with a host-only [Kick]
                // beside every member but the host themselves.
                int n=FillLobbyMemberRows(ffaLobbyMemberRows,ffaBrowserContainer.transform,"FfaMem",
                    17f,t=>ApiClient.FfaKickFromLobby(t),ApiClient.FfaLobbyMembers,ApiClient.FfaLobbyIsHost,
                    m=>m.steam_id,
                    m=>{
                        bool isMe=m.steam_id==MatchTracker.LocalSteamId;
                        string nameC=isMe?"<color=#88FF88>":"<color=#FFFFFF>";
                        string ratingDisplay=m.rating>0
                            ?$"<color=#FFFFFF>FFA {m.rating}</color>"
                            :$"<color=#DDDDDD>1v1 {m.rating_1v1}</color>";
                        string hostTag=m.is_host?"  <color=#FFD94D>"+I18n.Tr("HOST")+"</color>":"";
                        int waitMin=m.wait_seconds/60,waitSec=m.wait_seconds%60;
                        string waitStr=waitMin>0?$"{waitMin}m{waitSec:D2}s":$"{waitSec}s";
                        return $"{nameC}{FfaSafeRich(Trunc(m.display_name,18))}</color>  {ratingDisplay}{hostTag}  <color=#888>{waitStr}</color>";
                    });
                UIFactory.SetText(txtFfaLobbyHeader,
                    I18n.TrF("<b>Your Lobby</b>  <color=#888>({0}/{1} - host starts at {2}+)</color>",Math.Max(n,ApiClient.FfaLobbyMemberCount),ApiClient.FfaLobbyMaxPlayers,ApiClient.FfaLobbyMinPlayers));
                if(n==0)
                {
                    UIFactory.SetText(txtFfaLobbyBody,"<color=#888>Loading members...</color>");
                    newH=29;
                }
                else
                {
                    UIFactory.SetText(txtFfaLobbyBody,"");
                    newH=2;
                }
            }
            else
            {
                for(int i=0;i<ffaLobbyMemberRows.Count;i++)
                { ffaLobbyMemberRows[i].targetSteamId=null; ffaLobbyMemberRows[i].root.SetActive(false); }
                var lobbies=ApiClient.CachedFfaLobbies;
                int n=lobbies?.Count??0;
                UIFactory.SetText(txtFfaLobbyHeader,n==0
                    ?I18n.Tr("<b>Open FFA Lobbies</b>  <color=#888>(none right now)</color>")
                    :I18n.TrF("<b>Open FFA Lobbies</b>  <color=#888>({0})</color>",n));
                while(ffaBrowserRows.Count<Math.Min(n,20))
                    ffaBrowserRows.Add(CreateFfaBrowserRow(ffaBrowserContainer.transform,$"FfaBrow{ffaBrowserRows.Count}"));
                for(int i=0;i<ffaBrowserRows.Count;i++)
                {
                    var row=ffaBrowserRows[i];
                    if(lobbies==null||i>=lobbies.Count)
                    { row.betTargets=null; row.betAmount=0; row.root.SetActive(false); continue; }
                    var l=lobbies[i];
                    row.lobbyId=l.lobby_id;
                    row.hasPassword=l.has_password;
                    int ageMin=l.age_seconds/60;
                    string age=ageMin>0?$"{ageMin}m":$"{l.age_seconds}s";
                    /* ASCII marker only — Gravity has no padlock glyph (#47).
                     * Compose-after-Tr, written Raw (#298c). */
                    string privTag=l.has_password?I18n.Tr("<color=#FFD94D>[PRIVATE]</color>")+"  ":"";
                    // Aug 8 (Sid): second line = WHO is inside ("(1v1)" suffix
                    // when the FFA glicko isn't established yet).
                    string memberLine=BuildLobbyMemberLine(l.members,showUnestablished:true);
                    // Aug 9: lobby-phase bet state. FFA backs ONE player, so a
                    // single target is enough to offer the button.
                    bool canBet=LobbyBetAvailable(l.bets_open,l.bet_targets,1);
                    var belief=LobbyBetBeliefFor("ffa",l.lobby_id);
                    row.betTargets=l.bet_targets;
                    row.betAmount=l.my_bet_amount>0?l.my_bet_amount:(belief!=null?belief.amount:0);
                    string betTag="";
                    if(row.betAmount>0)
                    {
                        string lbl=l.my_bet_amount>0
                            ?LobbyBetTargetLabel(l.bet_targets,l.my_bet_targets)
                            :(belief!=null?belief.label:"");
                        betTag="  "+I18n.TrF("<color=#FFD94D>your bet: {0}g on {1}</color>",row.betAmount,lbl);
                    }
                    else if(canBet)betTag="  "+I18n.Tr("<color=#FFD94D>bets open</color>");
                    UIFactory.SetTextRaw(row.txtInfo,
                        privTag+I18n.TrF("<color=#FFFFFF>{0}'s lobby</color>  <color=#7FD4FF>{1}/{2}</color>  <color=#888>open {3}</color>",
                            FfaSafeRich(Trunc(l.host_name,18)),l.player_count,l.max_players,age)
                        +betTag);
                    /* The roster goes to its OWN element now, so the header can
                     * never crowd it out. Written unconditionally on BOTH
                     * branches because these rows are pooled: a row that showed
                     * a roster last refresh must hide it when rebound to a lobby
                     * with none. Deactivating removes it from layout entirely
                     * (a layout group skips inactive children), so a memberless
                     * row collapses back to the 31px floor. No heights are set
                     * per fill any more -- content drives them. */
                    SetLobbyRosterText(row.txtMembers,row.membersGO,memberLine);
                    bool joinable=l.player_count<l.max_players
                        &&ApiClient.FfaQueueStatus!="leaving";
                    row.joinBtn.SetActive(joinable);
                    // Review find 2: an OPEN wager stays cancellable even if
                    // the lobby stops being bettable (dropped below two
                    // members, flipped casual) — otherwise the stake is
                    // stranded until the janitor.
                    bool showBetBtn=canBet||row.betAmount>0;
                    row.betBtn.SetActive(showBetBtn);
                    if(showBetBtn)
                        UIFactory.SetTextRaw(UIFactory.GetButtonText(row.betBtn),
                            row.betAmount>0?I18n.Tr("Cancel"):I18n.Tr("Bet"));
                    row.root.SetActive(true);
                }
                UIFactory.SetText(txtFfaLobbyBody,n==0
                    ?(ApiClient.FfaLobbiesUnavailable
                        ?"<color=#FFAA55>Lobby browser unavailable right now — the server may be updating.</color>"
                        :lobbies==null?$"<color=#888>{I18n.Tr("Loading...")}</color>"
                                      :"<color=#888>No open lobbies — create one and invite players on Discord!</color>")
                    :"");
                // Item 15: 29 -> 24, in lockstep with the build-time height of
                // txtFfaLobbyBody in BuildFfaTab (this write wins otherwise).
                newH=n==0?24:2;
            }
            var bodyComp=txtFfaLobbyBody as Component;
            if(bodyComp!=null)
            {
                var le=bodyComp.gameObject.GetComponent(UIFactory.tLE);
                if(le!=null)
                {
                    UIFactory.tLE.GetProperty("preferredHeight",BindingFlags.Public|BindingFlags.Instance)?.SetValue(le,(float)newH);
                    UIFactory.tLE.GetProperty("minHeight",BindingFlags.Public|BindingFlags.Instance)?.SetValue(le,(float)newH);
                }
                var rt=bodyComp.GetComponent<RectTransform>();
                if(rt!=null)rt.sizeDelta=new Vector2(rt.sizeDelta.x,newH);
            }
        }

        // ── Shared host-lobby panel machinery (v1.37 private lobbies) ──────
        private static LobbyMemberRow CreateLobbyMemberRow(Transform parent,string name,float fontSize,Action<string> kick)
        {
            var row=new LobbyMemberRow();
            row.root=new GameObject(name);
            row.root.transform.SetParent(parent,false);
            row.root.AddComponent<RectTransform>();
            UIFactory.AddHLG(row.root,spacing:8,padL:6,padR:6,forceExpandH:false);
            UIFactory.AddLE(row.root,prefH:27,minH:27,flexH:0);
            row.txt=CreateFfaTextCell("M",row.root.transform,700,UIFactory.AlignMidLeft,fontSize,C_WHITE,true,300);
            UIFactory.SetOverflowMode(row.txt,3);
            row.kickBtn=UIFactory.CreateButton("Kick",row.root.transform,"Kick",13f,C_WHITE,
                new Color(0.5f,0.2f,0.2f,0.9f),
                ()=>{if(!string.IsNullOrEmpty(row.targetSteamId))kick(row.targetSteamId);dirty=true;},
                sizeDelta:new Vector2(64,22));
            SetFfaLayoutWidth(row.kickBtn,64f,0f,64f);
            row.kickBtn.SetActive(false);
            row.root.SetActive(false);
            return row;
        }

        /// <summary>Validate a server-sent hex color before it enters rich
        /// text; returns "#RRGGBB" or null.</summary>
        private static string SafeHexColor(string c)
        {
            if(string.IsNullOrEmpty(c))return null;
            string s=c.StartsWith("#")?c:"#"+c;
            if(s.Length!=7)return null;
            for(int i=1;i<7;i++)
            {
                char ch=s[i];
                if(!((ch>='0'&&ch<='9')||(ch>='a'&&ch<='f')||(ch>='A'&&ch<='F')))return null;
            }
            return s;
        }

        /// <summary>Bind one browser row's roster element. Shared by the FFA
        /// and hosted-lobby browsers so the two can never drift (#330). Writes
        /// on every fill: these rows are pooled, so a row that carried a roster
        /// last refresh must drop it when rebound to a lobby without one. The
        /// empty case only toggles active state -- it deliberately does NOT
        /// clear the text, because an inactive element renders nothing and the
        /// stale string is overwritten before it can ever be shown again.
        /// SetActive(false) takes the element out of layout entirely, which is
        /// what lets the row collapse back to its floor.</summary>
        private static void SetLobbyRosterText(object txt,GameObject go,string line)
        {
            if(go==null)return;
            bool has=!string.IsNullOrEmpty(line);
            if(has)UIFactory.SetTextRaw(txt,line);
            go.SetActive(has);
        }

        /// <summary>Aug 8 (Sid): browser second line — who's inside a lobby
        /// before joining: "Name Title (1234)". Names AND titles are
        /// user-authored -> FfaSafeRich; per-member Trunc; first 5 members +
        /// "+N more" so a 10-player FFA can't snake off the row. Returns null
        /// when the server sent no members array (old server) -> one-line row.</summary>
        private static string BuildLobbyMemberLine(List<ApiClient.LobbyBrowserMember> members,bool showUnestablished)
        {
            if(members==null||members.Count==0)return null;
            var sb=new StringBuilder();
            int shown=0;
            foreach(var m in members)
            {
                if(shown>=5)
                {
                    sb.Append("  ").Append(I18n.TrF("<color=#888>+{0} more</color>",members.Count-shown));
                    break;
                }
                if(shown>0)sb.Append("<color=#555>,</color>  ");
                string nm=FfaSafeRich(Trunc(m.name,12));
                string title="";
                if(!string.IsNullOrEmpty(m.title))
                {
                    string tc=SafeHexColor(m.title_color)??"#9AA6B5";
                    title=$" <color={tc}>{FfaSafeRich(Trunc(m.title,14))}</color>";
                }
                string est=(showUnestablished&&!m.established)?" 1v1":"";
                sb.Append($"<color=#DDD>{nm}</color>{title} <color=#888>({m.rating}{est})</color>");
                shown++;
            }
            return sb.ToString();
        }

        /// <summary>Fill the pooled seated member rows shared by the 2v2/1v2
        /// hosted panels and the FFA in-lobby list. lineFor renders one
        /// member's text; kick buttons show for the HOST beside everyone but
        /// themselves (admin refusal is the server's call — token-mapped).</summary>
        private static int FillLobbyMemberRows<T>(List<LobbyMemberRow> rows,Transform parent,string poolTag,
            float fontSize,Action<string> kick,List<T> members,bool localIsHost,
            Func<T,string> steamIdOf,Func<T,string> lineFor)
        {
            int n=members?.Count??0;
            while(rows.Count<Math.Min(n,12))
                rows.Add(CreateLobbyMemberRow(parent,$"{poolTag}{rows.Count}",fontSize,kick));
            string mySid=MatchTracker.LocalSteamId;
            for(int i=0;i<rows.Count;i++)
            {
                var row=rows[i];
                if(members==null||i>=members.Count)
                {
                    row.targetSteamId=null;
                    row.root.SetActive(false);
                    continue;
                }
                var m=members[i];
                string sid=steamIdOf(m);
                row.targetSteamId=sid;   // #265: bind what this row RENDERS
                UIFactory.SetTextRaw(row.txt,lineFor(m));
                row.kickBtn.SetActive(localIsHost&&!string.IsNullOrEmpty(sid)&&sid!=mySid);
                row.root.SetActive(true);
            }
            return n;
        }

        private static HostLobbyBrowserRow CreateHostLobbyBrowserRow(Transform parent,string name,bool team)
        {
            var row=new HostLobbyBrowserRow();
            row.root=new GameObject(name);
            row.root.transform.SetParent(parent,false);
            row.root.AddComponent<RectTransform>();
            UIFactory.AddHLG(row.root,spacing:8,padL:6,padR:6,forceExpandH:false);
            /* minH only, no prefH -- see CreateFfaBrowserRow for the full
             * reasoning; the row height is derived from the info column. */
            UIFactory.AddLE(row.root,minH:29,flexH:0);
            var infoCol=new GameObject("InfoCol");infoCol.transform.SetParent(row.root.transform,false);
            infoCol.AddComponent<RectTransform>();
            UIFactory.AddVLG(infoCol,spacing:1);
            UIFactory.AddLE(infoCol,prefW:700,minW:300,flexW:1);
            row.txtInfo=UIFactory.CreateText("Info",infoCol.transform,"",15f,C_WHITE,
                UIFactory.AlignMidLeft,sizeDelta:new Vector2(700,25));
            UIFactory.SetOverflowMode(row.txtInfo,3);
            /* Wrap off: this cell holds ONLY the header now and must stay one
             * line. Left at 25px because 25/15pt = 1.67x is already clear of
             * the #297 edge -- the FFA row needed 28 only because its header
             * is 17pt. Truncate rather than FitOneLine: Overflow would let a
             * tall translated header paint over the roster underneath. */
            UIFactory.SetWordWrap(row.txtInfo,false);
            /* Roster element -- same construction as the FFA browser row. */
            row.txtMembers=UIFactory.CreateText("Members",infoCol.transform,"",13f,C_WHITE,
                UIFactory.AlignTopLeft,sizeDelta:new Vector2(0,16));
            UIFactory.SetWordWrap(row.txtMembers,true);
            UIFactory.SetTextAutoHeight(row.txtMembers,22);
            row.membersGO=(row.txtMembers as Component)?.gameObject;
            if(row.membersGO!=null)row.membersGO.SetActive(false);
            row.joinBtn=UIFactory.CreateButton("Join",row.root.transform,"Join",14f,C_WHITE,
                new Color(0.25f,0.42f,0.20f,0.95f),
                ()=>{JoinHostLobbyRow(row,team);dirty=true;},
                sizeDelta:new Vector2(80,24));
            SetFfaLayoutWidth(row.joinBtn,80f,0f,80f);
            // 2v2 only: the server never opens lobby bets on 1v2, and the fill
            // pass gates on `team` as well so a future payload change can't
            // surface the button there by accident.
            row.betBtn=UIFactory.CreateButton("Bet",row.root.transform,"Bet",14f,C_WHITE,
                new Color(0.35f,0.28f,0.10f,0.95f),
                // `team` is captured, not re-read: this pool is shared with the
                // 1v2 tab, and a bet request tagged "team" from a 1v2 row would
                // name a lobby id the team endpoint doesn't own.
                ()=>{if(team)ClickLobbyBet("team",row.lobbyId,row.betTargets,row.betAmount);dirty=true;},
                sizeDelta:new Vector2(70,24));
            SetFfaLayoutWidth(row.betBtn,70f,0f,70f);
            row.betBtn.SetActive(false);
            row.root.SetActive(false);
            return row;
        }

        private static void JoinHostLobbyRow(HostLobbyBrowserRow row,bool team)
        {
            if(string.IsNullOrEmpty(row.lobbyId))return;
            // Capture NOW (#265): the pooled row is rebound on refresh, and
            // the password modal outlives this click.
            string id=row.lobbyId;
            if(row.hasPassword)
            {
                CompetitiveUI.OpenArtistInput(
                    team?I18n.Tr("Private 2v2 lobby"):I18n.Tr("Private 1v2 lobby"),
                    I18n.Tr("Password"),"",
                    pw=>{
                        if(team)ApiClient.TeamLobbyJoin(id,teamLobbyPrefTeam,pw);
                        else ApiClient.OvtLobbyJoin(id,ovtPreferredSide,ovtSoloExtraPick,pw);
                        dirty=true;
                    });
                return;
            }
            if(team)ApiClient.TeamLobbyJoin(id,teamLobbyPrefTeam,null);
            else ApiClient.OvtLobbyJoin(id,ovtPreferredSide,ovtSoloExtraPick,null);
        }

        /// <summary>Codex r1 f6: hydrate the local Side/Extra/Team control
        /// state from the caller's OWN member row in the freshest /lobby/state
        /// payload, so recovery/rejoin never shows stale values. Runs from the
        /// render pass (every state poll MarkDirty()s, so it follows each
        /// poll); an in-flight prefs request's value wins until its response
        /// lands (PrefsInFlight covers request + response window).</summary>
        private static void HydrateHostLobbyPrefControls(ApiClient.HostLobbyClient cli,bool team)
        {
            if(string.IsNullOrEmpty(cli.OpenLobbyId)||cli.Members==null||cli.PrefsInFlight)return;
            string mySid=MatchTracker.LocalSteamId;
            if(string.IsNullOrEmpty(mySid)||mySid=="unknown")return;
            foreach(var m in cli.Members)
            {
                if(m==null||m.steam_id!=mySid)continue;
                if(team)
                    teamLobbyPrefTeam=(m.preferred_team==1||m.preferred_team==2)?m.preferred_team:0;
                else
                {
                    ovtPreferredSide=(m.preferred_side==1||m.preferred_side==2)?m.preferred_side:0;
                    ovtSoloExtraPick=m.solo_extra_pick;
                }
                return;
            }
        }

        /// <summary>One renderer for both host-lobby panels. Two modes, FFA
        /// pattern: browser rows (idle) / member-list text (seated). Every
        /// dynamic-height write mirrors RenderFfaLobbySection's prefH+minH+
        /// sizeDelta triple so #63's collapse can't happen.</summary>
        private static void RenderHostLobbySection(ApiClient.HostLobbyClient cli,List<HostLobbyBrowserRow> rows,
            List<LobbyMemberRow> memberRows,Action<string> kickAction,
            GameObject browserHost,object headerTxt,object bodyTxt,bool team,
            GameObject createBtn,GameObject createPrivBtn,GameObject startBtn,GameObject leaveBtn,GameObject prefBtn)
        {
            if(headerTxt==null||bodyTxt==null||browserHost==null)return;
            bool seated=!string.IsNullOrEmpty(cli.OpenLobbyId);
            bool leaving=cli.Status=="leaving";
            HydrateHostLobbyPrefControls(cli,team);
            // A live locked group in this mode owns the tab flow — lobby
            // controls step aside (mirror of the FFA locked gate).
            bool busy=team
                ?(ApiClient.CurrentTeamQueueState==ApiClient.TeamQueueState.Matched
                  ||ApiClient.CurrentTeamQueueState==ApiClient.TeamQueueState.ReadySent
                  ||!string.IsNullOrEmpty(ApiClient.ActiveTeamSeriesId))
                :(Plugin.PendingOvtSlot>=0||!string.IsNullOrEmpty(ApiClient.ActiveOvt1v2SeriesId));
            if(createBtn!=null)createBtn.SetActive(!seated&&!leaving&&!busy);
            if(createPrivBtn!=null)createPrivBtn.SetActive(!seated&&!leaving&&!busy);
            if(prefBtn!=null)
            {
                prefBtn.SetActive(!leaving&&!busy);
                // Aug 8 (Sid): "Team 1"/"Team 2" everywhere in the lobby
                // surfaces — the button said Orange/Blue while the member rows
                // said T1/T2. Color NAMES arrive with the team-color pass.
                UIFactory.SetTextRaw(UIFactory.GetButtonText(prefBtn),
                    teamLobbyPrefTeam==1?I18n.Tr("Team: <color=#FFB347>1</color>")
                    :teamLobbyPrefTeam==2?I18n.Tr("Team: <color=#88AAFF>2</color>"):I18n.Tr("Team: Any"));
            }
            if(startBtn!=null)
            {
                bool showStart=seated&&cli.IsHost&&!leaving;
                startBtn.SetActive(showStart);
                if(showStart)
                {
                    // Codex r2 f4/f6: while the host's OWN prefs write is
                    // unacked, Start dims and no-ops (StartLobby carries the
                    // authoritative early-return) — a Start landing mid-write
                    // would freeze a value the host just changed (the ovt
                    // extra-pick race).
                    if(cli.PrefsInFlight)
                        UIFactory.SetTextRaw(UIFactory.GetButtonText(startBtn),
                            I18n.Tr("<b><color=#999999>Start (saving...)</color></b>"));
                    else
                        UIFactory.SetTextRaw(UIFactory.GetButtonText(startBtn),
                            cli.CanStart?I18n.TrF("<b>Start Game ({0}/{1})</b>",cli.MemberCount,cli.MaxPlayers)
                                        :I18n.TrF("<b>Start (need {0})</b>",cli.MaxPlayers));
                }
            }
            if(leaveBtn!=null)leaveBtn.SetActive(seated||leaving);
            string browseHdr=team?I18n.Tr("<b>Hosted 2v2 Lobbies</b>"):I18n.Tr("<b>Custom 1v2 Lobbies</b>");
            string seatedHdr=team?I18n.Tr("<b>Your 2v2 Lobby</b>"):I18n.Tr("<b>Your Custom 1v2 Lobby</b>");
            int newH;
            if(seated)
            {
                for(int i=0;i<rows.Count;i++)rows[i].root.SetActive(false);
                // Aug 8 (Sid): pooled member ROWS with a host-only [Kick]
                // beside every member but the host themselves.
                int n=FillLobbyMemberRows(memberRows,browserHost.transform,team?"THLM":"O1HM",
                    team?14f:16f,kickAction,cli.Members,cli.IsHost,
                    m=>m.steam_id,
                    m=>{
                        bool isMe=m.steam_id==MatchTracker.LocalSteamId;
                        string nameC=isMe?"<color=#88FF88>":"<color=#FFFFFF>";
                        string hostTag=m.is_host?"  <color=#FFD94D>"+I18n.Tr("HOST")+"</color>":"";
                        // Aug 8 (Sid): claims render as "Team 1"/"Team 2" and
                        // "Solo"/"Duo" — same words as the selector buttons;
                        // nothing when unset/Any. Live from every state poll.
                        string prefTag;
                        if(team)
                            prefTag=m.preferred_team==1?"  <color=#FFB347>"+I18n.Tr("Team 1")+"</color>"
                                   :m.preferred_team==2?"  <color=#88AAFF>"+I18n.Tr("Team 2")+"</color>":"";
                        else
                            prefTag=(m.preferred_side==1?"  <color=#FFB347>"+I18n.Tr("Solo")+"</color>"
                                   :m.preferred_side==2?"  <color=#88AAFF>"+I18n.Tr("Duo")+"</color>":"")
                                   +(m.solo_extra_pick?"  <color=#888>+pick</color>":"");
                        int wm=m.wait_seconds/60,ws=m.wait_seconds%60;
                        string waitStr=wm>0?$"{wm}m{ws:D2}s":$"{ws}s";
                        // 2v2 shows the mode rating when one exists; both fall
                        // back to the 1v1 number the server sends for context.
                        string ratingStr=team&&m.rating>0
                            ?$"<color=#FFFFFF>2v2 {m.rating}</color>"
                            :$"<color=#DDDDDD>1v1 {m.rating_1v1}</color>";
                        return $"{nameC}{FfaSafeRich(Trunc(m.display_name,18))}</color>  {ratingStr}{prefTag}{hostTag}  <color=#888>{waitStr}</color>";
                    });
                UIFactory.SetTextRaw(headerTxt,seatedHdr
                    +I18n.TrF("  <color=#888>({0}/{1}{2})</color>",Math.Max(n,cli.MemberCount),cli.MaxPlayers,
                        cli.HasPassword?" - "+I18n.Tr("private"):""));
                if(n==0)
                {
                    UIFactory.SetTextRaw(bodyTxt,I18n.Tr("<color=#888>Loading members...</color>"));
                    newH=24;
                }
                else
                {
                    UIFactory.SetTextRaw(bodyTxt,"");
                    newH=2;
                }
            }
            else
            {
                for(int i=0;i<memberRows.Count;i++)
                { memberRows[i].targetSteamId=null; memberRows[i].root.SetActive(false); }
                var lobbies=cli.CachedLobbies;
                int n=lobbies?.Count??0;
                UIFactory.SetTextRaw(headerTxt,n==0
                    ?browseHdr+"  "+I18n.Tr("<color=#888>(none right now)</color>")
                    :browseHdr+I18n.TrF("  <color=#888>({0})</color>",n));
                while(rows.Count<Math.Min(n,12))
                    rows.Add(CreateHostLobbyBrowserRow(browserHost.transform,$"{(team?"T":"O")}HLob{rows.Count}",team));
                for(int i=0;i<rows.Count;i++)
                {
                    var row=rows[i];
                    if(lobbies==null||i>=lobbies.Count)
                    { row.betTargets=null; row.betAmount=0; row.root.SetActive(false); continue; }
                    var l=lobbies[i];
                    row.lobbyId=l.lobby_id;
                    row.hasPassword=l.has_password;
                    int ageMin=l.age_seconds/60;
                    string age=ageMin>0?$"{ageMin}m":$"{l.age_seconds}s";
                    /* ASCII marker only — no padlock glyph in Gravity (#47). */
                    string privTag=l.has_password?I18n.Tr("<color=#FFD94D>[PRIVATE]</color>")+"  ":"";
                    // Aug 8 (Sid): second line = WHO is inside (1v2 is unrated,
                    // so no "(1v1)" fallback suffix there).
                    string memberLine=BuildLobbyMemberLine(l.members,showUnestablished:team);
                    // Aug 9: a 2v2 bet backs a PAIR, so two live members must
                    // exist before the picker can produce a valid target.
                    bool canBet=team&&LobbyBetAvailable(l.bets_open,l.bet_targets,2);
                    var belief=LobbyBetBeliefFor("team",l.lobby_id);
                    row.betTargets=l.bet_targets;
                    row.betAmount=l.my_bet_amount>0?l.my_bet_amount:(belief!=null?belief.amount:0);
                    string betTag="";
                    if(row.betAmount>0)
                    {
                        string lbl=l.my_bet_amount>0
                            ?LobbyBetTargetLabel(l.bet_targets,l.my_bet_targets)
                            :(belief!=null?belief.label:"");
                        betTag="  "+I18n.TrF("<color=#FFD94D>your bet: {0}g on {1}</color>",row.betAmount,lbl);
                    }
                    else if(canBet)betTag="  "+I18n.Tr("<color=#FFD94D>bets open</color>");
                    UIFactory.SetTextRaw(row.txtInfo,
                        privTag+I18n.TrF("<color=#FFFFFF>{0}'s lobby</color>  <color=#7FD4FF>{1}/{2}</color>  <color=#888>open {3}</color>",
                            FfaSafeRich(Trunc(l.host_name,18)),l.player_count,l.max_players,age)
                        +betTag);
                    /* Roster to its own element -- see the FFA browser fill. */
                    SetLobbyRosterText(row.txtMembers,row.membersGO,memberLine);
                    row.joinBtn.SetActive(l.player_count<l.max_players&&!leaving&&!busy);
                    // Review find 2: an OPEN wager stays cancellable even if
                    // the lobby stops being bettable (dropped below two
                    // members, flipped casual) — otherwise the stake is
                    // stranded until the janitor.
                    bool showBetBtn=canBet||row.betAmount>0;
                    row.betBtn.SetActive(showBetBtn);
                    if(showBetBtn)
                        UIFactory.SetTextRaw(UIFactory.GetButtonText(row.betBtn),
                            row.betAmount>0?I18n.Tr("Cancel"):I18n.Tr("Bet"));
                    row.root.SetActive(true);
                }
                UIFactory.SetTextRaw(bodyTxt,n==0
                    ?(cli.LobbiesUnavailable
                        ?I18n.Tr("<color=#FFAA55>Lobby browser unavailable right now — the server may be updating.</color>")
                        :lobbies==null?$"<color=#888>{I18n.Tr("Loading...")}</color>"
                            :(team?I18n.Tr("<color=#888>No hosted 2v2 lobbies — create one and invite your friends!</color>")
                                  :I18n.Tr("<color=#888>No custom 1v2 lobbies — create one and invite your friends!</color>")))
                    :(leaving?I18n.Tr("<color=#888>Leaving...</color>"):""));
                newH=n==0?24:2;
            }
            var bodyComp=bodyTxt as Component;
            if(bodyComp!=null)
            {
                var le=bodyComp.gameObject.GetComponent(UIFactory.tLE);
                if(le!=null)
                {
                    UIFactory.tLE.GetProperty("preferredHeight",BindingFlags.Public|BindingFlags.Instance)?.SetValue(le,(float)newH);
                    UIFactory.tLE.GetProperty("minHeight",BindingFlags.Public|BindingFlags.Instance)?.SetValue(le,(float)newH);
                }
                var rt=bodyComp.GetComponent<RectTransform>();
                if(rt!=null)rt.sizeDelta=new Vector2(rt.sizeDelta.x,newH);
            }
        }

        // ── 1v2 tab (solo vs duo; UNSCORED beta) ──────────────────────────
        private static object txtOvtStatus, txtOvtSoloLbHeader, txtOvtDuoLbHeader, txtOvtRecentHeader, txtOvtRecentPage;
