            UIFactory.AddLE(rsv.scrollGO,flexH:1);
            ovtRecentContainer=rsv.content;
            ovtRecentViewport=rsv.content.transform.parent as RectTransform;
            ovtRecentScrollRect=rsv.scrollGO.GetComponent(UIFactory.tScrollRect) as Component;
            return outer;
        }

        /// <summary>Aug 7 item 13: fill the 1v2 live-games panel from
        /// CachedSpectateGames (mode=="1v2"). Panel hides when nothing is
        /// live-and-watchable; fighters never see their own game's button.</summary>
        private static void RenderOvtLiveGames()
        {
            if (ovtLivePanel == null || ovtLiveRowsHost == null) return;
            var games = ApiClient.CachedSpectateGames;
            int shown = 0;
            if (games != null)
            {
                foreach (var g in games)
                {
                    if (g == null || g.mode != "1v2" || !g.spectatable) continue;
                    if (shown >= 10) break;
                    if (ovtLiveRows.Count <= shown) ovtLiveRows.Add(CreateTeamLiveRow(ovtLiveRowsHost.transform));
                    var row = ovtLiveRows[shown];
                    row.root.SetActive(true);
                    // names is the server-composed display string; user-authored,
                    // so sanitize before it reaches TMP rich text.
                    UIFactory.SetTextRaw(row.txt,
                        $"<color=#DDD>{FfaSafeRich(Trunc(g.names, 60))}</color>  "
                        + $"<color=#888>({g.spectator_count}/{g.spectator_cap} {I18n.Tr("watching")})</color>");
                    bool canWatch = !LocalInSpectateRoster(g);
                    row.gameId = canWatch ? g.game_id : null;
                    if (row.watchBtn != null) row.watchBtn.SetActive(canWatch);
                    shown++;
                }
            }
            for (int i = shown; i < ovtLiveRows.Count; i++)
            { ovtLiveRows[i].gameId = null; ovtLiveRows[i].root.SetActive(false); }
            ovtLivePanel.SetActive(shown > 0);
        }

        private static float ovtTabRefreshAt, ovtRecentRefreshAt;
        private static void MaybeRefreshOvtTab()
        {
            if(currentTab!=11)return;
            ApiClient.UpdateOvtQueuePoll(false);   // safe no-op when not polling
            // v1.37 custom lobbies: one-shot membership rediscovery (a
            // relaunched client's seat must be found before its lease dies)
            // + the browser fetch. The state HEARTBEAT itself runs from
            // TickLeaveRecovery, not from this tab ticker.
            ApiClient.OvtLobby.ProbeServerState();
            ApiClient.OvtLobby.FetchLobbies(false);   // internally 3s-throttled
            if(Time.unscaledTime>=ovtRecentRefreshAt)
            {
                ovtRecentRefreshAt=Time.unscaledTime+10f;
                ApiClient.FetchOvtRecent(ovtRecentPageReq);
                // Aug 7 item 13: live 1v2 panel data (10s global throttle inside).
                ApiClient.MaybeFetchSpectateGames();
            }
            if(Time.unscaledTime>=ovtTabRefreshAt)
            {
                // Boards are slow-moving — 30s (was 3s when the combined board
                // was the tab's only data). Combined stays fetched so legacy
                // consumers of CachedOvtLeaderboard keep a fresh cache; the tab
                // itself renders the solo/duo split.
                ovtTabRefreshAt=Time.unscaledTime+30f;
                ApiClient.FetchOvtLeaderboard();
                ApiClient.FetchOvtLeaderboard(200,"solo");
                ApiClient.FetchOvtLeaderboard(200,"duo");
            }
        }

        private static void RefreshOneVTwoTab()
        {
            // Codex r1 f6: hydrate BEFORE the button text renders (the shared
            // section renderer also hydrates, but it runs after these writes).
            HydrateHostLobbyPrefControls(ApiClient.OvtLobby,team:false);
            if(ovtSideBtn!=null)UIFactory.SetText(UIFactory.GetButtonText(ovtSideBtn),ovtPreferredSide==1?"Side: Solo":ovtPreferredSide==2?"Side: Duo":"Side: Any");
            // Aug 8: host's setting - seated members render the HOST's row
            // value (ground truth from the state payload), not their local.
            if(ovtExtraBtn!=null)UIFactory.SetText(UIFactory.GetButtonText(ovtExtraBtn),OvtEffectiveExtraPick()?"Solo extra pick (host): ON":"Solo extra pick (host): OFF");
            bool polling=ApiClient.IsOvtQueuePolling;
            // Locked = a lock landed (pending slot / active series) even though
            // polling stopped. In that state Join must stay HIDDEN (re-joining
            // mid-lock is what used to let one click cancel a live series) and
            // Leave must stay VISIBLE — it is the only escape from a husk lock
            // (leave dissolves it server-side). Inside an actual ovt room both
            // are hidden: queue actions from within a running match are never
            // legitimate.
            bool ovtLocked=Plugin.PendingOvtSlot>=0||!string.IsNullOrEmpty(ApiClient.ActiveOvt1v2SeriesId);
            bool inOvtRoom=false;
            try{inOvtRoom=PhotonNetwork.InRoom&&(PhotonNetwork.CurrentRoom?.Name??"").StartsWith("ovt_");}catch{}
            bool ovtSeated=!string.IsNullOrEmpty(ApiClient.OvtLobby.OpenLobbyId);
            if(ovtLeaveBtn!=null)ovtLeaveBtn.SetActive((polling||ovtLocked)&&!inOvtRoom);
            if(txtOvtStatus!=null)
            {
                string st=ApiClient.OvtQueueStatus;
                string msg;
                if(inOvtRoom)msg=I18n.Tr("<color=#66DD66>In a 1v2 match.</color>");
                else if(st=="searching")msg=I18n.TrF("<color=#FFCC44>Searching…</color> {0} in lobby <color=#888>(locks at 3)</color>",ApiClient.OvtQueueCount);
                else if(st=="ready_join")
                {
                    // Locked lineup: who ended up solo vs duo.
                    string solo=Trunc(ApiClient.OvtLockedSoloName??"?",14);
                    var duo=ApiClient.OvtLockedDuo;
                    string duoNames=(duo!=null&&duo.Count>=2)?$"{Trunc(duo[0].display_name,14)} + {Trunc(duo[1].display_name,14)}":I18n.Tr("duo");
                    msg=I18n.TrF("<color=#66DD66>Match found! Joining…</color>  <color=#FFB347>{0}</color> <color=#888>vs</color> <color=#88AAFF>{1}</color>",solo,duoNames)
                        +(ApiClient.OvtSoloExtraPick?"  "+I18n.Tr("<color=#888>(solo extra pick)</color>"):"");
                }
                else if(st=="leaving")msg=I18n.Tr("<color=#888>Leaving queue…</color>");
                else if(ovtLocked)msg=I18n.Tr("<color=#FFB347>1v2 lobby pending</color> — Leave to dissolve it if nothing happens.");
                else if(ovtSeated)msg=I18n.Tr("<color=#88FF88>In a custom 1v2 lobby</color> <color=#888>— manage it in the panel below.</color>");
                else msg=I18n.Tr("Not in queue.");
                UIFactory.SetTextRaw(txtOvtStatus,msg);
            }
            // v1.37 custom lobbies panel (create/browse/password/host Start).
            RenderHostLobbySection(ApiClient.OvtLobby,ovtLobbyBrowserRows,
                ovtLobbyMemberRows,t=>ApiClient.OvtLobby.Kick(t),
                ovtLobbyBrowserHost,txtOvtHostLobbyHeader,txtOvtHostLobbyBody,team:false,
                ovtLobbyCreateBtn,ovtLobbyCreatePrivBtn,ovtLobbyStartBtn,ovtLobbyLeaveBtn,null);
            // Aug 7 item 13: live 1v2 games straight from the spectate feed.
            RenderOvtLiveGames();
            // Split activity boards (server-ordered; role-scoped W/L).
            FillOvtRoleBoard(ovtSoloLbContainer,ovtSoloLbRows,ApiClient.CachedOvtLeaderboardSolo,txtOvtSoloLbHeader,I18n.Tr("Solo Leaderboard"),"#FFB347");
            FillOvtRoleBoard(ovtDuoLbContainer,ovtDuoLbRows,ApiClient.CachedOvtLeaderboardDuo,txtOvtDuoLbHeader,I18n.Tr("Duo Leaderboard"),"#88AAFF");
            // 25f -> 23f: (FillOvtRoleBoard's row height) + (the board ScrollView's
            // spacing of 1), and item 15 took those rows 24 -> 22. A stale estimate
            // over-reports content height and leaves the inner ScrollRect enabled
            // on a list that fits, stealing the wheel from the tab scroll (#76).
            ToggleInnerScroll(ovtSoloScrollRect,(ApiClient.CachedOvtLeaderboardSolo?.Count??0)*23f);
            ToggleInnerScroll(ovtDuoScrollRect,(ApiClient.CachedOvtLeaderboardDuo?.Count??0)*23f);
            RefreshOvtRecent();
        }

        /// <summary>Hover pass for the Recent 1v2 panel: one region per series
        /// row, popping that series' end-of-game builds.
        ///
        /// Runs from the 1v2 tab's own OnGUI (OneVTwoHoverDrawer) because the
        /// SHARED card-tooltip drawer in CompetitiveUI refuses every tab except
        /// My Stats and 2v2 — a region registered from here would be collected
        /// and never drawn. This mirrors the FFA tab, which draws its own for
        /// the same reason, and reuses its clipping + measured-box helpers so
        /// there is one implementation of "bounded tooltip over a scrolled
        /// row", not three.</summary>
        private static void DrawOvtRecentHover()
        {
            try
            {
                if(Event.current==null||Event.current.type!=EventType.Repaint)return;
                if(!isOpen||currentTab!=11)return;
                Vector2 mouse=Event.current.mousePosition;
                string tip=null;
                for(int i=0;i<ovtRecentRows.Count&&tip==null;i++)
                {
                    if(i>=ovtRecentHoverBodies.Count)break;
                    string body=ovtRecentHoverBodies[i];
                    if(string.IsNullOrEmpty(body))continue;
                    var comp=ovtRecentRows[i] as Component;
                    if(comp==null||!comp.gameObject.activeInHierarchy)continue;
                    var rt=comp.GetComponent<RectTransform>();
                    if(rt==null)continue;
                    // Both masks: the recent list's viewport AND the whole-tab
                    // outer viewport (#185 — a row scrolled under either edge
                    // must not keep a live region over what is drawn there).
                    if(TryGetMaskedScreenRect(rt,ovtRecentViewport,ovtTabOuterViewport,out Rect r)
                       &&r.Contains(mouse))
                        tip=body;
                }
                if(tip==null)return;
                int previousDepth=GUI.depth;
                try{GUI.depth=-20000;DrawWideTooltip(tip,mouse,470f);}
                finally{GUI.depth=previousDepth;}
            }
            catch{}
        }

        // One rich line per entry: "#N Name  W-L (WR%)  Lv". Name takes the
        // title_color when the player has a colored title equipped.
        private static void FillOvtRoleBoard(GameObject container,List<object> pool,List<ApiClient.OvtLeaderboardEntry> lb,object headerTxt,string label,string accent)
        {
            if(container==null)return;
            // label arrives pre-translated (Tr'd at the call sites); the
            // templates put accent + label in holes so the composed result
            // is written Raw (compose-after-Tr, item 6).
            if(lb==null)
            {
                if(headerTxt!=null)UIFactory.SetTextRaw(headerTxt,I18n.TrF("<b><color={0}>{1}</color></b>  <color=#888>(unranked - loading...)</color>",accent,label));
                return;
            }
            if(headerTxt!=null)UIFactory.SetTextRaw(headerTxt,lb.Count==0
                ?I18n.TrF("<b><color={0}>{1}</color></b>  <color=#888>(unranked - no games yet)</color>",accent,label)
                :I18n.TrF("<b><color={0}>{1}</color></b>  <color=#888>(unranked - {2} players)</color>",accent,label,lb.Count));
            while(pool.Count<lb.Count&&pool.Count<100)
            {
                /* Item 15: 18pt/24 -> the 2v2 leaderboard row's 15pt/22. Width is
                 * unchanged (518 inside the 554 column). This also relaxes the
                 * line-box ratio from 1.33 to 1.47, which is the safer side of
                 * #297 for the Cyrillic display names these rows carry. */
                var t=UIFactory.CreateText($"{container.name}R{pool.Count}",container.transform,"",15f,C_WHITE,UIFactory.AlignMidLeft,sizeDelta:new Vector2(518,22));
                /* item 7c sweep: user-authored display names in a one-line cell. */
                UIFactory.FitOneLine(t);
                pool.Add(t);
            }
            for(int i=0;i<pool.Count;i++)
            {
                var comp=pool[i] as Component;if(comp==null)continue;
                if(i>=lb.Count){comp.gameObject.SetActive(false);continue;}
                var e=lb[i];
                comp.gameObject.SetActive(true);
                bool me=e.steam_id==MatchTracker.LocalSteamId;
                string nameCol=!string.IsNullOrEmpty(e.title_color)?e.title_color:(me?"#88FF88":"#FFFFFF");
                string rankCol=e.rank==1?"#FFD700":e.rank==2?"#C0C0C0":e.rank==3?"#CD7F32":"#FFD94D";
                UIFactory.SetTextRaw(pool[i],
                    $"<color={rankCol}>#{e.rank}</color>  <color={nameCol}>{Trunc(e.display_name,14)}</color>  {e.wins}-{e.losses} <color=#66DD66>({e.win_rate:F0}%)</color>  <color=#888>Lv{e.level}</color>");
            }
        }

        private static void RefreshOvtRecent()
        {
            if(ovtRecentContainer==null)return;
            var list=ApiClient.CachedOvtRecent??new List<ApiClient.OvtRecentSeries>();
            while(ovtRecentRows.Count<Math.Min(list.Count,10))
            {
                var t=UIFactory.CreateText($"O1RR{ovtRecentRows.Count}",ovtRecentContainer.transform,"",18f,C_WHITE,UIFactory.AlignTopLeft,sizeDelta:new Vector2(896,27));
                UIFactory.SetWordWrap(t,false);
                ovtRecentRows.Add(t);
            }
            float recTotalH=0f;
            // Kept index-aligned with the row pool BEFORE the loop, so the
            // hover scan can index it with a row index unconditionally — a
            // `continue` inside the loop must not be able to leave it short.
            while(ovtRecentHoverBodies.Count<ovtRecentRows.Count)ovtRecentHoverBodies.Add(null);
            for(int i=0;i<ovtRecentRows.Count;i++)
            {
                var comp=ovtRecentRows[i] as Component;if(comp==null){ovtRecentHoverBodies[i]=null;continue;}
                if(i>=list.Count){comp.gameObject.SetActive(false);ovtRecentHoverBodies[i]=null;continue;}
                int lines;
                string hoverBody;
                UIFactory.SetTextRaw(ovtRecentRows[i],BuildOvtRecentRowText(list[i],out lines,out hoverBody));
                ovtRecentHoverBodies[i]=hoverBody;
                int h=lines*24+10;
                UIFactory.SetPrefH(comp.gameObject,h);
                var rt=comp.GetComponent<RectTransform>();
                if(rt!=null)rt.sizeDelta=new Vector2(rt.sizeDelta.x,h);
                comp.gameObject.SetActive(true);
                recTotalH+=h+2;
            }
            ToggleInnerScroll(ovtRecentScrollRect,recTotalH);
            if(txtOvtRecentHeader!=null)
                UIFactory.SetTextRaw(txtOvtRecentHeader,ApiClient.CachedOvtRecentTotal==0
                    ?I18n.Tr("<b>Recent 1v2 Games</b>  <color=#888>- none yet</color>")
                    :I18n.TrF("<b>Recent 1v2 Games</b>  <color=#888>({0} series)</color>",ApiClient.CachedOvtRecentTotal));
            int pages=Math.Max(1,ApiClient.CachedOvtRecentPages);
            if(txtOvtRecentPage!=null)UIFactory.SetText(txtOvtRecentPage,$"{ovtRecentPageReq+1}/{pages}");
            if(ovtRecentPrevBtn!=null)ovtRecentPrevBtn.SetActive(ovtRecentPageReq>0);
            if(ovtRecentNextBtn!=null)ovtRecentNextBtn.SetActive(ovtRecentPageReq+1<pages);
        }

        // One series = one multi-line rich text: header (solo orange vs duo
        // blue, score, date), then per match a score/winner/duration line +
        // compact per-player cards lines (comma-joined, ~90-char cap).
        //
        // `hoverBody` is the series' end-of-game BUILDS, pre-formatted for
        // DrawWideTooltip and NULL when this series has none. Round-2 HIGH: the
        // server has been sending end_stats_by_steam and ApiClient has been
        // parsing it, and this renderer read only cards_by_steam — so every 1v2
        // build was silently dropped. It goes in a hover rather than inline
        // because a decoded build is ~7 packed lines per player: three players
        // over a BO3 would add ~60 lines to a row in a panel that already
        // budgets its height line-by-line (#245).
        private static string BuildOvtRecentRowText(ApiClient.OvtRecentSeries s,out int lines,out string hoverBody)
        {
            var sb=new StringBuilder();lines=1;
            hoverBody=null;
            var hb=new StringBuilder();
            // Stable order: solo, duo A, duo B (side colors match the header).
            // One table, used by the cards lines, the builds and the rewards
            // block, so the three can never disagree about who is who.
            string[][] who=new[]{
                new[]{s.solo_steam,s.solo_name,"#FFB347"},
                new[]{s.duo_a_steam,s.duo_a_name,"#88AAFF"},
                new[]{s.duo_b_steam,s.duo_b_name,"#88AAFF"}};
            string dt="";
            try{string d=!string.IsNullOrEmpty(s.completed_at)?s.completed_at:s.created_at;if(!string.IsNullOrEmpty(d)&&d.Length>=10)dt=DateFmt.Short(DateTime.Parse(d));}catch{}
            string statusTag=s.status=="completed"?"":"  "+I18n.Tr("<color=#888>(in progress)</color>");
            string extraTag=s.solo_extra_pick?"  "+I18n.Tr("<color=#888>+pick</color>"):"";
            string header=I18n.TrF("<color=#FFB347><b>{0}</b></color> <color=#888>vs</color> <color=#88AAFF>{1} + {2}</color>  <b>{3}-{4}</b>  <color=#999>{5}</color>",
                Trunc(s.solo_name??"?",14),Trunc(s.duo_a_name??"?",14),Trunc(s.duo_b_name??"?",14),s.solo_wins,s.duo_wins,dt);
            int gameNo=0;
            foreach(var m in s.matches)
            {
                gameNo++;
                string wTag=m.winner_side==1?I18n.Tr("<color=#FFB347>solo won</color>"):m.winner_side==2?I18n.Tr("<color=#88AAFF>duo won</color>"):"";
                string dur=m.duration_seconds>0?$"<color=#8FA3B8>{m.duration_seconds/60}:{m.duration_seconds%60:00}</color>":"";
                sb.Append($"  <color=#888>-</color> {m.solo_rounds}-{m.duo_rounds}  {wTag}  {dur}\n");
                lines++;
                if(m.cards_by_steam!=null&&m.cards_by_steam.Count>0)
                {
                    foreach(var w in who)
                    {
                        if(string.IsNullOrEmpty(w[0]))continue;
                        List<string> cards;
                        if(!m.cards_by_steam.TryGetValue(w[0],out cards)||cards==null||cards.Count==0)continue;
                        string joined=string.Join(", ",cards.ToArray());
                        if(joined.Length>90)joined=joined.Substring(0,90)+"...";
                        sb.Append($"      <color={w[2]}>{Trunc(w[1]??"?",12)}:</color> <color=#667788>{joined}</color>\n");
                        lines++;
                    }
                }
                // Builds for this game, into the hover body. The FFA tooltip's
                // WIDE budget: DrawWideTooltip is the same 470px measured box.
                if(m.end_stats_by_steam==null||m.end_stats_by_steam.Count==0)continue;
                var gameBlock=new StringBuilder();
                foreach(var w in who)
                {
                    if(string.IsNullOrEmpty(w[0]))continue;
                    string wire;
                    if(!m.end_stats_by_steam.TryGetValue(w[0],out wire))continue;
                    string block=BuildStatsTipBlock(wire,BUILD_TIP_WIDE_COLS,"  ");
                    if(block.Length==0)continue;
                    if(gameBlock.Length>0)gameBlock.Append('\n');
                    gameBlock.Append("<b><color=").Append(w[2]).Append('>')
                             .Append(Trunc(w[1]??"?",16)).Append("</color></b>\n").Append(block);
                }
                if(gameBlock.Length==0)continue;
                if(hb.Length>0)hb.Append('\n');
                hb.Append("<color=#8FA3B8>").Append(I18n.TrF("Game {0}",gameNo)).Append("</color>\n")
                  .Append(gameBlock);
            }
            if(hb.Length>0)
            {
                hoverBody=hb.ToString();
                header+="  "+I18n.Tr("<color=#556270>(hover for builds)</color>");
            }
            sb.Insert(0,header+statusTag+extraTag+"\n");
            // Bug #129: the per-player series xp/gold. The server has always sent
            // gold_by_steam/xp_by_steam here and the client has always PARSED them —
            // this panel just never drew them, which is a large part of why 1v2 read
            // as "no XP/gold". Series-cumulative, so labelled per series, not per game.
            // `lines` drives the row's LayoutElement height, so every appended line
            // must increment it or the text overpaints its neighbours (#199).
            if(s.xp_by_steam!=null||s.gold_by_steam!=null)
            {
                var rewards=new List<string>();
                foreach(var w in who)
                {
                    if(string.IsNullOrEmpty(w[0]))continue;
                    int xp=0,gold=0;
                    if(s.xp_by_steam!=null)s.xp_by_steam.TryGetValue(w[0],out xp);
                    if(s.gold_by_steam!=null)s.gold_by_steam.TryGetValue(w[0],out gold);
                    if(xp<=0&&gold<=0)continue;
                    rewards.Add($"<color={w[2]}>{Trunc(w[1]??"?",12)}</color> <color=#9BE8A0>+{xp}xp</color>"
                               +(gold>0?$" <color=#FFD94D>+{gold}g</color>":""));
                }
                if(rewards.Count>0)
                {
                    sb.Append("      "+I18n.Tr("<color=#667788>series:</color>")+" "+string.Join("   ",rewards.ToArray())+"\n");
                    lines++;
                }
            }
            return sb.ToString();
        }

        private static GameObject shopScrollGO;

        /// <summary>Broadcast-seat verification lever (Aug 23): open the overlay
        /// on a tab and optionally scroll the Shop list, so a seat with nobody at
        /// it can screenshot every tab. Gated by the caller on the broadcast
        /// identity; no state beyond what a click would set.</summary>
        internal static void DevOpenTab(int idx, float shopScroll, string infoArticleKey = null)
        {
            try
            {
                if (!isOpen) Toggle();
                if (!isOpen || pageGO == null) return;
                if (idx >= 0 && idx < NUM_TABS && idx != currentTab) SwitchTab(idx);
                if (idx == TAB_INFO && !string.IsNullOrEmpty(infoArticleKey))
                {
                    // Lever grammar (broadcast verification, #420):
                    //   15:<article-key>      open an article
                    //   15:search:<query>     drive the nav search filter
                    //   15:linktest           grid-scan the open article's links
                    if (infoArticleKey.StartsWith("search:", StringComparison.OrdinalIgnoreCase))
                        InfoSearch = infoArticleKey.Substring("search:".Length);
                    else if (string.Equals(infoArticleKey, "linktest", StringComparison.OrdinalIgnoreCase))
                        InfoLinkSelfTest();
                    else
                        SelectInfoArticle(infoArticleKey);
                }
                if (idx == 4 && shopScroll >= 0f && shopScrollGO != null && UIFactory.tScrollRect != null)
                {
                    var sr = shopScrollGO.GetComponent(UIFactory.tScrollRect);
                    var p = UIFactory.tScrollRect.GetProperty("verticalNormalizedPosition", BindingFlags.Public | BindingFlags.Instance);
                    if (sr != null && p != null) p.SetValue(sr, Mathf.Clamp01(1f - shopScroll));   // 0 = top of the list
                }
            }
            catch (Exception ex) { Plugin.Log.LogWarning($"[UI] DevOpenTab failed: {ex.Message}"); }
        }

        private static void SwitchTab(int idx){currentTab=idx;CompetitiveUI.ClearCardHoverRegions();for(int i=0;i<NUM_TABS;i++){if(tabPanels[i]!=null)tabPanels[i].SetActive(i==idx);}UpdateTabBarVisual();if(idx==1){lbTabRefreshAt=Time.unscaledTime+30f;ApiClient.FetchLeaderboard();ApiClient.FetchRecentSeries();ApiClient.FetchRecentMultimodeSeries();ApiClient.FetchActiveSeries();ApiClient.FetchRankTiers();var sid=MatchTracker.LocalSteamId;if(!string.IsNullOrEmpty(sid)&&sid!="unknown")ApiClient.FetchMyBets(sid);}if(idx==2&&ApiClient.CachedCardStats==null)ApiClient.FetchCardStats(200,MatchTracker.LocalSteamId);if(idx==3&&ApiClient.CachedAchievements==null){var id=MatchTracker.LocalSteamId;if(!string.IsNullOrEmpty(id)&&id!="unknown")ApiClient.FetchAchievements(id);}if(idx==4){var id=MatchTracker.LocalSteamId;if(!string.IsNullOrEmpty(id)&&id!="unknown"){ApiClient.FetchShopItems(id);ApiClient.FetchInventory(id);}else ApiClient.FetchShopItems();ApiClient.FetchNewestCosmetics();/* Aug 7 item 10: the New chip needs the newest cache; Home used to be its only fetch site */}if(idx==6){var id=MatchTracker.LocalSteamId;if(!string.IsNullOrEmpty(id)&&ApiClient.IsAdmin){ApiClient.FetchFlaggedMatches(id);ApiClient.FetchAdminRecentSeries(id);ApiClient.FetchAdminQuarantine(id);ApiClient.FetchAdminActions(id,25,0,"","",null);}}if(idx==TAB_BANNED){var id=MatchTracker.LocalSteamId;if(!string.IsNullOrEmpty(id)&&ApiClient.IsAdmin)ApiClient.FetchBannedUsers(id);}if(idx==7){ApiClient.FetchTournamentCurrent(MatchTracker.LocalSteamId,force:true);ApiClient.FetchSiteTournamentHistory();ApiClient.FetchActiveSeries();var _msid=MatchTracker.LocalSteamId;if(!string.IsNullOrEmpty(_msid)&&_msid!="unknown"){ApiClient.FetchPlayerTournaments(_msid);ApiClient.FetchMyBets(_msid);}}if(idx==8){if(ApiClient.CachedTeamLeaderboard==null||ApiClient.CachedTeamLeaderboard.Count==0)ApiClient.FetchTeamLeaderboard();var _msid=MatchTracker.LocalSteamId;if(!string.IsNullOrEmpty(_msid)&&_msid!="unknown")ApiClient.FetchTeamMatchHistory(_msid);}if(idx==9){if(ApiClient.CachedLeaderboard==null)ApiClient.FetchLeaderboard();}if(idx==10){var _asid=MatchTracker.LocalSteamId;if(!string.IsNullOrEmpty(_asid)&&_asid!="unknown"&&ApiClient.IsArtist){ApiClient.FetchArtistItems(_asid);ApiClient.FetchMySubmissions(_asid);ApiClient.FetchArtistSales(_asid);}}if(idx==11){ovtTabRefreshAt=Time.unscaledTime+30f;ovtRecentRefreshAt=Time.unscaledTime+10f;ApiClient.FetchOvtLeaderboard();ApiClient.FetchOvtLeaderboard(200,"solo");ApiClient.FetchOvtLeaderboard(200,"duo");ApiClient.FetchOvtRecent(ovtRecentPageReq);}if(idx==12){ffaLbRefreshAt=Time.unscaledTime+30f;ffaRecentRefreshAt=Time.unscaledTime+10f;ffaBetRefreshAt=Time.unscaledTime+10f;ApiClient.FetchFfaLeaderboard(200,ffaLbSortReq);ApiClient.FetchFfaRecent(ffaRecentPageReq,5);ApiClient.FetchFfaRecent(ffaRecentCasPageReq,5,false);ApiClient.FetchFfaBettable(MatchTracker.LocalSteamId);ApiClient.UpdateFfaQueueList(force:true);}if(idx==TAB_HOME){homeTabRefreshAt=Time.unscaledTime+15f;ApiClient.FetchOnlinePlayers();ApiClient.FetchNewestCosmetics();ApiClient.FetchReleaseNotes();}dirty=true;}

        // ── Home tab (v1.33) — splash/landing page: big logo, latest release
        // notes (GitHub), newest cosmetics, online/recently-online players,
        // plus the Discord Link + chat panels moved over from My Stats. ──
        private static object txtHomeOnlineHdr,txtHomeOnline,txtHomeReleases,txtHomeCosmetics;
        // Newest-cosmetics art rows (Sid feedback: show the actual cosmetic art,
        // animated frames included). A fixed pool filled by RefreshHomeTab; each
        // row is an Image (sprite for face art, or a preview_color swatch for
        // kinds with no shipped PNG) + a two-line text cell.
        private class HomeCosRow{public GameObject root;public GameObject artGO;public object artImg;public object txt;}
        private static readonly List<HomeCosRow> homeCosRows=new List<HomeCosRow>();
        // Item 4: pool covers the last TWO cosmetic-update batches (server
        // caps at 12); the rows live in a scroll so overflow is reachable.
        private const int HOME_COS_ROWS=12;
        private static HomeCosRow CreateHomeCosRow(Transform parent,int idx)
        {
            var r=new HomeCosRow();
            r.root=new GameObject($"hcos{idx}");r.root.transform.SetParent(parent,false);r.root.AddComponent<RectTransform>();
            UIFactory.AddHLG(r.root,spacing:8,padL:2,padR:2,forceExpandH:true);UIFactory.AddLE(r.root,prefH:80,minH:80,flexH:0);
            r.artGO=new GameObject("art");r.artGO.transform.SetParent(r.root.transform,false);r.artGO.AddComponent<RectTransform>();
            // Item 4: art doubled 38 -> 76, text 14 -> 17.
            UIFactory.AddLE(r.artGO,prefW:76,minW:76,prefH:76,flexW:0,flexH:0);
            if(UIFactory.tImage!=null)
            {
                r.artImg=r.artGO.AddComponent(UIFactory.tImage);
                try{UIFactory.tImage.GetProperty("preserveAspect",BindingFlags.Public|BindingFlags.Instance)?.SetValue(r.artImg,true);}catch{}
                try{UIFactory.tImage.GetProperty("raycastTarget",BindingFlags.Public|BindingFlags.Instance)?.SetValue(r.artImg,false);}catch{}
            }
            r.txt=UIFactory.CreateText("t",r.root.transform,"",17f,C_WHITE,UIFactory.AlignMidLeft,sizeDelta:new Vector2(310,76));
            UIFactory.SetWordWrap(r.txt,false);
            r.root.SetActive(false);
            return r;
        }
        private static float homeTabRefreshAt;
        private static Sprite _homeLogoSprite;private static bool _homeLogoTried;
        private static Sprite GetHomeLogoSprite()
        {
            if(_homeLogoTried)return _homeLogoSprite;
            _homeLogoTried=true;
            try
            {
                var asm=Assembly.GetExecutingAssembly();
                string resName=null;
                foreach(var n in asm.GetManifestResourceNames())if(n.EndsWith("logo.png",StringComparison.OrdinalIgnoreCase)){resName=n;break;}
                if(resName==null){Plugin.Log.LogWarning("[HOME] embedded logo resource not found");return null;}
                using(var st=asm.GetManifestResourceStream(resName))
                {
                    if(st==null)return null;
                    var bytes=new byte[st.Length];int off=0;
                    while(off<bytes.Length){int r=st.Read(bytes,off,bytes.Length-off);if(r<=0)break;off+=r;}
                    var tex=new Texture2D(2,2,TextureFormat.RGBA32,false);
                    if(!tex.LoadImage(bytes))return null;
                    tex.hideFlags=HideFlags.HideAndDontSave;
                    _homeLogoSprite=Sprite.Create(tex,new Rect(0,0,tex.width,tex.height),new Vector2(0.5f,0.5f));
                    _homeLogoSprite.hideFlags=HideFlags.HideAndDontSave;
                }
            }
            catch(Exception ex){Plugin.Log.LogWarning($"[HOME] logo load failed: {ex.Message}");}
            return _homeLogoSprite;
        }
        /* Player names / server strings entering rich text — neuter angle brackets
         * so a crafted name can't inject TMP tags into the Home panels. */
        private static string HomeSan(string s){return string.IsNullOrEmpty(s)?"":s.Replace("<","[").Replace(">","]");}
        /* Coarse by design (Sid's item 6): no exact minutes — under an hour is
         * just "recently online", beyond that flat hours. */
        private static string FmtAgo(int minutes){if(minutes<60)return I18n.Tr("recently online");return I18n.TrF("{0}h ago",minutes/60);}
        private static string HomeTitleSpan(ApiClient.OnlinePlayerEntry p){if(string.IsNullOrEmpty(p.title))return "";string tc=string.IsNullOrEmpty(p.titleColor)?"#FFFFFF":p.titleColor;return $" <b><color={tc}>[{HomeSan(p.title)}]</color></b>";}
