            var cosBox=UIFactory.CreatePanel("HCos",left.transform,C_PANEL);UIFactory.AddVLG(cosBox,spacing:3,padL:10,padR:10,padT:6,padB:6);UIFactory.AddLE(cosBox,prefH:340,minH:280,flexH:0);
