            chatSendBtn=UIFactory.CreateButton("ChSend",chHdrRow.transform,"Typing channel",13f,C_WHITE,C_BTN,()=>OpenChatTypingPicker(),sizeDelta:new Vector2(300,24));
            var chSV=UIFactory.CreateScrollView("ChSV",chatBox.transform,spacing:0);UIFactory.AddLE(chSV.scrollGO,prefH:240,minH:240,flexH:0);chatScrollRect=chSV.scrollGO.GetComponent(UIFactory.tScrollRect);chatContentRT=chSV.contentRT;chatViewportRT=chSV.scrollGO.transform.Find("Viewport") as RectTransform;txtChatLog=UIFactory.CreateText("ChLog",chSV.content.transform,"<color=#888><i>No messages yet. Messages sent here or in #scr-discussion on Discord show up here.</i></color>",14f,C_WHITE,UIFactory.AlignTopLeft,sizeDelta:new Vector2(560,400));UIFactory.SetWordWrap(txtChatLog,true);/* Bug #161: the chat pane opened parked halfway down. This element was the ONLY scrolling text in the file without auto-height, so its LayoutElement kept the 400px preferred height baked from sizeDelta.y no matter how little text there was. Content 400 vs a 240 viewport means "can scroll" is ALWAYS true, so the scroll-to-bottom parked the view over the empty lower 160px. With auto-height the content tracks the real text: short logs never scroll and sit at the top, long ones scroll to the newest line. */UIFactory.SetTextAutoHeight(txtChatLog);/* Round-3 blocker 5: CreateText pins minHeight AS WELL as preferredHeight from sizeDelta.y, and SetTextAutoHeight only clears the preferred one — so the content stayed pinned at 400px and the pane still opened parked over blank space. This element scrolls inside its own viewport and has no neighbour to be compressed against, so it does not need the anti-compression floor. */UIFactory.SetMinH(((Component)txtChatLog).gameObject,0f);
/* CreateText baked a LayoutElement with prefH=400 onto the chat-log GO. With the parent VLG/CSF reading
 * that, a single very long message (e.g. a 9000-char changelog paste) renders as TMP overflow but the
 * scroll content stays clamped at 400px -> unreachable bottom. Zero out the prefH so TMP's own
 * ILayoutElement.preferredHeight (its actual rendered height) drives the content size instead. */
            {var chatLE=(txtChatLog as Component)?.gameObject.GetComponent(UIFactory.tLE);if(chatLE!=null){var prefHProp=UIFactory.tLE.GetProperty("preferredHeight",BindingFlags.Public|BindingFlags.Instance);prefHProp?.SetValue(chatLE,-1f);}}
            return panel;
        }
        private static void RefreshHomeTab()
        {
            /* Discord-link state (moved from RefreshMyStats — statics live here now). */
            var s=ApiClient.CachedPlayerStats;
            if(linkCodeBtn!=null&&txtLinkCode!=null)
            {
                bool linked=s!=null&&!string.IsNullOrEmpty(s.discord_id);
                linkCodeBtn.SetActive(!linked);
                if(linked)
                {
                    // Item 8 reword: hidden state drops the asterisk mask +
                    // nested parens; revealed state puts the RAW handle in a
                    // TrF hole (never translated).
                    string raw=!string.IsNullOrEmpty(s.discord_username)?$"@{s.discord_username}":$"ID {s.discord_id}";
                    UIFactory.SetTextRaw(txtLinkCode,discordRevealed
                        ?I18n.TrF("<color=#00FF00>Linked to Discord</color> ({0})",raw)
                        :I18n.Tr("<color=#00FF00>Linked to Discord</color> <color=#888>(Click to show)</color>"));
                }
            }
            /* Online / recently-online players. */
            int onlineCount=ApiClient.CachedOnlineListCount>0?ApiClient.CachedOnlineListCount:ApiClient.CachedOnlineCount;
            if(txtHomeOnlineHdr!=null)UIFactory.SetText(txtHomeOnlineHdr,onlineCount>0?(onlineCount==1?I18n.TrF("{0} player online now",onlineCount):I18n.TrF("{0} players online now",onlineCount)):"");
            if(txtHomeOnline!=null)
            {
                var sb=new StringBuilder();
                var on=ApiClient.CachedOnlinePlayers;var rec=ApiClient.CachedRecentPlayers;
                sb.Append(I18n.Tr("<color=#66FF88>Online now</color>")).Append('\n');
                if(on==null)sb.Append($"<color=#888><i>{I18n.Tr("Loading...")}</i></color>").Append('\n');
                else if(on.Count==0)sb.Append(I18n.Tr("<color=#888><i>Nobody visible right now.</i></color>")).Append('\n');
                else foreach(var p in on)sb.Append($"<color=#66FF88>*</color> {HomeSan(p.name)}{HomeTitleSpan(p)}  <color=#8FA3B8>{p.rating}</color>\n");
                sb.Append("\n"+I18n.Tr("<color=#99AAEE>Recently online</color>")+"\n");
                if(rec==null||rec.Count==0)sb.Append("<color=#888><i>-</i></color>\n");
                else foreach(var p in rec)sb.Append($"{HomeSan(p.name)}{HomeTitleSpan(p)}  <color=#8FA3B8>{p.rating}</color>  <color=#777>{FmtAgo(p.minutesAgo)}</color>\n");
                sb.Append("\n"+I18n.Tr("<color=#666><i>Hide yourself here: Settings -> Appear offline.</i></color>"));
                UIFactory.SetTextRaw(txtHomeOnline,sb.ToString());
            }
            /* Latest releases (GitHub). */
            if(txtHomeReleases!=null)
            {
                var rel=ApiClient.CachedReleaseNotes;
                /* Bug #160 ("still squished to the left"): this was never a
                 * layout bug. GitHub release BODIES are authored with hard line
                 * breaks around column 78, so the English text carries its own
                 * wrap and no panel width can widen it — while the translated
                 * overlays were written as unbroken paragraphs and fill the
                 * column. Stretching the element (below) is necessary but not
                 * sufficient; UnwrapHardBreaks removes the baked-in breaks so
                 * TMP owns the wrapping in every language. */
                if(rel==null)UIFactory.SetText(txtHomeReleases,"<color=#888><i>Loading release notes...</i></color>");
                else if(rel.Count==0)UIFactory.SetText(txtHomeReleases,"<color=#888><i>Release notes unavailable right now.</i></color>");
                else
                {
                    var sb=new StringBuilder();
                    foreach(var r in rel)
                    {
                        sb.Append($"<color=#FFD94D>{HomeSan(r.tag)}</color>");
                        if(!string.IsNullOrEmpty(r.title)&&r.title!=r.tag)sb.Append($"  <b>{HomeSan(r.title)}</b>");
                        if(!string.IsNullOrEmpty(r.date))sb.Append($"  <color=#777>{r.date}</color>");
                        sb.Append('\n');
                        if(!string.IsNullOrEmpty(r.body))sb.Append($"<color=#C8D2DC>{r.body}</color>\n");   // already unwrapped upstream in ApiClient.CleanReleaseBody (r2 find 16)
                        sb.Append('\n');
                    }
                    // Release-notes BODIES are external GitHub content — stay
                    // untranslated by policy; Raw makes the bypass explicit.
                    UIFactory.SetTextRaw(txtHomeReleases,sb.ToString());
                }
            }
            /* Newest cosmetics — art thumbnails (animated where available). */
            {
                var cos=ApiClient.CachedNewestCosmetics;
                // Item 4: the list covers the last two update batches — name
                // both dates in the caption so the split is legible.
                string cosCaption=I18n.Tr("<color=#888><i>Grab them in the Shop tab.</i></color>");
                if(cos!=null&&cos.Count>0)
                {
                    var batchDates=new List<string>();
                    foreach(var cc in cos)
                    {
                        // F14: honor the user's date-order setting via the ISO
                        // date when the server sends it; the preformatted
                        // "Mon D" string stays the old-server fallback.
                        string bd=cc.dateIso.HasValue?DateFmt.Short(cc.dateIso.Value):cc.added;
                        if(!string.IsNullOrEmpty(bd)&&!batchDates.Contains(bd))batchDates.Add(bd);
                    }
                    if(batchDates.Count>=2)
                        cosCaption=I18n.TrF("<color=#888><i>Updates of {0} & {1} - grab them in the Shop tab.</i></color>",batchDates[0],batchDates[1]);
                    else if(batchDates.Count==1)
                        cosCaption=I18n.TrF("<color=#888><i>Update of {0} - grab them in the Shop tab.</i></color>",batchDates[0]);
                }
                if(txtHomeCosmetics!=null)
                    UIFactory.SetTextRaw(txtHomeCosmetics,
                        cos==null?$"<color=#888><i>{I18n.Tr("Loading...")}</i></color>":
                        cos.Count==0?I18n.Tr("<color=#888><i>None yet.</i></color>"):
                        cosCaption);
                for(int i=0;i<homeCosRows.Count;i++)
                {
                    var row=homeCosRows[i];
                    if(cos==null||i>=cos.Count){if(row.artImg!=null)TrackAnimatedThumb(row.artImg,null,0f);row.root.SetActive(false);continue;}
                    var c=cos[i];
                    // Defense-in-depth (learning #163): the server hides community
                    // face items whose PNG hasn't shipped (catalog_ready=false), but
                    // a client older than the release that flipped catalog_ready could
                    // still receive one — and a face sku with no local sprite renders
                    // as a flat preview_color swatch (the "green square"). Skip it.
                    if((c.kind??"")=="face"&&CustomCosmetics.GetShopSprite(c.sku)==null)
                    {if(row.artImg!=null)TrackAnimatedThumb(row.artImg,null,0f);row.root.SetActive(false);continue;}
                    string col=!string.IsNullOrEmpty(c.previewColor)&&c.previewColor.StartsWith("#")?c.previewColor:"#FFFFFF";
                    // kind/rarity are finite server sets — routed through the
                    // literal-switch helpers so the words are real harvested
                    // keys (Aug 15 item 3; Tr(variable) alone never harvests).
                    string kind=TrKindWord(c.kind);
                    string artistLine=!string.IsNullOrEmpty(c.artistName)?"  "+I18n.TrF("<color=#888>by {0}</color>",HomeSan(c.artistName)):"";
                    // F14: same ISO-date preference as the caption above.
                    string addedDisp=c.dateIso.HasValue?DateFmt.Short(c.dateIso.Value):c.added;
                    string addedTag=!string.IsNullOrEmpty(addedDisp)?$"  <color=#666>{addedDisp}</color>":"";
                    // July 17 round 4: not-yet-opened artist items show as a
                    // tease — the artist sets the real price when opening
                    // sales, so the seed price would mislead.
                    string priceTag=c.onSale?I18n.TrF("<color=#FFD94D>{0}g</color>",c.price):I18n.Tr("<color=#FF9BE0>coming soon!</color>");
                    // F12: same rule as the Shop list — ALL names go through
                    // the runtime Tr lookup (design-Q4 reversal, Aug 15
                    // item 1); a catalogue miss falls back to the raw English.
                    string nameDisp=I18n.Tr(c.name);
                    UIFactory.SetTextRaw(row.txt,
                        $"<color={col}>{HomeSan(nameDisp)}</color>  {priceTag}\n"
                        +$"<color=#8FA3B8>({HomeSan(kind)}, {HomeSan(TrRarity(c.rarity))})</color>{artistLine}{addedTag}");
                    if(row.artImg!=null)
                    {
                        var pSprite=UIFactory.tImage.GetProperty("sprite",BindingFlags.Public|BindingFlags.Instance);
                        var pColor=UIFactory.tImage.GetProperty("color",BindingFlags.Public|BindingFlags.Instance);
                        var sp=CustomCosmetics.GetShopSprite(c.sku);
                        if(sp!=null)
                        {
                            // Real cosmetic art (face PNGs) — white tint, register
                            // animation frames so multi-frame skus cycle on Home too.
                            try{pSprite?.SetValue(row.artImg,sp);pColor?.SetValue(row.artImg,Color.white);}catch{}
                            var frames=CustomCosmetics.GetShopFrames(c.sku,out float fps);
                            TrackAnimatedThumb(row.artImg,frames,fps);
                        }
                        else
                        {
                            // Kinds with no shipped art (titles/trails/colors/nametags)
                            // — a solid preview_color swatch (a null-sprite Image
                            // renders as its color).
                            Color sw;if(!ColorUtility.TryParseHtmlString(col,out sw))sw=new Color(0.4f,0.42f,0.5f);sw.a=1f;
                            try{pSprite?.SetValue(row.artImg,null);pColor?.SetValue(row.artImg,sw);}catch{}
                            TrackAnimatedThumb(row.artImg,null,0f);
                        }
                    }
                    row.root.SetActive(true);
                }
            }
            RefreshChatLog();
        }
        /* Throttled presence refresh while the Home tab is open (learning #62 —
         * tabs only repaint on dirty flips; this is the flip source). */
        private static void MaybeRefreshHomeTab()
        {
            if(currentTab!=TAB_HOME)return;
            if(Time.unscaledTime<homeTabRefreshAt)return;
            homeTabRefreshAt=Time.unscaledTime+15f;
            ApiClient.FetchOnlinePlayers();
        }
