        /// <summary>"finished in ..." span for a completed tournament. Async
        /// brackets run days-to-weeks, sync ones run hours — pick units that
        /// keep both honest at a glance.</summary>
        private static string FormatTournDuration(string kind, int seconds)
        {
            if (seconds <= 0) return null;
            if (kind == "async")
            {
                int days = seconds / 86400;
                if (days >= 14) return I18n.TrF("{0}w {1}d", days / 7, days % 7);
                if (days >= 1) return I18n.TrF("{0}d {1}h", days, (seconds % 86400) / 3600);
            }
            if (seconds >= 3600) return I18n.TrF("{0}h {1}m", seconds / 3600, (seconds % 3600) / 60);
            return I18n.TrF("{0}m", Math.Max(1, seconds / 60));
        }

        private static void AddRecentTournRow(string line, float size, int h)
        {
            var txt = UIFactory.CreateText("r", recentTournPopupRows.transform, "", size,
                C_LABEL, UIFactory.AlignMidLeft, sizeDelta: new Vector2(840, h));
            // Raw write: rows carry user-authored names (#298c).
            UIFactory.SetTextRaw(txt, line);
        }

        private static void RefreshRecentTournamentPlacements()
        {
            if (recentTournPopupPlacements == null) return;
            string mySid = MatchTracker.LocalSteamId;
            if (!string.IsNullOrEmpty(mySid) && mySid != "unknown"
                && ApiClient.CachedPlayerTournaments.TryGetValue(mySid, out var myH) && myH != null
                && myH.participant_count > 0)
            {
                UIFactory.SetTextRaw(recentTournPopupPlacements,
                    I18n.TrF("Your placements:  <color=#FFE580>1stx{0}</color>  <color=#C8C8C8>2ndx{1}</color>  <color=#D4894A>3rdx{2}</color>  <color=#888>(played {3})</color>",
                        myH.winner_count, myH.runner_up_count, myH.third_place_count, myH.participant_count));
            }
            else
            {
                UIFactory.SetTextRaw(recentTournPopupPlacements,
                    I18n.Tr("Your placements: <color=#888>no completed tournaments yet</color>"));
            }
        }

        private static void RefreshRecentTournamentsPopup()
        {
            if (recentTournPopupRows == null) return;
            // The placements request has its own cache and can finish after the
            // detail request, so update this header before the detail-reference
            // fast path returns.
            RefreshRecentTournamentPlacements();
            var data = string.Equals(
                ApiClient.CachedTournHistoryDetailKind,
                recentTournPopupKind,
                StringComparison.OrdinalIgnoreCase)
                ? ApiClient.CachedTournHistoryDetail
                : null;
            if (ReferenceEquals(data, recentTournFilledFrom)) return;
            recentTournFilledFrom = data;
            for (int i = recentTournPopupRows.transform.childCount - 1; i >= 0; i--)
                UnityEngine.Object.Destroy(recentTournPopupRows.transform.GetChild(i).gameObject);
            if (data == null) { AddRecentTournRow(I18n.Tr("<i>Loading...</i>"), 16f, 26); return; }
            // Aug 18's merge-regression rule remains: sync and async histories
            // stay separated. Separation now comes from sub-tab scoping — this
            // popup renders exactly the kind that was active when it opened.
            bool wantAsync = recentTournPopupKind == "async";
            AddRecentTournRow(wantAsync
                ? $"<color=#C9A6FF><b>{I18n.Tr("Async (6-week)")}</b></color>"
                : $"<color=#7FD4FF><b>{I18n.Tr("Sync (weekly)")}</b></color>", 16f, 28);
            bool anyInSection = false;
            foreach (var tt in data)
            {
                if (tt == null || !string.Equals(tt.kind, recentTournPopupKind,
                    StringComparison.OrdinalIgnoreCase)) continue;
                anyInSection = true;
                string dt = tt.ended_at;
                try
                {
                    if (!string.IsNullOrEmpty(dt))
                        dt = DateFmt.FullShortYear(TimeZoneInfo.ConvertTimeFromUtc(
                            DateTime.Parse(tt.ended_at, _INV, System.Globalization.DateTimeStyles.RoundtripKind).ToUniversalTime(),
                            _ResolveTz()));
                }
                catch { }
                string hdr = $"<b><color=#AABBEE>{dt}</color></b>  "
                           + I18n.TrF("<color=#BBB>{0} players</color>", tt.signup_count);
                string dur = FormatTournDuration(tt.kind, tt.duration_seconds);
                if (dur != null)
                    hdr += "  " + I18n.TrF("<color=#8FA3B8>finished in {0}</color>", dur);
                AddRecentTournRow(hdr, 17f, 30);
                if (tt.participants != null)
                {
                    foreach (var p in tt.participants)
                    {
                        if (p == null) continue;
                        string medal = p.placed_rank == 1 ? "<color=#FFE580>#1</color>"
                                     : p.placed_rank == 2 ? "<color=#C8C8C8>#2</color>"
                                     : p.placed_rank == 3 ? "<color=#D4894A>#3</color>"
                                     : "<color=#555>--</color>";
                        string nm = FfaSafeRich(Trunc(p.display_name ?? "?", 28));
                        string elo = p.elo > 0 ? $" <color=#9AA0A6>({p.elo})</color>" : "";
                        string seed = p.seed > 0 ? $"  <color=#666>s{p.seed}</color>" : "";
                        string wl = $"  <color=#7CFF7C>{p.wins}</color><color=#888>-</color><color=#FF8888>{p.losses}</color>";
                        string label = "";
                        if (!string.IsNullOrEmpty(p.result_label))
                        {
                            string lc = p.result_label == "CHAMPION" ? "#FFE580"
                                      : p.result_label.StartsWith("eliminated") ? "#B08585"
                                      : "#8FA3B8";
                            label = $"   <color={lc}>{p.result_label}</color>";
                        }
                        string ff = p.forfeited ? "  <color=#FF6666>[FF]</color>" : "";
                        AddRecentTournRow($"   {medal}  <b>{nm}</b>{elo}{seed}{wl}{label}{ff}", 14f, 22);
                    }
                }
                AddRecentTournRow("", 8f, 10);   // spacer between tournaments
            }
            if (!anyInSection)
                AddRecentTournRow(data.Length == 0
                    ? I18n.Tr("<i>No completed tournaments yet.</i>")
                    : $"   <color=#888>{I18n.Tr("none yet")}</color>",
                    data.Length == 0 ? 16f : 14f, data.Length == 0 ? 26 : 22);
        }

        /// <summary>Screen-space hit test for a ScreenSpaceCamera canvas rect.
        /// ROUNDS' canvas needs WorldToScreenPoint rather than raw coordinates
        /// (#6), which is why this is not a plain Contains().</summary>
        /// <summary>Bug 230, second half: every interactive child of an open
        /// modal popup must carry bypassModalBlock — the popup itself asserts
        /// ModalBlockInput (#200), which otherwise kills its OWN buttons'
        /// ClickHandlers; the bypassed backdrop dismisser was the only LIVE
        /// control, so any click could only close. Walk-and-mark covers every
        /// current and future child; re-run after each row rebuild (the
        /// refresh recreates rows with fresh, unmarked handlers).</summary>
        internal static void MarkPopupChildrenInteractive(GameObject popupRoot)
        {
            try
            {
                if (popupRoot == null) return;
                foreach (var ch in popupRoot.GetComponentsInChildren<ClickHandler>(true))
                    if (ch != null) ch.bypassModalBlock = true;
            }
            catch { }
        }

        private static bool PointerInsideRect(RectTransform rt)
        {
            if (rt == null) return false;
            var corners = new Vector3[4];
            rt.GetWorldCorners(corners);
            // Canvas lives in UIModule, which this csproj deliberately does not
            // reference (#15) — reach it through UIFactory's cached Type, the
            // same way ClickHandler resolves its own canvas camera.
            Camera cam = null;
            try
            {
                var cc = overlayCanvasGO != null && UIFactory.tCanvas != null
                    ? overlayCanvasGO.GetComponent(UIFactory.tCanvas) : null;
                if (cc != null)
                    cam = UIFactory.tCanvas.GetProperty("worldCamera",
                        BindingFlags.Public | BindingFlags.Instance)?.GetValue(cc) as Camera;
            }
            catch { }
            // Bug 230: NO Camera.main fallback. The overlay canvas is
            // ScreenSpaceOverlay (EnsureOverlayCanvas sets renderMode 0), so
            // worldCamera is LEGITIMATELY null and GetWorldCorners already
            // returns screen pixels — projecting those through the GAME
            // camera produced a garbage rect, the inside-test failed for
            // every click, and the backdrop dismissed clicks that were ON
            // the content ("clicking a bet just closes the menu"). A null
            // cam correctly falls through to corners-as-screen below; only
            // a real ScreenSpaceCamera canvas needs projection (#6), and
            // this helper only ever serves the overlay canvas.
            Vector2 min, max;
            if (cam != null)
            {
                Vector3 c0 = cam.WorldToScreenPoint(corners[0]);
                Vector3 c2 = cam.WorldToScreenPoint(corners[2]);
                min = new Vector2(Mathf.Min(c0.x, c2.x), Mathf.Min(c0.y, c2.y));
                max = new Vector2(Mathf.Max(c0.x, c2.x), Mathf.Max(c0.y, c2.y));
            }
            else
            {
                min = new Vector2(Mathf.Min(corners[0].x, corners[2].x), Mathf.Min(corners[0].y, corners[2].y));
                max = new Vector2(Mathf.Max(corners[0].x, corners[2].x), Mathf.Max(corners[0].y, corners[2].y));
            }
            Vector2 p = Input.mousePosition;
            return p.x >= min.x && p.x <= max.x && p.y >= min.y && p.y <= max.y;
        }
        public static void ShowInfoPopup(string title, string body)
        {
            try
            {
                HideInfoPopup();
                EnsureOverlayCanvas();
                infoPopupGO = new GameObject("CR_InfoPopup");
                infoPopupGO.hideFlags = HideFlags.HideAndDontSave;
                infoPopupGO.transform.SetParent(overlayCanvasGO.transform, false);
                var rt = infoPopupGO.AddComponent<RectTransform>();
                rt.anchorMin = Vector2.zero; rt.anchorMax = Vector2.one;
                rt.offsetMin = Vector2.zero; rt.offsetMax = Vector2.zero;

                var bd = UIFactory.CreatePanel("BD", infoPopupGO.transform, new Color(0f, 0f, 0f, 0.55f));
                var bdRT = bd.GetComponent<RectTransform>();
                bdRT.anchorMin = Vector2.zero; bdRT.anchorMax = Vector2.one;
                bdRT.offsetMin = Vector2.zero; bdRT.offsetMax = Vector2.zero;
                var bdImg = bd.GetComponent(UIFactory.tImage);
                if (bdImg != null) UIFactory.tImage.GetProperty("raycastTarget", BindingFlags.Public | BindingFlags.Instance)?.SetValue(bdImg, true);
                var bdClick = bd.AddComponent<ClickHandler>();
                bdClick.bypassModalBlock = true;
                bdClick.onClick = () => { if (ClickGuard.Claim(bd)) HideInfoPopup(); };

                var box = UIFactory.CreatePanel("Box", infoPopupGO.transform, new Color(0.10f, 0.12f, 0.16f, 0.97f));
                var boxRT = box.GetComponent<RectTransform>();
                boxRT.anchorMin = new Vector2(0.5f, 0.5f);
                boxRT.anchorMax = new Vector2(0.5f, 0.5f);
                boxRT.pivot = new Vector2(0.5f, 0.5f);
                // Clamp to the live canvas height (Codex review find): the
                // width-matched scaler gives a 32:9 window only ~540 vertical
                // units, so a fixed 640 box would clip top and bottom — the
                // very overflow class this popup exists to fix. The body
                // ScrollView absorbs the lost height.
                // x2 pass (Sid): the popup and its text were half this size. Height is
                // still clamped to the live canvas — a width-matched scaler leaves a 32:9
                // window only ~540 vertical units, and the body ScrollView absorbs the rest.
                float popupH = 1010f;
                try
                {
                    var canvasRT = overlayCanvasGO.GetComponent<RectTransform>();
                    if (canvasRT != null && canvasRT.rect.height > 200f)
                        popupH = Mathf.Min(1010f, canvasRT.rect.height - 40f);
                }
                catch { }
                boxRT.sizeDelta = new Vector2(960, popupH);
                UIFactory.AddVLG(box, spacing: 10, padL: 30, padR: 30, padT: 22, padB: 20);

                UIFactory.CreateText("IPTitle", box.transform, title ?? "",
                    34f, C_GOLD, UIFactory.AlignMidCenter, sizeDelta: new Vector2(900, 46));
                var sv = UIFactory.CreateScrollView("IPScroll", box.transform, spacing: 0);
                UIFactory.AddLE(sv.scrollGO, flexH: 1, prefH: 880);
                var bodyTxt = UIFactory.CreateText("IPBody", sv.content.transform, body ?? "",
                    24f, C_LABEL, UIFactory.AlignTopLeft, sizeDelta: new Vector2(890, 860));
                UIFactory.SetWordWrap(bodyTxt, true);
                UIFactory.SetTextAutoHeight(bodyTxt);
                UIFactory.CreateText("IPHint", box.transform, "<color=#888>click anywhere to close</color>",
                    22f, C_DIM, UIFactory.AlignMidCenter, sizeDelta: new Vector2(900, 34));
            }
            catch (Exception ex) { Plugin.Log.LogWarning($"[INFO-POPUP] show: {ex.Message}"); }
        }

        public static void HideInfoPopup()
        {
            try
            {
                if (infoPopupGO != null)
                {
                    UnityEngine.Object.Destroy(infoPopupGO);
                    infoPopupGO = null;
                }
            }
            catch (Exception ex) { Plugin.Log.LogWarning($"[INFO-POPUP] destroy: {ex.Message}"); }
        }

        // Filters (0=All,1=Ranked,2=Casual) whose tier fetch has COMPLETED this
        // session. Lets RefreshCardStats tell "tiers legitimately empty" apart
        // from "fetch never landed" (failed / raced the panel build) so it can
        // self-heal instead of showing blank tiers until a manual Refresh (#32).
        private static readonly HashSet<int> _tierFiltersLoaded = new HashSet<int>();
        private static float _tierAutoFetchAt = -999f;
        private static float _seriesAutoFetchAt = -999f;
        private static float _cardStatsAutoFetchAt = -999f;

        // Load the player's saved tiers for the active filter, repopulate
        // cardTierMap, mark dirty so the rows re-render.
        public static void LoadCardTiersForCurrentFilter()
        {
            string filterStr = cardFilter == 1 ? "ranked" : cardFilter == 2 ? "casual" : "all";
            int filterIdx = cardFilter;
            ApiClient.FetchCardTiers(MatchTracker.LocalSteamId, filterStr, (loaded) =>
            {
                // Drop the existing entries for this filter, replace with loaded.
                var keep = new Dictionary<string, string>();
                foreach (var kv in cardTierMap)
                {
                    if (!kv.Key.StartsWith($"{filterIdx}|")) keep[kv.Key] = kv.Value;
                }
                cardTierMap = keep;
                foreach (var kv in loaded)
                {
                    cardTierMap[CardTierKey(filterIdx, kv.Key)] = kv.Value;
                }
                _tierFiltersLoaded.Add(filterIdx);
                dirty = true;
            });
        }

        // Cycle one card's tier and write through to the server. Filter is
        // tied to the current cardFilter index (0=All,1=Ranked,2=Casual).
        // -- Achievements Tab ------------------------------------
