                    ApiClient.SetAppearOffline(id, st.appear_offline, (ok, resp) =>
                    {
                        if (!ok) CompetitiveUI.ShowNotification("Couldn't change Appear offline - try again", Color.yellow, 3f);
                        dirty = true;
