        /* Aug 6 item 4: avg DPS = damage dealt / game length. A row whose damage
         * column is NULL shows a DASH rather than "0.0 dps" (#257 — 0 is a real
         * value here: a player can genuinely deal no damage).
         *
         * Aug 7 review find 4: the cell is gated on DAMAGE, not on the row's
         * shots/blocks. A melee, body-damage, trap or Pacifist build finishes a
         * game with zero bullets and zero blocks and still deals real damage, so
         * the old hy/ho gate hid a fully populated timeline from exactly the
         * builds whose DPS is most worth seeing. The dash keeps the hy/ho gate,
         * though: it exists only so a row that ALREADY shows combat telemetry
         * doesn't lose a column, and widening it would stamp a dash across every
         * pre-telemetry row in the history. */
        /* The dash case goes through the SAME TrF template with "-" as the hole
         * value, rather than its own Tr("- dps") literal: one catalogue key
         * instead of two, and a bare "- dps" fragment is close to the
         * extractor's <3-letter rejection floor (#295c). */
        string dy="",dorp="";
        bool dmgYou=m.player_damage_dealt>=0,dmgOpp=m.opp_damage_dealt>=0;
        if(dmgYou||!string.IsNullOrEmpty(hy))
            dy="<color=#99B3E6>"+I18n.TrF("{0} dps",
                dmgYou&&m.duration_seconds>0
                    ?(m.player_damage_dealt/(float)m.duration_seconds).ToString("F1",_INV):"-")+"</color>";
        if(dmgOpp||!string.IsNullOrEmpty(ho))
            dorp="<color=#E69988>"+I18n.TrF("{0} dps",
                dmgOpp&&m.duration_seconds>0
                    ?(m.opp_damage_dealt/(float)m.duration_seconds).ToString("F1",_INV):"-")+"</color>";
        /* Which sample grid each side's timeline sits on follows the REPORTER,
         * never the viewer — see ViewerWasReporter.
         * F7 (Codex r3): decimated timelines have variable stride — when the
         * row carries a real duration, the honest interval is
         * duration/n over the derivative buckets present (DpsStepFor);
         * the reporter-grid cadence survives only as the no-duration fallback. */
        bool viewerReported=ViewerWasReporter(m);
        float dpsStepYou=DpsStepFor(m.player_damage_timeline,m.duration_seconds,viewerReported?DPS_STEP_LOCAL:DPS_STEP_PEER);
        float dpsStepOpp=DpsStepFor(m.opp_damage_timeline,m.duration_seconds,viewerReported?DPS_STEP_PEER:DPS_STEP_LOCAL);
        UIFactory.SetTextRaw(row.txtHitYou,hy);UIFactory.SetTextRaw(row.txtBlockYou,by);UIFactory.SetTextRaw(row.txtKpsYou,ky);UIFactory.SetTextRaw(row.txtDpsYou,dy);UIFactory.SetTextRaw(row.txtHitOpp,ho);UIFactory.SetTextRaw(row.txtBlockOpp,bo);UIFactory.SetTextRaw(row.txtKpsOpp,ko);UIFactory.SetTextRaw(row.txtDpsOpp,dorp);/* Review [8]: only register a hover zone when the cell actually renders text — an EMPTY element has preferredWidth 0, which ResolveHoverSource treats as "no fraction" = FULL-width region: an invisible hover trap across the row. */if(!string.IsNullOrEmpty(hy))RegisterPairGraphRectFor(row.txtHitYou,m.player_hit_timeline,false,false,m.point_times,m.point_timeline,null,null,m.duration_seconds);if(!string.IsNullOrEmpty(by))RegisterPairGraphRectFor(row.txtBlockYou,m.player_block_timeline,true,false,m.point_times,m.point_timeline,null,null,m.duration_seconds);if(!string.IsNullOrEmpty(ho))RegisterPairGraphRectFor(row.txtHitOpp,m.opp_hit_timeline,false,true,m.point_times,m.point_timeline,null,null,m.duration_seconds);if(!string.IsNullOrEmpty(bo))RegisterPairGraphRectFor(row.txtBlockOpp,m.opp_block_timeline,true,true,m.point_times,m.point_timeline,null,null,m.duration_seconds);/* Aug 7 item 3d: hovering a DPS cell pops that side's per-second damage line. ONE side per region, never the pair: the two series come off different emitters (a 5s own-seat grid vs a ~3s peer heartbeat) and the DPS chart drives both its lines from a single step, so pairing them would stretch one line 1.67x across the time axis AND scale its values wrong. Each cell registers its own series in the MY slot so the popup's blue subject label matches the blue line it names. CumulativeToDps returns an EMPTY series for a missing or one-sample timeline, and the register call early-returns on that, so a row with no damage timeline registers nothing even though the cell renders its dash. */if(!string.IsNullOrEmpty(dy))RegisterDpsGraphRectFor(row.txtDpsYou,CumulativeToDps(m.player_damage_timeline,dpsStepYou),null,m.point_times,m.point_timeline,dpsStepYou,null,I18n.Tr("you"),m.duration_seconds);if(!string.IsNullOrEmpty(dorp))RegisterDpsGraphRectFor(row.txtDpsOpp,CumulativeToDps(m.opp_damage_timeline,dpsStepOpp),null,m.point_times,m.point_timeline,dpsStepOpp,null,FfaSafeRich(Trunc(string.IsNullOrEmpty(m.opponent_name)?I18n.Tr("opponent"):m.opponent_name,18)),m.duration_seconds);}/* Item 4: hovering the W/L score pops a line graph of the scoring history. */RegisterScoreGraphRectFor(row.txtResult,m.point_timeline,m.won);/* July 22 item 6: click-to-copy game ID. */row.currentMatchId=m.match_id;if(row.btnId!=null)row.btnId.SetActive(!string.IsNullOrEmpty(m.match_id));UIFactory.SetText(row.txtXP,m.xp_gained>0?(m.gold_gained>0?$"+{m.xp_gained}xp <color=#FFD94D>+{m.gold_gained}g</color>":$"+{m.xp_gained}xp"):"");string dt="";try{if(!string.IsNullOrEmpty(m.ended_at)&&m.ended_at.Length>=10)dt=DateFmt.Short(DateTime.Parse(m.ended_at));}catch{}UIFactory.SetText(row.txtDate,dt);/* Round-2 HIGH: the bodies are built FIRST because whether a build exists decides what the cell says. A row with no cards but a stored build used to render an empty cell and register no hover, so its build had no surface at all. */string myBuildBody=CardsPlusBuildBody(m.cards_display,m.player_end_stats);string oppBuildBody=CardsPlusBuildBody(m.opp_cards_display,m.opp_end_stats);UIFactory.SetTextRaw(row.txtCards,HistoryCardCellText(I18n.Tr("Cards:"),m.cards_display,myBuildBody));UIFactory.SetTextRaw(row.txtOppCards,HistoryCardCellText(I18n.Tr("Opp:")+"  ",m.opp_cards_display,oppBuildBody));if(rCardModeTxt!=null)UIFactory.SetText(rCardModeTxt,HistoryCardModeLabel());if(cCardModeTxt!=null)UIFactory.SetText(cCardModeTxt,HistoryCardModeLabel());/* Aug 12 item 1: one hover, cards AND the end-of-game build. CardsPlusBuildBody returns NULL for a row with no stored build (every match before this shipped), and a null bodyOverride is exactly the pre-existing call — so old rows keep the identical tooltip and CompetitiveUI's memoised comma-split body. */RegisterHoverRectFor(row.txtCards,m.cards_display,false,null,myBuildBody);RegisterHoverRectFor(row.txtOppCards,m.opp_cards_display,true,null,oppBuildBody);row.root.SetActive(true);}

        // Resolve a TMP text component's screen-space rect via its parent
        // chain. Handles both Screen Space - Overlay (corners are screen
        // coords already) and Screen Space - Camera (need WorldToScreenPoint
        // via the canvas's worldCamera). Caches nothing — runs per FillRow.
        // Bug #61: shared resolver for hover-region registration. Extracts the
        // element's RectTransform, its canvas camera (null on the Overlay canvas,
        // where world corners ARE screen coords), the rendered-text width fraction
        // (#22 / learning #90 — the card text lives in a fixed-width box but only
        // fills part of it; registering the whole box made the empty right side a
        // dead hover zone), and a registration-time rect as fallback. The hit test
        // in CompetitiveUI recomputes the rect LIVE from these pieces each frame,
        // so scrolling the history ScrollView can no longer desync the hover
        // region from its row (bug #61 — regions used to be baked once per
        // refresh and drifted as content moved).
        private static bool ResolveHoverSource(object txt, out RectTransform rt, out Camera cam,
                                               out float frac, out Rect rect, out RectTransform clip)
        {
            rt = null; cam = null; frac = -1f; rect = default(Rect); clip = null;
            try
            {
                var comp = txt as Component;
                if (comp == null) return false;
                rt = comp.GetComponent<RectTransform>();
                if (rt == null) return false;
                bool isOverlay = true;
                Transform t = rt;
                while (t != null)
                {
                    // UIFactory.CreateScrollView names its masked child "Viewport";
                    // the nearest one bounds where this row is actually visible.
                    if (clip == null && t.gameObject.name == "Viewport")
                        clip = t as RectTransform;
                    var canvasComp = t.GetComponent(UIFactory.tCanvas);
                    if (canvasComp != null)
                    {
                        var bf = BindingFlags.Public | BindingFlags.Instance;
                        var rmProp = UIFactory.tCanvas.GetProperty("renderMode", bf);
                        if (rmProp != null)
                        {
                            int rm = (int)rmProp.GetValue(canvasComp);
                            isOverlay = (rm == 0);
                            if (!isOverlay)
                            {
                                var wcProp = UIFactory.tCanvas.GetProperty("worldCamera", bf);
                                cam = (wcProp?.GetValue(canvasComp) as Camera) ?? Camera.main;
                            }
                        }
                        break;
                    }
                    t = t.parent;
                }
                if (!isOverlay && cam == null) return false;
                // Rendered-text width fraction. The element is left-aligned
                // (AlignTopLeft) so the live rect keeps the left edge and only
                // trims the right. prefLocal and rect.width are both local units,
                // so the ratio maps cleanly onto screen width at any canvas scale.
                try
                {
                    var prefProp = comp.GetType().GetProperty("preferredWidth",
                                       BindingFlags.Public | BindingFlags.Instance);
                    float localW = rt.rect.width;
                    if (prefProp != null && localW > 0f)
                    {
                        float prefLocal = (float)prefProp.GetValue(comp);
                        if (prefLocal > 0f) frac = Mathf.Clamp01(prefLocal / localW);
                    }
                }
                catch { /* keep full-width region on any reflection miss */ }
                rect = CompetitiveUI.LiveRegionRect(rt, cam, frac, clip, default(Rect));
                return true;
            }
            catch { return false; }
        }

        // ── Aug 12 item 1: end-of-game build stats inside the card tooltips ──
        // TabStatsOverlay.DecodeBuildStats owns BOTH the labels (the hold-Tab
        // overlay's own localised ones) and the value formatting, so nothing
        // here names a stat and this file therefore cannot mislabel one. It
        // returns an EMPTY list for a row with no build — the column is NULL
        // for every match recorded before this shipped — or for a wire version
        // this client cannot decode, and every caller below then renders the
        // card list exactly as it did before. That is what makes an old row
        // look deliberate rather than broken: nothing is added, nothing is
        // replaced by a dash.
        //
        // COLUMN BUDGETS (#245 — measured, not guessed). The SHARED tooltip
        // (CompetitiveUI.DrawCardHoverTooltip) is a hard 260px box: its body
        // rect is 244px at fontSize 12, and its HEIGHT comes from the '\n'
        // COUNT alone. So a line long enough to WRAP is drawn past the bottom
        // of the box and clipped away — text silently missing (#292/#237),
        // which is the one failure mode that must not be possible here.
        // 34 chars x ~6.3px (IMGUI Arial 12, mixed case) = ~214px, ~30px slack.
        // The widest single cell any shipped locale can produce is 27 chars
        // ("Kulors bromseffekt" (sv, 18) + space + "100.00"), measured straight
        // off I18nCatalogues — so one cell always fits a line on its own, and
        // the packer below can only ever degrade to FEWER columns, never to a
        // wrapped line. The FFA tab draws its OWN 470px tooltip and measures it
        // with GUIStyle.CalcHeight, so it can take a wider line safely.
        private const int BUILD_TIP_NARROW_COLS = 34;
        private const int BUILD_TIP_WIDE_COLS = 56;

        /// <summary>Lay a stored build-stat wire out as tooltip lines, packing
        /// as many stats per line as <paramref name="budgetChars"/> allows.
        /// Returns "" (never null) when there is no build to show.</summary>
        private static string BuildStatsTipBlock(string wire, int budgetChars, string indent = "")
        {
            if (string.IsNullOrEmpty(wire)) return "";
            List<TabStatsOverlay.BuildStatLine> rows;
            try { rows = TabStatsOverlay.DecodeBuildStats(wire); }
            catch { return ""; }
            if (rows == null || rows.Count == 0) return "";
            if (indent == null) indent = "";
            int budget = Math.Max(12, budgetChars - indent.Length);
            var sb = new StringBuilder(rows.Count * 40);
            // Names WHEN the snapshot was taken. It is load-bearing copy, not
            // decoration: HP is terminal health, so the loser's row honestly
            // reads "0/100" and without this header that reads as a bug.
            sb.Append(indent).Append("<color=#66809A>").Append(I18n.Tr("Build at game end")).Append("</color>");
            int lineLen = 0;
            for (int i = 0; i < rows.Count; i++)
            {
                string label = rows[i].label ?? "";
                string val = rows[i].value ?? "";
                // Budget on the PLAIN text — rich-text tags occupy no width.
                int cell = label.Length + 1 + val.Length;
                if (lineLen == 0 || lineLen + 3 + cell > budget)
                {
                    sb.Append('\n').Append(indent);
                    lineLen = 0;
                }
                else
                {
                    sb.Append("   ");
                    lineLen += 3;
                }
                sb.Append("<color=#8FA3B8>").Append(label).Append("</color> <b>").Append(val).Append("</b>");
                lineLen += cell;
            }
            return sb.ToString();
        }

        /// <summary>The bullet card list CompetitiveUI derives from a comma
        /// line, reproduced here so a body carrying BOTH cards and a build can
        /// be handed over as one pre-formatted override. Kept byte-identical to
        /// DrawCardHoverTooltip's own derivation (same bullet, same
        /// CardTextLocalizer lookup) so the tooltip does not change appearance
        /// depending on which of the two paths built it.</summary>
        private static string CardsBulletBody(string cardsDisplay)
        {
            if (string.IsNullOrEmpty(cardsDisplay)) return "";
            var sb = new StringBuilder(cardsDisplay.Length + 32);
            string[] cards;
            try { cards = cardsDisplay.Split(','); }
            catch { cards = new[] { cardsDisplay }; }
            foreach (var c in cards)
            {
                string name = (c ?? "").Trim();
                if (name.Length == 0) continue;
                string disp = null;
                try { disp = CardTextLocalizer.PrettyName(name, name); } catch { }
                if (sb.Length > 0) sb.Append('\n');
                sb.Append("• ").Append(disp ?? name);
            }
            return sb.ToString();
        }

        /// <summary>Body override for a My Stats history row's card cell:
        /// the full card list PLUS the end-of-game build.
        ///
        /// Returns NULL when there is no build to add, which is the point —
        /// the caller then passes no override at all and CompetitiveUI keeps
        /// using its own memoised comma-split body (#162: that memo is why the
        /// pre-build path costs nothing per Repaint). So rows recorded before
        /// this feature keep byte-identical rendering AND their old perf.
        ///
        /// It does NOT require cards. It used to, with a comment claiming an
        /// empty card cell "could only ever attach to an invisible element" —
        /// a self-fulfilling claim (#351), since the cell was empty precisely
        /// because this path refused to give it anything to say. A player who
        /// finished a game without picking a card has a perfectly valid stored
        /// build, and that was the only surface it could ever have had
        /// (round-2 HIGH). The caller now renders an explicit "no cards +
        /// hover for build" line for exactly this case — see
        /// HistoryCardCellText for why the visible text is load-bearing and
        /// not decoration.</summary>
        private static string CardsPlusBuildBody(string cardsDisplay, string endStats)
        {
            string build = BuildStatsTipBlock(endStats, BUILD_TIP_NARROW_COLS);
            if (build.Length == 0) return null;
            string cards = CardsBulletBody(cardsDisplay);
            // Cards FIRST, build second — not just for reading order. The
            // drawer's overflow rule (CompetitiveUI.EnsureTipLayout) drops from
            // the end and skips card bullets, so this ordering is what makes
            // the build the part that gets elided in a window too small to hold
            // everything.
            return cards.Length > 0 ? cards + "\n" + build : build;
        }

        /// <summary>Text for a My Stats history row's card cell.
        ///
        /// Normally the card line, exactly as before. When the row has NO
        /// cards but DOES carry a decodable build (`body` non-null), it
        /// renders an explicit "no cards" line plus the hover hint instead of
        /// the empty string it used to render.
        ///
        /// That line is load-bearing, not decoration. RegisterHoverRectFor
        /// will now happily register a body-only region, but the region's
        /// WIDTH comes from the element's rendered text, and an empty element
        /// measures 0 — which ResolveHoverSource turns into a full-width
        /// invisible hover trap. Giving the cell real text is what makes the
        /// zone both hittable and bounded to the words it belongs to. The hint
        /// wording mirrors the FFA tab's, which is the surface players already
        /// know this gesture from.
        ///
        /// `label` arrives already translated (the caller's literal sits at
        /// its own Tr call site) and callers write the result Raw, so nothing
        /// here re-enters the catalogue.</summary>
        private static string HistoryCardCellText(string label, string cardsDisplay, string body)
        {
            if (!string.IsNullOrEmpty(cardsDisplay))
                return $"        {label} {(_historyCardsFull ? cardsDisplay : FormatCardLine(cardsDisplay))}";
            if (string.IsNullOrEmpty(body)) return "";
            return $"        {label} " + I18n.Tr("<color=#666>no cards</color>  <color=#556270>(hover for build)</color>");
        }

        /// <summary>Register a card-tooltip hover zone over `txt`.
        ///
        /// The gate is "cards OR body", matching CompetitiveUI's own
        /// (RegisterCardHoverRegion refuses only when BOTH are empty). It used
        /// to demand a non-empty card line, which made a build-only row
        /// unreachable on every surface that has one (round-2 HIGH).
        ///
        /// CALLER CONTRACT, and the reason the relaxation is not enough on its
        /// own: ResolveHoverSource derives the region's width from the
        /// element's RENDERED text (#90). An element rendering nothing has
        /// preferredWidth 0, which it reads as "no fraction" and falls back to
        /// the FULL element width — an invisible hover trap across the whole
        /// row (the 1v1 review [8] bug). So a caller passing a bodyOverride for
        /// a cell with no card text must give that cell something visible to
        /// say first; every caller in this file does.</summary>
        private static void RegisterHoverRectFor(object txt, string fullLine, bool isOpponent,
                                                 string titleOverride = null, string bodyOverride = null)
        {
            if (txt == null) return;
            if (string.IsNullOrEmpty(fullLine) && string.IsNullOrEmpty(bodyOverride)) return;
            try
            {
                RectTransform rt; Camera cam; float frac; Rect rect; RectTransform clip;
                if (!ResolveHoverSource(txt, out rt, out cam, out frac, out rect, out clip)) return;
                CompetitiveUI.RegisterCardHoverRegion(rect, fullLine, isOpponent, titleOverride, bodyOverride, rt, cam, frac, clip, txt);
            }
            catch { /* silent — tooltip is opt-in cosmetic */ }
        }

        /// <summary>Item 4: register the score text as a hover region that pops the
        /// scoring-history line graph. Same screen-rect resolution as the card
        /// hover (Overlay vs ScreenSpaceCamera canvases, learning #6), trimmed to
        /// the rendered text width (learning #90).</summary>
        private static void RegisterScoreGraphRectFor(object txt, string timeline, bool won)
        {
            if (txt == null || string.IsNullOrEmpty(timeline) || timeline.IndexOf(':') < 0) return;
            try
            {
                RectTransform rt; Camera cam; float frac; Rect rect; RectTransform clip;
                if (!ResolveHoverSource(txt, out rt, out cam, out frac, out rect, out clip)) return;
                CompetitiveUI.RegisterScoreGraphRegion(rect, timeline, won, rt, cam, frac, clip, txt);
            }
            catch { }
        }

        // July 21 item 2: hover the FPS tag → both players' fps timelines on one
        // chart (same live-rect mechanics as the score graph). July 22 item 1:
        // optional point-marker data + a my-cadence override (2v2 series are 3s).
        private static void RegisterTeleGraphRectFor(object txt, string mySeries, string oppSeries, bool isPing,
                                                     string pointTimes = null, string pointTimeline = null,
                                                     float myStep = 0f,
                                                     RectTransform outerClip = null, string subjectLabel = null,
                                                     int durationSeconds = 0)
        {
            if (txt == null || (string.IsNullOrEmpty(mySeries) && string.IsNullOrEmpty(oppSeries))) return;
            try
            {
                RectTransform rt; Camera cam; float frac; Rect rect; RectTransform clip;
                if (!ResolveHoverSource(txt, out rt, out cam, out frac, out rect, out clip)) return;
                // F7 (Codex r3): the row's real match length rides along so
                // the chart scales decimated (variable-stride) timelines
                // across the whole game — same contract as the pair graphs.
                CompetitiveUI.RegisterFpsGraphRegion(rect, mySeries, oppSeries, isPing, rt, cam, frac, clip, txt,
                                                     pointTimes, pointTimeline, myStep, outerClip, subjectLabel,
                                                     durationSeconds);
            }
            catch { }
        }

        // Aug 7 item 3d: hover a DPS cell → that side's damage-per-second line.
        // Copy of RegisterTeleGraphRectFor minus isPing. The series must ALREADY
        // be differenced (CumulativeToDps) — the chart plots values, not slopes —
        // and myStep is the cadence that produced it, which drives BOTH lines
        // here, so a caller mixing two cadences into one region would misplot one.
        private static void RegisterDpsGraphRectFor(object txt, string mySeries, string oppSeries,
                                                    string pointTimes = null, string pointTimeline = null,
                                                    float myStep = 0f,
                                                    RectTransform outerClip = null, string subjectLabel = null,
                                                    int durationSeconds = 0)
        {
            if (txt == null || (string.IsNullOrEmpty(mySeries) && string.IsNullOrEmpty(oppSeries))) return;
            try
            {
                RectTransform rt; Camera cam; float frac; Rect rect; RectTransform clip;
                if (!ResolveHoverSource(txt, out rt, out cam, out frac, out rect, out clip)) return;
                CompetitiveUI.RegisterDpsGraphRegion(rect, mySeries, oppSeries, rt, cam, frac, clip, txt,
                                                     pointTimes, pointTimeline, myStep, outerClip, subjectLabel,
                                                     durationSeconds);   // F7 (Codex r3)
            }
            catch { }
        }

        // July 22 item 1: hover a Hit%/Block% tag → that player's cumulative
        // pair chart (fired-vs-hit / dmg-vs-blocks) with point markers.
        // Bug 181 item 2: durationSeconds (the row's real match length) rides
        // along so the chart scales its samples across the whole game —
        // correct for both old fixed-cadence and new decimated timelines.
        private static void RegisterPairGraphRectFor(object txt, string pairSeries, bool isBlock, bool subjectIsOpp,
                                                     string pointTimes, string pointTimeline,
                                                     RectTransform outerClip = null, string subjectLabel = null,
                                                     int durationSeconds = 0)
        {
            if (txt == null || string.IsNullOrEmpty(pairSeries)) return;
            try
            {
                RectTransform rt; Camera cam; float frac; Rect rect; RectTransform clip;
                if (!ResolveHoverSource(txt, out rt, out cam, out frac, out rect, out clip)) return;
                CompetitiveUI.RegisterPairGraphRegion(rect, pairSeries, isBlock, subjectIsOpp, rt, cam, frac, clip, txt,
                                                      pointTimes, pointTimeline, outerClip, subjectLabel,
                                                      durationSeconds);
            }
            catch { }
        }

        // July 22 item 7: hover a 2v2 player's telemetry cell → their combo popup.
        private static void RegisterComboGraphRectFor(object txt, ApiClient.TeamPlayerTele tele, string playerName, bool isRightTeam)
        {
            if (txt == null || tele == null) return;
            try
            {
                RectTransform rt; Camera cam; float frac; Rect rect; RectTransform clip;
                if (!ResolveHoverSource(txt, out rt, out cam, out frac, out rect, out clip)) return;
                CompetitiveUI.RegisterPlayerComboRegion(rect, tele.fps_timeline, tele.ping_timeline,
                    tele.hit_timeline, tele.block_timeline, playerName, isRightTeam, rt, cam, frac, clip, txt);
            }
            catch { }
        }

        // July 22 item 7: one 2v2 telemetry cell — "Name 142fps 23ms Hit 42% Blk 31%",
        // team-tinted; degrades to fps-only for old-client peers; empty when no data.
        private static void FillTeleCell(object txt, ApiClient.TeamSeriesMatch m, ApiClient.TeamSeriesSlot sl, bool right, string hexOverride = null)
        {
            string s = "";
            ApiClient.TeamPlayerTele tele = null;
            if (sl != null)
            {
                // hexOverride = the stamped team-identity hex (readability-floored
                // upstream); null keeps the positional light-blue/orange defaults.
                string hex = hexOverride ?? (right ? "#FFB086" : "#8CCFFF");
                string sid = sl.steam_id ?? "";
                if (m.telemetry_by_player != null) m.telemetry_by_player.TryGetValue(sid, out tele);
                int favg = 0;
                if (m.fps_by_player != null) m.fps_by_player.TryGetValue(sid, out favg);
                string nm = sl.name ?? "?";
                if (nm.Length > 10) nm = nm.Substring(0, 10);
                if (tele != null)
                {
                    float hp = tele.bullets_fired > 0 ? 100f * tele.bullets_hit / tele.bullets_fired : 0f;
                    float bp = tele.blocks_activated > 0 ? 100f * tele.blocks_successful / tele.blocks_activated : 0f;
                    string fpsPart = favg > 0 ? favg + "fps " : "";
                    string pingPart = tele.ping_avg > 0 ? tele.ping_avg + "ms " : "";
                    s = $"<color={hex}>{nm}</color> <color=#8FA3B8>{fpsPart}{pingPart}Hit {hp:F0}% Blk {bp:F0}%</color>";
                }
                else if (favg > 0)
                {
                    s = $"<color={hex}>{nm}</color> <color=#8FA3B8>{favg}fps</color>";
                }
            }
            UIFactory.SetText(txt, s);
            if (tele != null) RegisterComboGraphRectFor(txt, tele, sl.name ?? "?", right);
        }

        // Compact a comma-separated card-name list into bracketed chips like
        // [MA][EM][EC][BS] for the F5 history rows. Each chip is the first two
        // letters of the card name, upper-cased. Vanilla ROUNDS shows the same
        // 2-letter glyph in the in-game corner indicator so the abbreviation
        // is already a familiar mental model for players. Original full names
        // still flow through cards_display in the API response (the leaderboard
        // detail panel + the 2v2 series viewer both keep the long form), so
        // we lose no information — just compress the row.
        private static string FormatCardLine(string raw)
        {
            if (string.IsNullOrEmpty(raw)) return "";
            var sb = new System.Text.StringBuilder();
            foreach (var part in raw.Split(','))
            {
                string name = part.Trim();
                if (string.IsNullOrEmpty(name)) continue;
                // Strip leading "Common/Uncommon/..." rarity prefix the server
                // sometimes pre-attaches in <color> markup; we want just the
                // card's display name for the abbreviation.
                int lt = name.IndexOf('>');
                if (lt >= 0 && lt < name.Length - 1) name = name.Substring(lt + 1);
                int gt = name.IndexOf('<');
                if (gt > 0) name = name.Substring(0, gt);
                name = name.Trim();
                if (name.Length == 0) continue;
                string ab = name.Length >= 2 ? name.Substring(0, 2).ToUpperInvariant()
                                              : name.ToUpperInvariant();
                sb.Append('[').Append(ab).Append("] ");
            }
            return sb.ToString().TrimEnd();
        }
        // FPS tag — rendered in its own dedicated text field to the right of the
        // opponent name. Player side uses the same blue as the cards line, opponent
        // uses the matching red, mirroring how each side reads in the cards/opp panel.
        private static string BuildFpsTag(ApiClient.MatchHistoryEntry m){if(m==null)return"";int p=m.player_fps_avg,o=m.opponent_fps_avg;if(p<=0&&o<=0)return"";string pStr=p>0?p.ToString():"-";string oStr=o>0?o.ToString():"-";return$"<color=#888>FPS:</color> <color=#99B3E6>{pStr}</color> <color=#888>/</color> <color=#E69988>{oStr}</color>";}
        // July 22 item 3: latency is its OWN tag (separate hover graph).
        private static string BuildPingTag(ApiClient.MatchHistoryEntry m){if(m==null)return"";int pp=m.player_ping_avg,op=m.opponent_ping_avg;if(pp<=0&&op<=0)return"";string a=pp>0?pp.ToString():"-";string b=op>0?op.ToString():"-";return$"<color=#888>Ping:</color> <color=#99B3E6>{a}</color> <color=#888>/</color> <color=#E69988>{b}</color><color=#888>ms</color>";}

        /// <summary>Aug 6 item 4 — turn a CUMULATIVE damage timeline into a
        /// per-interval DPS series the hover-graph parser can plot.
        ///
        /// The server stores damage as a running total ("0,12,40,55"), because
        /// that is what the client accumulates during the match. A chart of the
        /// raw values is a monotonically-rising line that says nothing about WHEN
        /// the damage happened, so each sample is differenced against the previous
        /// one and divided by the sample interval.
        ///
        /// IMPORTANT: in 1v1 the two sides are sampled at DIFFERENT rates — the
        /// seat that REPORTED buckets its own damage at 5s, and it observes the
        /// peer through ~3s cr_gstats heartbeats (the same asymmetry the FPS/ping
        /// graphs already carry as myStep vs a hardcoded 3f). Pass each side its
        /// own step, and derive which is which from the reporter, never from the
        /// viewer (ViewerWasReporter) — a history row is re-oriented to the
        /// viewer on read, so the two do not always coincide.
        ///
        /// The first sample is differenced against an implied 0, so the damage
        /// dealt before the first tick is part of the chart rather than dropped.
        /// That also keeps index i aligned with match time i*step, which is what
        /// the chart assumes when it lays out the x-axis.
        ///
        /// Returns a comma-separated INT CSV, because the hover chart parses
        /// kind-5 series with int.TryParse (CompetitiveUI.ParseIntSeriesKeepZeros)
        /// — a "12.40" sample would fail to parse and be silently dropped, and a
        /// whole series of them draws nothing at all. Sub-1 DPS therefore rounds
        /// to 0; do not "restore" decimals here without a parser that reads them.
        /// Returns "" when there is nothing plottable (fewer than 2 samples = no
        /// segment to draw), which keeps the caller from registering a dead hover
        /// region. Negative deltas are clamped to 0: a cumulative series should
        /// never decrease, and a stale pre-reset peer heartbeat must not draw
        /// below the axis.</summary>
        public static string CumulativeToDps(string cumulativeCsv, float stepSeconds)
        {
            if (string.IsNullOrEmpty(cumulativeCsv) || stepSeconds <= 0f) return "";
            try
            {
                var parts = cumulativeCsv.Split(',');
                if (parts.Length < 2) return "";
                var sb = new System.Text.StringBuilder();
                float prev = 0f; int written = 0;
                for (int i = 0; i < parts.Length; i++)
                {
                    if (!float.TryParse(parts[i].Trim(), System.Globalization.NumberStyles.Float,
                                        System.Globalization.CultureInfo.InvariantCulture, out float cur))
                        continue;
                    float d = (cur - prev) / stepSeconds;
                    if (d < 0f) d = 0f;
                    if (written++ > 0) sb.Append(',');
                    sb.Append(Mathf.RoundToInt(d).ToString(System.Globalization.CultureInfo.InvariantCulture));
                    prev = cur;
                }
                return written >= 2 ? sb.ToString() : "";
            }
            catch { return ""; }
        }

        /// <summary>F7 (Codex r3): the sample interval a DECIMATED cumulative
        /// timeline actually carries. Decimation (ClampTimeline's decimate-to-
        /// fit, and the server-side compaction on long games) makes the stride
        /// variable — dividing deltas by the fixed 3s/5s cadence overstates
        /// DPS by however much was decimated. When the row's real duration is
        /// known, the honest uniform approximation is duration/n — Codex r4
        /// f5: there are n DERIVATIVE buckets, because the first sample is
        /// differenced against zero (the pre-match baseline), so n-1 here
        /// halved the DPS of a two-sample game. duration/(n-1) is only right
        /// for plot COORDINATES, which the graph regions compute separately.
        /// A row without a duration keeps the legacy cadence estimate.
        /// Comma-count is used for n so this needs no parse.</summary>
        public static float DpsStepFor(string cumulativeCsv, int durationSeconds, float fallbackStep)
        {
            if (durationSeconds <= 0 || string.IsNullOrEmpty(cumulativeCsv)) return fallbackStep;
            int n = 1;
            for (int i = 0; i < cumulativeCsv.Length; i++) if (cumulativeCsv[i] == ',') n++;
            return durationSeconds / (float)n;
        }

        /// <summary>Sample interval, in seconds, of the stream a client records for
        /// ITS OWN seat. On a history row that is the REPORTER's side, which is not
        /// always the viewer's — see ViewerWasReporter.</summary>
        public const float DPS_STEP_LOCAL = 5f;
        /// <summary>Sample interval of the stream a client records for the PEER it
        /// observes (cr_gstats heartbeat cadence), in seconds.</summary>
        public const float DPS_STEP_PEER = 3f;
        /// <summary>FFA samples every participant on the one 3s telemetry tick,
        /// so a whole match shares a single cadence — unlike 1v1, where the two
        /// sides come off different emitters.</summary>
        public const float DPS_STEP_FFA = 3f;

        /// <summary>Did the VIEWER's client report this 1v1 match?
        ///
        /// This picks the DPS grid, and getting it from the viewer instead of
        /// the reporter was a real bug: the 5s grid belongs to whichever client
        /// SAMPLED ITS OWN SEAT, i.e. the reporter, and the ~3s grid to the peer
        /// it observed over cr_gstats. The server preserves that reporter/peer
        /// origin on write but re-orients the row to viewer/opponent on read, so
        /// "player_damage_timeline" is only the 5s stream when the viewer
        /// happened to be the reporter. Divide the other way round and the
        /// numbers are off by 5/3 in one direction or 3/5 in the other.
        ///
        /// Mirrors the election in GameStateWatcher (search: "Opponent will
        /// report this match") rather than re-deriving it: no reporter column is
        /// stored server-side, so re-running the same rule is the only way back
        /// to the answer. Both halves of that rule matter — the election only
        /// runs when the opponent ALSO had the mod (otherwise only our client
        /// could report), and it compares PARSED LONGS, not the id strings.</summary>
        private static bool ViewerWasReporter(ApiClient.MatchHistoryEntry m)
        {
            if (m == null) return true;
            // Surviving evidence that the opponent had the mod. Deliberately
            // wider than the hit/block pair the row renders: a peer heartbeats
            // fps and active-seconds every 3s regardless of playstyle, so a
            // build that never fires or blocks (the same population find 4 in
            // FillRow is about) is still recognisable as modded.
            bool oppHadMod = m.opponent_fps_avg > 0 || m.opp_active_seconds > 0f
                             || m.opp_bullets_fired > 0 || m.opp_blocks_activated > 0
                             || m.opp_damage_dealt >= 0
                             || !string.IsNullOrEmpty(m.opp_damage_timeline);
            if (!oppHadMod) return true;
            long mine = 0, theirs = 0;
            long.TryParse(MatchTracker.LocalSteamId, out mine);
            long.TryParse(m.opponent_steam_id, out theirs);
            // A "photon_" placeholder or a missing id parses to 0. The election
            // never runs in that case either (it requires a resolved, non-photon
            // opponent id), and its outcome there is "we report" — so fall back
            // to the viewer rather than letting a 0 decide the comparison.
            if (mine <= 0 || theirs <= 0) return true;
            return mine <= theirs;   // ties go to us, exactly as the election does
        }

        /* Visible-character budgets for the two history opponent cells (see
         * FormatOpponentForRow). Characters, not pixels: Gravity averages ~0.62x
         * its point size per glyph for mixed-case text — the same basis as the
         * txtXP and "Cartas: COMPLETO" width notes elsewhere in this file.
         * ROW: txtOpp is 240px at 18pt (~21 chars) and FillRow prefixes "vs ",
         * leaving 18 — which is also what Truncate used to leave VISIBLE, so
         * nothing that rendered before this cap disappears because of it.
         * SERIES: txtSeriesHead is 500px at 19pt (~42 chars), but its template
         * ("Series W 2-1  vs {0}" / "Series 2-1  vs {0}  (in progress)") spends
         * 17-27 of them depending on locale, and its right-hand neighbour
         * txtSeriesElo is a right-aligned 160px cell whose left half is blank —
         * 20 keeps the name clear of it in every locale. */
        private const int HIST_OPP_BUDGET_ROW = 18;
        private const int HIST_OPP_BUDGET_SERIES = 20;
        // Below this many characters a truncated title tag is unreadable noise
        // ("[MA..") and is dropped whole instead.
        private const int TITLE_MIN_VISIBLE = 5;

        // Renders the opponent name + colored title tag for match-history rows. Title is the
        // opponent's CURRENT active title (view-time, not snapshot-at-match) - cheap join in the
        // history endpoint, good enough to answer "who am I looking at right now."
        //
        /* Aug-3 review find F5. `budget` caps the VISIBLE characters of the whole
         * "Name [TITLE]" result, and it became load-bearing when these cells got
         * FitOneLine. FitOneLine (Overflow + no wrap) is what stops a Cyrillic line
         * being dropped WHOLE by the Truncate default (#297) — but Overflow also
         * means nothing clips the tail, so a 20-char name plus a title painted
         * straight across the FPS/Ping cells beside it in the same row. The bound
         * therefore has to live in the STRING: the row already sits inside the
         * ScrollView's RectMask2D, which clips at the COLUMN edge, far past the
         * neighbour, and a per-cell RectMask2D is exactly the per-frame cost #162
         * says to keep out of this panel (these cells are pooled across every
         * history row and rewritten on every refresh). Capping the string keeps
         * FitOneLine's "can never blank" property intact — one painted line,
         * always — while restoring the horizontal bound Truncate used to provide.
         * Name and title share the budget by max-min fair water-filling (#260) so
         * a long title cannot annihilate the name, and a short name leaves its
         * surplus to the title. */
        private static string FormatOpponentForRow(ApiClient.MatchHistoryEntry m,int nameMax,int budget)
        {
            string rawName = m?.opponent_name ?? "";
            string rawTitle = m?.opponent_title ?? "";
            int nameOnly = Math.Min(nameMax, Math.Max(2, budget));
            if (m == null || string.IsNullOrEmpty(rawTitle)) return Trunc(rawName, nameOnly);
            string nm, ttl;
            // 3 = the " []" this function adds around the tag.
            FitTwoParts(rawName, rawTitle, budget, 3, nameMax, out nm, out ttl);
            // Only a title that was actually CUT short can be noise — a genuinely
            // short title ("MVP") must still render.
            if (ttl.Length < rawTitle.Length && ttl.Length < TITLE_MIN_VISIBLE)
                return Trunc(rawName, nameOnly);
            string col = string.IsNullOrEmpty(m.opponent_title_color) ? "#CCCCCC" : m.opponent_title_color;
            // Podium detection reads the RAW title — matching is by exact text, so a
            // truncated one would silently stop qualifying for the glitter span.
            if (IsPodiumTitle(rawTitle))
                return $"{nm} {PodiumSparkleSpan(ttl, col, 0)}";
            return $"{nm} <b><color={col}>[{ttl}]</color></b>";
        }

        private static void RefreshSession()
        {
            if(!ReferenceEquals(sessionSplitLayoutTarget,txtSessionSplit))
            {
                sessionSplitLayoutTarget=txtSessionSplit;
                UIFactory.SetTextAutoHeight(txtSessionSplit);
                UIFactory.SetWordWrap(txtSessionSplit,true);
            }
            int games=GameStateWatcher.SessionMatchCount;
            bool inRoom=GameStateWatcher.IsInRoom;
            string oppSteamId=GameStateWatcher.OpponentSteamId;
            string oppName=GameStateWatcher.OpponentDisplayName;
            var history=ApiClient.CachedMatchHistory;
            // Show opponent lifetime record when in room. The server carries
            // the complete H2H; the local window supplies the last-played date.
            if(inRoom&&!string.IsNullOrEmpty(oppSteamId)&&!oppSteamId.StartsWith("photon_"))
            {
                ApiClient.FetchOpponentLifetime(oppSteamId);
                int ltW=0,ltL=0;
                string lastPlayed="";
                if(history!=null)foreach(var m in history)
                {
                    if(m.opponent_steam_id!=oppSteamId)continue;
                    if(m.won)ltW++;else ltL++;
                    if(string.IsNullOrEmpty(lastPlayed))
                    {
                        try{lastPlayed=DateFmt.Full(DateTime.Parse(m.ended_at));}catch{}
                    }
                }
                if(ApiClient.CachedOppLifetime.TryGetValue(oppSteamId,out var lifetime))
                {ltW=lifetime[0];ltL=lifetime[1];}
                if(ltW+ltL>0)
                {
                    string col=ltW>ltL?"#00FF00":ltW<ltL?"#FF6666":"#AAAAAA";
                    string lastStr=string.IsNullOrEmpty(lastPlayed)?"":I18n.TrF("  (last: {0})",lastPlayed);
                    UIFactory.SetTextRaw(txtSessionOppLifetime,
                        I18n.TrF("  vs {0}:  <color={1}>{2}W-{3}L lifetime</color>{4}",oppName,col,ltW,ltL,lastStr));
                }
                else UIFactory.SetTextRaw(txtSessionOppLifetime,I18n.TrF("  vs {0}:  First time playing!",oppName));
                UIFactory.SetColor(txtSessionOppLifetime,new Color(0.6f,0.75f,1f));
            }
            else if(inRoom&&!string.IsNullOrEmpty(oppName)&&oppName!="Opponent")
            {
                UIFactory.SetTextRaw(txtSessionOppLifetime,I18n.TrF("  In room with {0}",oppName));
                UIFactory.SetColor(txtSessionOppLifetime,C_DIM);
            }
            else UIFactory.SetText(txtSessionOppLifetime,"");

            if(games<=0)
            {
                UIFactory.SetText(txtSessionSum,inRoom?"In a game — no results yet":"No games this session");
                UIFactory.SetColor(txtSessionSum,C_DIM);
                UIFactory.SetText(txtSessionSplit,"");
                UIFactory.SetText(txtSessionSweeps,"");
                return;
            }

            int mins=(int)(DateTime.UtcNow-GameStateWatcher.SessionStartTime).TotalMinutes;
            string time=mins>=60?$"{mins/60}h {mins%60}m":$"{mins}m";
            int rw=GameStateWatcher.SessionRankedWins,rl=GameStateWatcher.SessionRankedLosses;
            int cw=GameStateWatcher.SessionCasualWins,cl=GameStateWatcher.SessionCasualLosses;
            int t2w=GameStateWatcher.SessionTeamSeriesWins,t2l=GameStateWatcher.SessionTeamSeriesLosses;
            int ovw=GameStateWatcher.SessionOvtWins,ovl=GameStateWatcher.SessionOvtLosses;
            int ffw=GameStateWatcher.SessionFfaWins,ffl=GameStateWatcher.SessionFfaLosses;
            int sesSweepG=0,sesSweepT=0;
            if(history!=null)
            {
                var sesStart=GameStateWatcher.SessionStartTime;
                foreach(var m in history)
                {
                    DateTime mTime=DateTime.UtcNow;
                    try{if(!string.IsNullOrEmpty(m.ended_at))mTime=DateTime.Parse(m.ended_at).ToUniversalTime();}catch{}
                    if(mTime<sesStart)continue;
                    if(m.won&&m.opponent_rounds_won==0)sesSweepG++;
                    if(!m.won&&m.player_rounds_won==0)sesSweepT++;
                }
            }
            UIFactory.SetTextRaw(txtSessionSum,
                I18n.TrF("{0} games    {1}W - {2}L    {3}",games,rw+cw+ovw+ffw,rl+cl+ovl+ffl,time));
            UIFactory.SetColor(txtSessionSum,C_WHITE);
            var splitParts=new List<string>();
            if(rw+rl>0)splitParts.Add(I18n.TrF("<color=#FFD94D>Ranked:</color> {0}W/{1}L",rw,rl));
            if(t2w+t2l>0)splitParts.Add(I18n.TrF("<color=#FFB347>2v2:</color> {0}W/{1}L",t2w,t2l));
            if(ovw+ovl>0)splitParts.Add(I18n.TrF("<color=#7FD4FF>1v2:</color> {0}W/{1}L",ovw,ovl));
            if(ffw+ffl>0)
            {
                string places=GameStateWatcher.SessionFfaPlacementsCsv;
                splitParts.Add(I18n.TrF("<color=#D8A7FF>FFA:</color> {0}W-{1}L",ffw,ffl)+
                    (string.IsNullOrEmpty(places)?"":" "+I18n.TrF("(placements {0})",places)));
            }
            if(cw+cl>0)splitParts.Add(I18n.TrF("Casual: {0}W/{1}L",cw,cl));
            UIFactory.SetTextRaw(txtSessionSplit,
                splitParts.Count>0?"  "+string.Join("    ",splitParts.ToArray()):"");
            if(sesSweepG+sesSweepT>0)
                UIFactory.SetTextRaw(txtSessionSweeps,
                    "  "+I18n.TrF("Sweeps: <color=#00FF00>5-0 x{0}</color>  <color=#FF6666>0-5 x{1}</color>",sesSweepG,sesSweepT));
            else UIFactory.SetText(txtSessionSweeps,"");

            var wl=GameStateWatcher.SessionWLByOpponent;
            var st=GameStateWatcher.SessionTimeByOpponent;
            int idx=0;
            if(wl!=null)foreach(var kvp in wl)
            {
                int[] a=kvp.Value;
                if(a==null||a.Length<4)continue;
                int av=a.Length>4?a[4]:0,avl=a.Length>5?a[5]:0;
                int fw=a.Length>6?a[6]:0,fl=a.Length>7?a[7]:0;
                int ow=a[0]+a[2]+av+fw,ol=a[1]+a[3]+avl+fl;
                // 2v2 teammates are keyed "w/ Name"; render that prefix as-is.
                string line=kvp.Key.StartsWith("w/ ")
                    ?$"  {kvp.Key}:  {ow}W-{ol}L"
                    :$"  vs {kvp.Key}:  {ow}W-{ol}L";
                var breakdown=new List<string>();
                if(a[0]+a[1]>0)breakdown.Add($"R:{a[0]}-{a[1]}");
                if(a[2]+a[3]>0)breakdown.Add($"C:{a[2]}-{a[3]}");
                if(av+avl>0)breakdown.Add($"1v2:{av}-{avl}");
                if(breakdown.Count>1)line+="  ("+string.Join(" ",breakdown.ToArray())+")";
                if(fw+fl>0)line+=$"  FFA {fw}W-{fl}L";
                if(st!=null&&st.ContainsKey(kvp.Key))
                {
                    int m=(int)st[kvp.Key];
                    line+=m>=60?$"   {m/60}h {m%60}m":$"   {m}m";
                }
                while(sessionOppTexts.Count<=idx)
                {
                    var rowText=UIFactory.CreateText($"so{sessionOppTexts.Count}",
                        sessionOppContainer.transform,"",15f,C_LABEL,sizeDelta:new Vector2(340,22));
                    UIFactory.SetTextAutoHeight(rowText);
                    UIFactory.SetWordWrap(rowText,true);
                    sessionOppTexts.Add(rowText);
                }
                UIFactory.SetTextRaw(sessionOppTexts[idx],line);
                UIFactory.SetColor(sessionOppTexts[idx],ow>ol?C_GREEN:ow<ol?C_RED:C_DIM);
                var go=(sessionOppTexts[idx]as Component)?.gameObject;
                if(go)go.SetActive(true);
                idx++;
            }
            for(int i=idx;i<sessionOppTexts.Count;i++)
            {
                var go=(sessionOppTexts[i]as Component)?.gameObject;
                if(go)go.SetActive(false);
            }
        }

        private static void RefreshLeaderboard(){_podiumLbRows.Clear();/* Item 1 (the "Oro v" bug): translate the base label FIRST, then append the arrow, and write Raw so the composed string is never re-looked-up. */string[]hL={I18n.Tr("#"),I18n.Tr("Lv"),I18n.Tr("Player"),I18n.Tr("Rating"),I18n.Tr("W"),I18n.Tr("L"),I18n.Tr("W/L"),I18n.Tr("Gold")};string[]hK={"rank","level","display_name","rating","wins","losses","wl_ratio","gold"};if(lbSortTexts!=null)for(int i=0;i<hK.Length&&i<lbSortTexts.Length;i++){if(lbSortTexts[i]==null)continue;string arrow=lbSort==hK[i]?(lbSortDesc?" v":" ^"):"";UIFactory.SetTextRaw(lbSortTexts[i],hL[i]+arrow);UIFactory.SetColor(lbSortTexts[i],lbSort==hK[i]?C_WHITE:C_LABEL);if(lbSortBtns!=null&&i<lbSortBtns.Length)UIFactory.SetImageColor(lbSortBtns[i],lbSort==hK[i]?C_TABACT:C_TAB);}var board=ApiClient.CachedLeaderboard;foreach(var r in lbRows)r.root.SetActive(false);if(board==null||board.entries==null||board.entries.Length==0){UIFactory.SetText(txtLBDetail,"No leaderboard data");UIFactory.SetText(txtLBDetailB,"");UIFactory.SetText(txtLBCount,"");return;}var entries=new List<ApiClient.LeaderboardEntry>(board.entries);switch(lbSort){case "rank":entries.Sort((a,b)=>lbSortDesc?b.rank.CompareTo(a.rank):a.rank.CompareTo(b.rank));break;case "level":entries.Sort((a,b)=>lbSortDesc?b.level.CompareTo(a.level):a.level.CompareTo(b.level));break;case "display_name":entries.Sort((a,b)=>lbSortDesc?string.Compare(b.display_name,a.display_name,StringComparison.OrdinalIgnoreCase):string.Compare(a.display_name,b.display_name,StringComparison.OrdinalIgnoreCase));break;case "rating":entries.Sort((a,b)=>lbSortDesc?b.rating.CompareTo(a.rating):a.rating.CompareTo(b.rating));break;case "wins":entries.Sort((a,b)=>lbSortDesc?b.wins.CompareTo(a.wins):a.wins.CompareTo(b.wins));break;case "losses":entries.Sort((a,b)=>lbSortDesc?b.losses.CompareTo(a.losses):a.losses.CompareTo(b.losses));break;case "wl_ratio":entries.Sort((a,b)=>{float ra=a.losses>0?(float)a.wins/a.losses:a.wins*100f;float rb=b.losses>0?(float)b.wins/b.losses:b.wins*100f;return lbSortDesc?rb.CompareTo(ra):ra.CompareTo(rb);});break;case "gold":/* Aug 6 item 6: hide_gold players carry gold==-1 — treat as +infinity so they sit at the TOP of the default descending sort (they were sorting below 0-gold players). */entries.Sort((a,b)=>{int ga=a.gold<0?int.MaxValue:a.gold;int gb=b.gold<0?int.MaxValue:b.gold;return lbSortDesc?gb.CompareTo(ga):ga.CompareTo(gb);});break;}/* July 22 item 8: search filter (whole board is client-side; ~500 cap). Reset to page 0 when the query changes. */if(lbSearchField!=null)UIFactory.SetText(lbSearchField,"");string lbQ=(lbSearch??"").Trim();if(lbQ!=lbSearchLast){lbSearchLast=lbQ;lbPage=0;}if(lbQ.Length>0)entries.RemoveAll(e=>e.display_name==null||e.display_name.IndexOf(lbQ,StringComparison.OrdinalIgnoreCase)<0);int lbPP=100,lbTotalP=(entries.Count+lbPP-1)/lbPP;lbPage=Math.Max(0,Math.Min(lbPage,lbTotalP-1));int lbStart=lbPage*lbPP,lbEnd=Math.Min(lbStart+lbPP,entries.Count);for(int i=lbStart;i<lbEnd&&(i-lbStart)<lbRows.Count;i++){var e=entries[i];var row=lbRows[i-lbStart];row.steamId=e.steam_id;bool local=e.steam_id==MatchTracker.LocalSteamId;string ratio=e.losses>0?$"{(float)e.wins/e.losses:F1}":e.wins>0?$"{e.wins}:0":"0:0";UIFactory.SetText(row.txtRank,$"{e.rank}");UIFactory.SetColor(row.txtRank,e.rank==1?new Color(1f,0.84f,0f):e.rank==2?new Color(0.75f,0.75f,0.75f):e.rank==3?new Color(0.8f,0.5f,0.2f):C_GOLD);UIFactory.SetText(row.txtLv,$"{e.level}");string _lbName=Trunc(e.display_name,20);if(!string.IsNullOrEmpty(e.title)){string _tc=string.IsNullOrEmpty(e.title_color)?"#FFFFFF":e.title_color;if(IsPodiumTitle(e.title)){_podiumLbRows.Add(new object[]{row.txtName,_lbName,e.title,_tc});_lbName=$"{_lbName} {PodiumSparkleSpan(e.title,_tc,_podiumTick)}";}else{_lbName=$"{_lbName} <b><color={_tc}>[{e.title}]</color></b>";}}/* SetTextRaw (find 15): a bare display name must never hit the translation catalogue — a player literally named "Done." would render as "Hecho.". */UIFactory.SetTextRaw(row.txtName,_lbName);UIFactory.SetColor(row.txtName,local?C_GREEN:C_WHITE);/* v1.29: rating cell carries the Discord rank-role color, so ranks read at a glance */string _rc=string.IsNullOrEmpty(e.rank_color)?"#FFFFFF":e.rank_color;UIFactory.SetText(row.txtRating,$"<color={_rc}>{e.rating}</color>");UIFactory.SetText(row.txtW,$"{e.wins}");UIFactory.SetText(row.txtL,$"{e.losses}");UIFactory.SetText(row.txtWL,ratio);if(e.gold<0){UIFactory.SetText(row.txtGold,"<color=#888><i>Hidden</i></color>");}else{UIFactory.SetText(row.txtGold,e.gold>0?$"{e.gold}":"0");}bool sel=e.steam_id==selectedSteamId;/* podium tint alphas halved per Sid feedback — 0.22 read too strong behind text */UIFactory.SetImageColor(row.hlWrap,sel?new Color(0.2f,0.25f,0.4f,0.4f):e.rank==1?new Color(1f,0.84f,0f,0.11f):e.rank==2?new Color(0.75f,0.75f,0.78f,0.10f):e.rank==3?new Color(0.8f,0.5f,0.2f,0.10f):new Color(0.15f,0.15f,0.2f,0.01f));SetLbRowOutline(row,e.rank<=3);row.root.SetActive(true);}UIFactory.SetTextRaw(txtLBCount,lbQ.Length>0?I18n.TrF("{0} of {1} players",entries.Count,board.total_players):I18n.TrF("{0} players ranked",board.total_players));lbPrev.SetActive(lbPage>0);lbNext.SetActive(lbPage<lbTotalP-1);UIFactory.SetText(txtLBPage,lbTotalP>1?$"{lbPage+1}/{lbTotalP}":"");if(!string.IsNullOrEmpty(selectedSteamId)&&selectedStats!=null){var ps=selectedStats;UIFactory.SetTextRaw(txtLBPlayerName,$"{ps.display_name}   <color=#66CCFF>{I18n.TrF("Level {0}",ps.level)}</color>");string _rkLine=!string.IsNullOrEmpty(ps.rank_name)?I18n.TrF("Rank: <b><color={0}>{1}</color></b>",string.IsNullOrEmpty(ps.rank_color)?"#FFFFFF":ps.rank_color,ps.rank_name):"";string _modeBlock=ModeRatingBlock(ps);/* Every emitted mode row ends in a newline; one more creates exactly one empty line before the match summary. */string detail="\n"+(_rkLine.Length>0?_rkLine+"\n":"")+_modeBlock+(_modeBlock.Length>0?"\n":"")+I18n.TrF("{0} matches ({1}W / {2}L)  WR: {3}%",ps.total_matches,ps.wins,ps.losses,(ps.total_matches>0?ps.wins*100f/ps.total_matches:0f).ToString("F0",_INV))+"\n";if(ps.ranked_series_wins+ps.ranked_series_losses>0)detail+=I18n.TrF("<color=#FFD94D>Ranked (series): {0}W / {1}L</color>",ps.ranked_series_wins,ps.ranked_series_losses)+"\n";/* Leave % - denominator includes DCs as their own events */if(ps.ranked_dc_count>0||ps.ranked_series_wins+ps.ranked_series_losses>0){int totalRanked=ps.ranked_series_wins+ps.ranked_series_losses+ps.ranked_dc_count;int dc=ps.ranked_dc_count;if(totalRanked>0){float pct=(float)dc/totalRanked*100f;string dcCol=pct<5f?"#44AA44":pct<15f?"#DDAA33":"#FF4444";detail+=I18n.TrF("<color={0}>Leave: {1}/{2} ({3}%)</color>",dcCol,dc,totalRanked,pct.ToString("F0",_INV))+"\n";}}/* Hit% / Block% - lifetime counters driven by Harmony patches (Gun.Attack / HealthHandler.TakeDamage / Block.TryBlock / Block.DoBlock). Accumulates only when this player reported a match. Show a dash for players who haven't reported yet so the rows stay consistent with the My Stats Record section (instead of silently disappearing). */{string hitLine=ps.bullets_fired>0?I18n.TrF("<color=#FF9988>Hit:</color> {0}% <color=#888>({1}/{2})</color>",((float)ps.bullets_hit*100f/ps.bullets_fired).ToString("F1",_INV),ps.bullets_hit,ps.bullets_fired):I18n.Tr("<color=#FF9988>Hit:</color> -");string blkLine=ps.blocks_activated>0?I18n.TrF("<color=#99CCFF>Block:</color> {0}% <color=#888>({1}/{2})</color>",((float)ps.blocks_successful*100f/ps.blocks_activated).ToString("F1",_INV),ps.blocks_successful,ps.blocks_activated):I18n.Tr("<color=#99CCFF>Block:</color> -");detail+=$"{hitLine}\n{blkLine}\n";}/* Head to head — server-computed (full matches table) replaces the
 * earlier client-side iteration over CachedMatchHistory which was
