        /// <summary>Screen-space (IMGUI, Y-down) rect of the picker's search
        /// anchor, so CompetitiveUI can draw its TextField exactly over it. Same
        /// contract as GetCompareSearchScreenRect.</summary>
        public static Rect GetPickerSearchScreenRect()
        {
            try
            {
                var go = (pickerSearchAnchor as Component)?.gameObject;
                if (go == null || !go.activeInHierarchy) return new Rect(0, 0, 0, 0);
                var rt = go.GetComponent<RectTransform>();
                if (rt == null) return new Rect(0, 0, 0, 0);
                var c = new Vector3[4]; rt.GetWorldCorners(c); // 0=BL,1=TL,2=TR,3=BR
                float x = c[0].x, w = c[2].x - c[0].x, h = c[1].y - c[0].y;
                float guiY = Screen.height - c[1].y;
                if (w < 1f || h < 1f) return new Rect(0, 0, 0, 0);
                return new Rect(x, guiY, w, h);
            }
            catch { return new Rect(0, 0, 0, 0); }
        }

        /// <summary>note (Aug 9): an optional wrapped caption under the title.
        /// Lobby-phase betting needs its refund rule stated at the moment the
        /// target is chosen, and the amount modal that follows lives in
        /// CompetitiveUI with a fixed layout.</summary>
        private static void ShowPicker(string title, Func<List<string>> items,
                                      Func<string, string> label, Func<string, Color> color,
                                      Func<string, bool> isSelected, Action<string> onPick,
                                      bool multiSelect, string note = null)
        {
            try
            {
                HidePicker();
                EnsureOverlayCanvas();
                pickerTitle = title ?? "";
                pickerItemsFn = items;
                pickerItems.Clear();
                pickerLabelFn = label; pickerColorFn = color;
                pickerSelectedFn = isSelected; pickerPickFn = onPick;
                pickerMulti = multiSelect;
                pickerSearch = "";

                pickerGO = new GameObject("CR_Picker");
                pickerGO.hideFlags = HideFlags.HideAndDontSave;
                pickerGO.transform.SetParent(overlayCanvasGO.transform, false);
                var rt = pickerGO.AddComponent<RectTransform>();
                rt.anchorMin = Vector2.zero; rt.anchorMax = Vector2.one;
                rt.offsetMin = Vector2.zero; rt.offsetMax = Vector2.zero;

                var bd = UIFactory.CreatePanel("BD", pickerGO.transform, new Color(0f, 0f, 0f, 0.55f));
                var bdRT = bd.GetComponent<RectTransform>();
                bdRT.anchorMin = Vector2.zero; bdRT.anchorMax = Vector2.one;
                bdRT.offsetMin = Vector2.zero; bdRT.offsetMax = Vector2.zero;
                var bdImg = bd.GetComponent(UIFactory.tImage);
                if (bdImg != null)
                    UIFactory.tImage.GetProperty("raycastTarget", BindingFlags.Public | BindingFlags.Instance)?.SetValue(bdImg, true);
                var bdClick = bd.AddComponent<ClickHandler>();
                bdClick.bypassModalBlock = true;   // #200 — the closer must survive its own block
                /* ClickHandler does NO occlusion test — it hit-tests only its own
                 * rect plus ancestor masks (#185), and this backdrop covers the
                 * whole screen INCLUDING the box. Without the box-rect exclusion
                 * below, every click on a row would fire the row's button AND
                 * this closer (they hold different ClickGuard keys, so the
                 * per-control guard does not dedupe them, #142). Single-select
                 * survives that by luck because it closes anyway; the
                 * MULTI-select card picker would shut on every toggle. */
                bdClick.onClick = () =>
                {
                    if (MouseInsidePickerBox()) return;
                    if (ClickGuard.Claim(bd)) HidePicker();
                };

                var box = UIFactory.CreatePanel("Box", pickerGO.transform, new Color(0.10f, 0.12f, 0.16f, 0.98f));
                var boxRT = box.GetComponent<RectTransform>();
                boxRT.anchorMin = new Vector2(0.5f, 0.5f);
                boxRT.anchorMax = new Vector2(0.5f, 0.5f);
                boxRT.pivot = new Vector2(0.5f, 0.5f);
                /* Height is clamped to the LIVE canvas height, never a constant:
                 * the F5 canvas is WIDTH-matched, so a 32:9 window gets far fewer
                 * than 1080 vertical units and a fixed box would clip off-screen
                 * with no way to reach the bottom rows (#199). The list
                 * ScrollView absorbs whatever height is lost. */
                float boxH = 760f;
                try
                {
                    var canvasRT = overlayCanvasGO.GetComponent<RectTransform>();
                    if (canvasRT != null && canvasRT.rect.height > 200f)
                        boxH = Mathf.Min(760f, canvasRT.rect.height - 60f);
                }
                catch { }
                if (boxH < 240f) boxH = 240f;
                boxRT.sizeDelta = new Vector2(620, boxH);
                pickerBoxRT = boxRT;   // read by the backdrop's click-away test
                UIFactory.AddVLG(box, spacing: 8, padL: 18, padR: 18, padT: 14, padB: 14);

                UIFactory.CreateText("PkTitle", box.transform, pickerTitle, 22f, C_GOLD,
                    UIFactory.AlignMidCenter, sizeDelta: new Vector2(580, 30));
                if (!string.IsNullOrEmpty(note))
                {
                    var noteTxt = UIFactory.CreateText("PkNote", box.transform,
                        $"<color=#FFD94D>{note}</color>", 14f, C_SUB,
                        UIFactory.AlignMidLeft, sizeDelta: new Vector2(580, 52));
                    UIFactory.SetWordWrap(noteTxt, true);
                    // Overflow, not the global Truncate default: a translated
                    // note in an OS-fallback script has taller line metrics and
                    // would lose its last line inside a fixed box (#292/#297).
                    UIFactory.SetOverflowMode(noteTxt, 0);
                }
                UIFactory.CreateText("PkCap", box.transform,
                    "<color=#88AAFF>Type to filter</color>", 14f, C_SUB,
                    UIFactory.AlignMidLeft, sizeDelta: new Vector2(580, 18));
                // Empty anchor — CompetitiveUI.DrawPickerSearch paints the real
                // IMGUI field over this rect. Keeping the TMP text empty avoids
                // the double-layered box the Compare search originally had.
                pickerSearchAnchor = UIFactory.CreateText("PkSearch", box.transform, "",
                    14f, C_SUB, UIFactory.AlignMidLeft, sizeDelta: new Vector2(580, 26));
                pickerCountTxt = UIFactory.CreateText("PkCount", box.transform, "",
                    13f, C_DIM, UIFactory.AlignMidLeft, sizeDelta: new Vector2(580, 18));

                var sv = UIFactory.CreateScrollView("PkSV", box.transform, spacing: 2);
                UIFactory.AddLE(sv.scrollGO, flexH: 1);
                pickerListContent = sv.content;

                var closeBtn = UIFactory.CreateButton("PkClose", box.transform, "Close", 15f, C_WHITE,
                    new Color(0.28f, 0.30f, 0.38f, 0.95f), HidePicker,
                    sizeDelta: new Vector2(580, 30));
                // flexH:0 so the button keeps its 30px against the flexH:1 list
                // above it. CreateButton already attached a LayoutElement; a
                // second one is the codebase's normal idiom here because
                // LayoutUtility takes the MAX of set values across components
                // and treats the first one's unset (-1) flex as absent.
                UIFactory.AddLE(closeBtn, prefH: 30, flexH: 0);

                RebuildPickerList();
            }
            catch (Exception ex) { Plugin.Log.LogWarning($"[PICKER] show: {ex.Message}"); }
        }

        /// <summary>True when the cursor is over the picker's box. The picker
        /// lives on the ScreenSpaceOverlay canvas, so world corners ARE screen
        /// pixels and no WorldToScreenPoint is needed (that conversion is only
        /// for ROUNDS' ScreenSpaceCamera canvases, #6).</summary>
        private static bool MouseInsidePickerBox()
        {
            try
            {
                if (pickerBoxRT == null) return false;
                var c = new Vector3[4]; pickerBoxRT.GetWorldCorners(c);
                Vector3 mp = Input.mousePosition;
                float minX = Mathf.Min(c[0].x, c[2].x), maxX = Mathf.Max(c[0].x, c[2].x);
                float minY = Mathf.Min(c[0].y, c[2].y), maxY = Mathf.Max(c[0].y, c[2].y);
                return mp.x >= minX && mp.x <= maxX && mp.y >= minY && mp.y <= maxY;
            }
            catch { return false; }
        }

        public static void HidePicker()
        {
            try
            {
                if (pickerGO != null) { UnityEngine.Object.Destroy(pickerGO); pickerGO = null; }
                pickerBoxRT = null;
                pickerListContent = null; pickerSearchAnchor = null; pickerCountTxt = null;
                pickerSearch = "";
                pickerItems.Clear();
                pickerItemsFn = null;
                pickerLabelFn = null; pickerColorFn = null; pickerSelectedFn = null; pickerPickFn = null;
                dirty = true;
            }
            catch (Exception ex) { Plugin.Log.LogWarning($"[PICKER] hide: {ex.Message}"); }
        }

        /// <summary>Rebuild the visible rows from pickerItems + the filter. Rows
        /// are destroyed and re-created rather than pooled: the list is at most a
        /// few dozen entries and only changes on a keystroke, and pooling here
        /// would have to survive the overlay being destroyed on close.</summary>
        private static void RebuildPickerList()
        {
            if (pickerListContent == null) return;
            try
            {
                // Re-pull the item set every rebuild so an async load (the card
                // catalogue) appears without the user having to reopen.
                if (pickerItemsFn != null)
                {
                    pickerItems.Clear();
                    var fresh = pickerItemsFn();
                    if (fresh != null) pickerItems.AddRange(fresh);
                }

                for (int c = pickerListContent.transform.childCount - 1; c >= 0; c--)
                    UnityEngine.Object.Destroy(pickerListContent.transform.GetChild(c).gameObject);

                string q = (pickerSearch ?? "").Trim();
                var shown = new List<string>();
                foreach (var key in pickerItems)
                {
                    // Filter on the TRANSLATED label — the user is reading and
                    // typing the displayed text, not the raw English switch key.
                    string disp = pickerLabelFn != null ? pickerLabelFn(key) : key;
                    if (q.Length == 0 || (disp ?? "").IndexOf(q, StringComparison.OrdinalIgnoreCase) >= 0
                        || (key ?? "").IndexOf(q, StringComparison.OrdinalIgnoreCase) >= 0)
                        shown.Add(key);
                }

                if (pickerCountTxt != null)
                    /* "Showing {0} of {1}", not a bare "{0} of {1}": the
                     * extractor rejects any fragment with fewer than 3 LETTERS
                     * (#295c), and "of" is two — the bare form was silently
                     * unharvestable, i.e. permanently English in every locale.
                     * Verified against tools/i18n_source.json, which contains
                     * "{0} of {1} left" and "{0} of {1} players" but no bare
                     * "{0} of {1}". */
                    UIFactory.SetTextRaw(pickerCountTxt,
                        $"<color=#888>{I18n.TrF("Showing {0} of {1}", shown.Count, pickerItems.Count)}</color>");

                if (shown.Count == 0)
                {
                    var none = UIFactory.CreateText("PkNone", pickerListContent.transform,
                        $"<color=#888>{I18n.Tr("No matches.")}</color>", 14f, C_DIM,
                        UIFactory.AlignMidLeft, sizeDelta: new Vector2(560, 26));
                    UIFactory.FitOneLine(none);
                    return;
                }

                for (int i = 0; i < shown.Count; i++)
                {
                    string key = shown[i];
                    string disp = pickerLabelFn != null ? pickerLabelFn(key) : key;
                    bool sel = pickerSelectedFn != null && pickerSelectedFn(key);
                    Color col = pickerColorFn != null ? pickerColorFn(key) : C_WHITE;
                    string mark = pickerMulti
                        ? (sel ? "<color=#77FF99>[X]</color> " : "<color=#555>[ ]</color> ")
                        : (sel ? "<color=#77FF99>></color> " : "  ");
                    var b = UIFactory.CreateButton($"Pk{i}", pickerListContent.transform,
                        $"{mark}<color=#{ColorToHex(col)}>{FfaSafeRich(disp)}</color>", 15f, C_WHITE,
                        sel ? new Color(0.18f, 0.30f, 0.24f, 0.95f) : C_TAB,
                        // CreateButton already wraps this in ClickGuard.Claim —
                        // claiming again here would be a same-frame no-op (#158).
                        () =>
                        {
                            pickerPickFn?.Invoke(key);
                            if (!pickerMulti) HidePicker();
                            else RebuildPickerList();   // refresh the [X] marks in place
                            dirty = true;
                        },
                        sizeDelta: new Vector2(560, 26));
                    // Explicit prefH: a scroll-view child with no preferred height
                    // sizes to zero inside the viewport (#63).
                    UIFactory.AddLE(b, prefW: 560, prefH: 26, flexW: 0, flexH: 0);
                    // The row text is sized for the base font; a translated label
                    // in an OS-fallback script has taller metrics and the global
                    // Truncate default would drop the whole line (#292/#297).
                    UIFactory.FitOneLine(UIFactory.GetButtonText(b));
                }
            }
            catch (Exception ex) { Plugin.Log.LogWarning($"[PICKER] rebuild: {ex.Message}"); }
        }

        /// <summary>Open the metric dropdown for whichever sub-tab is active.</summary>
        private static void OpenMetricPicker()
        {
            var arr = ActiveMetrics;
            ShowPicker(I18n.Tr("Choose a metric"), () => new List<string>(arr),
                TrMetric,
                _ => C_WHITE,
                k => k == ActiveMetricName,
                k =>
                {
                    for (int i = 0; i < arr.Length; i++)
                        if (arr[i] == k) { ActiveMetricIndex = i; break; }
                },
                multiSelect: false);
        }

        /// <summary>A card's display color. RARITY-based — the plugin has no
        /// per-card theme color anywhere (the theme tint only ever reaches the
        /// screen because CardSnapshot renders the real prefab), so rarity is the
        /// only card color source that exists client-side.
        ///
        /// Aug 7 item 2 — resolution order is LOCAL REGISTRY FIRST, server value
        /// second. CardRarityLookup is built from the live CardInfo prefabs in
        /// THIS build of ROUNDS, so it is ground truth for what a card is today.
        /// The catalogue's `rarity` is a historical PER-PICK SNAPSHOT written by
        /// whichever client reported each match, so one card accumulates several
        /// stored rarities over its life (prod: 20 names carry >=2 — Drill Ammo
        /// is stored as Rare 610x, Common 3x and Unknown 3x) and a minority row
        /// could win the server's sort and colour the card wrongly. The server
        /// value is used only when the local registry has nothing: before the
        /// first match of the session the scene scan has not run, and a card the
        /// installed game no longer ships is Unknown forever.</summary>
        private static Color CardColorFor(string cardName)
        {
            try
            {
                string local = null;
                try { local = CardRarityLookup.GetRarity(cardName); } catch { }
                if (!string.IsNullOrEmpty(local)
                    && !string.Equals(local, "Unknown", StringComparison.OrdinalIgnoreCase))
                    return GetRarityColor(local);
                if (ApiClient.CardCatalog != null)
                    foreach (var e in ApiClient.CardCatalog)
                        if (string.Equals(e.name, cardName, StringComparison.OrdinalIgnoreCase))
                            return GetRarityColor(e.rarity);
                return GetRarityColor(local);
            }
            catch { return C_LABEL; }
        }

        private static void ToggleCompareCard(string cardName)
        {
            if (string.IsNullOrEmpty(cardName)) return;
            if (compareCardsSelected.Contains(cardName)) compareCardsSelected.Remove(cardName);
            else
            {
                if (compareCardsSelected.Count >= COMPARE_CARDS_MAX)
                {
                    CompetitiveUI.ShowNotification(I18n.TrF("Max {0} cards", COMPARE_CARDS_MAX),
                        new Color(1f, 0.6f, 0.3f));
                    return;
                }
                compareCardsSelected.Add(cardName);
            }
            dirty = true;
        }

        private static GameObject BuildCompareTab(Transform parent)
        {
            // Round 5 item 3: outer VLG wrapper hosts the sub-tab anchor above
            // the two-column HLG content.
            var outer = new GameObject("CompareOuter");
            outer.transform.SetParent(parent, false);
            outer.AddComponent<RectTransform>();
            UIFactory.AddVLG(outer, spacing: 4);
            UIFactory.AddLE(outer, flexH: 1);
            MakeSubTabAnchor(9, outer.transform, true);

            /* Aug 6 item 2 — Players / Cards sub-tabs. This is a LOCAL row, not
             * MakeSubTabAnchor: that mechanism parks the GLOBAL tab-group bar
             * (GROUP_MEMBERS) into whichever tab is active and is already in use
             * above for tab 9 itself. Two independent bars, two independent
             * jobs. */
            var subRow = new GameObject("CmpSubTabs");
            subRow.transform.SetParent(outer.transform, false);
            subRow.AddComponent<RectTransform>();
            UIFactory.AddHLG(subRow, spacing: 4, padL: 8);
            UIFactory.AddLE(subRow, prefH: 26, minH: 26, flexH: 0);
            /* Aug 7 item 2: the search box is now SHARED by both sub-tabs, so a
             * term left over from the other list would filter this one to
             * nothing — "Cards" opening on an empty list reads as broken. Clear
             * it on every switch. */
            compareSubTabPlayersBtn = UIFactory.CreateButton("CmpSTP", subRow.transform, "Players",
                14f, C_WHITE, C_TABACT, () => { if (compareSubTab != 0) { compareSubTab = 0; compareSearch = ""; dirty = true; } },
                sizeDelta: new Vector2(120, 24));
            UIFactory.AddLE(compareSubTabPlayersBtn, prefW: 120, prefH: 24, flexW: 0, flexH: 0);
            compareSubTabCardsBtn = UIFactory.CreateButton("CmpSTC", subRow.transform, "Cards",
                14f, C_LABEL, C_TAB, () => { if (compareSubTab != 1) { compareSubTab = 1; compareSearch = ""; ApiClient.FetchCardCatalog(); dirty = true; } },
                sizeDelta: new Vector2(120, 24));
            UIFactory.AddLE(compareSubTabCardsBtn, prefW: 120, prefH: 24, flexW: 0, flexH: 0);
            // Trailing flex spacer keeps the two buttons left-aligned. It lives
            // INSIDE this row, so the row's derived flexible width can't stretch
            // a sibling column (#132) — the row is the full tab width anyway.
            var stSpacer = new GameObject("S"); stSpacer.transform.SetParent(subRow.transform, false);
            stSpacer.AddComponent<RectTransform>(); UIFactory.AddLE(stSpacer, flexW: 1);

            var panel = new GameObject("Compare");
            panel.transform.SetParent(outer.transform, false);
            panel.AddComponent<RectTransform>();
            UIFactory.AddHLG(panel, spacing: 8);
            UIFactory.AddLE(panel, flexH: 1);

            // LEFT: player picker. Narrower than before (was 300/260) — lopi wanted
            // it shorter width-wise; the freed horizontal space on the right belongs
            // to the chart panel. Scroll works anywhere over the viewport now
            // (CreateScrollView sets viewport raycastTarget).
            var left = UIFactory.CreatePanel("CmpL", panel.transform, C_PANEL);
            UIFactory.AddVLG(left, spacing: 4, padL: 8, padR: 8, padT: 6, padB: 6);
            /* Aug-3 item 12 (ES "Borrar busque"): the btnRow below holds two buttons
             * that each PREFER 120px, but 222 - 16 padding - 4 spacing left only 202
             * for 240 of preferred width, so Unity lerped both down to ~101px and
             * Truncate ate the label. Removing the stacked flexW:1 would not have
             * helped — flex only distributes SURPLUS, and there was none. 268 gives
             * 252 inner, 248 for the pair, so both keep their full 120 (+4 of flex)
             * and "Borrar busqueda" (~105px at 13pt) fits. Costs the chart panel
             * (flexW:1) 46px out of ~1600. */
            UIFactory.AddLE(left, prefW: 268, minW: 240, flexW: 0, flexH: 1);
            txtCompareHeader = UIFactory.CreateText("CmpLH", left.transform, "Compare Players", 19f, C_GOLD,
                UIFactory.AlignMidLeft, sizeDelta: new Vector2(204, 26));
            // Round 4 item 2: the status line is longer than the 204px column and
            // TMP's default overflow spilled it over the graph — wrap to two lines
            // inside the column instead.
            txtCompareStatus = UIFactory.CreateText("CmpSt", left.transform, "Select up to 12 players",
                13f, C_LABEL, UIFactory.AlignTopLeft, sizeDelta: new Vector2(204, 38));
            UIFactory.SetWordWrap(txtCompareStatus, true);
            // Static caption ABOVE the field. The field itself is the IMGUI box drawn by
            // CompetitiveUI over the empty `compareSearchField` anchor below — keeping the
            // anchor's TMP text EMPTY means only one layer of text shows in the box (was
            // double-layered before: native label text behind the IMGUI field).
            /* Aug 7 item 2 — the search serves BOTH sub-tabs now. It used to be
             * deactivated on Cards (whose chooser was a modal dropdown carrying
             * its own search); the dropdown is gone and the card list is a
             * persistent left-column list exactly like the player list, so the
             * caption/anchor pair stays live and only its LABEL changes. The
             * anchor's TMP text must stay EMPTY — CompetitiveUI paints the real
             * IMGUI field over this rect, and text here shows through it. */
            compareSearchCap = UIFactory.CreateText("CmpSearchCap", left.transform, $"<color=#88AAFF>{I18n.Tr("Search players")}</color>",
                12f, C_SUB, UIFactory.AlignMidLeft, sizeDelta: new Vector2(204, 16));
            compareSearchField = UIFactory.CreateText("CmpSearchLbl", left.transform, "",
                13f, C_SUB, UIFactory.AlignMidLeft, sizeDelta: new Vector2(204, 22));
            var btnRow = new GameObject("CmpBtns"); btnRow.transform.SetParent(left.transform, false);
            btnRow.AddComponent<RectTransform>(); UIFactory.AddHLG(btnRow, spacing: 4, forceExpandH: true);
            UIFactory.AddLE(btnRow, prefH: 24, flexH: 0);
            var clrBtn = UIFactory.CreateButton("CmpClr", btnRow.transform, "Clear", 13f, C_WHITE,
                new Color(0.4f, 0.2f, 0.2f, 0.9f),
                // Clears whichever selection the active sub-tab owns.
                () => { if (compareSubTab == 1) compareCardsSelected.Clear(); else compareSelected.Clear(); dirty = true; },
                sizeDelta: new Vector2(120, 24));
            UIFactory.AddLE(clrBtn, prefH: 24, flexW: 1, flexH: 0);
            compareClrSearchBtn = UIFactory.CreateButton("CmpClrS", btnRow.transform, "Clear Search", 13f, C_WHITE,
                new Color(0.25f, 0.3f, 0.4f, 0.9f), () => { compareSearch = ""; dirty = true; },
                sizeDelta: new Vector2(120, 24));
            UIFactory.AddLE(compareClrSearchBtn, prefH: 24, flexW: 1, flexH: 0);
            // childForceExpandWidth:false → the row buttons keep their own (narrower)
            // width and sit left-aligned, leaving a dead strip on the right of the picker
            // that's still inside the scroll viewport. Sid can click/scroll there without
            // selecting a player (the freed space stays in the picker, not handed to the
            // right panel like the previous attempt).
            var sv = UIFactory.CreateScrollView("CmpSV", left.transform, spacing: 2, childForceExpandWidth: false);
            UIFactory.AddLE(sv.scrollGO, flexH: 1);
            comparePickerContent = sv.content;

            // RIGHT: metric toggle + graph + cards.
            var right = UIFactory.CreatePanel("CmpR", panel.transform, C_PANEL);
            UIFactory.AddVLG(right, spacing: 6, padL: 10, padR: 10, padT: 8, padB: 8);
            UIFactory.AddLE(right, flexW: 1, flexH: 1);
            var metricRow = new GameObject("CmpMetRow"); metricRow.transform.SetParent(right.transform, false);
            metricRow.AddComponent<RectTransform>(); UIFactory.AddHLG(metricRow, spacing: 4, forceExpandH: true);
            UIFactory.AddLE(metricRow, prefH: 30, flexH: 0);
            /* Aug 6 item 2 replaced the < / label / > cycler with the searchable
             * dropdown; bug 176 (Stan) asked for BOTH — the arrows walk the list
             * one step at a time, the center button still opens the picker. The
             * arrows write ActiveMetricIndex (NOT compareMetric directly) so they
             * stay sub-tab aware — same state the picker rows write, so the two
             * controls can never fork. */
            var cmpPrev = UIFactory.CreateButton("CmpMetP", metricRow.transform, "<",
                15f, C_WHITE, C_TAB, () =>
                {
                    int len = ActiveMetrics.Length;
                    ActiveMetricIndex = (ActiveMetricIndex - 1 + len) % len;
                    dirty = true;
                }, sizeDelta: new Vector2(30, 30));
            UIFactory.AddLE(cmpPrev, prefW: 30, prefH: 30, flexW: 0, flexH: 0);
            compareMetricBtn = UIFactory.CreateButton("CmpMet", metricRow.transform, "Showing: Elo over games",
                15f, C_WHITE, C_TAB, OpenMetricPicker, sizeDelta: new Vector2(320, 30));
            UIFactory.AddLE(compareMetricBtn, prefH: 30, flexW: 1, flexH: 0);
            var cmpNext = UIFactory.CreateButton("CmpMetN", metricRow.transform, ">",
                15f, C_WHITE, C_TAB, () =>
                {
                    int len = ActiveMetrics.Length;
                    ActiveMetricIndex = (ActiveMetricIndex + 1) % len;
                    dirty = true;
                }, sizeDelta: new Vector2(30, 30));
            UIFactory.AddLE(cmpNext, prefW: 30, prefH: 30, flexW: 0, flexH: 0);
            compareMetricBtnTxt = UIFactory.GetButtonText(compareMetricBtn);
            // The label is one line in a 30px row and carries a translated metric
            // name; without this the global Truncate default clips it (#292).
            UIFactory.FitOneLine(compareMetricBtnTxt);

            // Chart plot — FILLS the right panel (was a fixed 640x320 that used ~1/4 of
            // the space, forcing abbreviated/cut-off names). The chart math reads the
            // RectTransform's actual size at render time (CompareChartSize) so it scales.
            compareGraphPanel = new GameObject("CmpGraph");
            compareGraphPanel.transform.SetParent(right.transform, false);
            compareGraphPanel.AddComponent<RectTransform>();
            UIFactory.AddLE(compareGraphPanel, flexW: 1, flexH: 1);
            var gbg = compareGraphPanel.AddComponent(UIFactory.tImage);
            UIFactory.tImage.GetProperty("color", BindingFlags.Public | BindingFlags.Instance)
                ?.SetValue(gbg, new Color(0.08f, 0.09f, 0.12f, 0.7f));
            if (UIFactory.tMask != null)
            {
                var gm = compareGraphPanel.AddComponent(UIFactory.tMask);
                try { UIFactory.tMask.GetProperty("showMaskGraphic", BindingFlags.Public | BindingFlags.Instance)?.SetValue(gm, true); } catch {}
            }

            // Table-metric scroll (shown for every metric except the Elo graph).
            // Used for Top/Worst Cards, Hit/Block %, Avg metrics, Peak Elo, XP,
            // Achievements, Region time. Word-wrap on so the content height tracks
            // the rendered text and the scroll actually scrolls (learnings #63).
            var cardsSV = UIFactory.CreateScrollView("CmpCardsSV", right.transform, spacing: 0);
            UIFactory.AddLE(cardsSV.scrollGO, flexH: 1);
            compareCardsScroll = cardsSV.scrollGO;
            compareCardsContent = cardsSV.content;
            // txtCompareCards is the empty/loading message; the actual card data is
            // rendered as a multi-column grid of per-player blocks (BuildCompareCardGrid)
            // so 12 players wrap sideways instead of running off the bottom.
            txtCompareCards = UIFactory.CreateText("CmpCards", cardsSV.content.transform, "",
                15f, C_DIM, UIFactory.AlignTopLeft, sizeDelta: new Vector2(820, 24));
            UIFactory.SetWordWrap(txtCompareCards, true);
            UIFactory.SetTextAutoHeight(txtCompareCards);
            // Scroll affordance — matches the 2v2 tab's pattern (codebase avoids
            // real Unity Scrollbars). Tells the user the panel scrolls.
            UIFactory.CreateText("CmpScrollHint", right.transform,
                "<color=#777><i>hover the panel and scroll for more</i></color>",
                12f, C_DIM, UIFactory.AlignMidCenter, sizeDelta: new Vector2(820, 16));

            return outer;
        }

        private static void ToggleCompareSelect(int rowIdx)
        {
            if (rowIdx < 0 || rowIdx >= comparePickerSteamIds.Count) return;
            string sid = comparePickerSteamIds[rowIdx];
            if (string.IsNullOrEmpty(sid)) return;
            /* The row pool is shared between sub-tabs, so the slot holds a card
             * name while Cards is active. Dispatch on the sub-tab BEFORE touching
             * compareSelected, or a card name lands in the player selection and
             * every downstream stats lookup silently misses. */
            if (compareSubTab == 1) { ToggleCompareCard(sid); return; }
            if (compareSelected.Contains(sid))
            {
                compareSelected.Remove(sid);
            }
            else
            {
                if (compareSelected.Count >= COMPARE_MAX)
                {
                    // F9 sweep: a $-string at a ShowNotification site harvests NOTHING
                    // (the extractor strips interpolated strings — the compiler composes
                    // them, so a whole-string key could never match). TrF puts the count
                    // in a hole and makes the template the key.
                    CompetitiveUI.ShowNotification(I18n.TrF("Max {0} players", COMPARE_MAX), new Color(1f, 0.6f, 0.3f));
                    return;
                }
                compareSelected.Add(sid);
                if (!compareStatsCache.ContainsKey(sid))
                    ApiClient.FetchPlayerStatsForView(sid, (d) => { if (d != null) compareStatsCache[sid] = d; dirty = true; });
            }
            dirty = true;
        }

        private static void RefreshCompare()
        {
            if (ApiClient.CachedLeaderboard == null) ApiClient.FetchLeaderboard();
            /* If the picker is open and its supplied item set has grown, rebuild
             * it. Guarded on a COUNT CHANGE rather than rebuilt unconditionally
             * so a routine dirty pass doesn't destroy the rows out from under a
             * click or reset the user's scroll position.
             *
             * Aug 7 item 2: this was written for the card chooser's catalogue
             * landing mid-open. That chooser is gone (cards are a persistent
             * left-column list now) and the only remaining caller is the metric
             * dropdown, whose supplier is a static array — so today this never
             * fires. Kept because it is part of the generic picker's contract
             * with an async supplier, not Compare-tab state. */
            if (pickerGO != null && pickerItemsFn != null)
            {
                var fresh = pickerItemsFn();
                if ((fresh?.Count ?? 0) != pickerItems.Count) RebuildPickerList();
            }
            bool cardsTab = compareSubTab == 1;
            string metricName = ActiveMetricName;

            // Sub-tab button state.
            if (compareSubTabPlayersBtn != null)
            {
                UIFactory.SetImageColor(compareSubTabPlayersBtn, cardsTab ? C_TAB : C_TABACT);
                var t = UIFactory.GetButtonText(compareSubTabPlayersBtn);
                UIFactory.SetColor(t, cardsTab ? C_LABEL : C_WHITE);
            }
            if (compareSubTabCardsBtn != null)
            {
                UIFactory.SetImageColor(compareSubTabCardsBtn, cardsTab ? C_TABACT : C_TAB);
                var t = UIFactory.GetButtonText(compareSubTabCardsBtn);
                UIFactory.SetColor(t, cardsTab ? C_WHITE : C_LABEL);
            }
            /* Aug 7 item 2 — the search box is LIVE on both sub-tabs. It used to
             * be deactivated on Cards, which is also what suppressed the IMGUI
             * field (GetCompareSearchScreenRect returns zero for an inactive
             * anchor). Now only the caption changes; the field itself filters
             * whichever list the sub-tab is showing. The caption is re-set every
             * refresh rather than at build time so a locale switch retranslates
             * it, and each literal sits INSIDE its own Tr call (#295a). */
            if (compareSearchCap != null)
            {
                ((Component)compareSearchCap).gameObject.SetActive(true);
                UIFactory.SetTextRaw(compareSearchCap, "<color=#88AAFF>"
                    + (cardsTab ? I18n.Tr("Search cards") : I18n.Tr("Search players")) + "</color>");
            }
            if (compareSearchField != null)
                ((Component)compareSearchField).gameObject.SetActive(true);
            if (compareClrSearchBtn != null) compareClrSearchBtn.SetActive(true);
            if (txtCompareHeader != null)
                UIFactory.SetTextRaw(txtCompareHeader, cardsTab
                    ? I18n.Tr("Compare Cards") : I18n.Tr("Compare Players"));

            if (compareMetricBtnTxt != null)
                /* item 11: composed BEFORE SetText, so the finished string could
                 * never match a catalogue key (only the build-time literal
                 * "Showing: Elo over games" was ever harvested). Translate the parts,
                 * then compose, then SetTextRaw so the chokepoint does not re-Tr it. */
                UIFactory.SetTextRaw(compareMetricBtnTxt,
                    I18n.TrF("Showing: {0}", TrMetric(metricName)) + "   <color=#888>" + I18n.Tr("(click to change)") + "</color>");
            if (txtCompareStatus != null)
                UIFactory.SetTextRaw(txtCompareStatus, cardsTab
                    ? I18n.TrF("Selected {0}/{1}  -  click a card to add/remove", compareCardsSelected.Count, COMPARE_CARDS_MAX)
                    : I18n.TrF("Selected {0}/{1}  -  click a player to add/remove", compareSelected.Count, COMPARE_MAX));
            // Keep the anchor label EMPTY — the IMGUI text field (CompetitiveUI.DrawCompareSearch)
            // draws over it and shows the value/placeholder. Setting text here too caused the
            // double-layered, hard-to-read box.
            if (compareSearchField != null) UIFactory.SetText(compareSearchField, "");

            if (cardsTab) { RefreshCompareCardsTab(metricName); return; }

            // Build the picker list from the current leaderboard, filtered by the
            // search box. comparePickerSteamIds[rowIdx] maps the VISIBLE row index to
            // a steam_id so ToggleCompareSelect(rowIdx) resolves correctly.
            var board = ApiClient.CachedLeaderboard;
            var allEntries = (board != null && board.entries != null)
                ? board.entries : new ApiClient.LeaderboardEntry[0];
            string q = (compareSearch ?? "").Trim();
            var shown = new List<ApiClient.LeaderboardEntry>();
            foreach (var e in allEntries)
            {
                if (string.IsNullOrEmpty(q)
                    || (e.display_name != null && e.display_name.IndexOf(q, StringComparison.OrdinalIgnoreCase) >= 0))
                    shown.Add(e);
            }
            int n = shown.Count;
            while (comparePickerSteamIds.Count < n) comparePickerSteamIds.Add("");
            for (int i = 0; i < n; i++)
            {
                var e = shown[i];
                comparePickerSteamIds[i] = e.steam_id;
                while (comparePickerRows.Count <= i)
                {
                    int idx = comparePickerRows.Count;
                    var b = UIFactory.CreateButton($"cmpP{idx}", comparePickerContent.transform, "",
                        13f, C_WHITE, C_TAB, () => ToggleCompareSelect(idx), sizeDelta: new Vector2(168, 24));
                    UIFactory.AddLE(b, prefW: 168, prefH: 24, flexW: 0, flexH: 0);
                    comparePickerRows.Add(b);
                    comparePickerTexts.Add(UIFactory.GetButtonText(b));
                }
                var row = comparePickerRows[i];
                row.SetActive(true);
                bool sel = compareSelected.Contains(e.steam_id);
                int selOrder = compareSelected.IndexOf(e.steam_id);
                Color swatch = sel && selOrder >= 0 ? COMPARE_COLORS[selOrder % COMPARE_COLORS.Length] : C_LABEL;
                string dot = sel ? $"<color=#{ColorToHex(swatch)}>[X]</color> " : "<color=#555>[ ]</color> ";
                UIFactory.SetText(comparePickerTexts[i], $"{dot}{Trunc(e.display_name, 16)}  <color=#888>{e.rating}</color>");
                UIFactory.SetImageColor(row, sel ? new Color(0.2f, 0.3f, 0.25f, 0.9f) : C_TAB);
            }
            for (int i = n; i < comparePickerRows.Count; i++) comparePickerRows[i].SetActive(false);

            // Route each metric to the renderer that fits its data:
            //   "Elo over games"      → line graph        (compareGraphPanel)
            //   "Top/Worst Cards"     → multi-column grid  (compareCardsScroll)
            //   everything else       → bar/grouped/stacked chart (compareGraphPanel)
            bool isCards = metricName == "Top Cards" || metricName == "Worst Cards";
            /* Aug 7 item 2d: "Player Nemesis" joins the cards metrics on the
             * SCROLLING surface. Its height grows with the selection (up to 12
             * blocks of 6 lines) and compareGraphPanel is a fixed mask with no
             * scroll, so anything past the first few players would be invisible
             * there (#199/#245). */
            bool useScroll = isCards || metricName == "Player Nemesis";
            if (compareGraphPanel != null) compareGraphPanel.SetActive(!useScroll);
            if (compareCardsScroll != null) compareCardsScroll.SetActive(useScroll);

            if (metricName == "Elo over games") BuildCompareGraph();
            else if (metricName == "Elo over time") BuildCompareGraph(timeAxis: true);
            else if (metricName == "FFA Elo over games") BuildCompareGraph(ffa: true);
            else if (metricName == "FFA Elo over time") BuildCompareGraph(timeAxis: true, ffa: true);
            else if (isCards) BuildCompareCardGrid(metricName);
            else if (metricName == "Player Nemesis") BuildComparePlayerNemesisPanel();
            else BuildCompareBarChart(metricName);
        }

        /// <summary>Aug 7 item 2 — the Cards sub-tab's left column is now a
        /// PERSISTENT list of the whole card catalogue, exactly like the player
        /// picker: same pooled grow-only rows, same [X]/[ ] + name + stat
        /// shape, same search box. It used to list only the already-SELECTED
        /// cards, with a "Choose cards..." button raising a modal dropdown to add
        /// any; that dropdown is gone.
        ///
        /// The catalogue arrives asynchronously, so an empty list here means
        /// "still loading" and NOT "no cards" — the two are labelled differently
        /// because a permanent "No cards" on a slow connection reads as a broken
        /// tab. Everything else is drawn into compareGraphPanel, a masked
        /// free-positioning surface, so no row can overpaint a sibling the way a
        /// fixed-height VLG stack does (#199).</summary>
        private static void RefreshCompareCardsTab(string metricName)
        {
            ApiClient.FetchCardCatalog();

            /* Build the visible card list from the catalogue, filtered by the
             * SAME search box the player list uses. Matched against both the
             * localized display name (what the user is reading and typing) and
             * the raw stored name, mirroring how the old dropdown filtered. */
            var cat = ApiClient.CardCatalog;
            string q = (compareSearch ?? "").Trim();
            var shownCards = new List<ApiClient.CardCatalogEntry>();
            if (cat != null)
            {
                foreach (var e in cat)
                {
                    if (e == null || string.IsNullOrEmpty(e.name)) continue;
                    if (q.Length == 0) { shownCards.Add(e); continue; }
                    string disp = null;
                    try { disp = CardTextLocalizer.PrettyName(e.name, e.name); } catch { }
                    if ((disp != null && disp.IndexOf(q, StringComparison.OrdinalIgnoreCase) >= 0)
                        || e.name.IndexOf(q, StringComparison.OrdinalIgnoreCase) >= 0)
                        shownCards.Add(e);
                }
            }

            // Left column: one row per VISIBLE card, colored by rarity, marked
            // [X] when selected. Same pool as the player picker — only one
            // sub-tab is ever visible, so the slot means "row key", player or
            // card, and ToggleCompareSelect dispatches on compareSubTab.
            int n = shownCards.Count;
            while (comparePickerSteamIds.Count < n) comparePickerSteamIds.Add("");
            for (int i = 0; i < n; i++)
            {
                var ent = shownCards[i];
                string card = ent.name;
                comparePickerSteamIds[i] = card;
                while (comparePickerRows.Count <= i)
                {
                    int idx = comparePickerRows.Count;
                    var b = UIFactory.CreateButton($"cmpP{idx}", comparePickerContent.transform, "",
                        13f, C_WHITE, C_TAB, () => ToggleCompareSelect(idx), sizeDelta: new Vector2(168, 24));
                    UIFactory.AddLE(b, prefW: 168, prefH: 24, flexW: 0, flexH: 0);
                    comparePickerRows.Add(b);
                    comparePickerTexts.Add(UIFactory.GetButtonText(b));
                }
                var row = comparePickerRows[i];
                row.SetActive(true);
                bool sel = compareCardsSelected.Contains(card);
                Color cc = CardColorFor(card);
                string disp2 = CardTextLocalizer.PrettyName(card, card) ?? card;
                string mark = sel ? "<color=#77FF99>[X]</color> " : "<color=#555>[ ]</color> ";
                /* 14 visible name characters, not the player list's 16: the card
                 * row carries a wider trailing stat (pick counts run to 4-5
                 * digits where a rating is always 4) inside the same 168px row,
                 * and the global Truncate default would drop the overflow rather
                 * than wrap it (#292). Card names are DB-stored strings, so they
                 * go through FfaSafeRich before reaching TMP rich text. */
                UIFactory.SetTextRaw(comparePickerTexts[i],
                    $"{mark}<color=#{ColorToHex(cc)}>{FfaSafeRich(Trunc(disp2, 14))}</color>"
                    + $"  <color=#888>{ent.times_picked}</color>");
                UIFactory.SetImageColor(row, sel ? new Color(0.2f, 0.3f, 0.25f, 0.9f) : C_TAB);
            }
            for (int i = n; i < comparePickerRows.Count; i++) comparePickerRows[i].SetActive(false);

            /* Empty-state line, reusing row 0 of the same pool so it can never
             * outlive the list (a separately-created child would leak one object
             * per refresh). Distinguishes "loading" from "nothing matched": the
             * catalogue is null until /cards answers. */
            if (n == 0)
            {
                if (comparePickerRows.Count == 0)
                {
                    // The pool is grown inside the row loop above, which does not
                    // run when nothing is visible — so a user who opens Compare
                    // straight onto Cards has no row to write into yet.
                    var b0 = UIFactory.CreateButton("cmpP0", comparePickerContent.transform, "",
                        13f, C_WHITE, C_TAB, () => ToggleCompareSelect(0), sizeDelta: new Vector2(168, 24));
                    UIFactory.AddLE(b0, prefW: 168, prefH: 24, flexW: 0, flexH: 0);
                    comparePickerRows.Add(b0);
                    comparePickerTexts.Add(UIFactory.GetButtonText(b0));
                }
                comparePickerRows[0].SetActive(true);
                UIFactory.SetImageColor(comparePickerRows[0], C_TAB);
                UIFactory.SetTextRaw(comparePickerTexts[0], "<color=#888>"
                    + (cat == null ? I18n.Tr("Loading...") : I18n.Tr("No matches.")) + "</color>");
                // Slot 0 must not resolve to a real card while it shows this.
                if (comparePickerSteamIds.Count == 0) comparePickerSteamIds.Add("");
                comparePickerSteamIds[0] = "";
            }

            // Cards metrics all render into the chart panel.
            if (compareGraphPanel != null) compareGraphPanel.SetActive(true);
            if (compareCardsScroll != null) compareCardsScroll.SetActive(false);
            BuildCompareCardMetric(metricName);
        }

        private static string ColorToHex(Color c)
        {
            int r = Mathf.Clamp((int)(c.r * 255f), 0, 255);
            int g = Mathf.Clamp((int)(c.g * 255f), 0, 255);
            int b = Mathf.Clamp((int)(c.b * 255f), 0, 255);
            return $"{r:X2}{g:X2}{b:X2}";
        }

        /// <summary>The Elo line graph. `ffa` (Aug 7 item 1) selects the FFA
        /// rating series instead of the 1v1 one — same axes, colours and sizing,
        /// because the two are the same shape of data and a second copy of this
        /// method would drift (#279). The FFA series is parsed by ApiClient into
        /// a parallel pair with the SAME 1500-baseline prepend as the 1v1 one, so
        /// every length assumption below still holds.</summary>
        private static void BuildCompareGraph(bool timeAxis = false, bool ffa = false)
        {
            if (compareGraphPanel == null) return;
            for (int c = compareGraphPanel.transform.childCount - 1; c >= 0; c--)
                UnityEngine.Object.Destroy(compareGraphPanel.transform.GetChild(c).gameObject);
            CompetitiveUI.ClearCardHoverRegions();   // Records hovers die with the panel (Aug 17)

            // Gather each selected player's Elo series from cache. timeAxis
            // (v1.29 "Elo over time") plots x by SNAPSHOT DATE instead of game
            // index, so gaps in play show as flat stretches, and players who
            // started months apart line up on a real calendar.
            var names = new List<string>();
            var cols = new List<Color>();
            var seriesList = new List<float[]>();
            var timesList = new List<float[]>();
            for (int i = 0; i < compareSelected.Count; i++)
            {
                string sid = compareSelected[i];
                if (!compareStatsCache.TryGetValue(sid, out var ps) || ps == null) continue;
                var hist = ffa ? ps.ffa_rating_history : ps.rating_history;
                var histTimes = ffa ? ps.ffa_rating_history_times : ps.rating_history_times;
                // <2 snapshots is SKIPPED, not drawn: a single point is a dot with
                // no line, which reads as a rendering failure rather than as "this
                // player has one rated game". Same rule the 1v1 series has always
                // had — and it is the common case for FFA, which is newer.
                if (hist == null || hist.Count < 2) continue;
                float[] times = null;
                if (timeAxis)
                {
                    if (histTimes == null || histTimes.Count != hist.Count)
                        continue; // no usable timestamps for this player
                    times = histTimes.ToArray();
                }
                names.Add(Trunc(ps.display_name ?? "?", 14));
                cols.Add(COMPARE_COLORS[i % COMPARE_COLORS.Length]);
                seriesList.Add(hist.ToArray());
                timesList.Add(times);
            }

            CompareChartSize(out float W, out float H);
            float padL = 56f, padR = 16f, padT = 30f, padB = 26f;
            float plotW = W - padL - padR, plotH = H - padT - padB;

            if (seriesList.Count == 0)
            {
                /* Name the LADDER in the empty state: with four Elo metrics in the
                 * dropdown, "no ranked history" on the FFA chart reads as a bug to
                 * a player who has plenty of 1v1 history. Both literals sit inside
                 * their own Tr call — I18n.Tr(variable) harvests nothing (#295a). */
                var msg = UIFactory.CreateText("CmpNone", compareGraphPanel.transform,
                    ffa ? I18n.Tr("<color=#888>Select 2+ players with rated FFA history to compare FFA Elo.</color>")
                        : "<color=#888>Select 2+ players with ranked history to compare Elo.</color>",
                    15f, C_DIM, UIFactory.AlignMidCenter, sizeDelta: new Vector2(W - 20, 40));
                var mrt = (msg as Component)?.gameObject.GetComponent<RectTransform>();
                if (mrt != null) { mrt.anchorMin = new Vector2(0.5f, 0.5f); mrt.anchorMax = new Vector2(0.5f, 0.5f); mrt.anchoredPosition = Vector2.zero; }
                var mle = (msg as Component)?.gameObject.GetComponent(UIFactory.tLE);
                if (mle != null) UnityEngine.Object.Destroy(mle as UnityEngine.Object);
                return;
            }

            // Global Y range + max length (X = game index, shared across players).
            float minV = float.MaxValue, maxV = float.MinValue; int maxLen = 0;
            foreach (var s in seriesList)
            {
                if (s.Length > maxLen) maxLen = s.Length;
                foreach (var v in s) { if (v < minV) minV = v; if (v > maxV) maxV = v; }
            }
            if (maxLen < 2) maxLen = 2;
            // Round the Y range to clean Elo numbers (e.g. 1400, 1500, … 1900) instead of
            // padded fractions like 1437→1913 with a label at 2185. Snap min DOWN and max
            // UP to a nice step, then label every step.
            float rawRange = Mathf.Max(1f, maxV - minV);
            float step = NiceStep(rawRange / 4f);
            float gMin = Mathf.Floor(minV / step) * step;
            float gMax = Mathf.Ceil(maxV / step) * step;
            if (gMax - gMin < step) gMax = gMin + step;
            minV = gMin; maxV = gMax; float range = maxV - minV;

            // Y-axis: a gridline + clean Elo label at every step.
            int yDivs = Mathf.Clamp(Mathf.RoundToInt(range / step), 2, 8);
            for (int gi = 0; gi <= yDivs; gi++)
            {
                float val = gMin + gi * step;
                if (val > gMax + 0.5f) break;
                float yy = padB + (val - gMin) / range * plotH;
                DrawBar($"CmpYGrid{gi}", padL, yy, plotW, 1f, new Color(1f, 1f, 1f, 0.10f));
                MakeGraphLabel($"CmpYLbl{gi}", $"<color=#999>{FullNum(val)}</color>",
                    new Vector2(0, 0), new Vector2(padL - 4f, yy - 6f), new Vector2(50, 12), UIFactory.AlignMidRight);
            }
            // X axis: game index (default) or calendar time (timeAxis).
            float tMin = 0f, tRange = 1f;
            if (timeAxis)
            {
                tMin = float.MaxValue; float tMax = float.MinValue;
                foreach (var ts in timesList)
                    foreach (var t in ts) { if (t < tMin) tMin = t; if (t > tMax) tMax = t; }
                tRange = Mathf.Max(0.5f, tMax - tMin);
                // Date gridlines: 4 divisions labeled M/d (days since 2020-01-01 base).
                var epoch = new DateTime(2020, 1, 1);
                for (int d = 0; d <= 4; d++)
                {
                    float tv = tMin + tRange * d / 4f;
                    float xx = padL + (tv - tMin) / tRange * plotW;
                    DrawBar($"CmpXGrid{d}", xx, padB, 1f, plotH, new Color(1f, 1f, 1f, 0.07f));
                    string dl = DateFmt.Short(epoch.AddDays(tv));
                    MakeGraphLabel($"CmpXDate{d}", $"<color=#999>{dl}</color>",
                        new Vector2(0, 0), new Vector2(xx - 24f, padB - 16f), new Vector2(48, 12), UIFactory.AlignMidCenter);
                }
            }
            else
            {
                MakeGraphLabel("CmpXLbl", $"<color=#888>{I18n.Tr("games ->")}</color>", new Vector2(1, 0), new Vector2(-padR, padB - 14f), new Vector2(90, 12), UIFactory.AlignMidRight);
            }

            // Draw each player's line + legend chip (full names — there's room now).
            for (int si = 0; si < seriesList.Count; si++)
            {
                var pts = seriesList[si];
                var ts = timesList[si];
                Color col = cols[si];
                for (int j = 0; j < pts.Length - 1; j++)
                {
                    float x1 = timeAxis
                        ? padL + (ts[j] - tMin) / tRange * plotW
                        : padL + (float)j / (maxLen - 1) * plotW;
                    float y1 = padB + (pts[j] - minV) / range * plotH;
                    float x2 = timeAxis
                        ? padL + (ts[j + 1] - tMin) / tRange * plotW
                        : padL + (float)(j + 1) / (maxLen - 1) * plotW;
                    float y2 = padB + (pts[j + 1] - minV) / range * plotH;
                    DrawGraphSegment($"CmpL{si}_{j}", x1, y1, x2, y2, col, 2f);
                }
                // Legend: a SOLID colored line swatch (matches the player's graph line)
                // + their name. The old "--" dashes were too thin to read as a color.
                int perRow = 3;
                float colW = plotW / perRow;
                float lx = padL + (si % perRow) * colW;
                float ly = -2f - (si / perRow) * 16f;
                // Swatch line sits in the panel's top band; convert top-anchored ly to a
                // bottom-left y for DrawGraphSegment (it anchors at bottom-left).
                float swY = H + ly - 7f;
                DrawGraphSegment($"CmpLegSw{si}", lx + 2f, swY, lx + 24f, swY, col, 4f);
                MakeGraphLabel($"CmpLeg{si}", $"<b>{names[si]}</b>",
                    new Vector2(0, 1), new Vector2(lx + 30f, ly), new Vector2(colW - 30f, 16), UIFactory.AlignMidLeft, 13f);
            }
        }

        // Helper: a rotated 1px-tall rect acting as a line segment in compareGraphPanel.
        private static void DrawGraphSegment(string name, float x1, float y1, float x2, float y2, Color col, float thick)
        {
            float dx = x2 - x1, dy = y2 - y1;
            float len = Mathf.Sqrt(dx * dx + dy * dy);
            float angle = Mathf.Atan2(dy, dx) * Mathf.Rad2Deg;
            var seg = new GameObject(name);
            seg.transform.SetParent(compareGraphPanel.transform, false);
            var srt = seg.AddComponent<RectTransform>();
            srt.anchorMin = Vector2.zero; srt.anchorMax = Vector2.zero; srt.pivot = new Vector2(0f, 0.5f);
            srt.anchoredPosition = new Vector2(x1, y1);
            srt.sizeDelta = new Vector2(len, thick);
            srt.localRotation = Quaternion.Euler(0, 0, angle);
            var img = seg.AddComponent(UIFactory.tImage);
            UIFactory.tImage.GetProperty("color", BindingFlags.Public | BindingFlags.Instance)?.SetValue(img, col);
        }

        // Helper: a positioned label inside compareGraphPanel (bottom-left anchored coords).
        // Returns the created text object (Aug 17: the Records rows register
        // hover regions on their labels); existing callers ignore the value.
        private static object MakeGraphLabel(string name, string text, Vector2 anchor, Vector2 pos, Vector2 size, int align, float fontSize = 11f)
        {
            var lbl = UIFactory.CreateText(name, compareGraphPanel.transform, text, fontSize, C_DIM, align, sizeDelta: size);
            /* Aug-3 item 12 ("chart labels missing / pie has leader lines but no
             * text"). CreateText floors the font at 12pt and cd73a96 made Truncate
             * the global default; every label here is built into an 11-16px rect,
             * so a 12pt Gravity line (~14.4-16.2px of line box) did not fit
             * VERTICALLY and TMP dropped the whole line — in every language. Only
             * the three >=18px titles survived, which is exactly the reported
             * symptom (the pie TITLE shows, every slice/legend/axis label is gone).
             * A chart label floats over the plot with nothing to overlap, so
             * Overflow was always the correct mode here. Wrap off too: a 64px box
             * otherwise breaks "US 42%" onto a second line and truncates harder. */
            UIFactory.FitOneLine(lbl);
            var go = (lbl as Component)?.gameObject;
            if (go == null) return lbl;
            var rt = go.GetComponent<RectTransform>();
            rt.anchorMin = anchor; rt.anchorMax = anchor; rt.pivot = anchor;
            rt.anchoredPosition = pos; rt.sizeDelta = size;
            var le = go.GetComponent(UIFactory.tLE);
            if (le != null) UnityEngine.Object.Destroy(le as UnityEngine.Object);
            return lbl;
        }

        // Helper: a filled rectangle bar in compareGraphPanel, anchored bottom-left
        // (same coordinate space as DrawGraphSegment / the line graph plot math).
        private static void DrawBar(string name, float x, float y, float w, float h, Color col)
        {
            if (h < 0f) h = 0f;
            var go = new GameObject(name);
            go.transform.SetParent(compareGraphPanel.transform, false);
            var rt = go.AddComponent<RectTransform>();
            rt.anchorMin = Vector2.zero; rt.anchorMax = Vector2.zero; rt.pivot = new Vector2(0f, 0f);
            rt.anchoredPosition = new Vector2(x, y);
            rt.sizeDelta = new Vector2(w, h);
            var img = go.AddComponent(UIFactory.tImage);
            UIFactory.tImage.GetProperty("color", BindingFlags.Public | BindingFlags.Instance)?.SetValue(img, col);
        }

        // Region → color for the stacked "Region Time" chart + its legend.
        private static Color RegionColor(string region)
        {
            // Distinct, well-separated hues — the old palette had several near-identical
            // blues (us/in/kr looked the same in the legend).
            switch ((region ?? "").ToLowerInvariant())
            {
                case "us":   return new Color(0.25f, 0.55f, 1.00f);  // blue
                case "usw":  return new Color(0.15f, 0.85f, 0.85f);  // cyan
                case "ussc": return new Color(0.35f, 0.80f, 0.35f);  // green
                case "eu":   return new Color(1.00f, 0.62f, 0.18f);  // orange
                case "asia": return new Color(0.95f, 0.32f, 0.32f);  // red
                case "jp":   return new Color(1.00f, 0.42f, 0.80f);  // pink
                case "au":   return new Color(0.68f, 0.42f, 1.00f);  // purple
                case "sa":   return new Color(0.80f, 0.85f, 0.20f);  // yellow-green
                case "kr":   return new Color(1.00f, 0.82f, 0.28f);  // gold
                case "in":   return new Color(0.45f, 0.40f, 0.92f);  // indigo
                case "cae":  return new Color(0.50f, 0.78f, 0.62f);  // sea green
                case "za":   return new Color(0.90f, 0.55f, 0.35f);  // terracotta
                case "ru": case "rue": return new Color(0.80f, 0.50f, 0.55f); // mauve
                default:     return new Color(0.70f, 0.70f, 0.74f);  // grey
            }
        }

        // Actual on-screen size of the chart panel (it now FILLS the right panel, so the
        // chart math must read the live RectTransform instead of a fixed 640x320). Falls
        // back to sane defaults before the first layout pass computes the rect.
        private static void CompareChartSize(out float W, out float H)
        {
            W = 900f; H = 460f;
            try
            {
                var rt = compareGraphPanel != null ? compareGraphPanel.GetComponent<RectTransform>() : null;
                if (rt != null)
                {
                    if (rt.rect.width > 50f) W = rt.rect.width;
                    if (rt.rect.height > 50f) H = rt.rect.height;
                }
            }
            catch { }
        }

        // A "nice" round step so axis labels are clean numbers (100, 250, 500, 1000, …)
        // instead of maxV/divs giving 2185. Returns a step; caller takes ceil(max/step)*step.
        private static float NiceStep(float roughStep)
        {
            if (roughStep <= 0f) return 1f;
            float mag = Mathf.Pow(10f, Mathf.Floor(Mathf.Log10(roughStep)));
            float norm = roughStep / mag; // 1..10
            float nice = norm <= 1f ? 1f : norm <= 2f ? 2f : norm <= 2.5f ? 2.5f : norm <= 5f ? 5f : 10f;
            return nice * mag;
        }

        // Whole-number formatting with thousands separators — Sid wanted "12,345" not "12.3k".
        private static string FullNum(float v) => Mathf.RoundToInt(v).ToString("N0");

        // Mirror of the server XP curve (main.py xp_for_level = 100*n^1.5, cumulative).
        // Used to label the Total XP chart's gridlines with LEVELS instead of raw XP.
        private static long TotalXpForLevel(int level)
        {
            long sum = 0;
            for (int n = 1; n <= level && n <= 100; n++) sum += (long)(100.0 * Math.Pow(n, 1.5));
            return sum;
        }
        private static int LevelForXp(float xp)
        {
            long rem = (long)Math.Max(0f, xp); int lvl = 0;
            for (int n = 1; n <= 100; n++) { long need = (long)(100.0 * Math.Pow(n, 1.5)); if (rem < need) return lvl; rem -= need; lvl = n; }
            return 100;
        }

        // Smooth green(best) → yellow → red(worst) gradient for t in [0,1].
        private static Color GradeColor(float t)
        {
            t = Mathf.Clamp01(t);
            Color green = new Color(0.35f, 0.85f, 0.40f);
            Color amber = new Color(0.95f, 0.82f, 0.30f);
            Color red = new Color(0.95f, 0.40f, 0.40f);
            return t < 0.5f ? Color.Lerp(green, amber, t * 2f) : Color.Lerp(amber, red, (t - 0.5f) * 2f);
        }

        // Lazily-built white circle sprite for pie slices (Image type=Filled, Radial360).
        private static UnityEngine.Sprite _pieCircleSprite;
        private static UnityEngine.Sprite GetCircleSprite()
        {
            if (_pieCircleSprite != null) return _pieCircleSprite;
            try
            {
                int S = 128; float r = S * 0.5f, cx = r, cy = r;
                var tex = new Texture2D(S, S, TextureFormat.RGBA32, false);
                tex.hideFlags = HideFlags.HideAndDontSave;
                var px = new Color32[S * S];
                for (int y = 0; y < S; y++)
                    for (int x = 0; x < S; x++)
                    {
                        float dx = x + 0.5f - cx, dy = y + 0.5f - cy;
                        bool inside = dx * dx + dy * dy <= (r - 1f) * (r - 1f);
                        px[y * S + x] = inside ? new Color32(255, 255, 255, 255) : new Color32(255, 255, 255, 0);
                    }
                tex.SetPixels32(px); tex.Apply();
                _pieCircleSprite = UnityEngine.Sprite.Create(tex, new Rect(0, 0, S, S), new Vector2(0.5f, 0.5f), 100f);
                _pieCircleSprite.hideFlags = HideFlags.HideAndDontSave;
            }
            catch { _pieCircleSprite = null; }
            return _pieCircleSprite;
        }

        // ── July 21 item 9: Body Color shop glyphs ────────────────────────
        // A ROUNDS-character-ish preview (big circle body + two floating hands
        // + two feet) rasterized per color with a baked contrasting 1px outline
        // (dark SKUs like Obsidian/Charcoal would vanish on the panel without
        // it — which is also why the sprite must be served with Image.color =
        // WHITE, never tinted, or the outline gets tinted too). Prismatic gets
        // a baked rainbow (its preview_color is #FFFFFF = a lying white blob);
        // no runtime animation — a static frame is the agreed preview.
        // Cache tolerates destroyed sprites (Unity fake-null → rebuild).
        private static readonly Dictionary<string, UnityEngine.Sprite> _bodyGlyphCache =
            new Dictionary<string, UnityEngine.Sprite>();
        internal static UnityEngine.Sprite GetBodyGlyphSprite(string sku, string hex)
        {
            string key = sku == "pcolor_prismatic" ? "prismatic" : (hex ?? "").Trim().ToLowerInvariant();
            if (string.IsNullOrEmpty(key)) key = "#666a80";
            if (_bodyGlyphCache.TryGetValue(key, out var cached) && cached != null) return cached;
            try
            {
                const int S = 64;
                bool[] mask = new bool[S * S];
                Action<float, float, float> circle = (cx, cy, r) =>
                {
                    for (int y = 0; y < S; y++)
                        for (int x = 0; x < S; x++)
                        {
                            float dx = x + 0.5f - cx, dy = y + 0.5f - cy;
                            if (dx * dx + dy * dy <= r * r) mask[y * S + x] = true;
                        }
                };
                circle(32f, 36f, 20f);   // body
                circle(8f, 34f, 6f);     // left hand (ROUNDS hands float beside the body)
                circle(56f, 34f, 6f);    // right hand
                circle(22f, 9f, 5f);     // left foot
                circle(42f, 9f, 5f);     // right foot

                Color fill = new Color(0.40f, 0.42f, 0.50f);
                bool prismatic = key == "prismatic";
                if (!prismatic)
                {
                    string h = key.StartsWith("#") ? key : "#" + key;
                    if (!ColorUtility.TryParseHtmlString(h, out fill)) fill = new Color(0.40f, 0.42f, 0.50f);
                }
                float lum = 0.299f * fill.r + 0.587f * fill.g + 0.114f * fill.b;
                Color outline = (prismatic || lum > 0.5f) ? new Color(0.06f, 0.06f, 0.08f, 1f) : new Color(0.85f, 0.87f, 0.92f, 1f);

                var tex = new Texture2D(S, S, TextureFormat.RGBA32, false);
                tex.hideFlags = HideFlags.HideAndDontSave;
                var px = new Color32[S * S];
                for (int y = 0; y < S; y++)
                    for (int x = 0; x < S; x++)
                    {
                        int i = y * S + x;
                        if (!mask[i]) { px[i] = new Color32(0, 0, 0, 0); continue; }
                        bool edge = x == 0 || y == 0 || x == S - 1 || y == S - 1
                                    || !mask[i - 1] || !mask[i + 1] || !mask[i - S] || !mask[i + S];
                        Color c;
                        if (edge) c = outline;
                        else if (prismatic)
                            // Match the in-match prismatic look (S=0.85, V=1) across x.
                            c = Color.HSVToRGB(x / (float)(S - 1), 0.85f, 1f);
                        else c = fill;
                        px[i] = (Color32)c;
                    }
                tex.SetPixels32(px); tex.Apply();
                var sp = UnityEngine.Sprite.Create(tex, new Rect(0, 0, S, S), new Vector2(0.5f, 0.5f), 100f);
                sp.hideFlags = HideFlags.HideAndDontSave;
                _bodyGlyphCache[key] = sp;
                return sp;
            }
            catch { return null; }
        }

        // One pie wedge: a full circle Image radial-filled to `sweepFrac`, rotated so it
        // begins at `startFrac` of the way around (clockwise from top). Anchored at a
        // bottom-left point in compareGraphPanel.
        private static void DrawPieSlice(string name, float cx, float cy, float radius, float startFrac, float sweepFrac, Color col)
        {
            var sprite = GetCircleSprite();
            if (sprite == null) return;
            var go = new GameObject(name);
            go.transform.SetParent(compareGraphPanel.transform, false);
            var rt = go.AddComponent<RectTransform>();
            rt.anchorMin = Vector2.zero; rt.anchorMax = Vector2.zero; rt.pivot = new Vector2(0.5f, 0.5f);
            rt.anchoredPosition = new Vector2(cx, cy);
            rt.sizeDelta = new Vector2(radius * 2f, radius * 2f);
            rt.localRotation = Quaternion.Euler(0, 0, -startFrac * 360f); // clockwise
            var img = go.AddComponent(UIFactory.tImage);
            var bf = BindingFlags.Public | BindingFlags.Instance;
            UIFactory.tImage.GetProperty("sprite", bf)?.SetValue(img, sprite);
            UIFactory.tImage.GetProperty("color", bf)?.SetValue(img, col);
            try { UIFactory.tImage.GetProperty("type", bf)?.SetValue(img, Enum.ToObject(UIFactory.tImage.GetProperty("type", bf).PropertyType, 3)); } catch {} // Filled
            try { UIFactory.tImage.GetProperty("fillMethod", bf)?.SetValue(img, Enum.ToObject(UIFactory.tImage.GetProperty("fillMethod", bf).PropertyType, 4)); } catch {} // Radial360
            try { UIFactory.tImage.GetProperty("fillOrigin", bf)?.SetValue(img, 2); } catch {} // Top
            try { UIFactory.tImage.GetProperty("fillClockwise", bf)?.SetValue(img, true); } catch {}
            try { UIFactory.tImage.GetProperty("fillAmount", bf)?.SetValue(img, Mathf.Clamp01(sweepFrac)); } catch {}
        }

        // Charts every non-card, non-line metric as bars in compareGraphPanel:
        //   • single value per player  → one bar per player (Avg FPS, Peak Elo, Total
        //     XP, Achievements, Avg Cards/Game)
        //   • two values per player    → grouped bars (Hit / Block %)
        //   • distribution per player  → stacked bar (Region Time, by region %)
        // Y axis gets 4 gridlines + labels; player names sit under each group.
        private static void BuildCompareBarChart(string metricName)
        {
            if (compareGraphPanel == null) return;
            for (int c = compareGraphPanel.transform.childCount - 1; c >= 0; c--)
                UnityEngine.Object.Destroy(compareGraphPanel.transform.GetChild(c).gameObject);
            // Records rows register card-hover regions (Aug 17); every metric
            // rebuild destroys the panel's children, so the regions must die
            // with them or they linger as ghost zones over the next chart
            // (#143 class — dead source rects fall back to their frozen
            // registration rect). Tab 1 has no other card-hover producer.
            CompetitiveUI.ClearCardHoverRegions();

            // Gather selected players that have cached stats, preserving select order
            // (so bar color matches the picker swatch).
            var idxs = new List<int>();
            for (int i = 0; i < compareSelected.Count; i++)
                if (compareStatsCache.TryGetValue(compareSelected[i], out var ps) && ps != null)
                    idxs.Add(i);

            CompareChartSize(out float W, out float H);

            /* Aug 6 item 1: "Records" is a GLOBAL board — the three career-record
             * leaderboards exist independently of the selection, which only
             * decides who gets highlighted. It must therefore be dispatched
             * BEFORE the empty-selection guard, or the one metric that needs no
             * selection is the one that refuses to render without one. */
            if (metricName == "Records") { BuildCompareRecordsPanel(idxs, W, H); return; }

            if (idxs.Count == 0)
            {
                MakeGraphLabel("CmpBarNone", $"<color=#888>{I18n.TrF("Select players (left) to chart {0}.", "<b>" + TrMetric(metricName) + "</b>")}</color>",
                    new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(W - 40, 40), UIFactory.AlignMidCenter);
                return;
            }

            // Region distribution → pie-chart grid (much clearer than the old stacked bar).
            if (metricName == "Region Time") { BuildComparePieChart(idxs, W, H); return; }
            // Per-achievement comparison grid (v1.29).
            if (metricName == "Achievement Grid") { BuildCompareAchievementGrid(idxs, W, H); return; }
            /* Aug 6 item 1 — metrics whose data does NOT live on PlayerStatsData.
             * Each reads its own endpoint through ApiClient's compare-board caches
             * and renders a pie grid or a text board. Dispatched here (rather than
             * from RefreshCompare) so they inherit the "no players selected"
             * guard and the live chart size above. */
            if (metricName == "Build Types" || metricName == "Ranked Friends" || metricName == "Gold Sources")
            { BuildCompareGenericPie(idxs, W, H, metricName); return; }
            if (metricName == "Most Similar Player") { BuildCompareSimilarPanel(idxs, W, H); return; }
            if (metricName == "Nemesis Comparison") { BuildCompareNemesisPanel(idxs, W, H); return; }

            float padL = 60f, padR = 16f, padT = 34f, padB = 48f;
            float plotW = W - padL - padR, plotH = H - padT - padB;
            int n = idxs.Count;
            float groupW = plotW / n;

            string title; bool grouped = false, avgCards = false; string unit = "";
            switch (metricName)
            {
                /* item 11: these were assigned raw and only markup-wrapped at the
                 * MakeGraphLabel call below, so the finished string was never a
                 * catalogue key. Tr at the assignment; the markup wrap stays outside. */
                case "Hit / Block %": title = I18n.Tr("Hit % vs Block %"); grouped = true; unit = "%"; break;
                case "Avg Cards / Game": title = I18n.Tr("Avg Cards per Game  (lower = stronger)"); avgCards = true; break;
                case "Avg FPS": title = I18n.Tr("Average FPS"); break;
                case "Peak Elo": title = I18n.Tr("Peak Elo"); break;
                case "Total XP": title = I18n.Tr("Total XP"); break;
                case "Achievements": title = I18n.Tr("Achievements unlocked"); break;
                // v1.29 —  grouped pairs get data-driven scale (groupedData below).
                case "Top Streaks": title = I18n.Tr("Best Win Streak"); grouped = true; break;
                case "5-0s Given / Taken": title = I18n.Tr("5-0 Sweeps"); grouped = true; break;
                case "Bets Won / Lost": title = I18n.Tr("Betting Record"); grouped = true; break;
                case "Keys / Sec": title = I18n.Tr("Avg Keystrokes per Second (in combat)"); break;
                case "Keys / Game": title = I18n.Tr("Avg Key Presses per Game"); break;
                case "Avg Game Length": title = I18n.Tr("Avg Game Length (minutes)"); break;
                case "2v2 Rating": title = I18n.Tr("2v2 Rating"); break;
                // Aug 6 item 1 — simple single-value bars off PlayerStatsData.
                /* Aug 12 item 12: the stat FLIPPED SIDES. casual_rage_quit_pct
                 * is now the rate at which this player's casual 1v1 OPPONENTS
                 * quit on them (unmodded quickplay opponents included), not
                 * the rate at which the player quits. So the direction word
                 * reverses with it. The metric NAME stays "Rage Quit %" (owner
                 * decision, and it doubles as the internal switch key); only
                 * the meaning-carrying copy changes, which re-keys it for
                 * translation rather than carrying the old wording over
                 * (#289 — the old sentence is now false in every locale). */
                case "Rage Quit %": title = I18n.Tr("Casual Opponents Who Quit on You % (higher is better)"); unit = "%"; break;
                case "FFA Avg Kills": title = I18n.Tr("FFA Average Kills per Game"); break;
                case "FFA Avg Placement": title = I18n.Tr("FFA Average Placement (lower is better)"); break;
                case "Ranked DPS": title = I18n.Tr("Ranked Damage per Second"); break;
                case "FFA DPS": title = I18n.Tr("FFA Damage per Second"); break;
                case "Self-Death %": title = I18n.Tr("Self-Inflicted Deaths % (boundary + own bullet)"); unit = "%"; break;
                case "Ranked Uniqueness %": title = I18n.Tr("Opponent Variety % (unique opponents / series)"); unit = "%"; break;
                default: title = TrMetric(metricName); break;
            }
            // Per-pair legend labels for grouped metrics (solid vs dim bars).
            string legA = I18n.Tr("Hit"), legB = I18n.Tr("Block");
            switch (metricName)
            {
                // Units differ: ranked best is per-SERIES, casual per-GAME (item 5).
                case "Top Streaks": legA = I18n.Tr("Ranked (series)"); legB = I18n.Tr("Casual (games)"); break;
                case "5-0s Given / Taken": legA = I18n.Tr("Given"); legB = I18n.Tr("Taken"); break;
                case "Bets Won / Lost": legA = I18n.Tr("Won"); legB = I18n.Tr("Lost"); break;
            }
            bool groupedPct = metricName == "Hit / Block %";
            MakeGraphLabel("CmpBarTitle", $"<color=#CCC><b>{title}</b></color>",
                new Vector2(0, 1), new Vector2(padL, -4f), new Vector2(W - padL, 18), UIFactory.AlignMidLeft);

            Func<ApiClient.PlayerStatsData, float> v1 = null, v2 = null;
            switch (metricName)
            {
                case "Hit / Block %":
                    v1 = ps => ps.bullets_fired > 0 ? (float)ps.bullets_hit * 100f / ps.bullets_fired : 0f;
                    v2 = ps => ps.blocks_activated > 0 ? (float)ps.blocks_successful * 100f / ps.blocks_activated : 0f;
                    break;
                case "Avg Cards / Game": v1 = ps => ps.avg_cards_per_game; break;
                case "Avg FPS": v1 = ps => ps.avg_fps; break;
                case "Peak Elo": v1 = ps => ps.peak_rating; break;
                case "Total XP": v1 = ps => ps.total_xp; break;
                case "Achievements": v1 = ps => ps.achievements_unlocked; break;
                // v1.29 metrics — all server-computed fields on PlayerStatsData.
                case "Top Streaks":
                    v1 = ps => ps.best_ranked_streak;
                    v2 = ps => ps.best_casual_streak;
                    break;
                case "5-0s Given / Taken":
                    v1 = ps => ps.sweeps_given;
                    v2 = ps => ps.sweeps_taken;
                    break;
                case "Bets Won / Lost":
                    v1 = ps => ps.bets_won;
                    v2 = ps => ps.bets_lost;
                    break;
                case "Keys / Sec": v1 = ps => ps.avg_keys_per_sec; break;
                case "Keys / Game": v1 = ps => ps.avg_keys_per_game; break;
                case "Avg Game Length": v1 = ps => ps.avg_game_seconds / 60f; break;
                case "2v2 Rating": v1 = ps => ps.team_rating; break;
                /* Aug 6 item 1. Every one of these is a flat scalar the server
                 * already computed — the client must NOT re-derive them (e.g.
                 * self_death_pct's denominator is "deaths recorded", not
                 * deaths_total-as-C#-default), or the two ends disagree. */
                /* The three *_pct fields are FRACTIONS (0..1), not 0-100, despite
                 * the suffix — every one is `round(a / b, 4)` server-side
                 * (main.py:4673/4680/4715). Verified against the formulas, not
                 * the field names (#152/#219): plotting them raw put a 3.1%
                 * rage-quit rate on the axis as 0.03 and labelled it "0.0%".
                 * ranked_dps / ffa_dps / ffa_avg_* are already real units. */
                case "Rage Quit %": v1 = ps => ps.casual_rage_quit_pct * 100f; break;
                case "FFA Avg Kills": v1 = ps => ps.ffa_avg_kills; break;
                case "FFA Avg Placement": v1 = ps => ps.ffa_avg_placement; break;
                case "Ranked DPS": v1 = ps => ps.ranked_dps; break;
                case "FFA DPS": v1 = ps => ps.ffa_dps; break;
                case "Self-Death %": v1 = ps => ps.self_death_pct * 100f; break;
                case "Ranked Uniqueness %": v1 = ps => ps.ranked_uniqueness_pct * 100f; break;
                default: v1 = ps => 0f; break;
            }

            // Axis scale + a NICE round step so labels are clean whole numbers.
            float maxV, step;
            if (groupedPct) { maxV = 100f; step = 25f; }       // 0..100 %
            else if (avgCards) { maxV = 5f; step = 1f; }       // fixed 0..5, lines at each int
            else
            {
                float dataMax = 0.0001f;
                foreach (int i in idxs)
                {
                    var psX = compareStatsCache[compareSelected[i]];
                    float v = v1(psX); if (v > dataMax) dataMax = v;
                    if (grouped && v2 != null) { float vb = v2(psX); if (vb > dataMax) dataMax = vb; }
                }
                step = NiceStep(dataMax / 4f);
                maxV = Mathf.Ceil(dataMax * 1.08f / step) * step;
                if (maxV < step) maxV = step;
            }

            if (metricName == "Total XP")
            {
                // Gridlines/labels are LEVELS (at each level's cumulative-XP threshold),
                // not raw XP — Sid's request. Levels aren't evenly XP-spaced, so the lines
                // bunch toward the top; that's expected.
                int topLevel = LevelForXp(maxV);
                int lvlStep = Mathf.Max(1, Mathf.CeilToInt(topLevel / 6f));
                MakeGraphLabel("CmpBarY0", $"<color=#999>{I18n.TrF("Lv {0}", 0)}</color>",
                    new Vector2(0, 0), new Vector2(padL - 4f, padB - 6f), new Vector2(52, 12), UIFactory.AlignMidRight);
                for (int L = lvlStep; L <= topLevel; L += lvlStep)
                {
                    float xpAt = TotalXpForLevel(L);
                    if (xpAt > maxV) break;
                    float yy = padB + (xpAt / maxV) * plotH;
                    DrawBar($"CmpBarGridL{L}", padL, yy, plotW, 1f, new Color(1f, 1f, 1f, 0.10f));
                    MakeGraphLabel($"CmpBarYL{L}", $"<color=#999>{I18n.TrF("Lv {0}", L)}</color>",
                        new Vector2(0, 0), new Vector2(padL - 4f, yy - 6f), new Vector2(52, 12), UIFactory.AlignMidRight);
                }
            }
            else
            {
                int yDivs = Mathf.Clamp(Mathf.RoundToInt(maxV / step), 2, 10);
                for (int gi = 0; gi <= yDivs; gi++)
                {
                    float val = gi * step;
                    if (val > maxV + 0.001f) break;
                    float yy = padB + (val / maxV) * plotH;
                    DrawBar($"CmpBarGrid{gi}", padL, yy, plotW, 1f, new Color(1f, 1f, 1f, 0.10f));
                    MakeGraphLabel($"CmpBarYLbl{gi}", $"<color=#999>{(avgCards ? val.ToString("0") : FullNum(val))}{unit}</color>",
                        new Vector2(0, 0), new Vector2(padL - 4f, yy - 6f), new Vector2(52, 12), UIFactory.AlignMidRight);
                }
            }

            if (grouped)
                MakeGraphLabel("CmpHBLeg", I18n.TrF("<color=#EEEEEE>solid = {0}</color>   <color=#888888>dim = {1}</color>", legA, legB),
                    new Vector2(1, 1), new Vector2(-padR, -4f), new Vector2(260, 14), UIFactory.AlignMidRight);

            // Adaptive name length: full names when there's room, trimmed when crowded.
            int nameLen = Mathf.Clamp((int)(groupW / 8f), 5, 18);

            for (int gi2 = 0; gi2 < n; gi2++)
            {
                int i = idxs[gi2];
                var ps = compareStatsCache[compareSelected[i]];
                Color pc = COMPARE_COLORS[i % COMPARE_COLORS.Length];
                float gx = padL + gi2 * groupW;

                if (grouped)
                {
                    float bw = groupW * 0.32f, gap = groupW * 0.06f;
                    float bx0 = gx + (groupW - (bw * 2f + gap)) * 0.5f;
                    float hv = Mathf.Clamp(v1(ps), 0f, maxV), bvv = Mathf.Clamp(v2(ps), 0f, maxV);
                    DrawBar($"CmpGrpA{gi2}", bx0, padB, bw, hv / maxV * plotH, new Color(pc.r, pc.g, pc.b, 1f));
                    DrawBar($"CmpGrpB{gi2}", bx0 + bw + gap, padB, bw, bvv / maxV * plotH, new Color(pc.r * 0.5f, pc.g * 0.5f, pc.b * 0.5f, 1f));
                    MakeGraphLabel($"CmpGrpVA{gi2}", $"<color=#EEE>{v1(ps):F1}</color>", new Vector2(0, 0), new Vector2(bx0 - 8f, padB + hv / maxV * plotH + 1f), new Vector2(bw + 16f, 11), UIFactory.AlignMidCenter);
                    MakeGraphLabel($"CmpGrpVB{gi2}", $"<color=#AAA>{v2(ps):F1}</color>", new Vector2(0, 0), new Vector2(bx0 + bw + gap - 8f, padB + bvv / maxV * plotH + 1f), new Vector2(bw + 16f, 11), UIFactory.AlignMidCenter);
                }
                else
                {
                    float bw = groupW * 0.58f;
                    float bx = gx + (groupW - bw) * 0.5f;
                    float val = v1(ps);
                    float clamped = Mathf.Clamp(val, 0f, maxV);
                    Color bc = pc;
                    if (avgCards && val > 0f) bc = GradeColor((val - 1f) / 4f); // 1=best→green, 5=worst→red
                    DrawBar($"CmpBar{gi2}", bx, padB, bw, clamped / maxV * plotH, bc);
                    /* Aug-3 review find F9: the literal must sit INSIDE the TrF call
                     * or the extractor harvests nothing (#295a) — and the whole
                     * template goes in one key rather than "Lv " + a number
                     * (compose-after-Tr, #298c). Same "Lv {0}" key the Y-axis
                     * labels above already use. */
                    string vlbl = avgCards ? val.ToString("F2")
                                : metricName == "Total XP" ? I18n.TrF("Lv {0}", ps.level)
                                // Small-float metrics keep their decimals — FullNum's
                                // whole-number rounding made every game length a solid
                                // minute (Sid). 5.4m reads as 5m24s.
                                : metricName == "Avg Game Length" ? $"{val:F1}m"
                                : metricName == "Keys / Sec" ? val.ToString("F1")
                                /* Aug 6 item 1: these are all small floats where
                                 * FullNum's whole-number rounding destroys the
                                 * comparison (a 2.4 vs 2.6 avg placement would
                                 * both print "3"). Percentages carry their sign
                                 * so the axis unit isn't the only cue. */
                                : (metricName == "Rage Quit %" || metricName == "Self-Death %"
                                   || metricName == "Ranked Uniqueness %") ? $"{val:F1}%"
                                : (metricName == "Ranked DPS" || metricName == "FFA DPS"
                                   || metricName == "FFA Avg Kills" || metricName == "FFA Avg Placement")
                                    ? val.ToString("F1")
                                : FullNum(val);
                    MakeGraphLabel($"CmpBarV{gi2}", $"<color=#EEE>{vlbl}</color>",
                        new Vector2(0, 0), new Vector2(bx - 6f, padB + clamped / maxV * plotH + 1f), new Vector2(bw + 12f, 12), UIFactory.AlignMidCenter);
                }

                MakeGraphLabel($"CmpBarName{gi2}", $"<b><color=#{ColorToHex(pc)}>{Trunc(ps.display_name, nameLen)}</color></b>",
                    new Vector2(0, 0), new Vector2(gx - 4f, padB - 18f), new Vector2(groupW + 8f, 16), UIFactory.AlignMidCenter, 13f);
            }
        }

        // v1.29 — per-achievement comparison: one row per achievement, one column
        // per selected player, YES/no cells in each player's compare color. Data
        // comes from FetchAchievementsForCompare (cached per steam id).
        private static void BuildCompareAchievementGrid(List<int> idxs, float W, float H)
        {
            try
            {
                MakeGraphLabel("CmpAchTitle", $"<color=#CCC><b>{I18n.Tr("Achievement comparison")}</b></color>",
                    new Vector2(0, 1), new Vector2(16f, -4f), new Vector2(W - 20, 18), UIFactory.AlignMidLeft);

                bool missing = false;
                foreach (int i in idxs)
                {
                    string sid = compareSelected[i];
                    if (!ApiClient.CompareAchievements.ContainsKey(sid))
                    {
                        ApiClient.FetchAchievementsForCompare(sid);
                        missing = true;
                    }
                }
                if (missing)
                {
                    MakeGraphLabel("CmpAchLoad", $"<color=#888>{I18n.Tr("Loading achievements...")}</color>",
                        new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(W - 40, 30), UIFactory.AlignMidCenter);
                    return;
                }

                // Union of keys across the selected players, stable-sorted by display name.
                var keys = new List<string>();
                foreach (int i in idxs)
                    foreach (var k in ApiClient.CompareAchievements[compareSelected[i]].Keys)
                        if (!keys.Contains(k)) keys.Add(k);
                keys.Sort((a, b) => string.CompareOrdinal(AchName(a), AchName(b)));
                if (keys.Count == 0)
                {
                    MakeGraphLabel("CmpAchNone", $"<color=#888>{I18n.Tr("No achievement data.")}</color>",
                        new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(W - 40, 30), UIFactory.AlignMidCenter);
                    return;
                }

                // Bug batch item 12: with ~40 achievements a single column forced
                // 15px rows and 11f text — unreadable, and below ~12pt the SDF
                // font drops thin glyphs entirely. Split the grid into
                // side-by-side blocks so rows stay >=20px at a fixed 13f bold.
                //
                // COLUMN COUNT IS DERIVED, not fixed at 2 (Aug-11 find 6). This
                // grid is masked and does NOT scroll, so a hardcoded 2 columns
                // silently CLIPS its bottom rows the moment the catalogue
                // outgrows the panel: at 50 achievements that is 25 rows, and
                // 25 * the 20px floor exceeds the height a width-matched canvas
                // leaves here (#199's class — the arithmetic is invisible in
                // code review, so do it rather than assume). Work out how many
                // rows actually fit at the readable floor, then use as many
                // blocks as that requires; 2 stays the minimum so nothing
                // narrower than today appears at small counts, and 4 is the cap
                // because past that the per-player YES/- columns get too thin.
                const float rowFloor = 20f, headerBlock = 66f;
                int rowsThatFit = Mathf.Max(1, Mathf.FloorToInt((H - headerBlock) / rowFloor));
                int blocks = Mathf.Clamp(Mathf.CeilToInt(keys.Count / (float)rowsThatFit), 2, 4);
                int half = Mathf.CeilToInt(keys.Count / (float)blocks);
                float blockW = (W - 12f * (blocks + 1)) / blocks;
                float nameW = Mathf.Min(200f, blockW * 0.46f);
                float colW = (blockW - nameW - 8f) / Mathf.Max(1, idxs.Count);
                float headerY = -26f;
                float rowH = Mathf.Clamp((H - headerBlock) / Mathf.Max(1, half), rowFloor, 28f);
                const float fontSz = 13f;
                for (int blk = 0; blk < blocks; blk++)
                {
                    float bx = 12f + blk * (blockW + 12f);
                    int from = blk * half, to = Mathf.Min(keys.Count, (blk + 1) * half);
                    if (from >= to) break;
                    for (int c = 0; c < idxs.Count; c++)
                    {
                        int i = idxs[c];
                        var ps = compareStatsCache[compareSelected[i]];
                        Color pc = COMPARE_COLORS[i % COMPARE_COLORS.Length];
                        MakeGraphLabel($"CmpAchHdr{blk}_{c}",
                            $"<b><color=#{ColorToHex(pc)}>{Trunc(ps.display_name, Mathf.Clamp((int)(colW / 9f), 4, 16))}</color></b>",
                            new Vector2(0, 1), new Vector2(bx + nameW + c * colW, headerY), new Vector2(colW, 16), UIFactory.AlignMidCenter, 13f);
                    }
                    for (int r = from; r < to; r++)
                    {
                        float y = headerY - 20f - (r - from) * rowH;
                        MakeGraphLabel($"CmpAchN{r}", $"<color=#CCCCCC>{Trunc(I18n.Tr(AchName(keys[r])), 24)}</color>",
                            new Vector2(0, 1), new Vector2(bx, y), new Vector2(nameW, rowH), UIFactory.AlignMidLeft, fontSz);
                        for (int c = 0; c < idxs.Count; c++)
                        {
                            int i = idxs[c];
                            var achs = ApiClient.CompareAchievements[compareSelected[i]];
                            bool has = achs.TryGetValue(keys[r], out var ad) && ad.unlocked;
                            Color pc = COMPARE_COLORS[i % COMPARE_COLORS.Length];
                            // F9: Tr the word, then compose the markup around it —
                            // the literal has to be the TrF/Tr argument to harvest
                            // (#295a), and the markup is not part of the key (#298c).
                            string cell = has ? $"<b><color=#{ColorToHex(pc)}>{I18n.Tr("YES")}</color></b>" : "<color=#555555>-</color>";
                            MakeGraphLabel($"CmpAchC{r}_{c}", cell,
                                new Vector2(0, 1), new Vector2(bx + nameW + c * colW, y), new Vector2(colW, rowH), UIFactory.AlignMidCenter, fontSz);
                        }
                    }
                }
            }
            catch (Exception ex) { Plugin.Log.LogWarning($"[COMPARE] achievement grid failed: {ex.Message}"); }
        }

        private static string AchName(string key)
        {
            if (ApiClient.AchievementDisplayNames.TryGetValue(key, out var n) && !string.IsNullOrEmpty(n)) return n;
            // Fallback: prettify the key ("stan_slayer" → "Stan Slayer").
            var parts = (key ?? "").Split('_');
            for (int i = 0; i < parts.Length; i++)
                if (parts[i].Length > 0) parts[i] = char.ToUpperInvariant(parts[i][0]) + parts[i].Substring(1);
            return string.Join(" ", parts);
        }

        // Region distribution as a grid of per-player pie charts with a shared region
        // legend; the larger (1-2 player) pies also get leader lines + % labels sticking
        // out. Replaces the old stacked bar Sid called "hideous".
        private static void BuildComparePieChart(List<int> idxs, float W, float H)
        {
            try
            {
                MakeGraphLabel("CmpPieTitle", $"<color=#CCC><b>{I18n.Tr("Region distribution")}</b></color>",
                    new Vector2(0, 1), new Vector2(16f, -4f), new Vector2(W - 20, 18), UIFactory.AlignMidLeft);

                // Shared region legend.
                var regions = new List<string>();
                foreach (int i in idxs)
                {
                    var ps = compareStatsCache[compareSelected[i]];
                    if (ps.region_names == null) continue;
                    foreach (var rn in ps.region_names) if (!regions.Contains(rn)) regions.Add(rn);
                }
                // Bigger, more-readable legend chips (wrap every 4). A TMP <mark> highlight
                // gives each a solid color swatch that stays glued to its label (a separate
                // positioned rect drifted out of alignment).
                for (int li = 0; li < regions.Count; li++)
                {
                    float lxr = -14f - (li % 4) * 104f;
                    float lyr = -4f - (li / 4) * 17f;
                    string hex = ColorToHex(RegionColor(regions[li]));
                    MakeGraphLabel($"CmpPieLeg{li}",
                        $"<mark=#{hex}FF>  </mark> <b>{regions[li].ToUpperInvariant()}</b>",
                        new Vector2(1, 1), new Vector2(lxr, lyr), new Vector2(96, 14), UIFactory.AlignMidLeft, 13f);
                }

                int n = idxs.Count;
                int cols = n <= 1 ? 1 : n <= 2 ? 2 : n <= 6 ? 3 : 4;
                int rows = (n + cols - 1) / cols;
                float topPad = 30f + Mathf.Ceil(regions.Count / 4f) * 17f;
                float botPad = 8f;
                float cellW = (W - 20f) / cols;
                float cellH = (H - topPad - botPad) / Mathf.Max(1, rows);
                float radius = Mathf.Max(26f, Mathf.Min(cellW, cellH) * 0.36f);
                bool leaderLines = cols <= 3;

                for (int k = 0; k < n; k++)
                {
                    int i = idxs[k];
                    var ps = compareStatsCache[compareSelected[i]];
                    int col = k % cols, row = k / cols;
                    float cx = 10f + col * cellW + cellW * 0.5f;
                    float cy = H - topPad - row * cellH - cellH * 0.5f; // bottom-left coord space

                    MakeGraphLabel($"CmpPieName{k}",
                        $"<b><color=#{ColorToHex(COMPARE_COLORS[i % COMPARE_COLORS.Length])}>{FfaSafeRich(Trunc(ps.display_name, 14))}</color></b>",
                        new Vector2(0, 0), new Vector2(cx - cellW * 0.5f, cy + radius + 4f), new Vector2(cellW, 16), UIFactory.AlignMidCenter, 14f);

                    int tot = 0; if (ps.region_matches != null) foreach (var m in ps.region_matches) tot += m;
                    if (ps.region_names == null || tot <= 0)
                    {
                        MakeGraphLabel($"CmpPieNo{k}", $"<color=#888>{I18n.Tr("no data")}</color>",
                            new Vector2(0, 0), new Vector2(cx - 40f, cy - 6f), new Vector2(80, 12), UIFactory.AlignMidCenter);
                        continue;
                    }
                    // Border ring: a slightly larger dark circle behind the slices gives the
                    // pie a clean edge (Sid: "put a border around the edge, looks rough").
                    DrawPieSlice($"CmpPieBdr{k}", cx, cy, radius + 2.5f, 0f, 1f, new Color(0.10f, 0.11f, 0.14f, 1f));
                    float acc = 0f;
                    for (int ri = 0; ri < ps.region_names.Count; ri++)
                    {
                        int mm = ps.region_matches.Count > ri ? ps.region_matches[ri] : 0;
                        if (mm <= 0) continue;
                        float frac = (float)mm / tot;
                        DrawPieSlice($"CmpPie{k}_{ri}", cx, cy, radius, acc, frac, RegionColor(ps.region_names[ri]));
                        if (leaderLines && frac >= 0.07f)
                        {
                            float midFrac = acc + frac * 0.5f;
                            float ang = Mathf.PI * 0.5f - midFrac * 2f * Mathf.PI; // top, clockwise
                            float ex = cx + Mathf.Cos(ang) * radius, ey = cy + Mathf.Sin(ang) * radius;
                            float lx = cx + Mathf.Cos(ang) * (radius + 20f), ly = cy + Mathf.Sin(ang) * (radius + 20f);
                            DrawGraphSegment($"CmpPieLn{k}_{ri}", ex, ey, lx, ly, new Color(0.8f, 0.8f, 0.8f, 0.7f), 1.5f);
                            bool rightSide = Mathf.Cos(ang) >= 0f;
                            int align = rightSide ? UIFactory.AlignMidLeft : UIFactory.AlignMidRight;
                            float lblX = rightSide ? lx + 2f : lx - 66f;
                            MakeGraphLabel($"CmpPieLbl{k}_{ri}",
                                $"<color=#CCC>{ps.region_names[ri].ToUpperInvariant()} {frac * 100f:F0}%</color>",
                                /* item 12: 64px could not hold "US 42%" at the 12pt
                                 * floor, so it wrapped and then truncated even with
                                 * Overflow restored. 80 + the no-wrap in
                                 * MakeGraphLabel keeps both tokens on one line. */
                                new Vector2(0, 0), new Vector2(lblX, ly - 6f), new Vector2(80, 12), align);
                        }
                        acc += frac;
                    }
                }
            }
            catch (Exception ex) { Plugin.Log.LogWarning($"[COMPARE] pie chart failed: {ex.Message}"); }
        }

        // ── Aug 6 item 1: generic per-player pie + board panels ──────────────
        /* Slice palette. Deliberately NOT COMPARE_COLORS: a player's own compare
         * color labels their pie's title, and reusing it for slices makes "this
         * slice is me" read as meaningful when it isn't. */
        private static readonly Color[] PIE_SLICE_COLORS = {
            new Color(0.36f, 0.62f, 0.98f), new Color(0.98f, 0.55f, 0.30f),
            new Color(0.42f, 0.86f, 0.48f), new Color(0.92f, 0.80f, 0.28f),
            new Color(0.74f, 0.50f, 0.96f), new Color(0.30f, 0.86f, 0.82f),
            new Color(0.96f, 0.52f, 0.72f), new Color(0.62f, 0.80f, 0.36f),
            new Color(0.90f, 0.42f, 0.42f), new Color(0.50f, 0.58f, 0.90f),
            new Color(0.80f, 0.66f, 0.44f), new Color(0.56f, 0.76f, 0.68f),
        };
        // Aug 7 item 12: the tail bucket for label sets larger than the palette.
        // Grey on purpose — it must never be confusable with a real slice color.
        private static readonly Color PIE_OTHER_COLOR = new Color(0.55f, 0.55f, 0.58f);

        /// <summary>Per-player pie grid for Build Types / Ranked Friends / Gold
        /// Sources. Structurally the same as BuildComparePieChart, but the labels
        /// and values come from a per-metric endpoint cache instead of the
        /// region breakdown, and colours are keyed by the label's position in the
        /// UNION across players so one bucket is the same colour in every pie.</summary>
        private static void BuildCompareGenericPie(List<int> idxs, float W, float H, string metricName)
        {
            try
            {
                string title = metricName == "Build Types" ? I18n.Tr("Ranked build types")
                             : metricName == "Ranked Friends" ? I18n.Tr("Most-played ranked opponents")
                             : I18n.Tr("Where their gold came from");
                MakeGraphLabel("CmpGPTitle", $"<color=#CCC><b>{title}</b></color>",
                    new Vector2(0, 1), new Vector2(16f, -4f), new Vector2(W - 20, 18), UIFactory.AlignMidLeft);

                // Kick any missing fetches, then bail to a loading line. Fetches
                // are cached + in-flight-deduped, so calling them every render is
                // free after the first (matches the achievement grid's shape).
                bool missing = false;
                foreach (int i in idxs)
                {
                    string sid = compareSelected[i];
                    if (metricName == "Build Types")
                    { if (!ApiClient.BuildTypes.ContainsKey(sid)) { ApiClient.FetchBuildType(sid); missing = true; } }
                    else if (metricName == "Ranked Friends")
                    { if (!ApiClient.RankedFriends.ContainsKey(sid)) { ApiClient.FetchRankedFriends(sid); missing = true; } }
                    else
                    { if (!ApiClient.GoldSources.ContainsKey(sid)) { ApiClient.FetchGoldSources(sid); missing = true; } }
                }
                if (missing)
                {
                    MakeGraphLabel("CmpGPLoad", $"<color=#888>{I18n.Tr("Loading...")}</color>",
                        new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(W - 40, 30), UIFactory.AlignMidCenter);
                    return;
                }

                // Gather each player's (labels, values), then rank labels by their
                // AGGREGATE value across all selected players. Aug 7 item 12: the
                // old union was encounter-ordered and colored via `ui % 12`, so
                // Ranked Friends (up to ~96 distinct opponents across 12 players)
                // wrapped the palette — 3+ opponents shared the same yellow — and
                // every label past the 12-key legend cap silently had no key.
                // Now: <=12 distinct labels keep the exact palette; beyond that
                // the top 11 by aggregate stay and the tail folds into one grey
                // "Other" slice, so every drawn color is distinct AND keyed.
                var labelsPer = new List<List<string>>();
                var valuesPer = new List<List<int>>();
                var agg = new Dictionary<string, long>();
                foreach (int i in idxs)
                {
                    string sid = compareSelected[i];
                    List<string> L; List<int> V;
                    if (metricName == "Build Types")
                    { var d = ApiClient.BuildTypes[sid]; L = d.buckets; V = d.counts; }
                    else if (metricName == "Ranked Friends")
                    { var d = ApiClient.RankedFriends[sid]; L = d.names; V = d.seriesCounts; }
                    else
                    { var d = ApiClient.GoldSources[sid]; L = d.buckets; V = d.amounts; }
                    labelsPer.Add(L); valuesPer.Add(V);
                    for (int li = 0; li < L.Count; li++)
                        if (V.Count > li && V[li] > 0)
                            agg[L[li]] = (agg.TryGetValue(L[li], out long prev) ? prev : 0L) + V[li];
                }
                var ranked = new List<KeyValuePair<string, long>>(agg);
                // Deterministic order: aggregate desc, then ordinal name — the kept
                // set must not depend on selection order or fetch arrival (#265-adjacent
                // flicker: caches land asynchronously between renders).
                ranked.Sort((a, b) =>
                {
                    int c = b.Value.CompareTo(a.Value);
                    return c != 0 ? c : string.CompareOrdinal(a.Key, b.Key);
                });
                bool hasOther = ranked.Count > PIE_SLICE_COLORS.Length;
                int keep = hasOther ? PIE_SLICE_COLORS.Length - 1 : ranked.Count;
                var union = new List<string>();
                for (int ri = 0; ri < keep; ri++) union.Add(ranked[ri].Key);

                // Shared legend, 4 chips per line (same <mark> swatch trick as the
                // region legend — a separately-positioned swatch drifts). One count
                // drives both the loop and topPad below — they must never disagree.
                int legendCount = union.Count + (hasOther ? 1 : 0);
                for (int li = 0; li < legendCount; li++)
                {
                    bool isOther = li >= union.Count;
                    float lxr = -14f - (li % 4) * 118f;
                    float lyr = -4f - (li / 4) * 17f;
                    string hex = ColorToHex(isOther ? PIE_OTHER_COLOR : PIE_SLICE_COLORS[li]);
                    string lbl = isOther ? I18n.Tr("Other") : PieLabelDisplay(metricName, union[li]);
                    MakeGraphLabel($"CmpGPLeg{li}",
                        /* R2 finding 16: Ranked Friends puts OPPONENT DISPLAY NAMES in this
                         * legend, so it is user-authored text reaching TMP rich text. */
                        $"<mark=#{hex}FF>  </mark> <b>{FfaSafeRich(Trunc(lbl, 13))}</b>",
                        new Vector2(1, 1), new Vector2(lxr, lyr), new Vector2(110, 14), UIFactory.AlignMidLeft, 13f);
                }

                int n = idxs.Count;
                int cols = n <= 1 ? 1 : n <= 2 ? 2 : n <= 6 ? 3 : 4;
                int rows = (n + cols - 1) / cols;
                float topPad = 30f + Mathf.Ceil(legendCount / 4f) * 17f;
                float cellW = (W - 20f) / cols;
                float cellH = (H - topPad - 8f) / Mathf.Max(1, rows);
                float radius = Mathf.Max(24f, Mathf.Min(cellW, cellH) * 0.34f);
                bool leaderLines = cols <= 3;

                for (int k = 0; k < n; k++)
                {
                    int i = idxs[k];
                    var ps = compareStatsCache[compareSelected[i]];
                    var L = labelsPer[k]; var V = valuesPer[k];
                    int col = k % cols, row = k / cols;
                    float cx = 10f + col * cellW + cellW * 0.5f;
                    float cy = H - topPad - row * cellH - cellH * 0.5f;

                    MakeGraphLabel($"CmpGPName{k}",
                        $"<b><color=#{ColorToHex(COMPARE_COLORS[i % COMPARE_COLORS.Length])}>{FfaSafeRich(Trunc(ps.display_name, 14))}</color></b>",
                        new Vector2(0, 0), new Vector2(cx - cellW * 0.5f, cy + radius + 4f),
                        new Vector2(cellW, 16), UIFactory.AlignMidCenter, 14f);

                    long tot = 0;
                    for (int vi = 0; vi < V.Count; vi++) if (V[vi] > 0) tot += V[vi];
                    if (tot <= 0)
                    {
                        MakeGraphLabel($"CmpGPNo{k}", $"<color=#888>{I18n.Tr("no data")}</color>",
                            new Vector2(0, 0), new Vector2(cx - 40f, cy - 6f), new Vector2(80, 12), UIFactory.AlignMidCenter);
                        continue;
                    }
                    DrawPieSlice($"CmpGPBdr{k}", cx, cy, radius + 2.5f, 0f, 1f, new Color(0.10f, 0.11f, 0.14f, 1f));
                    float acc = 0f;
                    long otherV = 0;
                    /* Aug 7 item 12: label width is derived from the cell, not a
                     * hard 96px — "Bullet Speed" was Trunc(…,10)'d to "Bullet S.."
                     * even with half a cell of empty space beside it. ~9px/char at
                     * MakeGraphLabel's 12pt floor (measured in the Aug-3 pass:
                     * 64px could not hold "US 42%", 80px could). The clamp keeps
                     * labels from spilling into the NEIGHBORING pie cell — the
                     * panel mask only clips at panel edges (#292). */
                    float lblW = Mathf.Max(96f, cellW * 0.5f - 24f);
                    int lblChars = Mathf.Clamp((int)(lblW / 9f) - 4, 10, 24); // -4 chars reserved for " NN%"
                    for (int si = 0; si < L.Count; si++)
                    {
                        int v = V.Count > si ? V[si] : 0;
                        if (v <= 0) continue;
                        int ui = union.IndexOf(L[si]);
                        if (ui < 0) { otherV += v; continue; } // tail label -> Other slice below
                        float frac = (float)v / tot;
                        Color sc = PIE_SLICE_COLORS[ui];
                        DrawPieSlice($"CmpGP{k}_{si}", cx, cy, radius, acc, frac, sc);
                        if (leaderLines && frac >= 0.08f)
                        {
                            float midFrac = acc + frac * 0.5f;
                            float ang = Mathf.PI * 0.5f - midFrac * 2f * Mathf.PI;
                            float ex = cx + Mathf.Cos(ang) * radius, ey = cy + Mathf.Sin(ang) * radius;
                            float lx = cx + Mathf.Cos(ang) * (radius + 20f), ly = cy + Mathf.Sin(ang) * (radius + 20f);
                            DrawGraphSegment($"CmpGPLn{k}_{si}", ex, ey, lx, ly, new Color(0.8f, 0.8f, 0.8f, 0.7f), 1.5f);
                            bool rightSide = Mathf.Cos(ang) >= 0f;
                            int align = rightSide ? UIFactory.AlignMidLeft : UIFactory.AlignMidRight;
                            float lblX = rightSide ? lx + 2f : lx - lblW;
                            MakeGraphLabel($"CmpGPLbl{k}_{si}",
                                /* R3: leader labels carry the same user-authored names as the legend. */
                                $"<color=#CCC>{FfaSafeRich(Trunc(PieLabelDisplay(metricName, L[si]), lblChars))} {frac * 100f:F0}%</color>",
                                new Vector2(0, 0), new Vector2(lblX, ly - 6f), new Vector2(lblW, 12), align);
                        }
                        acc += frac;
                    }
                    if (otherV > 0)
                    {
                        float frac = (float)otherV / tot;
                        DrawPieSlice($"CmpGP{k}_oth", cx, cy, radius, acc, frac, PIE_OTHER_COLOR);
                        if (leaderLines && frac >= 0.08f)
                        {
                            float midFrac = acc + frac * 0.5f;
                            float ang = Mathf.PI * 0.5f - midFrac * 2f * Mathf.PI;
                            float ex = cx + Mathf.Cos(ang) * radius, ey = cy + Mathf.Sin(ang) * radius;
                            float lx = cx + Mathf.Cos(ang) * (radius + 20f), ly = cy + Mathf.Sin(ang) * (radius + 20f);
                            DrawGraphSegment($"CmpGPLn{k}_oth", ex, ey, lx, ly, new Color(0.8f, 0.8f, 0.8f, 0.7f), 1.5f);
                            bool rightSide = Mathf.Cos(ang) >= 0f;
                            int align = rightSide ? UIFactory.AlignMidLeft : UIFactory.AlignMidRight;
                            float lblX = rightSide ? lx + 2f : lx - lblW;
                            MakeGraphLabel($"CmpGPLblOth{k}",
                                $"<color=#CCC>{I18n.Tr("Other")} {frac * 100f:F0}%</color>",
                                new Vector2(0, 0), new Vector2(lblX, ly - 6f), new Vector2(lblW, 12), align);
                        }
                    }
                }
            }
            catch (Exception ex) { Plugin.Log.LogWarning($"[COMPARE] generic pie failed: {ex.Message}"); }
        }

        /// <summary>Prettify a pie slice label. Gold-source buckets arrive as
        /// server reason keys ("series_win", "level_reward"); opponent names and
        /// build-type buckets are already display strings.</summary>
        private static string PieLabelDisplay(string metricName, string raw)
        {
            if (metricName != "Gold Sources" || string.IsNullOrEmpty(raw)) return raw ?? "";
            var parts = raw.Split('_');
            for (int i = 0; i < parts.Length; i++)
                if (parts[i].Length > 0) parts[i] = char.ToUpperInvariant(parts[i][0]) + parts[i].Substring(1);
            return string.Join(" ", parts);
        }

        /// <summary>"Most Similar Player" — one column per selected player listing
        /// their nearest profile matches. A text board rather than a chart: the
        /// similarity score is only meaningful next to the name it belongs to.</summary>
        private static void BuildCompareSimilarPanel(List<int> idxs, float W, float H)
        {
            try
            {
                MakeGraphLabel("CmpSimTitle", $"<color=#CCC><b>{I18n.Tr("Most similar players")}</b></color>",
                    new Vector2(0, 1), new Vector2(16f, -4f), new Vector2(W - 20, 18), UIFactory.AlignMidLeft);
                MakeGraphLabel("CmpSimSub",
                    $"<color=#888>{I18n.Tr("by hit %, block %, ranked DPS, keys/sec and build-type mix")}</color>",
                    new Vector2(0, 1), new Vector2(16f, -22f), new Vector2(W - 20, 14), UIFactory.AlignMidLeft);

                bool missing = false;
                foreach (int i in idxs)
                {
                    string sid = compareSelected[i];
                    if (!ApiClient.SimilarPlayers.ContainsKey(sid)) { ApiClient.FetchSimilarPlayers(sid); missing = true; }
                }
                if (missing)
                {
                    MakeGraphLabel("CmpSimLoad", $"<color=#888>{I18n.Tr("Loading...")}</color>",
                        new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(W - 40, 30), UIFactory.AlignMidCenter);
                    return;
                }

                int n = idxs.Count;
                int cols = Mathf.Clamp(n, 1, 4);
                int rows = (n + cols - 1) / cols;
                float cellW = (W - 24f) / cols;
                // Rows are laid out from a measured budget rather than a constant:
                // an ultrawide window has far fewer vertical units than 1080 and a
                // fixed stack would run off the bottom of the mask (#199).
                float cellH = (H - 46f) / Mathf.Max(1, rows);
                float lineH = 17f;
                int maxLines = Mathf.Max(1, (int)((cellH - 22f) / lineH));

                for (int k = 0; k < n; k++)
                {
                    int i = idxs[k];
                    var ps = compareStatsCache[compareSelected[i]];
                    var d = ApiClient.SimilarPlayers[compareSelected[i]];
                    int col = k % cols, row = k / cols;
                    float x = 12f + col * cellW;
                    float yTop = -44f - row * cellH;

                    MakeGraphLabel($"CmpSimN{k}",
                        $"<b><color=#{ColorToHex(COMPARE_COLORS[i % COMPARE_COLORS.Length])}>{FfaSafeRich(Trunc(ps.display_name, 16))}</color></b>",
                        new Vector2(0, 1), new Vector2(x, yTop), new Vector2(cellW - 8f, 16), UIFactory.AlignMidLeft, 14f);

                    if (d.names.Count == 0)
                    {
                        MakeGraphLabel($"CmpSimNo{k}", $"<color=#888>{I18n.Tr("no data")}</color>",
                            new Vector2(0, 1), new Vector2(x, yTop - 18f), new Vector2(cellW - 8f, 14), UIFactory.AlignMidLeft, 13f);
                        continue;
                    }
                    for (int r = 0; r < d.names.Count && r < maxLines; r++)
                    {
                        float score = d.scores.Count > r ? d.scores[r] : 0f;
                        MakeGraphLabel($"CmpSim{k}_{r}",
                            $"<color=#CCC>{r + 1}. {FfaSafeRich(Trunc(d.names[r], 14))}</color>  <color=#88CC99>{score:F0}%</color>",
                            new Vector2(0, 1), new Vector2(x, yTop - 18f - r * lineH),
                            new Vector2(cellW - 8f, lineH), UIFactory.AlignMidLeft, 13f);
                    }
                }
            }
            catch (Exception ex) { Plugin.Log.LogWarning($"[COMPARE] similar panel failed: {ex.Message}"); }
        }

        /// <summary>"Nemesis Comparison" — ONE board over the whole selection, not
        /// per player: the question is "who beats these players most", which only
        /// has an answer for the set. Needs 2+ selected (the server rejects fewer).
        /// "Player Nemesis" (below) is the per-player counterpart.
        ///
        /// Aug 7: the endpoint was rescoped from ALL 1v1 matches (casual included)
        /// to completed ranked 1v1 SERIES, so every count on this board is a
        /// SERIES count. The wire field names are frozen (`wins`/`games`), so the
        /// labels are the only place that can say so — they must.</summary>
        private static void BuildCompareNemesisPanel(List<int> idxs, float W, float H)
        {
            try
            {
                MakeGraphLabel("CmpNemTitle", $"<color=#CCC><b>{I18n.Tr("Nemesis Comparison - who beats this group most")}</b></color>",
                    new Vector2(0, 1), new Vector2(16f, -4f), new Vector2(W - 20, 18), UIFactory.AlignMidLeft);

                var sids = new List<string>();
                foreach (int i in idxs) sids.Add(compareSelected[i]);
                string key = ApiClient.NemesisKeyFor(sids);
                if (key == null)
                {
                    MakeGraphLabel("CmpNemNeed",
                        $"<color=#888>{I18n.Tr("Select 2-12 players to find their common nemesis.")}</color>",
                        new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(W - 40, 30), UIFactory.AlignMidCenter);
                    return;
                }
                if (!ApiClient.NemesisBoards.ContainsKey(key))
                {
                    ApiClient.FetchNemesis(key);
                    MakeGraphLabel("CmpNemLoad", $"<color=#888>{I18n.Tr("Loading...")}</color>",
                        new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(W - 40, 30), UIFactory.AlignMidCenter);
                    return;
                }
                var d = ApiClient.NemesisBoards[key];
                if (d.names.Count == 0)
                {
                    // "games" was left over from the pre-Aug-7 endpoint, which
                    // counted all 1v1 matches. The threshold this empty state
                    // reports is the subtitle's "minimum 5 series", so it has to
                    // name the same unit or it reads as a different rule.
                    MakeGraphLabel("CmpNemNone",
                        $"<color=#888>{I18n.Tr("No opponent has enough ranked series against this group yet.")}</color>",
                        new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(W - 40, 30), UIFactory.AlignMidCenter);
                    return;
                }

                MakeGraphLabel("CmpNemSub",
                    $"<color=#888>{I18n.Tr("ranked 1v1 series vs anyone in the selection, minimum 5 series")}</color>",
                    new Vector2(0, 1), new Vector2(16f, -22f), new Vector2(W - 20, 14), UIFactory.AlignMidLeft);

                /* Column budget, stated because an over-budget row compresses its
                 * neighbours and TMP paints the overflow across them (#199/#245).
                 * Left edge 24 + name (<=300) + Win% 90 @ +0 + Record 120 @ +100
                 * (right-aligned, so it ends at name+220) + 12px gutter leaves the
                 * "faced by" column everything from name+232 to W-24. At the 900px
                 * default that is 900 - (24+300+232) - 24 = 320px; the column is
                 * floored at 120px so an unusually narrow panel drops characters
                 * rather than colliding with Record. */
                float x = 24f, rowH = 22f, top = -46f;
                float wName = Mathf.Min(300f, (W - 60f) * 0.45f);
                float xFaced = x + wName + 232f;
                float wFaced = Mathf.Max(120f, W - xFaced - 24f);
                MakeGraphLabel("CmpNemH1", $"<color=#999><b>{I18n.Tr("Player")}</b></color>",
                    new Vector2(0, 1), new Vector2(x, top), new Vector2(wName, 16), UIFactory.AlignMidLeft, 13f);
                MakeGraphLabel("CmpNemH2", $"<color=#999><b>{I18n.Tr("Win %")}</b></color>",
                    new Vector2(0, 1), new Vector2(x + wName, top), new Vector2(90, 16), UIFactory.AlignMidRight, 13f);
                MakeGraphLabel("CmpNemH3", $"<color=#999><b>{I18n.Tr("Series")}</b></color>",
                    new Vector2(0, 1), new Vector2(x + wName + 100f, top), new Vector2(120, 16), UIFactory.AlignMidRight, 13f);
                MakeGraphLabel("CmpNemH4", $"<color=#999><b>{I18n.Tr("Faced by")}</b></color>",
                    new Vector2(0, 1), new Vector2(xFaced, top), new Vector2(wFaced, 16), UIFactory.AlignMidLeft, 13f);

                /* Aug 7 item 2b: attribution. The server sends STEAM IDS, so map
                 * them back to the names the user picked on the left; a selected
                 * player whose stats have not loaded yet falls back to their id
                 * rather than vanishing from the list. ~7.2px per character at 13pt
                 * Gravity is the same estimate the other text columns here use. */
                int facedChars = Mathf.Max(8, (int)(wFaced / 7.2f));
                var selNames = new Dictionary<string, string>();
                foreach (int i in idxs)
                {
                    string sid = compareSelected[i];
                    selNames[sid] = compareStatsCache.TryGetValue(sid, out var sps) && sps != null
                                    && !string.IsNullOrEmpty(sps.display_name) ? sps.display_name : sid;
                }

                int maxRows = Mathf.Max(1, (int)((H - 70f) / rowH));
                for (int r = 0; r < d.names.Count && r < maxRows; r++)
                {
                    float y = top - 20f - r * rowH;
                    float wr = d.winRates.Count > r ? d.winRates[r] * 100f : 0f;
                    int wins = d.wins.Count > r ? d.wins[r] : 0;
                    int games = d.games.Count > r ? d.games[r] : 0;
                    MakeGraphLabel($"CmpNemN{r}", $"<color=#DDD>{r + 1}. {FfaSafeRich(Trunc(d.names[r], 22))}</color>",
                        new Vector2(0, 1), new Vector2(x, y), new Vector2(wName, rowH), UIFactory.AlignMidLeft, 14f);
                    MakeGraphLabel($"CmpNemW{r}",
                        $"<b><color=#{ColorToHex(GradeColor(Mathf.Clamp01(wr / 100f)))}>{wr:F0}%</color></b>",
                        new Vector2(0, 1), new Vector2(x + wName, y), new Vector2(90, rowH), UIFactory.AlignMidRight, 14f);
                    MakeGraphLabel($"CmpNemR{r}", $"<color=#999>{wins} / {games}</color>",
                        new Vector2(0, 1), new Vector2(x + wName + 100f, y), new Vector2(120, rowH), UIFactory.AlignMidRight, 14f);
                    /* facedBy is EMPTY when the server predates the field, and it is
                     * cleared wholesale rather than partially filled, so a bounds
                     * check is the whole guard needed. An empty cell (rather than a
                     * placeholder) is right: the row above it already says which
                     * group was queried. */
                    if (d.facedBy.Count > r && d.facedBy[r] != null && d.facedBy[r].Count > 0)
                    {
                        var who = new List<string>();
                        foreach (string fid in d.facedBy[r])
                            who.Add(selNames.TryGetValue(fid, out var nm) ? nm : fid);
                        MakeGraphLabel($"CmpNemF{r}", $"<color=#8FA3B8>{FfaSafeRich(FitNameList(who, facedChars))}</color>",
                            new Vector2(0, 1), new Vector2(xFaced, y), new Vector2(wFaced, rowH), UIFactory.AlignMidLeft, 13f);
                    }
                }
            }
            catch (Exception ex) { Plugin.Log.LogWarning($"[COMPARE] nemesis panel failed: {ex.Message}"); }
        }

        /// <summary>"Player Nemesis" (Aug 7 item 2d) — one block per selected
        /// player: their own top-5 worst opponents, going DOWN the panel. Unlike
        /// the comparison board this is a per-player question, so a selected
        /// player's nemesis MAY be another selected player and the server
        /// deliberately does not exclude them.
        ///
        /// It renders into compareCardsScroll, NOT compareGraphPanel: the height
        /// is unbounded by the selection (12 players x (1 header + 5 rows) at
        /// ~18px per line + 10px between blocks = 12 x 118 = 1416px against a
        /// ~460px viewport — and far less than 460 on an ultrawide, where the
        /// WIDTH-matched canvas gives well under 1080 vertical units, #199).
        /// compareGraphPanel free-positions into a fixed mask with no scroll, so
        /// the lower blocks would simply be invisible there. Each block is an
        /// auto-height text, i.e. a real preferred height — a flexH child inside a
        /// scroll viewport collapses to zero (#63).</summary>
        private static void BuildComparePlayerNemesisPanel()
        {
            if (compareCardsContent == null || txtCompareCards == null) return;
            try
            {
                ClearCompareScrollContainers();

                var sids = new List<string>();
                foreach (var s in compareSelected) sids.Add(s);
                string key = ApiClient.NemesisKeyFor(sids);
                if (key == null)
                {
                    UIFactory.SetTextRaw(txtCompareCards,
                        $"<color=#888>{I18n.Tr("Select 2-12 players (left) to see who beats each of them most.")}</color>");
                    ((Component)txtCompareCards).gameObject.SetActive(true);
                    return;
                }
                if (!ApiClient.PlayerNemesisBoards.ContainsKey(key))
                {
                    ApiClient.FetchPlayerNemesis(key);
                    UIFactory.SetTextRaw(txtCompareCards, $"<color=#888>{I18n.Tr("Loading...")}</color>");
                    ((Component)txtCompareCards).gameObject.SetActive(true);
                    return;
                }
                ((Component)txtCompareCards).gameObject.SetActive(false);

                var d = ApiClient.PlayerNemesisBoards[key];
                var col = new GameObject("CmpPNemCol");
                col.transform.SetParent(compareCardsContent.transform, false);
                col.AddComponent<RectTransform>();
                UIFactory.AddVLG(col, spacing: 10, padL: 8, padR: 8, padT: 4, padB: 8);

                UIFactory.SetTextAutoHeight(UIFactory.CreateText("CmpPNemSub", col.transform,
                    $"<color=#888>{I18n.Tr("Each player's worst ranked 1v1 opponents - minimum 3 series, top 5")}</color>",
                    13f, C_DIM, UIFactory.AlignTopLeft, sizeDelta: new Vector2(820, 18)));

                if (d.players.Count == 0)
                {
                    UIFactory.SetTextAutoHeight(UIFactory.CreateText("CmpPNemNone", col.transform,
                        $"<color=#888>{I18n.Tr("No ranked 1v1 series recorded for the selected players yet.")}</color>",
                        14f, C_DIM, UIFactory.AlignTopLeft, sizeDelta: new Vector2(820, 20)));
                    return;
                }

                /* Driven off the SERVER's list, in the server's order (it echoes the
                 * requested order): a steam id the server does not know is absent
                 * from `players` entirely, so iterating the selection instead would
                 * invent empty blocks for unknown players. The header colour is
                 * matched back to the left picker BY STEAM ID rather than by
                 * position — the two orderings are not guaranteed equal. */
                for (int p = 0; p < d.players.Count; p++)
                {
                    var g = d.players[p];
                    int selIdx = compareSelected.IndexOf(g.steamId);
                    Color pc = COMPARE_COLORS[(selIdx >= 0 ? selIdx : p) % COMPARE_COLORS.Length];

                    var sb = new System.Text.StringBuilder(256);
                    string who = string.IsNullOrEmpty(g.name) ? g.steamId : g.name;
                    sb.Append($"<color=#{ColorToHex(pc)}><b>{FfaSafeRich(Trunc(who, 22))}</b></color>");
                    if (g.nemeses == null || g.nemeses.Count == 0)
                        // A complete answer, not a failure: nobody has taken 3+
                        // series off them. Rendering nothing at all would read as a
                        // dropped row.
                        sb.Append($"\n   <color=#777>{I18n.Tr("no opponent has taken 3+ series from them")}</color>");
                    else
                        for (int r = 0; r < g.nemeses.Count; r++)
                        {
                            var e = g.nemeses[r];
                            string hex = ColorToHex(GradeColor(Mathf.Clamp01(e.lossRate)));
                            sb.Append($"\n   <color=#DDD>{r + 1}. {FfaSafeRich(Trunc(string.IsNullOrEmpty(e.name) ? e.steamId : e.name, 20))}</color>"
                                    + $"   <b><color=#{hex}>{e.lossRate * 100f:F0}%</color></b>"
                                    + $"   <color=#999>{I18n.TrF("lost {0} of {1}", e.seriesLost, e.seriesPlayed)}</color>");
                        }

                    /* Wrap ON + auto-height, exactly like the card-grid cells: the
                     * content height then tracks the rendered text so the scroll
                     * really scrolls (#63), and a long OS-fallback name wraps
                     * instead of being clipped by the global Truncate default
                     * (#292/#297). */
                    var blk = UIFactory.CreateText($"CmpPNem{p}", col.transform, sb.ToString(),
                        14f, C_DIM, UIFactory.AlignTopLeft, sizeDelta: new Vector2(820, 24));
                    UIFactory.SetWordWrap(blk, true);
                    UIFactory.SetTextAutoHeight(blk);
                }
            }
            catch (Exception ex) { Plugin.Log.LogWarning($"[COMPARE] player nemesis panel failed: {ex.Message}"); }
        }

        /* "bounce_kill" is DELIBERATELY absent. The bounce-kill telemetry was
         * cut in the Aug-6 round-4 review, and GameStateWatcher now always
         * reports -1 for it, which _obs() maps to NULL — so players.record_bounce_kill
         * stays NULL forever and /records?board=bounce_kill (which filters
         * IS NOT NULL) can only ever return empty arrays. Leaving it listed
         * rendered a third column headed "Most Bounces Before A Kill" that no
         * game could ever populate: the same half-cut shape as #279, where a
         * feature was removed and its UI sibling left live.
         * The server endpoint and column are intentionally kept — they cost
         * nothing and are ready if the telemetry is ever revived; re-adding the
         * string here is then the only client change needed. */
        // Aug 17 (Sid): six match-derived boards. bounce_kill stays available
        // server-side but un-listed (its telemetry was cut client-side).
        // longest_game / shortest_game are MATCH boards — both participants
        // render, "A vs B".
        // Two pages (Sid, Aug 18: "add a second Records page"). Page 2 opens
        // with the offers-based Luckiest and is where the future telemetry
        // records (stun length, bullet speed, cloud size) will land.
        private static readonly string[][] RECORD_PAGES =
        {
            new[] { "single_hit", "max_health", "avg_dps", "rarest_hand", "longest_game", "shortest_game" },
            new[] { "luckiest" },
        };
        private static int recordsPage;
        // Admin record-removal two-click arm (a mis-click here deletes a board
        // row with no API undo, so the first click only arms).
        private static string recExclArmKey;
        private static float recExclArmAt;

        /// <summary>r3 finding 7: the 300s records TTL needs a WAKE — with
        /// the Compare tab idle nothing re-renders, so FetchRecordsBoard
        /// never re-enters to observe expiry and an admin exclusion stayed
        /// visible until restart. 5s throttle; the fetch itself is
        /// TTL/in-flight/backoff guarded, so this is a no-op except at
        /// expiry, and fetch completion MarkDirty()s the re-render.</summary>
        private static float lastCompareRecordsPoke;
        private static void MaybeRefreshCompareRecords()
        {
            if (currentTab != 9 || compareSubTab == 1) return;
            string metricName = COMPARE_METRICS[Math.Max(0, Math.Min(compareMetric, COMPARE_METRICS.Length - 1))];
            if (metricName != "Records") return;
            if (Time.realtimeSinceStartup - lastCompareRecordsPoke < 5f) return;
            lastCompareRecordsPoke = Time.realtimeSinceStartup;
            // r4 f3: the armed "?" only cleared on a rebuild, so on a quiet
            // tab it sat stale past its 5s window and the next click
            // re-armed with no visible change (a third click to act).
            if (recExclArmKey != null && Time.unscaledTime - recExclArmAt > 5f)
            {
                recExclArmKey = null;
                MarkDirty();
            }
            var boards = RECORD_PAGES[recordsPage % RECORD_PAGES.Length];
            foreach (var b in boards) ApiClient.FetchRecordsBoard(b);
        }

        private static string RecordBoardHeading(string board)
        {
            switch (board)
            {
                case "single_hit": return I18n.Tr("Highest Single Hit");
                case "max_health": return I18n.Tr("Highest Health");
                case "avg_dps": return I18n.Tr("Highest Avg DPS");
                case "rarest_hand": return I18n.Tr("Rarest Hand");
                case "luckiest": return I18n.Tr("Luckiest (rare draws)");
                case "longest_game": return I18n.Tr("Longest Game");
                case "shortest_game": return I18n.Tr("Shortest Game");
                default: return board;
            }
        }

        private static string RecordValueText(string board, int v)
        {
            switch (board)
            {
                case "avg_dps":
                    // r4 f2: this branch returned before the >=1M compactor,
                    // so a forged self-report still overflowed the cell.
                    float dps = v / 10f;
                    return (dps >= 1000000f
                        ? (dps / 1000000f).ToString("0.#", _INV) + "M"
                        : dps.ToString("0.0", _INV)) + "/s";
                case "rarest_hand":
                case "luckiest": return v + "%";
                case "longest_game":
                case "shortest_game": return $"{v / 60}:{v % 60:00}";
                default:
                    // r3 finding 9: the 64px value cell renders in Overflow
                    // mode, so an absurd (forged) value walked left across the
                    // name cell. Legit records never reach 1M — compact form
                    // bounds the glyph run deterministically.
                    return v >= 1000000
                        ? (v / 1000000f).ToString("0.#", _INV) + "M"
                        : FullNum(v);
            }
        }

        /// <summary>"Records" — GLOBAL per-game record boards in a 3x2 grid.
        /// Each row is a concrete game: holder (name + title + elo), value,
        /// date, with the cards it was set with on HOVER (the row is too
        /// narrow to print builds inline). Not per-selection boards — the
        /// selected players are highlighted where they appear.</summary>
        private static void BuildCompareRecordsPanel(List<int> idxs, float W, float H)
        {
            try
            {
                MakeGraphLabel("CmpRecTitle", $"<color=#CCC><b>{I18n.Tr("Game records (all players) - hover a row for the cards")}</b></color>",
                    new Vector2(0, 1), new Vector2(16f, -4f), new Vector2(W - 240, 20), UIFactory.AlignMidLeft, 15f);

                // Page flip (Sid, Aug 18). The button is rebuilt with the rest
                // of the panel every render, so the label always reflects the
                // live page. CreateButton already ClickGuards (#158).
                if (recordsPage >= RECORD_PAGES.Length) recordsPage = 0;
                var boards = RECORD_PAGES[recordsPage];
                var pgBtn = UIFactory.CreateButton("CmpRecPg", compareGraphPanel.transform,
                    I18n.TrF("Page {0}/{1}", recordsPage + 1, RECORD_PAGES.Length), 14f, C_WHITE, C_BTN,
                    () => { recordsPage = (recordsPage + 1) % RECORD_PAGES.Length; recExclArmKey = null; MarkDirty(); },
                    sizeDelta: new Vector2(90, 20));
                var pgRt = pgBtn.GetComponent<RectTransform>();
                pgRt.anchorMin = pgRt.anchorMax = pgRt.pivot = new Vector2(1, 1);
                pgRt.anchoredPosition = new Vector2(-16f, -4f);

                // Per-board rendering (review F5): the old all-or-nothing gate
                // held the WHOLE panel on "Loading..." if any single board
                // never cached — against a pre-batch server the four new
                // boards 400 forever and even the two legacy boards vanished.
                bool anyCached = false;
                foreach (var b in boards)
                {
                    if (ApiClient.RecordsBoards.ContainsKey(b)) anyCached = true;
                    // ALWAYS called (r2 finding 5): the 300s refresh TTL lives
                    // INSIDE FetchRecordsBoard, and a ContainsKey gate here
                    // made it unreachable — an admin exclusion never reached
                    // other running clients (#247: verify the trigger can
                    // actually fire). Dedupe/backoff bound the cadence.
                    ApiClient.FetchRecordsBoard(b);
                }
                if (!anyCached)
                {
                    MakeGraphLabel("CmpRecLoad", $"<color=#888>{I18n.Tr("Loading...")}</color>",
                        new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(W - 40, 30), UIFactory.AlignMidCenter, 14f);
                    return;
                }

                // Which selected players to highlight, and in what colour.
                var hi = new Dictionary<string, Color>();
                foreach (int i in idxs)
                    hi[compareSelected[i]] = COMPARE_COLORS[i % COMPARE_COLORS.Length];

                const int COLS = 3;
                // Page 2 currently holds one board; a 1-row grid there would
                // stretch a single section over the whole panel height, so the
                // section height is always computed from a FULL page's rows —
                // boards keep the same size on every page.
                int gridRows = (RECORD_PAGES[0].Length + COLS - 1) / COLS;
                float colW = (W - 32f) / COLS;
                float secH = (H - 30f) / gridRows;
                float rowH = 22f;
                int maxRows = Mathf.Max(3, (int)((secH - 52f) / rowH));

                for (int c = 0; c < boards.Length; c++)
                {
                    string board = boards[c];
                    bool isMatchBoard = board == "longest_game" || board == "shortest_game";
                    float x = 16f + (c % COLS) * colW;
                    float secY = -26f - (c / COLS) * secH;
                    MakeGraphLabel($"CmpRecH{c}", $"<b><color=#DDCC88>{RecordBoardHeading(board)}</color></b>",
                        new Vector2(0, 1), new Vector2(x, secY), new Vector2(colW - 10f, 16), UIFactory.AlignMidLeft, 14f);

                    if (!ApiClient.RecordsBoards.TryGetValue(board, out var d))
                    {
                        MakeGraphLabel($"CmpRecP{c}", $"<color=#888>{I18n.Tr("Loading...")}</color>",
                            new Vector2(0, 1), new Vector2(x, secY - 22f), new Vector2(colW - 10f, 14), UIFactory.AlignMidLeft, 14f);
                        continue;
                    }
                    if (d.names.Count == 0)
                    {
                        MakeGraphLabel($"CmpRecNo{c}", $"<color=#888>{I18n.Tr("no data yet")}</color>",
                            new Vector2(0, 1), new Vector2(x, secY - 22f), new Vector2(colW - 10f, 14), UIFactory.AlignMidLeft, 14f);
                        continue;
                    }
                    bool rich = d.dates.Count == d.names.Count;   // enrichment present
                    // Admin record-removal (Sid, Aug 18): rows grow a small [x]
                    // when the server sent match ids and the viewer is admin.
                    // Everything in the row shifts left by the same amount so
                    // no cell overlaps (#245's model-the-budget rule).
                    bool canExcl = ApiClient.IsAdmin && d.matchIds.Count == d.names.Count;
                    float adm = canExcl ? 20f : 0f;
                    if (recExclArmKey != null && Time.unscaledTime - recExclArmAt > 5f)
                        recExclArmKey = null;   // stale arm quietly expires
                    for (int r = 0; r < d.names.Count && r < maxRows; r++)
                    {
                        float y = secY - 22f - r * rowH;
                        string sid = d.steamIds.Count > r ? d.steamIds[r] : "";
                        bool isSel = !string.IsNullOrEmpty(sid) && hi.ContainsKey(sid);
                        string nameHex = isSel ? ColorToHex(hi[sid]) : "CCCCCC";
                        string bold = isSel ? "<b>" : "", boldEnd = isSel ? "</b>" : "";

                        // Name cell. Wider than the old 13-char cut (Sid:
                        // "names are being cutoff for no reason") — the value
                        // column is 64px and the date 44px; everything else is
                        // the name's. Match boards render "A vs B".
                        string nameCell;
                        if (isMatchBoard && rich && d.names2.Count > r && !string.IsNullOrEmpty(d.names2[r]))
                        {
                            // Both participants take the highlight (round-2
                            // f12: only p1 carried a steam id, so a selected
                            // player sitting in the p2 seat stayed gray).
                            string sid2 = d.steamIds2.Count > r ? d.steamIds2[r] : "";
                            bool isSel2 = !string.IsNullOrEmpty(sid2) && hi.ContainsKey(sid2);
                            string nameHex2 = isSel2 ? ColorToHex(hi[sid2]) : "CCCCCC";
                            string bold2 = isSel2 ? "<b>" : "", bold2End = isSel2 ? "</b>" : "";
                            nameCell = $"{bold}<color=#{nameHex}>{FfaSafeRich(Trunc(d.names[r], 12))}</color>{boldEnd}"
                                     + $" <color=#888>vs</color> {bold2}<color=#{nameHex2}>{FfaSafeRich(Trunc(d.names2[r], 12))}</color>{bold2End}";
                        }
                        else
                        {
                            // Full-size suffixes (Sid, Aug 18: nothing below
                            // the 14pt FPS/Ping floor) — the name budget gives
                            // the ground the tags gained.
                            nameCell = $"{bold}<color=#{nameHex}>{FfaSafeRich(Trunc(d.names[r], 16))}</color>{boldEnd}";
                            if (rich && d.titles.Count > r && !string.IsNullOrEmpty(d.titles[r]))
                            {
                                string tc = (d.titleColors.Count > r && !string.IsNullOrEmpty(d.titleColors[r]))
                                    ? d.titleColors[r] : "#FFD94D";
                                nameCell += $" <color={tc}>[{FfaSafeRich(Trunc(d.titles[r], 10))}]</color>";
                            }
                            if (rich && d.ratings.Count > r && d.ratings[r] > 0)
                                nameCell += $" <color=#8E99A8>{d.ratings[r]}</color>";
                        }
                        var nameLbl = MakeGraphLabel($"CmpRecN{c}_{r}",
                            $"<color=#777>{r + 1}.</color> {nameCell}",
                            new Vector2(0, 1), new Vector2(x, y), new Vector2(colW - 130f - adm, rowH), UIFactory.AlignMidLeft, 14f);
                        MakeGraphLabel($"CmpRecV{c}_{r}",
                            $"<color=#99CCAA>{RecordValueText(board, d.values.Count > r ? d.values[r] : 0)}</color>",
                            new Vector2(0, 1), new Vector2(x + colW - 130f - adm, y), new Vector2(64, rowH), UIFactory.AlignMidRight, 14f);
                        if (rich && d.dates.Count > r && !string.IsNullOrEmpty(d.dates[r]))
                            MakeGraphLabel($"CmpRecD{c}_{r}",
                                $"<color=#667>{ShortRecDate(d.dates[r])}</color>",
                                new Vector2(0, 1), new Vector2(x + colW - 62f - adm, y), new Vector2(56, rowH), UIFactory.AlignMidRight, 14f);

                        if (canExcl && !string.IsNullOrEmpty(d.matchIds[r]))
                        {
                            // Two-click arm: click 1 turns the control into a
                            // yellow "?", click 2 (within 5s, same row) fires
                            // the exclusion. Seat boards name the row's holder;
                            // the game-length boards exclude match-wide.
                            string armKey = $"{board}:{d.matchIds[r]}:{sid}";
                            bool armed = recExclArmKey == armKey;
                            string mid = d.matchIds[r];
                            string exclSid = isMatchBoard ? "" : sid;
                            var xBtn = UIFactory.CreateButton($"CmpRecX{c}_{r}",
                                compareGraphPanel.transform, armed ? "?" : "x", 14f,
                                armed ? new Color(1f, 0.85f, 0.3f) : new Color(1f, 0.45f, 0.45f),
                                C_BTN, () =>
                                {
                                    float armAge = Time.unscaledTime - recExclArmAt;
                                    // r1 finding 5: the 5s window must be checked
                                    // HERE, not only at rebuild time — on a quiet
                                    // tab nothing rebuilds, so key equality alone
                                    // would honor a minutes-old arm.
                                    if (recExclArmKey != armKey || armAge > 5f)
                                    {
                                        recExclArmKey = armKey;
                                        recExclArmAt = Time.unscaledTime;
                                        MarkDirty();
                                        return;
                                    }
                                    // r1 finding 6: a rebuild replacing this button
                                    // mid-press could let ONE physical click both
                                    // arm and submit (the replacement has a fresh
                                    // ClickGuard key). The ghost lands within 1-2
                                    // frames (<70ms even at 30fps); 0.12s kills it
                                    // without swallowing a real fast second click
                                    // (r2 finding 6 measured 0.25s doing exactly
                                    // that at 60fps).
                                    if (armAge < 0.12f) return;
                                    recExclArmKey = null;
                                    ApiClient.AdminExcludeRecord(MatchTracker.LocalSteamId, board,
                                        mid, exclSid, "admin removal via Records UI", (ok, resp) =>
                                        {
                                            if (ok)
                                            {
                                                // r2 finding 7 (accepted, bounded): two
                                                // overlapping exclusions on ONE board can
                                                // race a refetch into re-caching the older
                                                // snapshot. The DB is correct; the display
                                                // self-heals within the 300s TTL now that
                                                // the render path actually refetches (F5).
                                                ApiClient.RecordsBoards.Remove(board);
                                                ApiClient.FetchRecordsBoard(board);
                                                CompetitiveUI.ShowNotification(I18n.Tr("Record removed."), Color.green, 4f);
                                            }
                                            else
                                                CompetitiveUI.ShowNotification(
                                                    I18n.TrF("Record removal failed: {0}", Trunc(resp ?? "", 60)),
                                                    Color.red, 6f);
                                            MarkDirty();
                                        });
                                }, sizeDelta: new Vector2(18, 18));
                            var xRt = xBtn.GetComponent<RectTransform>();
                            xRt.anchorMin = xRt.anchorMax = xRt.pivot = new Vector2(0, 1);
                            xRt.anchoredPosition = new Vector2(x + colW - 20f, y - 2f);
                        }

                        // Hover: the record game's cards (+ both builds on the
                        // match boards). Registered only when there is a body
                        // (#106 — the name cell always renders text).
                        if (rich && nameLbl != null)
                        {
                            string body = BuildRecordHoverBody(d, r, isMatchBoard);
                            if (!string.IsNullOrEmpty(body))
                                RegisterHoverRectFor(nameLbl, "", false,
                                    GameStateWatcher.StripRichText(d.names[r] ?? ""), body);
                        }
                    }
                }
            }
            catch (Exception ex) { Plugin.Log.LogWarning($"[COMPARE] records panel failed: {ex.Message}"); }
        }

        /// <summary>Month+day from the record game's timestamp — the row's
        /// 44px date cell cannot fit more, and the full date is not worth a
        /// hover. Routed through DateFmt (round-2 f13) and converted to the
        /// VIEWER'S local day (round-3 f5: a UTC date truncation put late-
        /// evening US records on "tomorrow"). Date-only strings (older
        /// server) keep the literal calendar day — ToLocalTime on an
        /// unspecified-kind date would silently treat it as UTC and shift it.</summary>
        private static string ShortRecDate(string iso)
        {
            try
            {
                if (iso.IndexOf('T') >= 0)
                {
                    var dt = DateTime.Parse(iso, _INV, System.Globalization.DateTimeStyles.RoundtripKind);
                    return DateFmt.MonthDay(dt.Kind == DateTimeKind.Unspecified ? dt : dt.ToLocalTime());
                }
                var parts = iso.Split('-');
                if (parts.Length == 3)
                    return DateFmt.MonthDay(new DateTime(
                        int.Parse(parts[0], _INV), int.Parse(parts[1], _INV),
                        int.Parse(parts[2], _INV)));
            }
            catch { }
            return iso;
        }

        private static void AppendHoverTitleElo(StringBuilder sb, ApiClient.RecordsBoardData d, int r)
        {
            if (d.titles.Count > r && !string.IsNullOrEmpty(d.titles[r]))
            {
                string tc = (d.titleColors.Count > r && !string.IsNullOrEmpty(d.titleColors[r]))
                    ? d.titleColors[r] : "#FFD94D";
                sb.Append(" <color=").Append(tc).Append(">[").Append(FfaSafeRich(d.titles[r])).Append("]</color>");
            }
            if (d.ratings.Count > r && d.ratings[r] > 0)
                sb.Append(" <color=#8E99A8>(").Append(d.ratings[r]).Append(")</color>");
        }

        /// <summary>Pipe-joined card list -> one bullet per line, localized
        /// via the game's own card localization (same treatment as the legacy
        /// tooltip path) and sanitized (#156 — names are client-reported).
        /// IMGUI's OS font has the bullet glyph (#47 is a TMP/Gravity limit).</summary>
        private static string HoverCardLines(string pipeCards, string indent)
        {
            if (string.IsNullOrEmpty(pipeCards)) return null;
            var parts = pipeCards.Split('|');
            var sb = new StringBuilder();
            int shown = 0;
            for (int i = 0; i < parts.Length; i++)
            {
                string nm = parts[i].Trim();
                if (nm.Length == 0) continue;
                // r3 finding 8: the tooltip's overflow pass drops NON-bullet
                // lines first, so an unbounded card list evicted the score/
                // duration/opponent headers this hover exists to show. 40
                // bullets + headers fit every supported resolution; the rest
                // collapse into a counted line.
                if (shown >= 40)
                {
                    int extra = 0;
                    for (int j = i; j < parts.Length; j++)
                        if (parts[j].Trim().Length > 0) extra++;
                    sb.Append('\n').Append(indent)
                      .Append("<color=#888>").Append(I18n.TrF("+{0} more lines", extra)).Append("</color>");
                    break;
                }
                string disp = nm;
                try { disp = CardTextLocalizer.PrettyName(nm, nm); } catch { }
                if (sb.Length > 0) sb.Append('\n');
                sb.Append(indent).Append("\u2022 ").Append(FfaSafeRich(disp));
                shown++;
            }
            return sb.Length > 0 ? sb.ToString() : null;
        }

        private static string BuildRecordHoverBody(ApiClient.RecordsBoardData d, int r, bool isMatchBoard)
        {
            var sb = new StringBuilder();
            string myCards = d.cards.Count > r ? d.cards[r] : "";
            // Sid (Aug 18): game details up top — score (half-point
            // convention, server-mirrored) and duration.
            bool det = d.durations.Count > r && d.scores.Count > r;
            if (det && (!string.IsNullOrEmpty(d.scores[r]) || d.durations[r] > 0))
            {
                if (!string.IsNullOrEmpty(d.scores[r]))
                    sb.Append("<color=#99CCAA><b>").Append(FfaSafeRich(d.scores[r])).Append("</b></color>");
                if (d.durations[r] > 0)
                {
                    if (sb.Length > 0) sb.Append("  ");
                    sb.Append("<color=#8FA3B8>").Append(d.durations[r] / 60).Append(':')
                      .Append((d.durations[r] % 60).ToString("00", _INV)).Append("</color>");
                }
                sb.Append('\n');
            }
            if (isMatchBoard)
            {
                string oppCards = d.cards2.Count > r ? d.cards2[r] : "";
                // UNTRUNCATED in the hover (Sid, Aug 18) — the row cells
                // truncate for space; the hover is where the full name lives.
                sb.Append("<b>").Append(FfaSafeRich(d.names[r] ?? "?")).Append("</b>");
                AppendHoverTitleElo(sb, d, r);
                sb.Append('\n').Append(HoverCardLines(myCards, "  ") ?? I18n.Tr("  <color=#888>(no cards recorded)</color>"));
                if (d.names2.Count > r && !string.IsNullOrEmpty(d.names2[r]))
                {
                    sb.Append("\n<b>").Append(FfaSafeRich(d.names2[r])).Append("</b>");
                    if (d.ratings2.Count > r && d.ratings2[r] > 0) sb.Append(" <color=#8E99A8>(").Append(d.ratings2[r]).Append(")</color>");
                    sb.Append('\n').Append(HoverCardLines(oppCards, "  ") ?? I18n.Tr("  <color=#888>(no cards recorded)</color>"));
                }
            }
            else
            {
                // r3 finding 6: the holder's UNTRUNCATED title/elo must have a
                // surface — the row truncates the title to 10 chars and the
                // tooltip title strip is plain text, so the seat-board body
                // carries the full name + title + elo line the match boards
                // already had.
                sb.Append("<b>").Append(FfaSafeRich(d.names[r] ?? "?")).Append("</b>");
                AppendHoverTitleElo(sb, d, r);
                sb.Append('\n');
                if (d.names2.Count > r && !string.IsNullOrEmpty(d.names2[r]))
                    sb.Append(I18n.TrF("<color=#889>vs {0}</color>", FfaSafeRich(d.names2[r]))).Append('\n');
                sb.Append(HoverCardLines(myCards, "") ?? I18n.Tr("<color=#888>(no cards recorded)</color>"));
            }
            return sb.ToString();
        }

        // ── Aug 6 item 2: Cards sub-tab renderers ────────────────────────────
        /// <summary>Chart the selected CARDS. Four of the five metrics come off
        /// the /cards catalogue row the picker already loaded; "Top Pickers"
        /// reads /cards/top-pickers per card.</summary>
        private static void BuildCompareCardMetric(string metricName)
        {
            if (compareGraphPanel == null) return;
            for (int c = compareGraphPanel.transform.childCount - 1; c >= 0; c--)
                UnityEngine.Object.Destroy(compareGraphPanel.transform.GetChild(c).gameObject);
            CompetitiveUI.ClearCardHoverRegions();   // Records hovers die with the panel (Aug 17)

            CompareChartSize(out float W, out float H);
            try
            {
                if (compareCardsSelected.Count == 0)
                {
                    MakeGraphLabel("CmpCMNone",
                        $"<color=#888>{I18n.TrF("Choose cards (left) to compare {0}.", "<b>" + TrMetric(metricName) + "</b>")}</color>",
                        new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(W - 40, 40), UIFactory.AlignMidCenter);
                    return;
                }
                if (ApiClient.CardCatalog == null)
                {
                    MakeGraphLabel("CmpCMLoad", $"<color=#888>{I18n.Tr("Loading...")}</color>",
                        new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(W - 40, 30), UIFactory.AlignMidCenter);
                    return;
                }
                if (metricName == "Top Pickers") { BuildCompareCardPickers(W, H); return; }

                string title = metricName == "Times Picked" ? I18n.Tr("Times picked (all players)")
                             : metricName == "Card Win Rate" ? I18n.Tr("Win rate holding this card")
                             : metricName == "Pass Rate" ? I18n.Tr("Pass rate (offered but not taken)")
                             : I18n.Tr("Times offered");
                bool pct = metricName == "Card Win Rate" || metricName == "Pass Rate";
                MakeGraphLabel("CmpCMTitle", $"<color=#CCC><b>{title}</b></color>",
                    new Vector2(0, 1), new Vector2(60f, -4f), new Vector2(W - 60, 18), UIFactory.AlignMidLeft);

                // Resolve each selected card's row once.
                var names = new List<string>(); var vals = new List<float>(); var cols = new List<Color>();
                foreach (var card in compareCardsSelected)
                {
                    ApiClient.CardCatalogEntry hit = null;
                    foreach (var e in ApiClient.CardCatalog)
                        if (string.Equals(e.name, card, StringComparison.OrdinalIgnoreCase)) { hit = e; break; }
                    names.Add(CardTextLocalizer.PrettyName(card, card) ?? card);
                    cols.Add(CardColorFor(card));
                    float v = 0f;
                    if (hit != null)
                        v = metricName == "Times Picked" ? hit.times_picked
                          : metricName == "Card Win Rate" ? hit.win_rate * 100f
                          : metricName == "Pass Rate" ? hit.pass_rate * 100f
                          : hit.times_offered;
                    vals.Add(v);
                }

                float padL = 60f, padR = 16f, padT = 34f, padB = 48f;
                float plotW = W - padL - padR, plotH = H - padT - padB;
                int n = names.Count;
                float groupW = plotW / n;

                float maxV, step;
                if (pct) { maxV = 100f; step = 25f; }
                else
                {
                    float dataMax = 0.0001f;
                    foreach (var v in vals) if (v > dataMax) dataMax = v;
                    step = NiceStep(dataMax / 4f);
                    maxV = Mathf.Ceil(dataMax * 1.08f / step) * step;
                    if (maxV < step) maxV = step;
                }
                int yDivs = Mathf.Clamp(Mathf.RoundToInt(maxV / step), 2, 10);
                for (int gi = 0; gi <= yDivs; gi++)
                {
                    float val = gi * step;
                    if (val > maxV + 0.001f) break;
                    float yy = padB + (val / maxV) * plotH;
                    DrawBar($"CmpCMGrid{gi}", padL, yy, plotW, 1f, new Color(1f, 1f, 1f, 0.10f));
                    MakeGraphLabel($"CmpCMY{gi}", $"<color=#999>{FullNum(val)}{(pct ? "%" : "")}</color>",
                        new Vector2(0, 0), new Vector2(padL - 4f, yy - 6f), new Vector2(52, 12), UIFactory.AlignMidRight);
                }

                int nameLen = Mathf.Clamp((int)(groupW / 8f), 5, 18);
                for (int gi = 0; gi < n; gi++)
                {
                    float gx = padL + gi * groupW;
                    float bw = groupW * 0.58f;
                    float bx = gx + (groupW - bw) * 0.5f;
                    float clamped = Mathf.Clamp(vals[gi], 0f, maxV);
                    // Bars carry the card's RARITY colour — the only per-card
                    // colour source the plugin has (see CardColorFor).
                    DrawBar($"CmpCMBar{gi}", bx, padB, bw, clamped / maxV * plotH, cols[gi]);
                    MakeGraphLabel($"CmpCMV{gi}",
                        $"<color=#EEE>{(pct ? vals[gi].ToString("F1") + "%" : FullNum(vals[gi]))}</color>",
                        new Vector2(0, 0), new Vector2(bx - 6f, padB + clamped / maxV * plotH + 1f),
                        new Vector2(bw + 12f, 12), UIFactory.AlignMidCenter);
                    MakeGraphLabel($"CmpCMName{gi}",
                        $"<b><color=#{ColorToHex(cols[gi])}>{FfaSafeRich(Trunc(names[gi], nameLen))}</color></b>",
                        new Vector2(0, 0), new Vector2(gx - 4f, padB - 18f), new Vector2(groupW + 8f, 16),
                        UIFactory.AlignMidCenter, 13f);
                }
            }
            catch (Exception ex) { Plugin.Log.LogWarning($"[COMPARE] card metric failed: {ex.Message}"); }
        }

        /// <summary>"Top Pickers" — a mini-leaderboard per selected card, laid out
        /// as columns.</summary>
        private static void BuildCompareCardPickers(float W, float H)
        {
            MakeGraphLabel("CmpCPTitle", $"<color=#CCC><b>{I18n.Tr("Who picks these cards the most")}</b></color>",
                new Vector2(0, 1), new Vector2(16f, -4f), new Vector2(W - 20, 18), UIFactory.AlignMidLeft);

            bool missing = false;
            foreach (var card in compareCardsSelected)
                if (!ApiClient.CardTopPickers.ContainsKey(card)) { ApiClient.FetchCardTopPickers(card); missing = true; }
            if (missing)
            {
                MakeGraphLabel("CmpCPLoad", $"<color=#888>{I18n.Tr("Loading...")}</color>",
                    new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(W - 40, 30), UIFactory.AlignMidCenter);
                return;
            }

            int n = compareCardsSelected.Count;
            int cols = Mathf.Clamp(n, 1, 4);
            int rows = (n + cols - 1) / cols;
            float cellW = (W - 24f) / cols;
            float cellH = (H - 40f) / Mathf.Max(1, rows);
            float rowH = 18f;
            int maxRows = Mathf.Max(1, (int)((cellH - 24f) / rowH));

            for (int k = 0; k < n; k++)
            {
                string card = compareCardsSelected[k];
                var d = ApiClient.CardTopPickers[card];
                int col = k % cols, row = k / cols;
                float x = 12f + col * cellW;
                float yTop = -30f - row * cellH;
                Color cc = CardColorFor(card);
                MakeGraphLabel($"CmpCPH{k}",
                    $"<b><color=#{ColorToHex(cc)}>{FfaSafeRich(Trunc(CardTextLocalizer.PrettyName(card, card) ?? card, 18))}</color></b>",
                    new Vector2(0, 1), new Vector2(x, yTop), new Vector2(cellW - 8f, 16), UIFactory.AlignMidLeft, 14f);
                if (d.names.Count == 0)
                {
                    MakeGraphLabel($"CmpCPNo{k}", $"<color=#888>{I18n.Tr("no data")}</color>",
                        new Vector2(0, 1), new Vector2(x, yTop - 20f), new Vector2(cellW - 8f, 14), UIFactory.AlignMidLeft, 13f);
                    continue;
                }
                for (int r = 0; r < d.names.Count && r < maxRows; r++)
                {
                    float y = yTop - 20f - r * rowH;
                    int picks = d.picks.Count > r ? d.picks[r] : 0;
                    float wr = d.winRates.Count > r ? d.winRates[r] * 100f : 0f;
                    MakeGraphLabel($"CmpCP{k}_{r}",
                        $"<color=#CCC>{r + 1}. {FfaSafeRich(Trunc(d.names[r], 12))}</color> <color=#999>x{picks}</color> <color=#88CC99>{wr:F0}%</color>",
                        new Vector2(0, 1), new Vector2(x, y), new Vector2(cellW - 8f, rowH), UIFactory.AlignMidLeft, 13f);
                }
            }
        }

        // Card metrics (Top / Worst) as a multi-column grid of per-player blocks so
        // many players wrap sideways instead of running off the bottom of the page.
        // Built into compareCardsContent (the card scroll's content). 3 columns.
        /// <summary>Removes every metric-owned container from the Compare tab's
        /// shared scroll surface. Two metrics build into it (the card grids and
        /// the Player Nemesis stack) and each must leave the other's leftovers
        /// destroyed, or switching between them stacks both.</summary>
        private static void ClearCompareScrollContainers()
        {
            if (compareCardsContent == null) return;
            var a = compareCardsContent.transform.Find("CmpCardCols");
            if (a != null) UnityEngine.Object.Destroy(a.gameObject);
            var b = compareCardsContent.transform.Find("CmpPNemCol");
            if (b != null) UnityEngine.Object.Destroy(b.gameObject);
        }

        private static void BuildCompareCardGrid(string metricName)
        {
            if (compareCardsContent == null || txtCompareCards == null) return;
            // Tear down any prior grid container. Both containers are cleared
            // because this scroll surface now serves the card grids AND the
            // Player Nemesis stack — leaving the other metric's container behind
            // renders two metrics at once (Aug 7 item 2d).
            ClearCompareScrollContainers();

            if (compareSelected.Count == 0)
            {
                UIFactory.SetTextRaw(txtCompareCards, $"<color=#888>{I18n.TrF("Select players (left) to compare {0}.", "<b>" + TrMetric(metricName) + "</b>")}</color>");
                ((Component)txtCompareCards).gameObject.SetActive(true);
                return;
            }
            ((Component)txtCompareCards).gameObject.SetActive(false);

            // Columns container: an HLG of N vertical columns. Players fill column by
            // column (down, then across).
            int cols = compareSelected.Count <= 3 ? compareSelected.Count : compareSelected.Count <= 8 ? 2 : 3;
            if (cols < 1) cols = 1;
            int perCol = (compareSelected.Count + cols - 1) / cols;

            var grid = new GameObject("CmpCardCols");
            grid.transform.SetParent(compareCardsContent.transform, false);
            grid.AddComponent<RectTransform>();
            UIFactory.AddHLG(grid, spacing: 10, forceExpandH: false);

            var colGOs = new GameObject[cols];
            for (int c = 0; c < cols; c++)
            {
                var colGO = new GameObject($"CmpCol{c}");
                colGO.transform.SetParent(grid.transform, false);
                colGO.AddComponent<RectTransform>();
                UIFactory.AddVLG(colGO, spacing: 8);
                UIFactory.AddLE(colGO, flexW: 1);
                colGOs[c] = colGO;
            }

            for (int i = 0; i < compareSelected.Count; i++)
            {
                int col = Math.Min(i / perCol, cols - 1);
                string sid = compareSelected[i];
                Color pc = COMPARE_COLORS[i % COMPARE_COLORS.Length];
                var sb = new System.Text.StringBuilder();
                if (!compareStatsCache.TryGetValue(sid, out var ps) || ps == null)
                {
                    sb.Append($"<color=#{ColorToHex(pc)}><b>{I18n.Tr("(loading...)")}</b></color>");
                }
                else
                {
                    sb.Append($"<color=#{ColorToHex(pc)}><b>{ps.display_name}</b></color>\n");
                    if (metricName == "Worst Cards")
                        AppendCardList(sb, ps.worst_card_names, ps.worst_card_picks, ps.worst_card_win_rates, I18n.Tr("not enough data (4+ picks)"));
                    else
                        // F9: AppendCardList takes the message as a PARAMETER, so the
                        // Tr has to happen here at the call site — I18n.Tr(variable)
                        // inside the helper would harvest nothing (#295a). Matches the
                        // "not enough data (4+ picks)" branch directly above.
                        AppendCardList(sb, ps.top_card_names, ps.top_card_picks, ps.top_card_win_rates, I18n.Tr("no card data"));
                }
                var cell = UIFactory.CreateText($"CmpCell{i}", colGOs[col].transform, sb.ToString(),
                    14f, C_DIM, UIFactory.AlignTopLeft, sizeDelta: new Vector2(250, 24));
                UIFactory.SetWordWrap(cell, true);
                UIFactory.SetTextAutoHeight(cell);
            }
        }

        // Renders the currently-selected metric for all selected players into the
        // scroll panel. metricName drives the layout: card lists, per-player rows,
        // or a region breakdown. (Retained for reference; routing now uses
        // BuildCompareBarChart / BuildCompareCardGrid.)
        private static void BuildCompareMetricTable()
        {
            if (txtCompareCards == null) return;
            string metricName = COMPARE_METRICS[Math.Max(0, Math.Min(compareMetric, COMPARE_METRICS.Length - 1))];
            if (compareSelected.Count == 0)
            {
                UIFactory.SetTextRaw(txtCompareCards, $"<color=#888>{I18n.TrF("Select players (left) to compare {0}.", "<b>" + TrMetric(metricName) + "</b>")}</color>");
                return;
            }
            var sb = new System.Text.StringBuilder();
            for (int i = 0; i < compareSelected.Count; i++)
            {
                string sid = compareSelected[i];
                Color col = COMPARE_COLORS[i % COMPARE_COLORS.Length];
                if (!compareStatsCache.TryGetValue(sid, out var ps) || ps == null)
                {
                    sb.Append($"<color=#{ColorToHex(col)}><b>{I18n.Tr("(loading...)")}</b></color>\n\n");
                    continue;
                }
                sb.Append($"<color=#{ColorToHex(col)}><b>{ps.display_name}</b></color>  ");
                switch (metricName)
                {
                    case "Top Cards":
                        sb.Append("\n");
                        AppendCardList(sb, ps.top_card_names, ps.top_card_picks, ps.top_card_win_rates, "no card data");
                        break;
                    case "Worst Cards":
                        sb.Append("\n");
                        AppendCardList(sb, ps.worst_card_names, ps.worst_card_picks, ps.worst_card_win_rates,
                                       "not enough card data (need 4+ picks)");
                        break;
                    case "Hit / Block %":
                    {
                        string hit = ps.bullets_fired > 0
                            ? $"<color=#FF9988>Hit {(float)ps.bullets_hit * 100f / ps.bullets_fired:F1}%</color> <color=#888>({ps.bullets_hit}/{ps.bullets_fired})</color>"
                            : "<color=#888>Hit —</color>";
                        string blk = ps.blocks_activated > 0
                            ? $"<color=#99CCFF>Block {(float)ps.blocks_successful * 100f / ps.blocks_activated:F1}%</color> <color=#888>({ps.blocks_successful}/{ps.blocks_activated})</color>"
                            : "<color=#888>Block —</color>";
                        sb.Append($"{hit}   {blk}\n");
                        break;
                    }
                    case "Avg Cards / Game":
                    {
                        // Closer to 1 = stronger (wins faster, picks fewer cards).
                        float v = ps.avg_cards_per_game;
                        string vc = v > 0 && v <= 2.0f ? "#00FF00" : v <= 3.0f ? "#AAAAAA" : "#FF6666";
                        sb.Append(v > 0 ? $"<color={vc}>{v:F2}</color> cards/game  <color=#888>(lower = stronger)</color>\n"
                                        : "<color=#888>no data</color>\n");
                        break;
                    }
                    case "Avg FPS":
                        sb.Append(ps.avg_fps > 0 ? $"<color=#9AD0FF>{ps.avg_fps}</color> avg fps\n" : "<color=#888>no fps data</color>\n");
                        break;
                    case "Peak Elo":
                        sb.Append($"<color=#FFD94D>{ps.peak_rating:F0}</color> peak  <color=#888>(now {ps.rating:F0})</color>\n");
                        break;
                    case "Total XP":
                        sb.Append($"<color=#66CCFF>{ps.total_xp:N0}</color> XP  <color=#888>(Lv {ps.level})</color>\n");
                        break;
                    case "Achievements":
                    {
                        int total = ApiClient.AchievementDefs != null ? ApiClient.AchievementDefs.Count : 0;
                        sb.Append(total > 0
                            ? $"<color=#FFD94D>{ps.achievements_unlocked}/{total}</color> unlocked  <color=#888>({ps.achievements_unlocked * 100 / Math.Max(1, total)}%)</color>\n"
                            : $"<color=#FFD94D>{ps.achievements_unlocked}</color> unlocked\n");
                        break;
                    }
                    case "Region Time":
                        sb.Append("\n");
                        if (ps.region_names != null && ps.region_names.Count > 0)
                        {
                            int tot = 0; foreach (var m in ps.region_matches) tot += m;
                            for (int ri = 0; ri < ps.region_names.Count && ri < 8; ri++)
                            {
                                int mm = ps.region_matches.Count > ri ? ps.region_matches[ri] : 0;
                                int pct = tot > 0 ? mm * 100 / tot : 0;
                                sb.Append($"   <color=#AAD>{ps.region_names[ri].ToUpperInvariant()}</color>  {pct}% <color=#888>({mm})</color>\n");
                            }
                        }
                        else sb.Append("   <color=#888><i>no region data</i></color>\n");
                        break;
                    default:
                        sb.Append("\n");
                        break;
                }
                sb.Append("\n");
            }
            UIFactory.SetText(txtCompareCards, sb.ToString());
        }

        private static void AppendCardList(System.Text.StringBuilder sb, List<string> names,
                                           List<int> picks, List<float> wrs, string emptyMsg)
        {
            if (names != null && names.Count > 0)
            {
                for (int ci = 0; ci < names.Count && ci < 8; ci++)
                {
                    string p = picks != null && picks.Count > ci ? $" <color=#888>({picks[ci]}x)</color>" : "";
                    float wr = wrs != null && wrs.Count > ci ? wrs[ci] * 100f : 0f;
                    string wrCol = wr >= 55 ? "#00FF00" : wr <= 45 ? "#FF6666" : "#AAAAAA";
                    sb.Append($"   {names[ci]}{p}  <color={wrCol}>{wr:F0}%</color>\n");
                }
            }
            else sb.Append($"   <color=#888><i>{emptyMsg}</i></color>\n");
        }

        private static string GetAchievementText()
        {
            var ach=ApiClient.SelectedPlayerAchievements;
            if(ach==null)return "";
            int unlocked=0;
            string achText="\n"+I18n.Tr("<color=#99AAEE>Achievements:</color>")+"\n";
            foreach(var kvp in ApiClient.AchievementDefs)
            {
                bool got=ach.ContainsKey(kvp.Key)&&ach[kvp.Key].unlocked;
                if(got)unlocked++;
                string icon=got?"<color=#FFD94D>[X]</color>":"<color=#444444>[ ]</color>";
                string nameCol=got?"#FFFFFF":"#666666";
                achText+=$"  {icon} <color={nameCol}>{I18n.Tr(kvp.Value[0])}</color>\n";
            }
            achText+="\n  "+I18n.TrF("{0} / {1} unlocked",unlocked,ApiClient.AchievementDefs.Count);
            return achText;
        }

        /// <summary>Builds the clicked player's "Ranked Series vs You" section (returned) and
        /// the "Ranked History" section (out param). Split into two strings (round 3 screenshot
        /// markup) so the Older/Newer pager GameObject can sit BETWEEN them — directly under
        /// the series list it pages — instead of below the whole blob.</summary>
        private static string ModeHistoryDate(string iso)
        {
            if(string.IsNullOrEmpty(iso))return "";
            if(DateTimeOffset.TryParse(iso,System.Globalization.CultureInfo.InvariantCulture,
                System.Globalization.DateTimeStyles.AssumeUniversal,out DateTimeOffset parsed))
                return DateFmt.Short(parsed.ToLocalTime().DateTime);
            return "";
        }

        /// <summary>Bug 262 (Stan): rating deltas below ±5 show the first
        /// decimal ("+3.4"), at/above ±5 stay whole ("+12"). The server has
        /// stored 1-decimal floats since day one (all seven rating_change
        /// columns are DOUBLE PRECISION; the Discord bot already renders
        /// .1f per its own bug-18 precedent) — precision only ever died at
        /// the client's :F0 render sites, all of which now route here.
        /// Returns the SIGNED number text; callers keep their own
        /// color/markup conventions. Never wider than the old worst case
        /// ("-4.9" is 4 chars vs "-999"), so no cell can overflow (#393).</summary>
        internal static string RatingDeltaText(float rc)
        {
            string fmt = Mathf.Abs(rc) < 5f ? "+0.0;-0.0;0.0" : "+0;-0;0";
            return rc.ToString(fmt, System.Globalization.CultureInfo.InvariantCulture);
        }

        private static string ModeHistoryDelta(float value)
        {
            string color=value>0f?"#00FF00":value<0f?"#FF6666":"#AAAAAA";
            // Same conditional rule as everywhere else (was always-1-decimal;
            // unified on the bug-262 convention so surfaces agree).
            return $"<color={color}>"+RatingDeltaText(value)+"</color>";
        }

        private static string BuildPlayerModeHistoryText(string steamId)
        {
            var sb=new StringBuilder();
            if(ApiClient.CachedPlayerTeamHistory.TryGetValue(steamId,out var team)&&team!=null&&team.Count>0)
            {
                sb.Append("\n" + I18n.Tr("<color=#FFB347>2v2 History</color>") + "\n");
                foreach(var entry in team)
                {
                    string result=entry.won?"<color=#00FF00>W</color>":"<color=#FF6666>L</color>";
                    string oppA=entry.opponents!=null&&entry.opponents.Count>0
                        ?FfaSafeRich(Trunc(entry.opponents[0]??"?",12)):"?";
                    string oppB=entry.opponents!=null&&entry.opponents.Count>1
                        ?FfaSafeRich(Trunc(entry.opponents[1]??"?",12)):"?";
                    string delta=entry.has_rating_change?"  "+ModeHistoryDelta(entry.rating_change):"";
                    sb.Append("  ").Append(result).Append(' ').Append(entry.score??"?")
                      .Append(" w/ ").Append(FfaSafeRich(Trunc(entry.mate??"?",12)))
                      .Append(" vs ").Append(oppA).Append(" + ").Append(oppB)
                      .Append(delta).Append("  <color=#888>")
                      .Append(ModeHistoryDate(entry.completed_at)).Append("</color>\n");
                }
            }
            if(ApiClient.CachedPlayerOvtHistory.TryGetValue(steamId,out var ovt)&&ovt!=null&&ovt.Count>0)
            {
                sb.Append("\n" + I18n.Tr("<color=#7FD4FF>1v2 History</color>") + "\n");
                string viewedName=selectedStats?.display_name??"";
                foreach(var entry in ovt)
                {
                    string result=entry.won?"<color=#00FF00>W</color>":"<color=#FF6666>L</color>";
                    string matchup;
                    if(string.Equals(entry.role,"solo",StringComparison.OrdinalIgnoreCase))
                    {
                        string duoA=entry.duo!=null&&entry.duo.Count>0
                            ?FfaSafeRich(Trunc(entry.duo[0]??"?",12)):"?";
                        string duoB=entry.duo!=null&&entry.duo.Count>1
                            ?FfaSafeRich(Trunc(entry.duo[1]??"?",12)):"?";
                        matchup=I18n.TrF("as SOLO vs {0} + {1}",duoA,duoB);
                    }
                    else
                    {
                        string partner="?";
                        if(entry.duo!=null)
                        {
                            foreach(string duoName in entry.duo)
                            {
                                if(!string.Equals(duoName,viewedName,StringComparison.OrdinalIgnoreCase))
                                {partner=duoName??"?";break;}
                            }
                        }
                        matchup=I18n.TrF("as DUO (w/ {0}) vs {1}",FfaSafeRich(Trunc(partner,12)),
                            FfaSafeRich(Trunc(entry.solo??"?",12)));
                    }
                    // Bug #129: reward tag appended INLINE, exactly like the
                    // Ranked History rows' "+843xp +9g" — deliberately not a new
                    // line, so the 1v2 reward finally shows without growing the
                    // history block's height.
                    int oGold=entry.gold_gained+entry.series_gold_gained;
                    string oGoldTag=oGold>0?$"  <color=#FFD94D>+{oGold}g</color>":"";
                    sb.Append("  ").Append(result).Append(' ').Append(entry.score??"?")
                      .Append(' ').Append(matchup).Append(oGoldTag).Append("  <color=#888>")
                      .Append(ModeHistoryDate(entry.ended_at)).Append("</color>\n");
                }
            }
            if(ApiClient.CachedPlayerFfaHistory.TryGetValue(steamId,out var ffa)&&ffa!=null&&ffa.Count>0)
            {
                sb.Append("\n" + I18n.Tr("<color=#D8A7FF>FFA History</color>") + "\n");
                foreach(var entry in ffa)
                {
                    string result=entry.placement==1?"<color=#00FF00>":"<color=#FF6666>";
                    sb.Append("  ").Append(result).Append('#').Append(entry.placement)
                      .Append("</color> of ").Append(entry.player_count);
                    if(entry.has_rating_change)sb.Append("  ").Append(ModeHistoryDelta(entry.rating_change));
                    else sb.Append("  <color=#888>--</color>");
                    sb.Append("  ").Append(entry.kills).Append("k  <color=#888>")
                      .Append(ModeHistoryDate(entry.ended_at)).Append("</color>");

                    var participants=entry.participants;
                    if(participants!=null&&participants.Count>0)
                    {
                        // Sid: "player FFA history cuts off some people, can you have the
                        // names wrapped and tabbed to where the vs thing is?"
                        //
                        // Three separate causes of "cuts off": a 4-name cap with a
                        // "+N more" tail, a 12-char truncation, and — the invisible one —
                        // the client re-deriving which participant was the viewed player
                        // and skipping them by INDEX. The server already excludes the
                        // viewed player from this list (main.py's history query filters
                        // `p2.steam_id != :sid`), so that arithmetic was dropping a real
                        // opponent from every row. Do not re-add it.
                        //
                        // <indent> sets a persistent left margin that applies at every
                        // line start until closed, so wrapped continuation lines land
                        // under the "vs" instead of at the row's left edge. It is a
                        // percentage so it survives any change to the column width, and
                        // the closing tag is load-bearing — leaving it open would inherit
                        // the margin into every following row.
                        sb.Append("\n<indent=9%>vs ");
                        for(int p=0;p<participants.Count;p++)
                        {
                            if(p>0)sb.Append(", ");
                            sb.Append(FfaSafeRich(Trunc(participants[p]??"?",16)));
                        }
                        sb.Append("</indent>");
                    }
                    sb.Append('\n');
                }
            }
            return sb.ToString();
        }

        private static string BuildViewHistoryText(out string historyPart)
        {
            historyPart = "";
            if (string.IsNullOrEmpty(selectedSteamId)) return "";
            var hist = selectedViewHistory;
            if (hist == null) return "\n" + I18n.Tr("<color=#888><i>Loading match history...</i></color>") + "\n";
            var sb = new System.Text.StringBuilder();
            string myId = MatchTracker.LocalSteamId;
            bool viewingSelf = selectedSteamId == myId;
            string theirName = Trunc(selectedStats?.display_name ?? "Them", 12);

            // ── Ranked Series vs You (only when viewing someone else) ──
            // Shows ALL head-to-head ranked series, paginated (H2H_SERIES_PER_PAGE per
            // page) via the h2hPager controls. History is newest-first, so GroupBySeries
            // yields groups newest→oldest; page 0 is the most recent series.
            int h2hGroupCount = 0;
            if (!viewingSelf && !string.IsNullOrEmpty(myId) && myId != "unknown")
            {
                var vsMe = hist.FindAll(m => m.opponent_steam_id == myId
                    && !string.IsNullOrEmpty(m.series_id) && m.series_id != "null" && m.is_ranked);
                if (vsMe.Count > 0)
                {
                    var grp = GroupBySeries(vsMe);
                    grp.RemoveAll(g => g.matches == null || g.matches.Count == 0);
                    h2hGroupCount = grp.Count;
                    if (h2hGroupCount > 0)
                    {
                        int totalPages = (h2hGroupCount + H2H_SERIES_PER_PAGE - 1) / H2H_SERIES_PER_PAGE;
                        h2hSeriesTotalPages = totalPages;
                        if (h2hSeriesPage < 0) h2hSeriesPage = 0;
                        if (h2hSeriesPage > totalPages - 1) h2hSeriesPage = totalPages - 1;
                        int start = h2hSeriesPage * H2H_SERIES_PER_PAGE;
                        int end = Math.Min(start + H2H_SERIES_PER_PAGE, h2hGroupCount);
                        string pageTag = totalPages > 1 ? I18n.TrF("  <color=#888>(page {0}/{1}, {2} total)</color>", h2hSeriesPage + 1, totalPages, h2hGroupCount) : "";
                        sb.Append("\n" + I18n.Tr("<color=#FFD94D>Ranked Series vs You</color>") + pageTag + "\n");
                        for (int gi = start; gi < end; gi++)
                        {
                            var g = grp[gi];
                            var first = g.matches[0];
                            string score = first.series_score ?? "?-?";
                            string hdt = ""; try { if (!string.IsNullOrEmpty(first.ended_at) && first.ended_at.Length >= 10) hdt = DateFmt.FullShortYear(DateTime.Parse(first.ended_at)); } catch {}
                            // series_score is their side; flip for "your" series result.
                            bool sComplete = false, sIWon = false;
                            try { var p = score.Split('-'); int tw = int.Parse(p[0]), mw = int.Parse(p[1]); sComplete = tw >= 2 || mw >= 2; sIWon = mw > tw; } catch {}
                            string sHdr = sComplete ? (sIWon ? I18n.Tr("<color=#00FF00>WON</color>") : I18n.Tr("<color=#FF6666>LOST</color>")) : I18n.Tr("<color=#FFD94D>in progress</color>");
                            sb.Append(I18n.TrF("  {0}  <color=#888>{1} their side</color>  <color=#666>{2}</color>", sHdr, score, hdt) + "\n");
                            foreach (var m in g.matches)
                            {
                                // m.* is the VIEWED player's perspective; flip for "my" result.
                                bool iWon = !m.won;
                                string r = iWon ? "<color=#00FF00>W</color>" : "<color=#FF6666>L</color>";
                                string dt = ""; try { if (!string.IsNullOrEmpty(m.ended_at) && m.ended_at.Length >= 10) dt = DateFmt.Short(DateTime.Parse(m.ended_at)); } catch {}
                                // opponent_rounds_won is MY rounds (I'm their opponent); player_rounds_won is theirs.
                                sb.Append($"    {r}  {m.opponent_rounds_won}-{m.player_rounds_won}  <color=#888>{dt}</color>\n");
                                if (!string.IsNullOrEmpty(m.opp_cards_display))
                                    sb.Append($"      {I18n.Tr("<color=#6677AA>You:</color>")} {FormatCardLine(m.opp_cards_display)}\n");
                                if (!string.IsNullOrEmpty(m.cards_display))
                                    sb.Append($"      <color=#AA7766>{theirName}:</color> {FormatCardLine(m.cards_display)}\n");
                            }
                        }
                    }
                }
            }
            // Drive the pager visibility/labels off this render (it lives outside the
            // scrolled text so its buttons stay clickable).
            if (h2hPager != null)
            {
                bool showPager = h2hGroupCount > H2H_SERIES_PER_PAGE;
                h2hPager.SetActive(showPager);
                if (showPager)
                {
                    if (txtH2hPage != null) UIFactory.SetText(txtH2hPage, $"{h2hSeriesPage + 1}/{h2hSeriesTotalPages}");
                    if (h2hPrev != null) h2hPrev.SetActive(h2hSeriesPage > 0);
                    if (h2hNext != null) h2hNext.SetActive(h2hSeriesPage < h2hSeriesTotalPages - 1);
                }
            }

            // ── Ranked History (their recent completed ranked series) ──
            // Composed into its OWN string so it renders in txtLBDetailB, below
            // the pager (round 3 screenshot markup).
            var hb = new System.Text.StringBuilder();
            var ranked = hist.FindAll(m => m.is_ranked && !string.IsNullOrEmpty(m.series_id) && m.series_id != "null");
            if (ranked.Count > 0)
            {
                var grp = GroupBySeries(ranked);
                hb.Append("\n" + I18n.Tr("<color=#99AAEE>Ranked History</color>  <color=#888>(recent series)</color>") + "\n");
                int shown = 0;
                foreach (var g in grp)
                {
                    if (shown >= 12) break;
                    if (g.matches == null || g.matches.Count == 0) continue;
                    var first = g.matches[0];
                    string score = first.series_score ?? "?-?";
                    bool complete = false, won = false;
                    try { var p = score.Split('-'); int mw = int.Parse(p[0]), tw = int.Parse(p[1]); complete = mw >= 2 || tw >= 2; won = mw > tw; } catch {}
                    string oppName = Trunc(first.opponent_name ?? "?", 14);
                    string dt = ""; try { if (!string.IsNullOrEmpty(first.ended_at) && first.ended_at.Length >= 10) dt = DateFmt.Short(DateTime.Parse(first.ended_at)); } catch {}
                    string res = complete ? (won ? "<color=#00FF00>W</color>" : "<color=#FF6666>L</color>") : "<color=#FFD94D>-</color>";
                    string elo = (complete && first.series_rating_change != 0f)
                        ? $" <color={(first.series_rating_change > 0 ? "#00FF00" : "#FF6666")}>{RatingDeltaText(first.series_rating_change)}</color>"
                        : "";
                    hb.Append($"  {res} {score} vs {oppName}{elo}  <color=#888>{dt}</color>\n");
                    shown++;
                }
            }
            else
            {
                hb.Append("\n" + I18n.Tr("<color=#99AAEE>Ranked History:</color> <color=#888><i>no ranked series yet</i></color>") + "\n");
            }

            hb.Append(BuildPlayerModeHistoryText(selectedSteamId));
            historyPart = hb.ToString();
            return sb.ToString();
        }

        private static void RefreshCardStats(){/* Item 1 fix family: pre-translated base + arrow, written Raw. */string[]hL={I18n.Tr("Tier"),I18n.Tr("Card"),I18n.Tr("Rarity"),I18n.Tr("Picks"),I18n.Tr("Wins"),I18n.Tr("WR%"),I18n.Tr("Pass%")};string[]hK={"tier","card_name","card_rarity","times_picked","wins_with_card","win_rate","pass_rate"};if(cardSortTexts!=null)for(int i=0;i<7&&i<cardSortTexts.Length;i++){if(cardSortTexts[i]==null)continue;string arrow=cardSort==hK[i]?(cardSortDesc?" v":" ^"):"";UIFactory.SetTextRaw(cardSortTexts[i],hL[i]+arrow);UIFactory.SetColor(cardSortTexts[i],cardSort==hK[i]?C_WHITE:C_LABEL);if(cardSortBtns!=null&&i<cardSortBtns.Length)UIFactory.SetImageColor(cardSortBtns[i],cardSort==hK[i]?C_TABACT:C_TAB);}var cards=ApiClient.CachedCardStats;foreach(var r in cardRows)r.root.SetActive(false);
        // Self-heal (#32): refetch when the open-time fetch never landed —
        // stats null, or the tier set for the current filter never completed.
        if(cards==null&&Time.realtimeSinceStartup-_cardStatsAutoFetchAt>8f){_cardStatsAutoFetchAt=Time.realtimeSinceStartup;ApiClient.FetchCardStats(200,MatchTracker.LocalSteamId);}
        if(!_tierFiltersLoaded.Contains(cardFilter)&&Time.realtimeSinceStartup-_tierAutoFetchAt>8f){_tierAutoFetchAt=Time.realtimeSinceStartup;LoadCardTiersForCurrentFilter();}
        if(cards==null||cards.Count==0)return;var merged=new List<ApiClient.CardStatData>();var seen=new Dictionary<string,int>(StringComparer.OrdinalIgnoreCase);foreach(var c in cards){string key=(c.card_name??"?").ToLower().Replace(" ","");if(seen.ContainsKey(key)){var e=merged[seen[key]];e.times_picked+=c.times_picked;e.wins_with_card+=c.wins_with_card;e.win_rate=e.times_picked>0?(float)e.wins_with_card/e.times_picked:0;e.times_offered=Math.Max(e.times_offered,c.times_offered);if(c.times_offered>0)e.pass_rate=c.pass_rate;if((e.card_rarity==null||e.card_rarity=="Unknown")&&c.card_rarity!=null&&c.card_rarity!="Unknown")e.card_rarity=c.card_rarity;}else{seen[key]=merged.Count;merged.Add(new ApiClient.CardStatData{card_name=c.card_name,card_rarity=c.card_rarity,times_picked=c.times_picked,wins_with_card=c.wins_with_card,win_rate=c.win_rate,times_offered=c.times_offered,pass_rate=c.pass_rate});}}
        // Tier sort: map S/A/B/C/D/E/F to 0..6, unset to 99 so they sort to the
        // bottom regardless of direction. Comparator pulls each card's tier
        // from cardTierMap keyed by the active filter.
        int TierRank(string tier){if(string.IsNullOrEmpty(tier))return 99;switch(tier){case "S":return 0;case "A":return 1;case "B":return 2;case "C":return 3;case "D":return 4;case "E":return 5;case "F":return 6;}return 99;}
        switch(cardSort){case "tier":merged.Sort((a,b)=>{int ar=TierRank(cardTierMap.TryGetValue(CardTierKey(cardFilter,a.card_name),out var av)?av:"");int br=TierRank(cardTierMap.TryGetValue(CardTierKey(cardFilter,b.card_name),out var bv)?bv:"");return cardSortDesc?ar.CompareTo(br):br.CompareTo(ar);});break;case "card_name":merged.Sort((a,b)=>cardSortDesc?string.Compare(b.card_name,a.card_name,StringComparison.OrdinalIgnoreCase):string.Compare(a.card_name,b.card_name,StringComparison.OrdinalIgnoreCase));break;case "card_rarity":merged.Sort((a,b)=>cardSortDesc?string.Compare(b.card_rarity,a.card_rarity,StringComparison.OrdinalIgnoreCase):string.Compare(a.card_rarity,b.card_rarity,StringComparison.OrdinalIgnoreCase));break;case "times_picked":merged.Sort((a,b)=>cardSortDesc?b.times_picked.CompareTo(a.times_picked):a.times_picked.CompareTo(b.times_picked));break;case "wins_with_card":merged.Sort((a,b)=>cardSortDesc?b.wins_with_card.CompareTo(a.wins_with_card):a.wins_with_card.CompareTo(b.wins_with_card));break;case "win_rate":merged.Sort((a,b)=>cardSortDesc?b.win_rate.CompareTo(a.win_rate):a.win_rate.CompareTo(b.win_rate));break;case "pass_rate":merged.Sort((a,b)=>cardSortDesc?b.pass_rate.CompareTo(a.pass_rate):a.pass_rate.CompareTo(b.pass_rate));break;default:merged.Sort((a,b)=>cardSortDesc?b.times_picked.CompareTo(a.times_picked):a.times_picked.CompareTo(b.times_picked));break;}for(int i=0;i<merged.Count&&i<cardRows.Count;i++){var c=merged[i];var row=cardRows[i];float wr=c.win_rate*100;Color wrColor=wr>=55?C_GREEN:wr<=45?C_RED:C_WHITE;row.cardName=c.card_name;/* Item B: DISPLAY-only localized card name (game's own string table);
        row.cardName stays the English identity for sort/click/tier keys. Raw write —
        card names must never pass the translation catalogue. */UIFactory.SetTextRaw(row.txtName,CardTextLocalizer.PrettyName(c.card_name,c.card_name)??"?");string rarity=c.card_rarity??"Unknown";/* Rarity VALUE display map: finite server set, each literal inline in a Tr call so
        the extractor harvests it (Tr(variable) harvests nothing — learning #295a); the switch
        keeps unknown future values passing through Tr-by-value. Color keys off the ENGLISH value. */string rarityDisp;switch(rarity){case "Common":rarityDisp=I18n.Tr("Common");break;case "Uncommon":rarityDisp=I18n.Tr("Uncommon");break;case "Rare":rarityDisp=I18n.Tr("Rare");break;case "Unknown":rarityDisp=I18n.Tr("Unknown");break;default:rarityDisp=I18n.Tr(rarity);break;}UIFactory.SetTextRaw(row.txtRarity,rarityDisp);UIFactory.SetColor(row.txtRarity,GetRarityColor(rarity));UIFactory.SetText(row.txtPicks,$"{c.times_picked}");UIFactory.SetText(row.txtWins,$"{c.wins_with_card}");UIFactory.SetText(row.txtWR,$"{wr:F0}%");UIFactory.SetColor(row.txtWR,wrColor);if(c.times_offered>0){float pr=c.pass_rate*100;UIFactory.SetText(row.txtPass,$"{pr:F0}%");UIFactory.SetColor(row.txtPass,pr>=70?C_RED:pr<=30?C_GREEN:C_LABEL);}else{UIFactory.SetText(row.txtPass,"-");UIFactory.SetColor(row.txtPass,C_DIM);}
                // Tier badge — letter + color tied to the player's saved tier
                // for this (card, current filter).
                string key=CardTierKey(cardFilter,c.card_name);
                string tierLetter=cardTierMap.TryGetValue(key,out var tv)?tv:"";
                ApplyRowTierVisuals(row, tierLetter);
                row.root.SetActive(true);}}

        // Update one row's tier display in place (no full re-render). Used both
        // by RefreshCardStats's per-row loop and by the click handler so a
        // tier-cycle doesn't trigger a re-sort that shifts cards under the
        // user's mouse cursor.
        private static void ApplyRowTierVisuals(CardRow row, string tierLetter)
        {
            if (string.IsNullOrEmpty(tierLetter))
            {
                UIFactory.SetText(row.txtTier, "<b>-</b>");
                UIFactory.SetImageColor(row.tierBtn, new Color(0.18f, 0.20f, 0.24f, 0.85f));
                UIFactory.SetImageColor(row.hl, new Color(0, 0, 0, 0));
            }
            else
            {
                // Rich-text bold so the letter renders bold on SDF atlases that
                // silently no-op the fontStyle=Bold flag (lesson 14).
                UIFactory.SetText(row.txtTier, $"<b>{tierLetter}</b>");
                Color tc = GetTierColor(tierLetter);
                UIFactory.SetImageColor(row.tierBtn, tc);
                // Translucent tier tint — same hue, ~25% alpha so text stays
                // readable. Bounded to row.hl (Tier→Pass% column wrapper).
                UIFactory.SetImageColor(row.hl, new Color(tc.r, tc.g, tc.b, 0.25f));
            }
        }

        // Click-time tier cycle. Updates state + writes to server + repaints
        // ONLY this single row's visuals — no full re-render and no re-sort,
        // so the row stays put under the user's cursor for follow-up clicks.
        private static void CycleCardTierInPlace(CardRow row, string cardName)
        {
            if (string.IsNullOrEmpty(cardName)) return;
            string filterStr = cardFilter == 1 ? "ranked" : cardFilter == 2 ? "casual" : "all";
            string key = CardTierKey(cardFilter, cardName);
            string current = cardTierMap.TryGetValue(key, out var c) ? c : "";
            int idx = Array.IndexOf(TIER_CYCLE, current);
            if (idx < 0) idx = 0;
            string next = TIER_CYCLE[(idx + 1) % TIER_CYCLE.Length];
            cardTierMap[key] = next;
            ApiClient.SetCardTier(MatchTracker.LocalSteamId, cardName, filterStr, next);
            ApplyRowTierVisuals(row, next);
            // No `dirty = true` — re-sort would shift cards mid-click and the
            // user would end up cycling a different card on their next tap.
        }
        // Tier badge background colors. S = pop red, A = orange, ... F = grey.
        private static Color GetTierColor(string t){switch(t){case "S":return new Color(0.95f,0.30f,0.30f,0.90f);case "A":return new Color(1.00f,0.55f,0.22f,0.90f);case "B":return new Color(0.95f,0.85f,0.30f,0.90f);case "C":return new Color(0.45f,0.85f,0.45f,0.90f);case "D":return new Color(0.45f,0.70f,0.95f,0.90f);case "E":return new Color(0.65f,0.55f,0.95f,0.90f);case "F":return new Color(0.55f,0.55f,0.55f,0.90f);default:return new Color(0.18f,0.20f,0.24f,0.85f);}}

        // Compact stat line for one cell on the tier-list image. Pulls the
        // first 2 CardInfoStats off the matching CardInfo. Layered lookup
        // mirrors the popup: try CardChoice.instance.cards first (always-loaded
        // global registry), then Resources.FindObjectsOfTypeAll. Match against
        // canonical name + GO name + cardName field.
        private static string BuildCellStatLine(string cardName)
        {
            try
            {
                if (string.IsNullOrEmpty(cardName)) return "";
                string canonical = CardRarityLookup.GetCanonicalName(cardName) ?? cardName;
                /* Bug #155: match the RAW in-game spellings too. The canonical
                 * name corrects ROUNDS' own typos (Leach/Riccochet/"Poison
                 * bullets"), so for those cards neither cardName nor canonical
                 * matches any live CardInfo and the cell silently fell through
                 * to the hardcoded dict — the same root cause as the native
                 * snapshot's "no CardInfo prefab matches". */
                var keys = new List<string>();
                void AddKey(string s)
                {
                    if (string.IsNullOrEmpty(s)) return;
                    string k = s.ToLowerInvariant().Replace(" ", "");
                    if (!keys.Contains(k)) keys.Add(k);
                }
                AddKey(cardName); AddKey(canonical);
                try { foreach (var raw in CardRarityLookup.RawNamesFor(canonical)) AddKey(raw); } catch { }
                Component found = null;
                Component MatchOne(IEnumerable arr)
                {
                    if (arr == null) return null;
                    foreach (var c in arr)
                    {
                        var comp = c as Component;
                        if (comp == null) continue;
                        string goName = comp.gameObject.name?.Replace("(Clone)", "").Trim() ?? "";
                        string display = comp.GetType().GetField("cardName", BindingFlags.Public | BindingFlags.Instance)?.GetValue(comp) as string ?? "";
                        if (keys.Contains(goName.ToLowerInvariant().Replace(" ", ""))
                            || keys.Contains(display.ToLowerInvariant().Replace(" ", "")))
                            return comp;
                    }
                    return null;
                }
                // Path 1: CardChoice.instance.cards (always loaded)
                var ccType = AppDomain.CurrentDomain.GetAssemblies()
                    .Select(a => a.GetType("CardChoice")).FirstOrDefault(t => t != null);
                if (ccType != null)
                {
                    object cc = ccType.GetField("instance", BindingFlags.Public | BindingFlags.Static)?.GetValue(null);
                    var cardsArr = ccType.GetField("cards", BindingFlags.Public | BindingFlags.Instance)?.GetValue(cc) as Array;
                    found = MatchOne(cardsArr);
                }
                // Path 2: Resources fallback
                if (found == null) found = MatchOne(Resources.FindObjectsOfTypeAll<CardInfo>());
                // Path 3: hardcoded stats dict fallback (cards where Resources
                // didn't have the prefab loaded — Rico/Leech/etc).
                if (found == null) return BuildStatBlockFromFallback(cardName, 8);
                var sField = found.GetType().GetField("cardStats", BindingFlags.Public | BindingFlags.Instance)
                          ?? found.GetType().GetField("stats", BindingFlags.Public | BindingFlags.Instance);
                var arr = sField?.GetValue(found) as Array;
                // CardInfo found but its stats array is null/empty — fall back
                // to the hardcoded dict (some cards' stats are populated at
                // runtime by their effect components, not on CardInfo itself).
                if (arr == null || arr.Length == 0) return BuildStatBlockFromFallback(cardName, 8);
                // Snip — apply normalization to the live-stat path below.
                var sb = new StringBuilder();
                int shown = 0;
                // Show every non-empty stat — taller cell has room. Earlier
                // 2-stat cap left out the most informative parts of cards
                // like Spray (4 stats) and Demonic Pact (3 stats).
                for (int i = 0; i < arr.Length && shown < 8; i++)
                {
                    var s = arr.GetValue(i);
                    if (s == null) continue;
                    var st = s.GetType();
                    string stat = (st.GetField("stat", BindingFlags.Public | BindingFlags.Instance)?.GetValue(s) as string ?? "").Trim();
                    string amount = (st.GetField("amount", BindingFlags.Public | BindingFlags.Instance)?.GetValue(s) as string ?? "").Trim();
                    var posObj = st.GetField("positive", BindingFlags.Public | BindingFlags.Instance)?.GetValue(s);
                    bool positive = posObj is bool pb ? pb : true;
                    if (string.IsNullOrEmpty(stat) && string.IsNullOrEmpty(amount)) continue;
                    string col = positive ? "#88FF88" : "#FF8888";
                    if (sb.Length > 0) sb.Append("\n");
                    // Normalize the stat label so DMG/DAMAGE/etc all render
                    // consistently across cards.
                    string statNorm = NormalizeStatLabel(stat);
                    string statShort = statNorm.Length > 16 ? statNorm.Substring(0, 14) + "…" : statNorm;
                    sb.Append("<color=").Append(col).Append(">").Append(amount).Append("</color> ").Append(statShort);
                    shown++;
                }
                return sb.ToString();
            }
            catch { return ""; }
        }

        // ── Export tier list as fullscreen PNG ────────────────────
        // Builds a temporary fullscreen overlay with every card grouped by
        // tier, captures via ScreenCapture.CaptureScreenshot, surfaces the
        // saved path. Mirrors the "tierlist maker" community tool but with
        // our own per-card stats baked in.
        private static GameObject tierExportPanel;
        // Review r2 find 2: the capture wait made the export take up to ~45s,
        // so a second click mid-run destroyed the first coroutine's shared
        // panel out from under it (the resumed iterator then dereferenced
        // destroyed layout objects OUTSIDE the synchronous StartCoroutine
        // catch). In-flight latch with a realtime TTL — a coroutine killed by
        // its host dying can never wedge the latch for more than one export's
        // worth of time (#255/#270c: a suppression keyed on "a coroutine will
        // clear this" needs an expiry).
        private static float _tierExportInFlightUntil = -1f;
        // Review r3: the TTL alone cannot own cleanup — realtime keeps running
        // while a backgrounded game suspends frames, so a queued click can
        // start run 2 while run 1 is merely SUSPENDED; run 1's resume then
        // destroyed run 2's panel through the shared static and cleared run
        // 2's latch. Per-run ownership token (#299's pump-id rule): each run
        // captures its id, bails at every resume if superseded, cleans ONLY
        // its own objects, and touches shared state only while newest.
        private static int _tierExportRun;
        public static void ExportCardTierList()
        {
            if (Plugin.Instance == null) return;
            if (Time.realtimeSinceStartup < _tierExportInFlightUntil)
            {
                CompetitiveUI.ShowNotification(I18n.Tr("Export already in progress..."),
                    Color.yellow, 3f);
                return;
            }
            _tierExportInFlightUntil = Time.realtimeSinceStartup + 65f;
            _tierExportRun++;
            try { Plugin.Instance.StartCoroutine(ExportTierListCoroutine()); }
            catch (Exception ex)
            {
                _tierExportInFlightUntil = -1f;
                Plugin.Log.LogWarning($"[TIER-EXPORT] failed: {ex.Message}");
            }
        }

        private static System.Collections.IEnumerator ExportTierListCoroutine()
        {
            // Portrait export via offscreen World-Space canvas + Camera +
            // RenderTexture. Earlier versions used ScreenCapture which is
            // locked to the player's monitor aspect (always landscape on a
            // 1920x1080 screen). RenderTexture lets us pick any output size,
            // so we render a tall portrait PNG (1280×N) regardless of the
            // host screen.
            int myRun = _tierExportRun;
            if (tierExportPanel != null) UnityEngine.Object.Destroy(tierExportPanel);
            tierExportPanel = new GameObject("CR_TierExport");
            var myPanel = tierExportPanel;   // this run's own cleanup handle
            tierExportPanel.hideFlags = HideFlags.HideAndDontSave;
            // Park the offscreen canvas FAR from any in-game camera's frustum
            // so it can't accidentally render in the live view.
            tierExportPanel.transform.position = new Vector3(50000f, 50000f, 0f);

            // Reusable bg holder — a World-Space canvas, root of the export.
            var canvasComp = tierExportPanel.AddComponent(UIFactory.tCanvas);
            try
            {
                var rmProp = UIFactory.tCanvas.GetProperty("renderMode", BindingFlags.Public | BindingFlags.Instance);
                if (rmProp != null) rmProp.SetValue(canvasComp, Enum.ToObject(rmProp.PropertyType, 2)); // 2 = WorldSpace
                var sortProp = UIFactory.tCanvas.GetProperty("sortingOrder", BindingFlags.Public | BindingFlags.Instance);
                if (sortProp != null) sortProp.SetValue(canvasComp, 30000);
            }
            catch { }
            // GraphicRaycaster optional for rendering-only canvas — skip.

            var rootRT = tierExportPanel.GetComponent<RectTransform>();
            if (rootRT == null) rootRT = tierExportPanel.AddComponent<RectTransform>();
            // 3000 wide × 12 cells per row. Smaller cells (220×330
            // card art + 2 text rows) compress the vertical height so
            // the final image lands close to square aspect rather than
            // tall portrait.
            rootRT.sizeDelta = new Vector2(3000, 6000);  // height shrinks after layout
            rootRT.localScale = Vector3.one;

            var bg = UIFactory.CreatePanel("BG", tierExportPanel.transform, new Color(0.07f, 0.08f, 0.10f, 1f));
            var bgRT = bg.GetComponent<RectTransform>();
            bgRT.anchorMin = Vector2.zero; bgRT.anchorMax = Vector2.one;
            bgRT.offsetMin = Vector2.zero; bgRT.offsetMax = Vector2.zero;
            UIFactory.AddVLG(bg, spacing: 14, padL: 24, padR: 24, padT: 18, padB: 18);
            // ContentSizeFitter on the bg so the bg's preferredHeight tracks
            // the children's stacked heights — used to size the RenderTexture.
            try
            {
                Type csfType = null;
                foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
                {
                    csfType = asm.GetType("UnityEngine.UI.ContentSizeFitter");
                    if (csfType != null) break;
                }
                if (csfType != null)
                {
                    var csf = bg.AddComponent(csfType);
                    var ft = csfType.GetProperty("verticalFit", BindingFlags.Public | BindingFlags.Instance);
                    if (ft != null) ft.SetValue(csf, Enum.ToObject(ft.PropertyType, 2)); // PreferredSize
                }
            }
            catch { }

            // Title — sized for the 1600px-wide canvas, big enough to
            // read on phone display after ~0.67x scaling.
            string filterStr = cardFilter == 1 ? "Ranked" : cardFilter == 2 ? "Casual" : "All";
            UIFactory.CreateText("TXTitle", bg.transform,
                $"<b>Sid's Competitive Rounds  ·  Card Tier List</b>  <color=#888>({filterStr})</color>",
                36f, C_WHITE, UIFactory.AlignMidLeft, sizeDelta: new Vector2(2900, 52));

            // Group cards by tier.
            var cards = ApiClient.CachedCardStats ?? new List<ApiClient.CardStatData>();
            // Merge duplicates same as RefreshCardStats.
            var merged = new List<ApiClient.CardStatData>();
            var seen = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            foreach (var c in cards)
            {
                string key = (c.card_name ?? "?").ToLower().Replace(" ", "");
                if (seen.ContainsKey(key))
                {
                    var e = merged[seen[key]];
                    e.times_picked += c.times_picked; e.wins_with_card += c.wins_with_card;
                    e.win_rate = e.times_picked > 0 ? (float)e.wins_with_card / e.times_picked : 0;
                    if ((e.card_rarity == null || e.card_rarity == "Unknown") && !string.IsNullOrEmpty(c.card_rarity) && c.card_rarity != "Unknown") e.card_rarity = c.card_rarity;
                }
                else { seen[key] = merged.Count; merged.Add(new ApiClient.CardStatData { card_name = c.card_name, card_rarity = c.card_rarity, times_picked = c.times_picked, wins_with_card = c.wins_with_card, win_rate = c.win_rate, times_offered = c.times_offered, pass_rate = c.pass_rate }); }
            }
            string[] tierOrder = new[] { "S", "A", "B", "C", "D", "E", "F", "" };
            var byTier = new Dictionary<string, List<ApiClient.CardStatData>>();
            foreach (var t in tierOrder) byTier[t] = new List<ApiClient.CardStatData>();
            foreach (var c in merged)
            {
                string t = cardTierMap.TryGetValue(CardTierKey(cardFilter, c.card_name), out var tv) ? tv : "";
                if (!byTier.ContainsKey(t)) t = "";
                byTier[t].Add(c);
            }

            // Review r1 find 6 (card-image removal): with no packaged PNGs, a
            // CLEAN install's first export used to save before a single
            // native capture finished (~10 frames + 0.55s each, sequential) —
            // an all-placeholder image, and later captures cannot update a
            // saved PNG. Pre-request every card and WAIT for each to resolve
            // (cached or failed), with visible progress and a hard cap.
            // Subsequent exports are instant (snapshot cache); PNG-fallback
            // rigs (native disabled or unhealthy) skip the wait entirely.
            if (CardSnapshot.UseNativeSnapshots && CardSnapshot.SnapshotsHealthy)
            {
                var wanted = new List<string>();
                // Review r2 find 3a: a card name that NORMALIZES empty can
                // never be captured (RequestSnapshot declines it without
                // marking it failed) — including it in the wait list spins
                // the full cap for nothing.
                foreach (var c in merged)
                {
                    try
                    {
                        if (string.IsNullOrEmpty(CardImageLoader.NormalizeKey(c.card_name))) continue;
                        Sprite s0;
                        if (!CardSnapshot.TryGetSprite(c.card_name, out s0) || s0 == null)
                        {
                            CardSnapshot.RequestSnapshot(c.card_name, false);
                            wanted.Add(c.card_name);
                        }
                    }
                    catch { }
                }
                if (wanted.Count > 0)
                {
                    // Review r2 find 3b: a locale switch mid-wait invalidates
                    // the queue and cache (Generation bump) — every wanted
                    // entry then reads as pending forever. Abort the wait on
                    // a generation change and build with whatever exists;
                    // the next export re-captures in the new locale.
                    int genAtWaitStart = CardSnapshot.Generation;
                    // ~60 cards x 0.55s sequential + slack. A card the queue
                    // declines (RequestsBlocked) or that fails its retries
                    // counts as resolved — the cap only guards a genuinely
                    // unresolvable tail, and the export then renders whatever
                    // landed plus placeholders (the pre-fix behaviour).
                    float capUntil = Time.realtimeSinceStartup + 45f;
                    int lastShown = -1;
                    while (Time.realtimeSinceStartup < capUntil)
                    {
                        if (CardSnapshot.Generation != genAtWaitStart) break;
                        int pending = 0;
                        try
                        {
                            for (int i = 0; i < wanted.Count; i++)
                            {
                                Sprite s1;
                                if (CardSnapshot.TryGetSprite(wanted[i], out s1) && s1 != null) continue;
                                if (CardSnapshot.IsFailed(wanted[i])) continue;
                                if (!CardSnapshot.SnapshotsHealthy || CardSnapshot.RequestsBlocked) continue;
                                pending++;
                            }
                        }
                        catch { pending = 0; }
                        if (pending == 0) break;
                        int done = wanted.Count - pending;
                        if (done != lastShown)
                        {
                            lastShown = done;
                            CompetitiveUI.ShowNotification(
                                I18n.TrF("Rendering card art {0}/{1}...", done, wanted.Count),
                                new Color(0.7f, 0.85f, 1f), 2.5f);
                        }
                        yield return new WaitForSecondsRealtime(0.5f);
                        if (myRun != _tierExportRun)
                        {
                            // Superseded while suspended (r3): clean only this
                            // run's panel; latch/static belong to the new run.
                            try { if (myPanel != null) UnityEngine.Object.Destroy(myPanel); } catch { }
                            yield break;
                        }
                    }
                }
            }

            // Layout — 3000 wide × 12 cells per row. Smaller cells
            // shrink the row count so the final image lands close to
            // square instead of tall portrait. Each cell is 220×330
            // card art + ## played + ##% won.
            const int CANVAS_W = 3000;
            const int BADGE_W = 130;
            const int CELL_W = 226;
            const int CELL_H = 410;       // 330 image + 30 + 30 + 8 spacing + 12 pad
            const int IMG_W = 220, IMG_H = 330;
            const int CELL_GAP = 8;
            int cardsAreaW = CANVAS_W - 48 - BADGE_W - 14;
            int cellsPerRow = Math.Max(3, cardsAreaW / (CELL_W + CELL_GAP)); // = 6

            // Reflected setters for UnityEngine.UI.Image — used to bind
            // the loaded card Sprite to a fresh Image component on each
            // cell.
            var pImgSprite = UIFactory.tImage.GetProperty("sprite", BindingFlags.Public | BindingFlags.Instance);
            var pImgPreserve = UIFactory.tImage.GetProperty("preserveAspect", BindingFlags.Public | BindingFlags.Instance);
            var pImgColor = UIFactory.tImage.GetProperty("color", BindingFlags.Public | BindingFlags.Instance);

            foreach (var tier in tierOrder)
            {
                var list = byTier[tier];
                if (list.Count == 0) continue;
                Color tc = string.IsNullOrEmpty(tier) ? new Color(0.30f, 0.32f, 0.36f, 0.95f) : GetTierColor(tier);
                int rowsNeeded = (list.Count + cellsPerRow - 1) / cellsPerRow;
                int tierBlockH = rowsNeeded * (CELL_H + 6) + 12;

                // Tier row container — badge on the left, wrapping cards on the right.
                var tierGO = new GameObject($"T_{tier}");
                tierGO.transform.SetParent(bg.transform, false);
                tierGO.AddComponent<RectTransform>();
                UIFactory.AddHLG(tierGO, spacing: 8, padL: 8, padR: 8, padT: 6, padB: 6);
                UIFactory.AddLE(tierGO, prefH: tierBlockH, minH: tierBlockH, flexH: 0);

                // Tier badge.
                var badge = UIFactory.CreatePanel($"B_{tier}", tierGO.transform, tc);
                UIFactory.AddLE(badge, prefW: BADGE_W, minW: BADGE_W, prefH: tierBlockH - 12, minH: tierBlockH - 12, flexW: 0);
                UIFactory.CreateText("BL", badge.transform, $"<b>{(string.IsNullOrEmpty(tier) ? "Unranked" : tier)}</b>",
                    string.IsNullOrEmpty(tier) ? 36f : 84f, Color.black,
                    UIFactory.AlignMidCenter, sizeDelta: new Vector2(BADGE_W, tierBlockH - 12));

                // Cards container.
                var cardsCol = new GameObject($"R_{tier}");
                cardsCol.transform.SetParent(tierGO.transform, false);
                cardsCol.AddComponent<RectTransform>();
                UIFactory.AddVLG(cardsCol, spacing: 6, padL: 4, padR: 4, padT: 0, padB: 0);
                UIFactory.AddLE(cardsCol, flexW: 1, prefH: tierBlockH - 12, minH: tierBlockH - 12, flexH: 0);

                GameObject curRow = null;
                int curIdx = 0;
                foreach (var c in list)
                {
                    if (curRow == null || curIdx >= cellsPerRow)
                    {
                        curRow = new GameObject($"row{list.IndexOf(c)}");
                        curRow.transform.SetParent(cardsCol.transform, false);
                        curRow.AddComponent<RectTransform>();
                        UIFactory.AddHLG(curRow, spacing: CELL_GAP);
                        UIFactory.AddLE(curRow, prefH: CELL_H, minH: CELL_H, flexH: 0);
                        curIdx = 0;
                    }
                    var cell = UIFactory.CreatePanel($"C_{c.card_name}", curRow.transform,
                        new Color(tc.r, tc.g, tc.b, 0.22f));
                    UIFactory.AddVLG(cell, spacing: 4, padL: 4, padR: 4, padT: 6, padB: 6);
                    UIFactory.AddLE(cell, prefW: CELL_W, minW: CELL_W, prefH: CELL_H, minH: CELL_H, flexW: 0);

                    // Card art — fills most of the cell. preserveAspect=true
                    // so non-2:3 art letterboxes rather than distorts.
                    /* Tier export keeps the PNG-while-pending fallback: a
                     * bulk export with uncaptured cards reads far better
                     * with old art than with 60+ placeholder cells. */
                    Sprite sp = CardImageLoader.GetSprite(c.card_name, allowPngWhilePending: true);
                    var imgGO = new GameObject("Img");
                    imgGO.transform.SetParent(cell.transform, false);
                    imgGO.AddComponent<RectTransform>();
                    var imgComp = imgGO.AddComponent(UIFactory.tImage);
                    if (sp != null)
                    {
                        pImgSprite?.SetValue(imgComp, sp);
                        pImgPreserve?.SetValue(imgComp, true);
                        pImgColor?.SetValue(imgComp, Color.white);
                    }
                    else
                    {
                        // Missing-art fallback — solid colored placeholder
                        // with the card name written across it (localized
                        // when the game has a translation — L10n interim).
                        pImgColor?.SetValue(imgComp, new Color(0.20f, 0.22f, 0.26f, 1f));
                        string missNm = CardTextLocalizer.PrettyName(c.card_name, c.card_name) ?? "?";
                        UIFactory.CreateText("Miss", imgGO.transform,
                            $"<b>{Trunc(missNm, 14)}</b>",
                            22f, C_WHITE, UIFactory.AlignMidCenter, sizeDelta: new Vector2(IMG_W - 8, 60));
                    }
                    UIFactory.AddLE(imgGO, prefW: IMG_W, minW: IMG_W, prefH: IMG_H, minH: IMG_H, flexW: 0, flexH: 0);

                    // Picks count.
                    var playedTxt = UIFactory.CreateText("P", cell.transform,
                        $"<b>{c.times_picked} played</b>",
                        26f, C_WHITE, UIFactory.AlignMidCenter, sizeDelta: new Vector2(CELL_W - 8, 30));
                    UIFactory.SetBold(playedTxt, true);
                    // Win % colored by performance band.
                    float wr = c.win_rate * 100f;
                    string wrCol = wr >= 55 ? "#88FF88" : wr <= 45 ? "#FF8888" : "#FFFFFF";
                    var wrTxt = UIFactory.CreateText("W", cell.transform,
                        $"<b><color={wrCol}>{wr:F0}% won</color></b>",
                        26f, C_WHITE, UIFactory.AlignMidCenter, sizeDelta: new Vector2(CELL_W - 8, 30));
                    UIFactory.SetBold(wrTxt, true);

                    curIdx++;
                }
                // Pad the last row so cells aren't stretched if HLG forceExpandW is on.
                while (curRow != null && curIdx < cellsPerRow)
                {
                    var pad = new GameObject("pad");
                    pad.transform.SetParent(curRow.transform, false);
                    pad.AddComponent<RectTransform>();
                    UIFactory.AddLE(pad, prefW: CELL_W, minW: CELL_W, flexW: 0);
                    curIdx++;
                }
            }

            // (Legend dropped — inline labels "## played" / "##% won" make the
            // tier-color guide redundant. Tier-letter badges on the left of
            // each row already convey the ranking.)

            // Bottom watermark — Steam name on the left (claims the tier
            // list as theirs), mod info on the right. Both dark grey italic
            // matching the user's ask.
            string steamName = MatchTracker.LocalDisplayName;
            if (string.IsNullOrEmpty(steamName) || steamName == "unknown") steamName = "Anonymous";
            var wm = new GameObject("WM"); wm.transform.SetParent(bg.transform, false); wm.AddComponent<RectTransform>();
            UIFactory.AddHLG(wm, spacing: 0); UIFactory.AddLE(wm, prefH: 50, flexH: 0);
            UIFactory.CreateText("WMSteam", wm.transform,
                $"<color=#888><i>{steamName}'s tier list</i></color>",
                26f, C_DIM, UIFactory.AlignMidLeft, sizeDelta: new Vector2(1400, 50));
            var wmSp = new GameObject("S"); wmSp.transform.SetParent(wm.transform, false); wmSp.AddComponent<RectTransform>();
            UIFactory.AddLE(wmSp, flexW: 1);
            UIFactory.CreateText("WMTxt", wm.transform,
                $"<color=#888><i>Sid's Competitive Rounds mod  ·  v{Plugin.ModVersion}  ·  {DateTime.Now:yyyy-MM-dd}</i></color>",
                22f, C_DIM, UIFactory.AlignMidRight, sizeDelta: new Vector2(1500, 50));

            // Wait two frames for the LayoutGroups + ContentSizeFitter to
            // push the bg's preferred height into its RectTransform.
            yield return null;
            yield return null;
            if (myRun != _tierExportRun)
            {
                try { if (myPanel != null) UnityEngine.Object.Destroy(myPanel); } catch { }
                yield break;
            }
            try
            {
                Type canvasT = null;
                foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
                { canvasT = asm.GetType("UnityEngine.Canvas"); if (canvasT != null) break; }
                canvasT?.GetMethod("ForceUpdateCanvases", BindingFlags.Public | BindingFlags.Static)?.Invoke(null, null);
            }
            catch { }
            yield return null;
            if (myRun != _tierExportRun)
            {
                try { if (myPanel != null) UnityEngine.Object.Destroy(myPanel); } catch { }
                yield break;
            }

            // Resolve final canvas height from the bg's measured preferred size.
            int finalH = Mathf.CeilToInt(bgRT.rect.height);
            if (finalH < 600) finalH = 600;
            // Resize the canvas root so the world rect matches the content.
            rootRT.sizeDelta = new Vector2(CANVAS_W, finalH);
            yield return null;
            if (myRun != _tierExportRun)
            {
                try { if (myPanel != null) UnityEngine.Object.Destroy(myPanel); } catch { }
                yield break;
            }

            string outDir;
            try
            {
                outDir = System.IO.Path.GetFullPath(System.IO.Path.Combine(Application.dataPath, "..", "CompetitiveRoundsTierLists"));
                System.IO.Directory.CreateDirectory(outDir);
            }
            catch { outDir = Application.persistentDataPath; }
            string fn = $"tierlist-{filterStr}-{DateTime.Now:yyyyMMdd-HHmmss}.png";
            string fullPath = System.IO.Path.Combine(outDir, fn);

            // RenderTexture path: spawn a temp orthographic camera looking at
            // the offscreen canvas, render into a texture sized to the
            // canvas dimensions, ReadPixels → EncodeToPNG → file. Bypasses
            // ScreenCapture entirely (which is locked to monitor aspect).
            GameObject camGO = null;
            RenderTexture renderT = null;
            Texture2D tex = null;
            try
            {
                camGO = new GameObject("CR_TierCam");
                camGO.hideFlags = HideFlags.HideAndDontSave;
                camGO.transform.position = new Vector3(50000f, 50000f, -10f);
                var cam = camGO.AddComponent<Camera>();
                cam.orthographic = true;
                cam.orthographicSize = finalH / 2f;
                cam.aspect = (float)CANVAS_W / Math.Max(1, finalH);
                cam.clearFlags = CameraClearFlags.SolidColor;
                cam.backgroundColor = new Color(0.07f, 0.08f, 0.10f, 1f);
                cam.cullingMask = ~0;
                cam.nearClipPlane = 0.1f;
                cam.farClipPlane = 100f;

                renderT = new RenderTexture(CANVAS_W, finalH, 24);
                cam.targetTexture = renderT;
                cam.Render();

                var prevActive = RenderTexture.active;
                RenderTexture.active = renderT;
                tex = new Texture2D(CANVAS_W, finalH, TextureFormat.RGB24, false);
                tex.ReadPixels(new Rect(0, 0, CANVAS_W, finalH), 0, 0);
                tex.Apply();
                RenderTexture.active = prevActive;

                byte[] png = tex.EncodeToPNG();
                System.IO.File.WriteAllBytes(fullPath, png);
                Plugin.Log.LogInfo($"[TIER-EXPORT] saved {CANVAS_W}×{finalH} → {fullPath}");
            }
            catch (Exception ex) { Plugin.Log.LogWarning($"[TIER-EXPORT] capture failed: {ex.Message}"); }
            finally
            {
                try { if (camGO != null) UnityEngine.Object.Destroy(camGO); } catch { }
                try { if (renderT != null) UnityEngine.Object.Destroy(renderT); } catch { }
                try { if (tex != null) UnityEngine.Object.Destroy(tex); } catch { }
            }

            // Ownership-scoped cleanup (r3): destroy only THIS run's panel,
            // and touch the shared static/latch only while still the newest
            // run — a superseded run must never clear the successor's state.
            try { if (myPanel != null) UnityEngine.Object.Destroy(myPanel); } catch { }
            if (myRun == _tierExportRun)
            {
                tierExportPanel = null;
                // Release the reentrancy latch on the normal exit; the
                // entry-point TTL covers every abnormal one.
                _tierExportInFlightUntil = -1f;
            }

            CompetitiveUI.ShowNotification($"Tier list saved to {fullPath}", new Color(0.4f, 0.9f, 0.4f), 12f);
            Plugin.Log.LogInfo($"[TIER-EXPORT] done — {fullPath}");
        }
        private static Color GetRarityColor(string r){if(string.IsNullOrEmpty(r))return C_LABEL;switch(r.ToLower()){case "common":return C_COMMON;case "uncommon":return C_UNCOMMON;case "rare":return C_RARE;default:return C_LABEL;}}

        // -- Chat --------------------------------------------------
        /// <summary>Called from the background ChatClient thread. Appends a formatted
        /// line to the log with thread-safety.</summary>
        // Render dedup for server chat ids (v1.28.3 stopped reconnect-replay
        // re-prints — one of #30's "duplicated" reports). §2.6 changed the
        // SHAPE from a monotonic high-water mark to a bounded seen-id SET:
        // after a locale switch subscribes a new channel, its scrollback
        // refetch contains ids OLDER than the mark, and a high-water compare
        // would silently swallow the entire channel's history (the exact
        // hazard called out in localization-design §2.6). Local echoes carry
        // no id and always render.
        private static readonly HashSet<int> _seenChatIds = new HashSet<int>();
        /// <summary>Ids retracted by a moderator. A delete can arrive before
        /// the message it deletes (a live WS frame overtaking an in-flight
        /// scrollback fetch), so the id is remembered and the message is
        /// dropped on arrival. Same FIFO cap as the seen set.</summary>
        private static readonly HashSet<int> _retractedChatIds = new HashSet<int>();
        private static readonly Queue<int> _retractedChatOrder = new Queue<int>();
        private static readonly Queue<int> _seenChatOrder = new Queue<int>();
        private const int SEEN_CHAT_CAP = 600;
        // Wave-2 find 15: local echoes carry no id, so a locale-change
        // scrollback refetch re-delivers the sender's own recent lines with
        // their server ids and they render as duplicates. Remember recent
        // echoes by (name|message); a server row matching one is consumed
        // silently, exactly once.
        /* Aug-3 review find F6: the record carries the RENDERED line as well, so
         * consuming the echo simply DROPS the incoming duplicate — the rendered
         * row is already correctly placed, because a locally-generated line is
         * stamped "newer than anything shown" rather than off the wall clock
         * (NextLocalStamp). An earlier revision re-stamped the drawn row from the
         * server's created_at instead; that repair, and the clock estimator
         * before it, each produced their own ordering defects, so both are gone.
         * Line is retained purely to check the row is still on screen. */
        private struct EchoRecord { public string Key; public DateTime At; public string Line; public long Seq; }
        private static readonly List<EchoRecord> _recentEchoes = new List<EchoRecord>();


        /// <summary>A timestamp one tick newer than anything currently in the
        /// pane — the sort key for a line this client generated (a local echo,
        /// a /muted reply, a quick-chat line, a system notice).
        ///
        /// Using the wall clock here is what made a skewed clock file the
        /// player's own messages permanently out of order, and every attempt to
        /// correct that afterwards (a skew estimator, then a canonical-row
        /// re-stamp) produced its own review findings. A locally-generated line
        /// is ALWAYS the newest thing the player has seen, so saying exactly
        /// that needs no clock and no correction.
        ///
        /// Caller must hold chatLinesLock.</summary>
        private static DateTime NextLocalStamp()
        {
            /* r4 find 4: the wall clock must NOT participate while the pane has
             * rows. Taking max(newest, UtcNow) let a clock running fast stamp a
             * local line minutes into the future, where it became a barrier
             * every genuine later server row sorted BELOW. Anchoring purely on
             * the newest row already shown means "immediately after everything
             * visible" — which is exactly what a line the player just produced
             * is, on any clock. UtcNow is used only to seed an empty pane, where
             * there is nothing it can invert. */
            /* r7 find 1: the pane being EMPTY does not mean nothing is known
             * about the server's clock. Anchor on the newest server stamp seen
             * anywhere this session — including rows the length cap has since
             * evicted, and rows filtered out of the current view — so an empty
             * pane no longer falls back to a local clock that may be minutes
             * off. Only a session that has never received a single server row
             * has nothing to anchor to; see the note below. */
            DateTime newest = lastServerStampSeen;
            for (int i = 0; i < chatLines.Count; i++)
                if (chatLines[i].SentUtc > newest) newest = chatLines[i].SentUtc;
            if (newest == DateTime.MinValue) return DateTime.UtcNow;
            return newest.AddTicks(1);
        }

        /// <summary>Is this exact rendered line still in the pane? Used to decide
        /// whether an echo marker may be consumed — see the dedupe block.
        /// Caller must hold chatLinesLock.</summary>
        private static bool ChatLineStillRendered(long seq)
        {
            if (seq <= 0) return false;
            for (int i = chatLines.Count - 1; i >= 0; i--)
                if (chatLines[i].Seq == seq) return true;
            return false;
        }

        public static void OnChatMessage(string json)
        {
            try
            {
                string source = ExtractChatField(json, "source");
                string name = ExtractChatField(json, "display_name");
                string message = ExtractChatField(json, "message");
                int rating = ExtractChatIntField(json, "rating");
                string title = ExtractChatField(json, "title");
                string titleColor = ExtractChatField(json, "title_color");
                string channel = ExtractChatField(json, "channel");
                /* Aug 6 item 5 (Codex round 1, MEDIUM): moderator retraction.
                 * The server broadcasts {"type":"delete","id":N,"channel":...}
                 * with NO message key, and the empty-message guard below used
                 * to swallow it — so a deleted line stayed on screen until the
                 * client restarted, which is exactly the case the delete
                 * endpoint exists for.
                 *
                 * Handled HERE, before that guard, and deliberately BEFORE the
                 * chatId read further down: a retraction's id must never reach
                 * lastServerStampSeen (it is the local-echo ordering anchor,
                 * #310) nor the seen-id set (that would make the real message
                 * unrenderable if it arrived after the delete). */
                if (string.IsNullOrEmpty(message))
                {
                    string frameType = ExtractChatField(json, "type");
                    if (frameType == "delete")
                    {
                        int delId = ExtractChatIntField(json, "id");
                        if (delId > 0)
                        {
                            bool removed = false;
                            lock (chatLinesLock)
                            {
                                for (int i = chatLines.Count - 1; i >= 0; i--)
                                {
                                    if (chatLines[i].ChatId != delId) continue;
                                    chatLines.RemoveAt(i);
                                    removed = true;
                                    break;   // ids are unique
                                }
                                // R2 finding 9: TOMBSTONE regardless of whether a
                                // row was present. A retraction can arrive BEFORE
                                // its own message — the live WS delete overtaking
                                // an in-flight /chat/recent snapshot is the normal
                                // case, not an exotic one — and without a
                                // tombstone that snapshot row renders the deleted
                                // content and it stays on screen. Bounded by the
                                // same FIFO discipline as the seen-id set.
                                // R3 (LOW): only enqueue when the id is genuinely
                                // NEW. Idempotent moderation retries rebroadcast
                                // the same id, and enqueuing every copy meant a
                                // later dequeue of an early duplicate removed the
                                // set entry while other copies still sat in the
                                // queue — evicting a tombstone that was still
                                // supposed to be live.
                                // Chat-mod design v3 D3: this mutation moved
                                // INSIDE chatLinesLock — the reader at the
                                // seen-id gate below holds that lock, and this
                                // method runs from both the WS thread and the
                                // scrollback coroutine, so the old outside-the-
                                // lock placement was an unsynchronized HashSet.
                                if (_retractedChatIds.Add(delId))
                                    _retractedChatOrder.Enqueue(delId);
                                while (_retractedChatOrder.Count > SEEN_CHAT_CAP)
                                    _retractedChatIds.Remove(_retractedChatOrder.Dequeue());
                            }
                            if (removed)
                            {
                                // D3's second half: no RefreshChatLog() here —
                                // it touches Unity UI and this can be the WS
                                // background thread. MarkDirty() is the pattern
                                // every other path in this method uses; the
                                // next UI tick rebuilds the pane, and the
                                // overlay re-pulls CopyChatTail every repaint.
                                MarkDirty();
                                Plugin.Log.LogInfo($"[CHAT] message {delId} retracted by a moderator");
                            }
                        }
                    }
                    /* Chat lockdown (design v3 S7): flat, no "message" key,
                     * bare number — old clients drop it at the guard above.
                     * Broadcast on toggle AND unicast as a snapshot to every
                     * new socket, so ChatClient.ChatLocked converges across
                     * reconnects; the change guard keeps repeat snapshots from
                     * re-printing the system line. */
                    if (frameType == "lock")
                    {
                        bool lockedNow = ExtractChatIntField(json, "locked") > 0;
                        if (ChatClient.ChatLocked != lockedNow)
                        {
                            ChatClient.ChatLocked = lockedNow;
                            AppendSystemChatLine(lockedNow
                                ? I18n.Tr("Chat has been locked by moderators - messages are paused.")
                                : I18n.Tr("Chat has been unlocked - carry on."));
                            MarkDirty();
                            Plugin.Log.LogInfo($"[CHAT] lockdown={lockedNow}");
                        }
                    }
                    /* Aug 7 item 9: auto-mod notice. The server censors the
                     * message (it never persisted or broadcast) and tells THIS
                     * socket only: {"type":"muted","minutes":N} — no "message"
                     * key, so old clients ignore it. Rendered as a system line
                     * so the sender knows why their line vanished; without it
                     * the local echo shows and then silently evaporates on the
                     * next scrollback (today's confusing muted-sender UX). */
                    if (frameType == "muted")
                    {
                        int mins = ExtractChatIntField(json, "minutes");
                        if (mins <= 0) mins = 15;
                        AppendSystemChatLine(I18n.TrF(
                            "Your message was removed and you are muted for {0} minutes (auto-moderation).", mins));
                        MarkDirty();
                    }
                    return;
                }
                /* item 13: server created_at (ISO-8601, TIMESTAMPTZ) — present on
                 * live frames, on every scrollback entry, and on ChatClient's local
                 * echo. Falls back to now for pre-field rows and system lines so the
                 * ordering key is TOTAL (a default(DateTime) would sort every such
                 * line to the top of the pane forever).
                 * F7: the fallback is ChatClient.NowUtc(), not UtcNow — every other
                 * value in this field is SERVER time, so a locally-invented stand-in
                 * has to be on the server's clock or a skewed machine sorts its
                 * fallback rows into the wrong place. */
                DateTime sentUtc;
                {
                    string ts = ExtractChatField(json, "timestamp");
                    if (string.IsNullOrEmpty(ts) || !DateTime.TryParse(ts, System.Globalization.CultureInfo.InvariantCulture,
                            System.Globalization.DateTimeStyles.AdjustToUniversal | System.Globalization.DateTimeStyles.AssumeUniversal,
                            out sentUtc))
                        sentUtc = ChatClient.NowUtc();
                }
                int chatId = ExtractChatIntField(json, "id");
                // Anchor for NextLocalStamp — recorded for EVERY server row,
                // including ones about to be deduped away or muted, since what
                // matters is the clock evidence, not whether the row renders.
                if (chatId > 0)
                    lock (chatLinesLock)
                        if (sentUtc > lastServerStampSeen) lastServerStampSeen = sentUtc;
                // Echo key includes STEAM identity + channel (round-3 find
                // N11: two players can share a display name — name|message
                // alone let another Alex's real "gg" consume our marker and
                // vanish).
                string echoKey = ExtractChatField(json, "steam_id") + "|"
                    + (string.IsNullOrEmpty(channel) ? "global" : channel)   // pre-179 rows carry no channel
                    + "|" + name + "|" + message;
                // Local mute filter (computed OUTSIDE the lock — it reads
                // config). Hides messages from any name in MutedChatNames.
                // Case-insensitive comparison so /mute Sid matches "sid" too.
                bool muted = IsMuted(name);
                // Bound any single message so a giant paste can't overflow the scroll content
                // and trap the scroll position past TMP's reachable bottom.
                if (message.Length > CHAT_LINE_MAX_CHARS)
                    message = message.Substring(0, CHAT_LINE_MAX_CHARS - 3) + "...";
                // Stream-chat bridge (Aug 18): Twitch/YouTube viewer chat is
                // relayed into SCR chat server-side with its own source tag.
                // Unknown sources still degrade to [Game] (server-first
                // deploys stay safe — older clients render bridged lines as
                // [Game], never drop them).
                string prefix = source == "discord" ? "<color=#A0B4FF>[Discord]</color>"
                    : source == "twitch" ? "<color=#C89BFF>[Twitch]</color>"
                    : source == "youtube" ? "<color=#FF8080>[YouTube]</color>"
                    : "<color=#B0FFB0>[Game]</color>";
                // §2.6: language-channel messages get a [RU]/[ES] tag beside
                // the source tag. Scrollback ordering merges both streams
                // into the one flat list — no tabs, no per-channel panels.
                if (!string.IsNullOrEmpty(channel) && channel != "global")
                    prefix += $"<color=#FFB56B>[{channel.ToUpperInvariant()}]</color>";
                string ratingTag = rating > 0 ? $" <color=#CCCCCC>({rating})</color>" : "";
                string titleTag = "";
                if (!string.IsNullOrEmpty(title))
                {
                    string col = string.IsNullOrEmpty(titleColor) ? "#CCCCCC" : titleColor;
                    titleTag = $" <color={col}>[{Escape(title)}]</color>";
                }
                string line = $"{prefix} <b>{Escape(name)}</b>{titleTag}{ratingTag}: {Escape(message)}";
                // R2-Low2: the seen-id record and the chatLines append are ONE
                // atomic section. Split across two lock blocks, a picker clear
                // (which wipes _seenChatIds + chatLines together) could
                // interleave between them: the id lands pre-clear, the line
                // post-clear, and the row then exists WITHOUT its id in the
                // seen set — a later history response re-renders it as a
                // duplicate. All formatting above is lock-free precompute; the
                // lock holds only collection ops. OnChatMessage runs from both
                // the WS background thread and the scrollback coroutine, hence
                // chatLinesLock throughout.
                lock (chatLinesLock)
                {
                    if (chatId > 0)
                    {
                        if (_retractedChatIds.Contains(chatId)) return;  // deleted before it arrived
                        if (!_seenChatIds.Add(chatId)) return;  // already rendered
                        _seenChatOrder.Enqueue(chatId);
                        while (_seenChatOrder.Count > SEEN_CHAT_CAP)
                            _seenChatIds.Remove(_seenChatOrder.Dequeue());
                        /* This server row may BE a line we already rendered as a
                         * local echo. Drop it if so — but only if the echo is
                         * still on screen.
                         *
                         * Consuming the marker unconditionally was round-3
                         * blocker 3: an echo evicted by the 60-line cap left its
                         * marker behind, and the canonical row was then swallowed
                         * on arrival and discarded by id on every later fetch —
                         * the message vanished from the player's own pane.
                         *
                         * No re-stamping happens here any more. Locally-generated
                         * lines are stamped as "newest" when they are created (see
                         * NextLocalStamp), so they are already in the right place
                         * and never need the server's timestamp to correct them —
                         * which also means two identical messages can no longer
                         * swap timestamps by pairing in the wrong direction. */
                        for (int e = _recentEchoes.Count - 1; e >= 0; e--)
                        {
                            if (_recentEchoes[e].Key != echoKey) continue;
                            /* CONTINUE, not break (r5 finds 4+6): several
                             * markers can share a key (the same message sent
                             * twice), and history replays oldest-first while
                             * this scans newest-first. Stopping at the first
                             * key match let a dead marker mask a live one, so a
                             * canonical row was dropped whose echo had already
                             * been evicted. Keep looking for one whose row is
                             * still on screen; if none is, fall through and
                             * render the server's row. */
                            if (!ChatLineStillRendered(_recentEchoes[e].Seq)) continue;
                            _recentEchoes.RemoveAt(e);
                            return;
                        }
                    }
                    else if (source == "ingame" && !muted)
                    {
                        /* r5 find 5: only record a marker when a row will
                         * actually be drawn. A muted self-send used to leave a
                         * marker with Seq == 0 that no row could ever satisfy,
                         * and the newest-first scan below stopped on it. */
                        // An id-less ingame line is our own local echo — remember
                        // it so its persisted twin (scrollback refetch) dedupes.
                        // Line is kept so the twin can repair this row's SentUtc (F6).
                        /* Bounded by COUNT, never by the wall clock (finding 8):
                         * a forward clock step used to prune a live marker and
                         * let its canonical row render as a duplicate. "The last
                         * 20 things I sent" is the bound this always wanted. */
                        _recentEchoes.Add(new EchoRecord { Key = echoKey, At = DateTime.UtcNow, Line = line });
                        // r4 find 12: must exceed CHAT_LOG_MAX, or a burst of
                        // sends prunes a marker whose echo is still on screen and
                        // its canonical row then renders as a duplicate.
                        while (_recentEchoes.Count > CHAT_LOG_MAX + 4) _recentEchoes.RemoveAt(0);
                    }
                    // Muted lines still record their id above (a history
                    // redelivery dedups by id, exactly as before) but never
                    // reach the pane.
                    if (!muted)
                    {
                        // Item 5: keep the parsed channel on the entry (it used to
                        // be discarded after prefix formatting) so RefreshChatLog
                        // can filter by display channel. Pre-channel rows = global.
                        /* item 13: insert by SentUtc, not append. With the socket
                         * now subscribed to EVERY channel, one pane merges three
                         * streams plus a scrollback replay, and arrival order is
                         * not send order. Tail-biased linear scan: the common case
                         * (a live message, newest of all) exits on the first
                         * comparison, and the list is capped at 60. `>` keeps
                         * equal timestamps in arrival order (stable). */
                        /* A row with no server id is locally generated (our own
                         * echo). Stamp it as the NEWEST thing in the pane rather
                         * than with this machine's clock: it is by definition the
                         * most recent thing the player has seen, and a skewed
                         * clock would otherwise file it minutes into the past or
                         * future with nothing able to correct it (blocker 4). */
                        DateTime stamp = chatId > 0 ? sentUtc : NextLocalStamp();
                        long seq = chatSeqNext++;
                        var entry = new ChatEntry { Line = line, AddedUtc = DateTime.UtcNow, SentUtc = stamp,
                            Channel = string.IsNullOrEmpty(channel) ? "global" : channel, Seq = seq,
                            ChatId = chatId,
                            Source = string.IsNullOrEmpty(source) ? "ingame" : source };
                        /* r4 find 3: compare against `stamp`, the value actually
                         * being stored — comparing the raw parsed `sentUtc` here
                         * placed a local line by a timestamp it does not carry,
                         * which on a slow clock inserted it at index 0 where the
                         * 60-line cap deleted it on the spot. */
                        int ins = chatLines.Count;
                        while (ins > 0 && chatLines[ins - 1].SentUtc > stamp) ins--;
                        chatLines.Insert(ins, entry);
                        if (chatId <= 0 && _recentEchoes.Count > 0)
                        {
                            // Bind the marker just written to the row just drawn.
                            var rec = _recentEchoes[_recentEchoes.Count - 1];
                            if (rec.Seq == 0 && rec.Key == echoKey)
                            { rec.Seq = seq; _recentEchoes[_recentEchoes.Count - 1] = rec; }
                        }
                        while (chatLines.Count > CHAT_LOG_MAX) chatLines.RemoveAt(0);
                    }
                }
                if (muted)
                {
                    Plugin.Log.LogInfo($"[CHAT] muted msg from {name} dropped locally");
                    return;
                }
                MarkDirty();
            }
            catch { }
        }

        // -- Local chat mute (per-display-name) -----------------
        // Stored as a pipe-delimited list in Plugin.MutedChatNames (BepInEx config).
        // Command syntax: "/mute name", "/unmute name", "/muted".
        // Filter applied in OnChatMessage; commands handled in CompetitiveUI's chat input submit.

        private static HashSet<string> _mutedCache;

        private static HashSet<string> GetMutedSet()
        {
            // Rebuild on each access - config writes are infrequent and the list is small.
            string raw = Plugin.MutedChatNames?.Value ?? "";
            var set = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (var part in raw.Split('|'))
            {
                var t = (part ?? "").Trim();
                if (!string.IsNullOrEmpty(t)) set.Add(t);
            }
            _mutedCache = set;
            return set;
        }

        private static bool IsMuted(string name)
        {
            if (string.IsNullOrEmpty(name)) return false;
            var s = _mutedCache ?? GetMutedSet();
            return s.Contains(name);
        }

        private static void SaveMutedSet(HashSet<string> set)
        {
            if (Plugin.MutedChatNames == null) return;
            Plugin.MutedChatNames.Value = string.Join("|", set);
            _mutedCache = set;
        }

        public static void HandleMuteCommand(string text)
        {
            try
            {
                if (text.Equals("/muted", StringComparison.OrdinalIgnoreCase))
                {
                    var s = GetMutedSet();
                    string list = s.Count == 0 ? "(none)" : string.Join(", ", s);
                    AppendSystemChatLine($"Muted: {list}");
                    return;
                }
                int sp = text.IndexOf(' ');
                if (sp < 0) return;
                string cmd = text.Substring(0, sp).ToLowerInvariant();
                string target = text.Substring(sp + 1).Trim();
                if (string.IsNullOrEmpty(target)) return;
                var set = GetMutedSet();
                if (cmd == "/mute")
                {
                    if (set.Add(target)) { SaveMutedSet(set); AppendSystemChatLine($"Muted <b>{Escape(target)}</b>"); }
                    else AppendSystemChatLine($"<b>{Escape(target)}</b> is already muted");
                }
                else if (cmd == "/unmute")
                {
                    if (set.Remove(target)) { SaveMutedSet(set); AppendSystemChatLine($"Unmuted <b>{Escape(target)}</b>"); }
                    else AppendSystemChatLine($"<b>{Escape(target)}</b> isn't muted");
                }
            }
            catch (Exception ex) { Plugin.Log.LogWarning($"[MUTE] {ex.Message}"); }
        }

        /// <summary>"/report &lt;name&gt; [reason]" — §2.6's v1 moderation
        /// groundwork: no moderation UI exists yet (D16), but a report files a
        /// bug_report-shaped row with the reporter's local chat log lines
        /// mentioning that name, so the v1 window produces EVIDENCE instead of
        /// nothing. Local-log evidence only (what this player actually saw).</summary>
        internal static void HandleReportCommand(string text)
        {
            try
            {
                string rest = text.Substring("/report ".Length).Trim();
                if (rest.Length == 0) { AppendSystemChatLine("Usage: /report [name] [reason]  (quote multi-word names: /report \"Bad Actor\" reason)"); return; }
                // Quoted names carry spaces (wave-2 find 14): /report "Bad
                // Actor" reason. Unquoted keeps first-token semantics.
                string name, reason;
                if (rest[0] == '"')
                {
                    int endQ = rest.IndexOf('"', 1);
                    if (endQ < 0) { AppendSystemChatLine("Unclosed quote — usage: /report \"Multi Word Name\" [reason]"); return; }
                    name = rest.Substring(1, endQ - 1).Trim();
                    reason = rest.Substring(endQ + 1).Trim();
                    if (name.Length == 0) { AppendSystemChatLine("Usage: /report [name] [reason]"); return; }
                }
                else
                {
                    int sp = rest.IndexOf(' ');
                    name = sp < 0 ? rest : rest.Substring(0, sp);
                    reason = sp < 0 ? "" : rest.Substring(sp + 1).Trim();
                }
                var lines = new List<string>();
                lock (chatLinesLock)
                {
                    for (int i = Math.Max(0, chatLines.Count - 80); i < chatLines.Count; i++)
                        if (chatLines[i].Line.IndexOf(name, StringComparison.OrdinalIgnoreCase) >= 0)
                            lines.Add(chatLines[i].Line);
                }
                string evidence = string.Join("\n", lines.ToArray());
                if (evidence.Length > 4000) evidence = evidence.Substring(evidence.Length - 4000);
                AppendSystemChatLine($"Filing chat report against '{name}'...");
                ApiClient.SubmitBugReport(GameStateWatcher.LocalSteamId,
                    GameStateWatcher.LocalDisplayName ?? "",
                    $"CHAT REPORT against '{name}'" + (reason.Length > 0 ? $": {reason}" : ""),
                    null, "low", "chat_report",
                    evidence.Length > 0 ? evidence : null,
                    (ok, _) => AppendSystemChatLine(ok
                        ? $"Report filed against '{name}'. An admin will review it."
                        : "Report failed to send - try again in a moment."));
            }
            catch (Exception ex) { Plugin.Log.LogWarning($"[CHAT-REPORT] {ex.Message}"); }
        }

        /// <summary>Quick-chat phrase line (localization-design §2.6). The
        /// phrase arrives already rendered in THIS client's locale; the name
        /// is Photon NickName, already bracket-neutralised by the caller.</summary>
        internal static void AddQuickChatLine(string name, string phrase)
        {
            string line = $"<color=#8FC9FF>[Q]</color> <b>{Escape(name)}</b>: {Escape(phrase)}";
            lock (chatLinesLock)
            {
                /* Aug-3 review find F7: SentUtc is MANDATORY on every entry. The list
                 * is kept sorted by it (OnChatMessage INSERTS by SentUtc, it does not
                 * append), and the insert scan walks left only while the previous
                 * entry is GREATER — so an entry left at default(DateTime) is a floor
                 * nothing can ever sort above. Every later arrival lands beneath it
                 * no matter how old it really is, which is how a reconnect scrollback
                 * ends up printing below a status line that was written after it.
                 * ChatClient.NowUtc() rather than UtcNow so a locally-created line
                 * sorts against server timestamps on the SERVER's clock. */
                /* r3 find 6: NextLocalStamp, not the wall clock. These lines are
                 * generated HERE and have no server row to correct them, so on a
                 * skewed clock they used to file minutes into the past or future
                 * and sit permanently out of order among real messages. "Newer
                 * than anything already shown" is what they actually are. */
                chatLines.Add(new ChatEntry { Line = line, AddedUtc = DateTime.UtcNow,
                                              SentUtc = NextLocalStamp(), Seq = chatSeqNext++ });
                while (chatLines.Count > CHAT_LOG_MAX) chatLines.RemoveAt(0);
            }
            MarkDirty();
        }

        // Adds a local-only system line to the chat log (gold-tinted, no broadcast).
        private static void AppendSystemChatLine(string body)
        {
            string line = $"<color=#FFD94D>[system]</color> {body}";
            lock (chatLinesLock)
            {
                /* F7 (repro: /muted while a reconnect scrollback is still in flight —
                 * the status line landed at the tail with default(DateTime) and the
                 * older server rows then inserted BELOW it). See AddQuickChatLine for
                 * why every entry must carry SentUtc. */
                /* r3 find 6: NextLocalStamp, not the wall clock. These lines are
                 * generated HERE and have no server row to correct them, so on a
                 * skewed clock they used to file minutes into the past or future
                 * and sit permanently out of order among real messages. "Newer
                 * than anything already shown" is what they actually are. */
                chatLines.Add(new ChatEntry { Line = line, AddedUtc = DateTime.UtcNow,
                                              SentUtc = NextLocalStamp(), Seq = chatSeqNext++ });
                while (chatLines.Count > CHAT_LOG_MAX) chatLines.RemoveAt(0);
            }
            MarkDirty();
        }

        /// <summary>Feedback for a send attempt refused by the lockdown
        /// (design v3 S7). Internal: CompetitiveUI's T-key/submit paths call it;
        /// ChatClient.Send's own gate stays silent (belt, not the surface).</summary>
        internal static void NotifyChatLockedAttempt()
        {
            AppendSystemChatLine(I18n.Tr("Chat is locked by moderators right now - your message was not sent."));
        }

        /// <summary>Item 5: display name for a chat channel id. "all" (and the
        /// "auto" default) = the merged view.
        /// Aug-3 item 13: the "global" channel is LABELLED "English" — it is the
        /// English-speaking room, and calling it "Global" was half the reason
        /// players read the picker as "everything" and never found es/ru. The
        /// WIRE value stays "global" everywhere (server CHAT_CHANNELS_ALLOWED);
        /// only the label moved.</summary>
        private static string ChatChannelDisplayName(string ch)
        {
            switch (ch)
            {
                case "es": return "Español";
                case "ru": return "Русский";
                case "uk": return "Українська";
                case "sv": return "Svenska";
                case "global": return I18n.Tr("English");
                default: return I18n.Tr("All (merged)");
            }
        }

        /// <summary>Aug-3 item 13: the VIEW picker. Writes ONLY
        /// Plugin.ChatDisplayChannel. With the socket permanently subscribed to
        /// every allowed channel (ChatClient.DerivedChannelSet is a constant now),
        /// the local buffer already holds all three streams, so changing the view
        /// is a PURE RENDER FILTER — no clear, no refetch, no repopulation race.
        /// The old handler wiped chatLines + _seenChatIds + _seenChatOrder +
        /// _recentEchoes and refetched with a channels override; that dance is what
        /// blanked the pane on every switch (and, until the refetch landed, kept the
        /// PREVIOUS channel's text under the new channel's label). It also wrote
        /// ChatClient.ExtraViewChannel, a property that no longer exists.</summary>
        private static void OpenChatViewPicker()
        {
            string cur = "all";
            try { cur = Plugin.ChatDisplayChannel?.Value ?? "all"; } catch { }
            CompetitiveUI.OpenArtistPicker(I18n.Tr("View channel"),
                new string[] { I18n.Tr("All (merged)"), I18n.Tr("English"), "Español", "Русский", "Українська", "Svenska" },
                new string[] { "all", "global", "es", "ru", "uk", "sv" },
                picked =>
                {
                    if (string.IsNullOrEmpty(picked)) return;
                    try { if (Plugin.ChatDisplayChannel != null) Plugin.ChatDisplayChannel.Value = picked; } catch { }
                    dirty = true;
                },
                actionLabel: I18n.Tr("Use"), showClear: false, itemNoun: "",
                selectedId: cur);
        }

        /// <summary>Aug-3 item 13: the TYPING picker. Writes ONLY
        /// ChatClient.SendChannel (persisted through Plugin.ChatSendChannel).
        /// There is deliberately no "All" entry: a message goes to exactly one
        /// channel, so "typing into the merged view" has no meaning — which is
        /// also why this cannot be folded back into the view picker.</summary>
        private static void OpenChatTypingPicker()
        {
            string cur = "global";
            try { cur = ChatClient.SendChannel ?? "global"; } catch { }
            CompetitiveUI.OpenArtistPicker(I18n.Tr("Typing channel"),
                new string[] { I18n.Tr("English"), "Español", "Русский", "Українська", "Svenska" },
                new string[] { "global", "es", "ru", "uk", "sv" },
                picked =>
                {
                    if (string.IsNullOrEmpty(picked)) return;
                    try { ChatClient.SendChannel = picked; } catch { }
                    dirty = true;
                },
                actionLabel: I18n.Tr("Use"), showClear: false, itemNoun: "",
                selectedId: cur);
        }

        private static void RefreshChatLog()
        {
            /* Aug-3 item 13: two states, read independently. The header names what
             * is being SHOWN; the second button names where typing goes. Neither
             * control can move the other. */
            string filter = "all";
            try { filter = Plugin.ChatDisplayChannel?.Value ?? "all"; } catch { }
            string send = "global";
            try { send = ChatClient.SendChannel ?? "global"; } catch { }
            if (txtChatHeader != null)
            {
                // Bug 213: name who in this room currently has chat muted, so
                // you know before typing at them. MutedPlayersLine() returns ""
                // when nobody is muted or we are not in an online room, so the
                // header falls back to its normal form and no row is wasted.
                // This is the ALWAYS-AVAILABLE surface — the in-game overlay's
                // copy only shows while the chat panel itself is up.
                string mutedLine = "";
                try { mutedLine = CompetitiveUI.MutedPlayersLine(); } catch { }
                UIFactory.SetTextRaw(txtChatHeader,
                    mutedLine.Length > 0
                        ? I18n.TrF("Viewing: {0}  <color=#888>(press T to chat)</color>", ChatChannelDisplayName(filter))
                          + "  <color=#997766>" + mutedLine + "</color>"
                        : I18n.TrF("Viewing: {0}  <color=#888>(press T to chat)</color>", ChatChannelDisplayName(filter)));
            }
            if (chatViewBtn != null)
                UIFactory.SetTextRaw(UIFactory.GetButtonText(chatViewBtn), I18n.Tr("Change view"));
            if (chatSendBtn != null)
                UIFactory.SetTextRaw(UIFactory.GetButtonText(chatSendBtn),
                    I18n.TrF("Typing: {0}  (Alt to change)", ChatChannelDisplayName(send)));
            if (txtChatLog == null) return;
            // "all" (and the "auto" default) keeps the merged view; only an explicit
            // concrete channel filters. System lines (null channel) always show.
            // Must list every concrete channel the view picker can write: a
            // channel missing here falls through to the merged view, so the
            // header would name one channel while the pane shows all of them.
            bool concrete = filter == "global" || filter == "es" || filter == "ru"
                || filter == "uk" || filter == "sv";
            /* item 4: capture the scroll state BEFORE the text changes — "was the
             * player already at the bottom" is a question about the view they were
             * looking at. `wasOverflowing` is the second half: when the content did
             * not exceed the viewport there is no meaningful scroll position (Unity
             * returns a flat 0 or 1), so treat that as "pin me". Without it the pane
             * would auto-scroll until the first overflow and then never again. */
            bool atBottom = true;
            try
            {
                float ch = chatContentRT != null ? chatContentRT.rect.height : 0f;
                float vh = chatViewportRT != null ? chatViewportRT.rect.height : 0f;
                if (ch > vh + 1f && chatScrollRect != null)
                {
                    var pv = UIFactory.tScrollRect.GetProperty("verticalNormalizedPosition", BindingFlags.Public | BindingFlags.Instance);
                    if (pv != null) atBottom = (float)pv.GetValue(chatScrollRect) <= 0.05f;
                }
            }
            catch { }
            string text; int shown = 0;
            lock (chatLinesLock)
            {
                var sb = new System.Text.StringBuilder();
                for (int i = 0; i < chatLines.Count; i++)
                {
                    if (concrete && !string.IsNullOrEmpty(chatLines[i].Channel) && chatLines[i].Channel != filter) continue;
                    if (shown > 0) sb.Append('\n');
                    shown++;
                    sb.Append(chatLines[i].Line);
                }
                text = sb.ToString();
            }
            /* item 13: render an EXPLICIT empty state. The old
             * `if (chatLines.Count == 0) return;` left the pane showing whatever was
             * already in it, so a view switch could keep the previous channel's
             * messages on screen under the new channel's label; and the sibling case
             * (buffer non-empty, filter matches nothing) rendered a blank pane with
             * no explanation at all. */
            if (shown == 0)
                text = "<color=#888><i>" + I18n.Tr("No messages in this channel yet.") + "</i></color>";
            UIFactory.SetTextRaw(txtChatLog, text);
            if (atBottom) Plugin.Instance?.StartCoroutine(ScrollChatToBottomNextFrame());
        }

        private static System.Collections.IEnumerator ScrollChatToBottomNextFrame()
        {
            /* item 4. The old body was a single `yield return null` then a blind
             * verticalNormalizedPosition = 0. Two defects: (a) one frame is not
             * enough for the ContentSizeFitter + TMP to have re-laid-out, so the
             * write landed against STALE bounds and parked the viewport where the
             * new (shorter) text is not; (b) with content shorter than the viewport
             * Unity's SetNormalizedPosition has a negative hiddenLength and aligns
             * content-BOTTOM to viewport-bottom, i.e. it shoves short content down
             * out of its natural top position. Force the layout, then only scroll
             * when there is something to scroll. */
            yield return null;
            try { UIFactory.tCanvas?.GetMethod("ForceUpdateCanvases", BindingFlags.Public | BindingFlags.Static)?.Invoke(null, null); } catch { }
            yield return null;
            if (chatScrollRect == null) yield break;
            bool canScroll = false;
            try
            {
                float ch = chatContentRT != null ? chatContentRT.rect.height : 0f;
                float vh = chatViewportRT != null ? chatViewportRT.rect.height : 0f;
                canScroll = ch > vh + 1f;
            }
            catch { }
            if (!canScroll) yield break;
            try
            {
                // ScrollRect.verticalNormalizedPosition: 0 = bottom, 1 = top.
                var p = UIFactory.tScrollRect.GetProperty("verticalNormalizedPosition", BindingFlags.Public | BindingFlags.Instance);
                p?.SetValue(chatScrollRect, 0f);
            }
            catch { }
        }

        private static string Escape(string s)
        {
            if (string.IsNullOrEmpty(s)) return "";
            // Strip TMP rich-text payloads that could break our own coloring or impersonate system lines.
            // Use ASCII parens instead of CJK brackets so the result stays in the Gravity SDF glyph range
            // (Cyrillic + many Latin locales don't have the U+3008/U+3009 variants as fallbacks).
            return s.Replace("<", "(").Replace(">", ")");
        }

        /// <summary>Numeric field parser - tolerates nulls, whitespace, integers and floats.</summary>
        /// <summary>Index of the character just past `"key":` at the TOP LEVEL of
        /// this chat object, or -1.
        ///
        /// A raw IndexOf finds the first textual occurrence anywhere — including
        /// inside a VALUE. Chat messages are user-authored, so a player typing
        /// the literal <c>"timestamp": "2099-01-01T00:00:00"</c> would have it
        /// parsed as the row's real timestamp (message is serialized BEFORE
        /// timestamp), which under the new time-ordered insert pins that line to
        /// the bottom of every client's pane permanently. Same #156 family as
        /// the scrollback slicer: user text is hostile input for naive scans.
        /// Walking string-aware and only accepting keys at depth 0 closes it for
        /// every field, including any added after `message` later.</summary>
        private static int FindChatKey(string json, string key)
        {
            if (string.IsNullOrEmpty(json) || string.IsNullOrEmpty(key)) return -1;
            // Callers pass either a whole object ("{...}", the WS frame) or one
            // slice from SliceTopLevelObjects (which may omit the braces), so the
            // depth at which OUR keys live differs by one. Anchor on the input.
            int k = 0;
            while (k < json.Length && char.IsWhiteSpace(json[k])) k++;
            int wantDepth = (k < json.Length && json[k] == '{') ? 1 : 0;
            int depth = 0, i = 0;
            bool inStr = false, keyPos = true;   // keyPos: this string is a KEY
            int strStart = -1;
            while (i < json.Length)
            {
                char c = json[i];
                if (inStr)
                {
                    if (c == '\\') { i += 2; continue; }
                    if (c == '"')
                    {
                        inStr = false;
                        if (depth == wantDepth && keyPos && i - strStart - 1 == key.Length
                            && string.CompareOrdinal(json, strStart + 1, key, 0, key.Length) == 0)
                        {
                            int p = i + 1;
                            while (p < json.Length && (json[p] == ' ' || json[p] == '\t')) p++;
                            if (p < json.Length && json[p] == ':') return p + 1;
                        }
                    }
                    i++; continue;
                }
                if (c == '"') { inStr = true; strStart = i; i++; continue; }
                else if (c == '{') { depth++; keyPos = true; }
                else if (c == '[') { depth++; keyPos = false; }
                else if (c == '}' || c == ']') depth--;
                else if (c == ',') keyPos = true;
                else if (c == ':') keyPos = false;
                i++;
            }
            return -1;
        }

        private static int ExtractChatIntField(string json, string key)
        {
            if (string.IsNullOrEmpty(json)) return 0;
            int p = FindChatKey(json, key);
            if (p < 0) return 0;
            while (p < json.Length && (json[p] == ' ' || json[p] == '\t')) p++;
            int end = p;
            while (end < json.Length && (char.IsDigit(json[end]) || json[end] == '-' || json[end] == '.')) end++;
            if (end == p) return 0;
            try
            {
                float f = float.Parse(json.Substring(p, end - p), System.Globalization.CultureInfo.InvariantCulture);
                return (int)Math.Round(f);
            }
            catch { return 0; }
        }

        private static string ExtractChatField(string json, string key)
        {
            // Tolerates any JSON formatting: "key":"val", "key": "val", "key":  "val".
            if (string.IsNullOrEmpty(json)) return "";
            int p = FindChatKey(json, key);
            if (p < 0) return "";
            while (p < json.Length && (json[p] == ' ' || json[p] == '\t')) p++;
            if (p >= json.Length || json[p] != '"') return "";
            p++;
            var sb = new System.Text.StringBuilder();
            while (p < json.Length)
            {
                char c = json[p];
                if (c == '\\' && p + 1 < json.Length)
                {
                    char n = json[p + 1];
                    if (n == 'n') { sb.Append('\n'); p += 2; }
                    else if (n == 't') { sb.Append('\t'); p += 2; }
                    else if (n == 'r') { sb.Append('\r'); p += 2; }
                    // \uXXXX decode (wave-2 find 7): the server may escape
                    // non-ASCII (older builds, or any dumps without
                    // ensure_ascii=False) — without this, Привет rendered as
                    // literal u041fu0440... on every remote client.
                    else if (n == 'u' && p + 5 < json.Length
                             && ushort.TryParse(json.Substring(p + 2, 4),
                                 System.Globalization.NumberStyles.HexNumber,
                                 System.Globalization.CultureInfo.InvariantCulture, out var u))
                    { sb.Append((char)u); p += 6; }
                    else { sb.Append(n); p += 2; }
                }
                else if (c == '"') break;
                else { sb.Append(c); p++; }
            }
            return sb.ToString();
        }

