        private static readonly string[] I18N_GRANT_LANG_LABELS = { "Espanol (es)", "Russkiy (ru)", "Ukrainska (uk)", "Svenska (sv)" };
        private static readonly string[] I18N_GRANT_LANG_CODES = { "es", "ru", "uk", "sv" };

        /// <summary>Removes an author's hard line breaks so the renderer can do
        /// the wrapping (bug #160). A single newline inside a paragraph becomes
        /// a space; a blank line keeps its paragraph break; and a line that
        /// carries its OWN structure — a list bullet, a heading, an indented or
        /// code line, a horizontal rule — keeps its break, because joining those
        /// would run a bullet into the sentence above it.
        ///
        /// Deliberately conservative: when in doubt, keep the break. Over-
        /// joining mangles a changelog's structure, which is worse than a
        /// narrow column.</summary>
        internal static string UnwrapHardBreaks(string body)
        {
            if (string.IsNullOrEmpty(body) || body.IndexOf('\n') < 0) return body;
            string[] lines = body.Replace("\r\n", "\n").Replace('\r', '\n').Split('\n');
            var sb = new StringBuilder(body.Length);
            /* Aug 7 item 6 (bug 160's ACTUAL regression): the original rules
             * classified BOTH sides of nearly every break in a real changelog
             * as "structure" — the house note style is `- ` bullets whose
             * hard-wrapped continuations are 2-space-indented, and "**Bold"
             * prose openers start with '*'. Result: the unwrapper fired on
             * approximately zero lines and the column stayed at the author's
             * ~90 chars. Two corrections: `**` is BOLD, not a bullet; and a
             * 2-space-indented line that does NOT itself start a bullet is a
             * CONTINUATION of the bullet above it — joinable by definition. */
            bool StartsBullet(string t)
            {
                if (t.Length == 0) return false;
                char c0 = t[0];
                if ((c0 == '-' || c0 == '*' || c0 == '+') && !(c0 == '*' && t.Length > 1 && t[1] == '*'))
                    return t.Length > 1 && t[1] == ' ';
                int d = 0; while (d < t.Length && char.IsDigit(t[d])) d++;
                return d > 0 && d < t.Length && (t[d] == '.' || t[d] == ')');
            }
            bool StartsStructure(string l)
            {
                string t = l.TrimStart();
                if (t.Length == 0) return true;
                if (StartsBullet(t)) return true;
                char c0 = t[0];
                if (c0 == '*' && t.Length > 1 && t[1] == '*') return false;  // "**Bold" = prose
                if (c0 == '#' || c0 == '>' || c0 == '|') return true;
                if (c0 == '`') return true;                       // fenced/inline code
                if (l.StartsWith("    ", StringComparison.Ordinal)) return true; // 4-space code block
                return false;
            }
            // A 2-space continuation joins its bullet; anything else with its
            // own structure keeps the break.
            bool IsContinuation(string l)
            {
                if (!l.StartsWith("  ", StringComparison.Ordinal)) return false;
                if (l.StartsWith("    ", StringComparison.Ordinal)) return false;
                string t = l.TrimStart();
                return t.Length > 0 && !StartsBullet(t) && t[0] != '#';
            }
            for (int i = 0; i < lines.Length; i++)
            {
                string cur = lines[i];
                sb.Append(cur.TrimEnd());
                if (i == lines.Length - 1) break;
                string next = lines[i + 1];
                bool joinable = cur.Trim().Length > 0            // not a blank line
                             && next.Trim().Length > 0           // next is not a paragraph break
                             && (IsContinuation(next)            // bullet continuation joins up
                                 || (!StartsStructure(cur) && !StartsStructure(next)));
                sb.Append(joinable ? " " : "\n");
            }
            return sb.ToString();
        }

        private static GameObject BuildAdminTab(Transform parent)
        {
            var panel = new GameObject("AdminPanel");
            panel.transform.SetParent(parent, false);
            panel.AddComponent<RectTransform>();
            UIFactory.AddVLG(panel, spacing: 6, padL: 8, padR: 8, padT: 6, padB: 6);
            UIFactory.AddLE(panel, flexH: 1);
            // Aug 7 item 7: the Admin group now has a Banned sibling — without
            // an anchor on THIS panel the shared sub-tab bar can never show
            // here (the #1 way a tab restructure "does nothing" in playtest).
            MakeSubTabAnchor(6, panel.transform, true);

            // BuildPage re-runs on a language switch, so the collected set has to
            // start empty or it accumulates destroyed objects across rebuilds.
            adminOnlySections.Clear();

            var hdrRow = new GameObject("AHdr"); hdrRow.transform.SetParent(panel.transform, false); hdrRow.AddComponent<RectTransform>();
            UIFactory.AddHLG(hdrRow, spacing: 8); UIFactory.AddLE(hdrRow, prefH: 32, flexH: 0);
            txtAdminPanelHdr = UIFactory.CreateText("AT", hdrRow.transform, "<b>Admin Panel</b>  <color=#888>(admins only)</color>", 18f, new Color(1f, 0.7f, 0.3f), UIFactory.AlignMidLeft, sizeDelta: new Vector2(600, 28));
            UIFactory.CreateButton("ARefresh", hdrRow.transform, "Refresh", 13f, C_WHITE, C_BTN, () =>
            {
                var sid = MatchTracker.LocalSteamId;
                if (string.IsNullOrEmpty(sid)) return;
                // Every fetch below is admin-HMAC gated, so for a moderator they
                // are four guaranteed 403s. Refresh what a moderator can actually
                // read instead — the mute list is the only live data on their view.
                if (!ApiClient.IsAdmin) { ApiClient.FetchChatMutes(sid); return; }
                ApiClient.FetchFlaggedMatches(sid); ApiClient.FetchBannedUsers(sid); ApiClient.FetchAdminRecentSeries(sid); ApiClient.FetchAdminQuarantine(sid);
            }, sizeDelta: new Vector2(90, 26));

            var actionRow = new GameObject("AAct"); actionRow.transform.SetParent(panel.transform, false); actionRow.AddComponent<RectTransform>();
            adminOnlySections.Add(actionRow);
            UIFactory.AddHLG(actionRow, spacing: 8); UIFactory.AddLE(actionRow, prefH: 30, flexH: 0);
            UIFactory.CreateButton("ABan", actionRow.transform, "Ban Steam ID...", 13f, C_WHITE, new Color(0.55f, 0.15f, 0.15f, 0.9f), () =>
                StartAdminBanFlow(), sizeDelta: new Vector2(140, 26));
            UIFactory.CreateButton("AGrant", actionRow.transform, "Grant Achievement...", 13f, C_WHITE, new Color(0.2f, 0.45f, 0.2f, 0.9f), () =>
                CompetitiveUI.OpenAdminPrompt("grant"), sizeDelta: new Vector2(170, 26));
            UIFactory.CreateButton("ARev", actionRow.transform, "Reverse Series...", 13f, C_WHITE, new Color(0.45f, 0.3f, 0.55f, 0.9f), () =>
                StartAdminReverseFlow(), sizeDelta: new Vector2(150, 26));
            UIFactory.CreateButton("ABugRpt", actionRow.transform, "Bug Reports...", 13f, C_WHITE, new Color(0.2f, 0.3f, 0.5f, 0.9f), () =>
                CompetitiveUI.OpenBugReportAdminViewer(), sizeDelta: new Vector2(150, 26));
            var artistActionRow = new GameObject("AArtistAct");
            artistActionRow.transform.SetParent(panel.transform, false);
            artistActionRow.AddComponent<RectTransform>();
            adminOnlySections.Add(artistActionRow);
            UIFactory.AddHLG(artistActionRow, spacing: 8);
            UIFactory.AddLE(artistActionRow, prefH: 30, flexH: 0);
            // Item 1 (v1.30): artist-role management. Assigning ITEMS to an
            // artist lives on the shop rows (admin-only "Artist" button there).
            UIFactory.CreateButton("AArtG", artistActionRow.transform, "Grant Artist...", 13f, C_WHITE, new Color(0.3f, 0.45f, 0.35f, 0.9f), () =>
                // Grant targets someone who ISN'T an artist yet, so the roster
                // can't offer them — use the name search (elo disambiguates).
                CompetitiveUI.OpenPlayerSearch("Grant the artist role - find the player",
                    (sid, pname) => { if (!string.IsNullOrEmpty(sid)) ApiClient.AdminSetArtist(MatchTracker.LocalSteamId, sid, true,
                        (ok, resp) => ShowArtistResult(ok, ok ? $"Artist role granted to {pname}." : resp)); }),
                sizeDelta: new Vector2(130, 26));
            UIFactory.CreateButton("AArtR", artistActionRow.transform, "Revoke Artist...", 13f, C_WHITE, new Color(0.45f, 0.3f, 0.3f, 0.9f), () =>
                // Bug batch item 5: revoking should list the CURRENT artists, not
                // ask for a raw Steam64.
                ApiClient.FetchArtistsList(ok =>
                {
                    var roster = ApiClient.CachedAllArtists;
                    if (roster == null || roster.Count == 0)
                    {
                        ShowArtistResult(false, "{\"detail\":\"no artists defined\"}");
                        return;
                    }
                    var names = new string[roster.Count];
                    var ids = new string[roster.Count];
                    for (int ai = 0; ai < roster.Count; ai++)
                    { names[ai] = roster[ai].display_name; ids[ai] = roster[ai].steam_id; }
                    CompetitiveUI.OpenArtistPicker("Revoke which artist?", names, ids,
                        picked => { if (!string.IsNullOrEmpty(picked)) ApiClient.AdminSetArtist(MatchTracker.LocalSteamId, picked, false,
                            (ok2, resp) => ShowArtistResult(ok2, ok2 ? "Artist revoked." : resp)); },
                        actionLabel: "Revoke", showClear: false);
                }),
                sizeDelta: new Vector2(135, 26));
            // Round 3 item 2: review queue for artist-submitted cosmetics.
            UIFactory.CreateButton("ACosR", artistActionRow.transform, "Cosmetic Reviews...", 13f, C_WHITE, new Color(0.3f, 0.4f, 0.55f, 0.9f), () =>
                CompetitiveUI.OpenCosmeticReview(), sizeDelta: new Vector2(150, 26));
            /* Bug #158: translation-moderator roles. Rebuilt — the server half
             * has been live since the i18n infrastructure shipped, but the
             * client half was absent from the entire repo when the report
             * arrived. Same two-button shape as the artist roles directly
             * above (search to grant, roster-pick to revoke) because a grant
             * targets someone who by definition is NOT on the roster yet. */
            UIFactory.CreateButton("ATrG", artistActionRow.transform, "Grant Translator...", 13f, C_WHITE, new Color(0.28f, 0.42f, 0.5f, 0.9f), () =>
                CompetitiveUI.OpenPlayerSearch(I18n.Tr("Grant a translation role - find the player"),
                    (sid, pname) =>
                    {
                        if (string.IsNullOrEmpty(sid)) return;
                        // Language second: the grant is per-language, and the
                        // server rejects any code outside the supported set.
                        CompetitiveUI.OpenArtistPicker(I18n.TrF("Which language for {0}?", pname),
                            I18N_GRANT_LANG_LABELS, I18N_GRANT_LANG_CODES,
                            lang =>
                            {
                                if (string.IsNullOrEmpty(lang)) return;
                                ApiClient.AdminSetI18nGrant(MatchTracker.LocalSteamId, sid, lang, true,
                                    (ok, resp) => ShowArtistResult(ok, ok
                                        ? I18n.TrF("{0} can now translate {1}.", pname, lang.ToUpperInvariant())
                                        : resp));
                            },
                            actionLabel: I18n.Tr("Grant"), showClear: false, itemNoun: "");
                    }),
                sizeDelta: new Vector2(155, 26));
            UIFactory.CreateButton("ATrR", artistActionRow.transform, "Revoke Translator...", 13f, C_WHITE, new Color(0.45f, 0.3f, 0.3f, 0.9f), () =>
                ApiClient.FetchI18nGrants(MatchTracker.LocalSteamId, ok =>
                {
                    var roster = ApiClient.CachedI18nGrants;
                    if (!ok || roster == null)
                    { ShowArtistResult(false, "{\"detail\":\"could not load the translator roster\"}"); return; }
                    if (roster.Count == 0)
                    { ShowArtistResult(false, "{\"detail\":\"nobody holds a translation role\"}"); return; }
                    /* One entry per (player, language) — a moderator for both
                     * languages appears twice, because revoking is per-language
                     * and collapsing them would make one click ambiguous. The
                     * id carries both halves so the callback needs no lookup. */
                    var names = new string[roster.Count];
                    var ids = new string[roster.Count];
                    for (int gi = 0; gi < roster.Count; gi++)
                    {
                        string who = string.IsNullOrEmpty(roster[gi].display_name)
                                   ? roster[gi].steam_id : roster[gi].display_name;
                        // Escape: these names are user-authored and the picker
                        // renders rich text — an unescaped <size=40> would let one
                        // roster entry cover or spoof its neighbours (r2 find 18).
                        names[gi] = $"{Escape(who)}  [{(roster[gi].language_code ?? "").ToUpperInvariant()}]";
                        ids[gi] = roster[gi].steam_id + "|" + roster[gi].language_code;
                    }
                    CompetitiveUI.OpenArtistPicker(I18n.Tr("Revoke which translation role?"), names, ids,
                        picked =>
                        {
                            if (string.IsNullOrEmpty(picked)) return;
                            // LastIndexOf, not IndexOf (r2 find 17): the id half
                            // is a free-text column that may itself contain '|',
                            // while a language code never does — so the FINAL
                            // separator is the only unambiguous one.
                            int bar = picked.LastIndexOf('|');
                            if (bar <= 0) return;
                            ApiClient.AdminSetI18nGrant(MatchTracker.LocalSteamId,
                                picked.Substring(0, bar), picked.Substring(bar + 1), false,
                                (ok2, resp) => ShowArtistResult(ok2, ok2 ? I18n.Tr("Translation role revoked.") : resp));
                        },
                        actionLabel: I18n.Tr("Revoke"), showClear: false, itemNoun: "");
                }),
                sizeDelta: new Vector2(160, 26));
            UIFactory.CreateButton("ACosQ", artistActionRow.transform, "Approved Update Queue...", 13f, C_WHITE, new Color(0.35f, 0.3f, 0.6f, 0.95f), () =>
                CompetitiveUI.OpenCosmeticReleaseQueue(), sizeDelta: new Vector2(190, 26));

            /* Aug 7 item 4: the four moderation surfaces that had no client code
             * at all. Width budget for this row: 130+165+165+185+235 = 880 plus
             * 4 gaps of 8 = 912, against the ~1828px the panel's content width
             * gives an HLG at the 1920-unit canvas — half of it spare, so nothing
             * here compresses a neighbour (#199/#245).
             * Each button is sized for a TRANSLATED label, not the English one:
             * CreateButton routes its text through CreateText, which calls
             * I18n.Tr, and the global Truncate default would drop the tail of a
             * ~30%-longer ru/es label in an English-sized box (#292). At 13pt
             * Gravity averages ~8px per glyph, so 235px carries ~29 characters
             * against "Delete Chat Message..."'s 22. */
            var modActionRow = new GameObject("AModAct");
            modActionRow.transform.SetParent(panel.transform, false);
            modActionRow.AddComponent<RectTransform>();
            UIFactory.AddHLG(modActionRow, spacing: 8);
            UIFactory.AddLE(modActionRow, prefH: 30, flexH: 0);
            // The roster and the audit log are admin-HMAC endpoints, so they join
            // the admin-only set even though they share this row with the three
            // controls a moderator is here for.
            adminOnlySections.Add(UIFactory.CreateButton("AAdmins", modActionRow.transform, "Admins...", 13f, C_WHITE, new Color(0.28f, 0.38f, 0.5f, 0.9f), () =>
                OpenAdminRosterPicker(), sizeDelta: new Vector2(130, 26)));
            adminOnlySections.Add(UIFactory.CreateButton("AActions", modActionRow.transform, "Action Log...", 13f, C_WHITE, new Color(0.3f, 0.34f, 0.42f, 0.9f), () =>
                OpenAdminActionLogPicker(0), sizeDelta: new Vector2(165, 26)));
            /* Aug 7 item 1: standing server alerts — compose (category picker →
             * message prompt → confirm) and revoke (recent-alert picker). */
            adminOnlySections.Add(UIFactory.CreateButton("AAlertNew", modActionRow.transform, "Server Alert...", 13f, C_WHITE, new Color(0.55f, 0.38f, 0.12f, 0.9f), () =>
                CompetitiveUI.OpenArtistPicker(I18n.Tr("Alert category"),
                    new[] { "Outage", "Issue", "Update", "Info" },
                    new[] { "outage", "issue", "update", "info" },
                    cat =>
                    {
                        if (string.IsNullOrEmpty(cat)) return;
                        CompetitiveUI.OpenArtistInput(I18n.Tr("Server alert"), I18n.Tr("Message (shown to every player)"), "",
                            msg =>
                            {
                                if (string.IsNullOrEmpty(msg) || msg.Trim().Length == 0) return;
                                CompetitiveUI.OpenConfirm(
                                    I18n.TrF("Broadcast [{0}] \"{1}\" to ALL players? It stands until revoked.", cat.ToUpperInvariant(), Trunc(msg, 60)),
                                    () => ApiClient.AdminCreateAlert(cat, msg, 0,
                                        (ok, resp) => ShowArtistResult(ok, ok ? I18n.Tr("Alert is live.") : resp)));
                            });
                    },
                    actionLabel: I18n.Tr("Pick"), showClear: false, itemNoun: ""),
                sizeDelta: new Vector2(150, 26)));
            adminOnlySections.Add(UIFactory.CreateButton("AAlertEnd", modActionRow.transform, "End Alert...", 13f, C_WHITE, new Color(0.42f, 0.3f, 0.3f, 0.9f), () =>
                ApiClient.FetchAdminAlerts(() =>
                {
                    var alerts = ApiClient.CachedAdminAlerts;
                    if (alerts == null || alerts.Count == 0)
                    { ShowArtistResult(false, "{\"detail\":\"no alerts on record\"}"); return; }
                    var names = new string[alerts.Count];
                    var ids = new string[alerts.Count];
                    for (int ai = 0; ai < alerts.Count; ai++)
                    {
                        names[ai] = $"[{alerts[ai].category}] {Trunc(alerts[ai].message, 40)}";
                        ids[ai] = alerts[ai].id.ToString();
                    }
                    CompetitiveUI.OpenArtistPicker(I18n.Tr("Revoke which alert?"), names, ids,
                        aid =>
                        {
                            if (string.IsNullOrEmpty(aid) || !int.TryParse(aid, out int idNum)) return;
                            ApiClient.AdminRevokeAlert(idNum,
                                (ok, resp) => ShowArtistResult(ok, ok ? I18n.Tr("Alert revoked.") : resp));
                        },
                        actionLabel: I18n.Tr("Revoke"), showClear: false, itemNoun: "");
                }),
                sizeDelta: new Vector2(135, 26)));
            UIFactory.CreateButton("AMutes", modActionRow.transform, "Chat Mutes...", 13f, C_WHITE, new Color(0.34f, 0.32f, 0.45f, 0.9f), () =>
                OpenChatMutePicker(), sizeDelta: new Vector2(165, 26));
            UIFactory.CreateButton("AMuteNew", modActionRow.transform, "Mute Player...", 13f, C_WHITE, new Color(0.5f, 0.33f, 0.2f, 0.9f), () =>
                StartChatMuteFlow(), sizeDelta: new Vector2(185, 26));
            UIFactory.CreateButton("AChatDel", modActionRow.transform, "Delete Chat Message...", 13f, C_WHITE, new Color(0.5f, 0.22f, 0.22f, 0.9f), () =>
                OpenChatDeletePicker(), sizeDelta: new Vector2(235, 26));
            // Mute-by-message (design v3 S6): works on BRIDGED chatters too
            // (Twitch/YouTube/Discord), which the player-search flow above
            // structurally cannot reach — they have no players row. Left
            // un-wrapped like its three siblings: the server scopes language
            // moderators to their own rows and refuses the rest verbatim.
            UIFactory.CreateButton("AMuteMsg", modActionRow.transform, "Mute From Message...", 13f, C_WHITE, new Color(0.55f, 0.3f, 0.35f, 0.9f), () =>
                OpenChatMuteFromMessagePicker(), sizeDelta: new Vector2(215, 26));
            // Whole-channel lockdown (design v3 S7) — the biggest hammer, so
            // admin HMAC only (wrapped like the other admin-only buttons).
            adminOnlySections.Add(UIFactory.CreateButton("ALockdown", modActionRow.transform, "Chat Lockdown...", 13f, C_WHITE, new Color(0.45f, 0.2f, 0.2f, 0.9f), () =>
                StartChatLockdownFlow(), sizeDelta: new Vector2(175, 26)));

            // Recent Ranked Series — the main series-management section (Award/Void/Reverse).
            var seriesHdrRow = new GameObject("ASHRow"); seriesHdrRow.transform.SetParent(panel.transform, false); seriesHdrRow.AddComponent<RectTransform>();
            adminOnlySections.Add(seriesHdrRow);
            UIFactory.AddHLG(seriesHdrRow, spacing: 8); UIFactory.AddLE(seriesHdrRow, prefH: 24, flexH: 0);
            txtAdminSeriesHdr = UIFactory.CreateText("ASH", seriesHdrRow.transform, "Recent Ranked Series", 16f, new Color(0.6f, 0.85f, 1f), UIFactory.AlignMidLeft, sizeDelta: new Vector2(700, 22));
            UIFactory.SetBold(txtAdminSeriesHdr, true);
            var seriesSV = UIFactory.CreateScrollView("ASSV", panel.transform, spacing: 3);
            adminOnlySections.Add(seriesSV.scrollGO);
            // Responsive 1:2 split: enough series space to operate at 1024x576,
            // while Flagged Matches receives the larger share at every height.
            UIFactory.AddLE(seriesSV.scrollGO, minH: 80, flexH: 1);
            adminSeriesContainer = seriesSV.content;

            // Rejected reports are independently scrollable and client-capped:
            // the Admin panel's outer VLG cannot absorb an unbounded fixed-height
            // list on wide monitors (#199/#245). Each child has prefH (#63).
            var quarantineHdrRow = new GameObject("AQHRow"); quarantineHdrRow.transform.SetParent(panel.transform, false); quarantineHdrRow.AddComponent<RectTransform>();
            adminOnlySections.Add(quarantineHdrRow);
            UIFactory.AddHLG(quarantineHdrRow, spacing: 8); UIFactory.AddLE(quarantineHdrRow, prefH: 24, flexH: 0);
            txtAdminQuarantineHdr = UIFactory.CreateText("AQH", quarantineHdrRow.transform, "Rejected Reports", 16f, new Color(1f, 0.65f, 0.35f), UIFactory.AlignMidLeft, sizeDelta: new Vector2(700, 22));
            UIFactory.SetBold(txtAdminQuarantineHdr, true);
            var quarantineSV = UIFactory.CreateScrollView("AQSV", panel.transform, spacing: 3);
            adminOnlySections.Add(quarantineSV.scrollGO);
            UIFactory.AddLE(quarantineSV.scrollGO, minH: 72, flexH: 1);
            adminQuarantineContainer = quarantineSV.content;

            var split = new GameObject("ASplit"); split.transform.SetParent(panel.transform, false); split.AddComponent<RectTransform>();
            adminOnlySections.Add(split);
            UIFactory.AddHLG(split, spacing: 8); UIFactory.AddLE(split, minH: 140, flexH: 2);

            // Left column: flagged matches.
            var leftCol = new GameObject("AFLeft"); leftCol.transform.SetParent(split.transform, false); leftCol.AddComponent<RectTransform>();
            UIFactory.AddVLG(leftCol, spacing: 4); UIFactory.AddLE(leftCol, flexW: 1, flexH: 1);
            txtAdminFlagsHdr = UIFactory.CreateText("AFH", leftCol.transform, "Flagged Matches", 16f, new Color(1f, 0.55f, 0.3f), sizeDelta: new Vector2(500, 24));
            UIFactory.SetBold(txtAdminFlagsHdr, true);
            var flagSV = UIFactory.CreateScrollView("AFSV", leftCol.transform, spacing: 2);
            UIFactory.AddLE(flagSV.scrollGO, flexH: 1);
            adminFlagsContainer = flagSV.content;

            /* Right column (Aug 7 item 7): the ACTION LOG, in-panel, where the
             * banned list used to sit — bans moved to the dedicated Banned
             * sub-tab. Same width-budget discipline as the old bans header
             * (#199/#245/#132: header flexW:1 + button flexW:0 inside 360). */
            var rightCol = new GameObject("AFRight"); rightCol.transform.SetParent(split.transform, false); rightCol.AddComponent<RectTransform>();
            UIFactory.AddVLG(rightCol, spacing: 4); UIFactory.AddLE(rightCol, prefW: 360, flexH: 1);
            var actHdrRow = new GameObject("AALRow"); actHdrRow.transform.SetParent(rightCol.transform, false); actHdrRow.AddComponent<RectTransform>();
            UIFactory.AddHLG(actHdrRow, spacing: 6); UIFactory.AddLE(actHdrRow, prefH: 26, flexH: 0);
            txtAdminActLogHdr = UIFactory.CreateText("AALH", actHdrRow.transform, "Action Log", 16f, new Color(0.72f, 0.80f, 1f), UIFactory.AlignMidLeft, sizeDelta: new Vector2(232, 24));
            UIFactory.SetBold(txtAdminActLogHdr, true);
            {
                var hdrGO = (txtAdminActLogHdr as Component)?.gameObject;
                if (hdrGO != null) UIFactory.AddLE(hdrGO, minW: 180, prefW: 232, flexW: 1, flexH: 0);
            }
            var actFullBtn = UIFactory.CreateButton("AALFull", actHdrRow.transform, "Full log...", 12f, C_WHITE,
                new Color(0.28f, 0.30f, 0.38f, 0.95f), () => OpenAdminActionLogPicker(0), sizeDelta: new Vector2(100, 24));
            UIFactory.AddLE(actFullBtn, prefW: 100, prefH: 24, flexW: 0, flexH: 0);
            var actSV = UIFactory.CreateScrollView("AALSV", rightCol.transform, spacing: 2);
            UIFactory.AddLE(actSV.scrollGO, flexH: 1);
            adminActLogContainer = actSV.content;

            ApplyAdminPanelScope();
            return panel;
        }

        /// <summary>Aug 7 item 7: the dedicated Banned sub-tab — the banned
        /// list moved here wholesale from the Admin panel's bottom-right
        /// column, gaining the full tab height. Reuses BuildAdminBanRow /
        /// FillAdminBanRow / ConfirmUnban / OpenBanSearchPicker unchanged.</summary>
        private static GameObject BuildBannedTab(Transform parent)
        {
            var panel = new GameObject("BannedPanel");
            panel.transform.SetParent(parent, false);
            panel.AddComponent<RectTransform>();
            UIFactory.AddVLG(panel, spacing: 6, padL: 8, padR: 8, padT: 6, padB: 6);
            UIFactory.AddLE(panel, flexH: 1);
            MakeSubTabAnchor(TAB_BANNED, panel.transform, true);

            var bansHdrRow = new GameObject("ABHRow"); bansHdrRow.transform.SetParent(panel.transform, false); bansHdrRow.AddComponent<RectTransform>();
            UIFactory.AddHLG(bansHdrRow, spacing: 6); UIFactory.AddLE(bansHdrRow, prefH: 28, flexH: 0);
            txtAdminBansHdr = UIFactory.CreateText("ABH", bansHdrRow.transform, "Banned Players", 17f, new Color(1f, 0.45f, 0.45f), UIFactory.AlignMidLeft, sizeDelta: new Vector2(400, 26));
            UIFactory.SetBold(txtAdminBansHdr, true);
            {
                var hdrGO = (txtAdminBansHdr as Component)?.gameObject;
                if (hdrGO != null) UIFactory.AddLE(hdrGO, minW: 200, prefW: 400, flexW: 1, flexH: 0);
            }
            var banSearchBtn = UIFactory.CreateButton("ABSearch", bansHdrRow.transform, "Search...", 13f, C_WHITE,
                new Color(0.28f, 0.30f, 0.38f, 0.95f), OpenBanSearchPicker, sizeDelta: new Vector2(110, 26));
            UIFactory.AddLE(banSearchBtn, prefW: 110, prefH: 26, flexW: 0, flexH: 0);
            var banSV = UIFactory.CreateScrollView("ABSV", panel.transform, spacing: 2);
            UIFactory.AddLE(banSV.scrollGO, flexH: 1);
            adminBansContainer = banSV.content;
            return panel;
        }

        private static void RefreshBannedTab()
        {
            // Admin-only data; the tab itself is IsAdmin-gated in TabVisible,
            // but the authority resolves asynchronously — mirror RefreshAdmin.
            if (!ApiClient.IsAdmin) return;
            var bans = ApiClient.CachedBannedUsers ?? new List<ApiClient.BannedUserEntry>();
            UIFactory.SetText(txtAdminBansHdr, $"Banned Users ({bans.Count})");
            for (int i = bans.Count; i < adminBanRowPool.Count; i++) adminBanRowPool[i].SetActive(false);
            for (int i = 0; i < bans.Count; i++)
            {
                if (i >= adminBanRowPool.Count) adminBanRowPool.Add(BuildAdminBanRow(adminBansContainer.transform, i));
                FillAdminBanRow(adminBanRowPool[i], bans[i]);
            }
        }

        private static void RefreshAdmin()
        {
            /* The tab is reachable by two authorities now (find 2), so decide what
             * this panel IS before rendering anything. Re-applied every refresh
             * rather than only at build: IsAdmin and the moderator probe both
             * resolve asynchronously and can flip on after the panel exists — the
             * same reason UpdateTabBarVisual repaints the tab buttons. */
            ApplyAdminPanelScope();
            // Everything below renders into a container that is now hidden, and
            // every list it reads is admin-only data a moderator never fetches.
            if (!ApiClient.IsAdmin) return;

            // Flag rows
            var flags = ApiClient.CachedFlaggedMatches ?? new List<ApiClient.FlaggedMatchEntry>();
            UIFactory.SetText(txtAdminFlagsHdr, $"Flagged Matches ({flags.Count} actionable)");
            // Hide pooled rows past current count
            for (int i = flags.Count; i < adminFlagRowPool.Count; i++) adminFlagRowPool[i].SetActive(false);
            for (int i = 0; i < flags.Count; i++)
            {
                if (i >= adminFlagRowPool.Count) adminFlagRowPool.Add(BuildAdminFlagRow(adminFlagsContainer.transform, i));
                FillAdminFlagRow(adminFlagRowPool[i], flags[i]);
            }

            // Action Log rows (Aug 7 item 7 — in-panel where the bans sat; the
            // bans render in RefreshBannedTab now). Plain text rows; the Full
            // log button keeps search/paging/details.
            var acts = ApiClient.CachedAdminActions ?? new List<ApiClient.AdminActionEntry>();
            int actShown = Math.Min(25, acts.Count);
            UIFactory.SetText(txtAdminActLogHdr, ApiClient.CachedAdminActionsTotal > 0
                ? $"Action Log ({ApiClient.CachedAdminActionsTotal})" : "Action Log");
            for (int i = actShown; i < adminActLogRowPool.Count; i++)
            { var go = (adminActLogRowPool[i] as Component)?.gameObject; if (go != null) go.SetActive(false); }
            for (int i = 0; i < actShown; i++)
            {
                if (i >= adminActLogRowPool.Count)
                {
                    var t = UIFactory.CreateText($"AAL{i}", adminActLogContainer.transform, "", 12f, C_LABEL,
                        UIFactory.AlignMidLeft, sizeDelta: new Vector2(340, 18));
                    UIFactory.FitOneLine(t);   // one-line cells, translated-metrics class (#292/#297)
                    adminActLogRowPool.Add(t);
                }
                var rowGO = (adminActLogRowPool[i] as Component)?.gameObject;
                if (rowGO != null) rowGO.SetActive(true);
                // AdminActionLabel already routes every user-authored field
                // through AdminDisplay (hostile-input flattening).
                UIFactory.SetTextRaw(adminActLogRowPool[i], AdminActionLabel(acts[i].id));
            }

            // Recent series rows (Award/Void/Reverse)
            var series = ApiClient.CachedAdminSeries ?? new List<ApiClient.AdminSeriesEntry>();
            int needResolve = 0;
            foreach (var s in series) if (s.incomplete && s.ladder == "2v2") needResolve++;
            UIFactory.SetText(txtAdminSeriesHdr, needResolve > 0
                ? $"Recent Ranked Series  <color=#FFCC44>({needResolve} 2v2 need resolving)</color>"
                : "Recent Ranked Series");
            for (int i = series.Count; i < adminSeriesRowPool.Count; i++) adminSeriesRowPool[i].SetActive(false);
            for (int i = 0; i < series.Count; i++)
            {
                if (i >= adminSeriesRowPool.Count) adminSeriesRowPool.Add(BuildAdminSeriesRow(adminSeriesContainer.transform, i));
                FillAdminSeriesRow(adminSeriesRowPool[i], series[i]);
            }

            // Quarantined match reports. The server's can_accept decision is
            // authoritative; the client only renders it and disables the button.
            var rejected = ApiClient.CachedQuarantineReports ?? new List<ApiClient.QuarantineReportEntry>();
            int shown = Math.Min(ADMIN_QUARANTINE_ROW_CAP, rejected.Count);
            string qHeader;
            if (ApiClient.IsAdminQuarantineLoading && !ApiClient.AdminQuarantineLoaded)
                qHeader = "Rejected Reports (loading...)";
            else if (!string.IsNullOrEmpty(ApiClient.AdminQuarantineError))
                qHeader = $"Rejected Reports ({rejected.Count})  <color=#FF7777>refresh failed</color>";
            else if (rejected.Count > shown)
                qHeader = $"Rejected Reports ({rejected.Count}, showing {shown})";
            else
                qHeader = $"Rejected Reports ({rejected.Count})";
            UIFactory.SetText(txtAdminQuarantineHdr, qHeader);
            for (int i = shown; i < adminQuarantineRowPool.Count; i++) adminQuarantineRowPool[i].SetActive(false);
            for (int i = 0; i < shown; i++)
            {
                if (i >= adminQuarantineRowPool.Count)
                    adminQuarantineRowPool.Add(BuildAdminQuarantineRow(adminQuarantineContainer.transform, i));
                FillAdminQuarantineRow(adminQuarantineRowPool[i], rejected[i]);
            }
        }

        private static GameObject BuildAdminQuarantineRow(Transform parent, int idx)
        {
            while (adminQuarantineRowBindings.Count <= idx) adminQuarantineRowBindings.Add(null);
            var row = UIFactory.CreatePanel($"AQ{idx}", parent, new Color(0.19f, 0.14f, 0.11f, 0.9f));
            UIFactory.AddHLG(row, spacing: 6, padL: 6, padR: 6, padT: 4, padB: 4);
            UIFactory.AddLE(row, prefH: 128, flexH: 0);

            var info = new GameObject("AQInfo"); info.transform.SetParent(row.transform, false); info.AddComponent<RectTransform>();
            UIFactory.AddVLG(info, spacing: 1);
            UIFactory.AddLE(info, minW: 420, flexW: 1, prefH: 120, flexH: 0);
            var top = UIFactory.CreateText($"AQT{idx}", info.transform, "", 13f, C_WHITE, UIFactory.AlignMidLeft, sizeDelta: new Vector2(680, 20));
            var players = UIFactory.CreateText($"AQP{idx}", info.transform, "", 12f, C_WHITE, UIFactory.AlignTopLeft, sizeDelta: new Vector2(680, 54));
            var reason = UIFactory.CreateText($"AQR{idx}", info.transform, "", 12f, new Color(1f, 0.75f, 0.55f), UIFactory.AlignMidLeft, sizeDelta: new Vector2(680, 20));
            var blocked = UIFactory.CreateText($"AQX{idx}", info.transform, "", 12f, C_LABEL, UIFactory.AlignMidLeft, sizeDelta: new Vector2(680, 20));
            // Truncate (3), not Ellipsis (1): TMP's ellipsis inserts U+2026,
            // which the static Gravity atlas lacks — renders as a box (#47).
            UIFactory.SetWordWrap(top, false); UIFactory.SetOverflowMode(top, 3);
            UIFactory.SetWordWrap(players, true); UIFactory.SetOverflowMode(players, 3);
            UIFactory.SetWordWrap(reason, false); UIFactory.SetOverflowMode(reason, 3);
            UIFactory.SetWordWrap(blocked, false); UIFactory.SetOverflowMode(blocked, 3);

            var actions = new GameObject("AQActions"); actions.transform.SetParent(row.transform, false); actions.AddComponent<RectTransform>();
            UIFactory.AddVLG(actions, spacing: 4);
            UIFactory.AddLE(actions, prefW: 88, prefH: 60, flexW: 0, flexH: 0);
            UIFactory.CreateButton($"AQA{idx}", actions.transform, "Accept", 11f, C_WHITE,
                new Color(0.2f, 0.45f, 0.2f, 0.9f),
                () => OnAdminQuarantineAction(idx, true), sizeDelta: new Vector2(84, 27));
            UIFactory.CreateButton($"AQD{idx}", actions.transform, "Discard", 11f, C_WHITE,
                new Color(0.5f, 0.25f, 0.16f, 0.9f),
                () => OnAdminQuarantineAction(idx, false), sizeDelta: new Vector2(84, 27));
            row.SetActive(false);
            return row;
        }

        private static void FillAdminQuarantineRow(GameObject row, ApiClient.QuarantineReportEntry e)
        {
            row.SetActive(true);
            string sfx = row.name.Substring(2);
            if (int.TryParse(sfx, out int rowIndex)
                && rowIndex >= 0 && rowIndex < adminQuarantineRowBindings.Count)
                adminQuarantineRowBindings[rowIndex] = e;
            string players;
            if (e.player_names == null || e.player_names.Count == 0)
                players = "(players unavailable)";
            else
            {
                var names = new List<string>();
                foreach (string name in e.player_names)
                    names.Add(AdminDisplay(string.IsNullOrWhiteSpace(name) ? "(deleted player)" : name, 24));
                players = string.Join(" vs ", names.ToArray());
            }

            string when = FormatAdminQuarantineTime(e.created_at);
            string mode = AdminDisplay(string.IsNullOrEmpty(e.mode) ? "unknown" : e.mode, 12);
            /* Codex round-3 residual 11: 20 chars hid team 2 of a 2v2 score
             * ("A + B 2 | C + D 1" runs ~30-55). The server composes and
             * bounds the string (names pre-trimmed), so give it the room. */
            string score = AdminDisplay(string.IsNullOrEmpty(e.score) ? "score unavailable" : e.score, 64);
            string room = AdminDisplay(string.IsNullOrEmpty(e.room) ? "room unavailable" : e.room, 24);
            string topLine = $"<color=#FFB46A>[{mode}]</color> {when}  <b>{score}</b>  <color=#778899>{room}</color>";
            string playersLine = $"Players: {players}";
            string reasonLine = $"Rejected: {AdminDisplay(string.IsNullOrEmpty(e.reason) ? "reason unavailable" : e.reason, 140)}"
                              + (e.http_status > 0 ? $"  <color=#888>HTTP {e.http_status}</color>" : "");
            string blockedLine = e.can_accept
                ? $"<color=#77CC88>Status: {AdminDisplay(string.IsNullOrEmpty(e.status) ? "pending" : e.status, 24)}; safe to accept</color>"
                : $"<color=#FFAA66>Accept blocked: {AdminDisplay(string.IsNullOrEmpty(e.accept_blocked_reason) ? "server did not provide a reason" : e.accept_blocked_reason, 140)}</color>";

            SetAdminRowText(row.transform.Find($"AQInfo/AQT{sfx}"), topLine);
            SetAdminRowText(row.transform.Find($"AQInfo/AQP{sfx}"), playersLine);
            SetAdminRowText(row.transform.Find($"AQInfo/AQR{sfx}"), reasonLine);
            SetAdminRowText(row.transform.Find($"AQInfo/AQX{sfx}"), blockedLine);

            var accept = row.transform.Find($"AQActions/AQA{sfx}")?.gameObject;
            if (accept != null)
            {
                SetButtonInteractable(accept, e.can_accept);
                UIFactory.SetImageColor(accept, e.can_accept
                    ? new Color(0.2f, 0.45f, 0.2f, 0.9f)
                    : new Color(0.18f, 0.18f, 0.18f, 0.75f));
                UIFactory.SetColor(UIFactory.GetButtonText(accept), e.can_accept ? C_WHITE : C_DIM);
            }
        }

        private static void OnAdminQuarantineAction(int index, bool accept)
        {
            // Bind the callback to what THIS rendered row displays, not to the
            // latest cache index. A refresh can replace/reorder the cache one
            // frame before the dirty UI redraw; indexing the new cache during
            // that frame could accept a different report than the visible row.
            if (index < 0 || index >= adminQuarantineRowBindings.Count) return;
            var e = adminQuarantineRowBindings[index];
            if (e == null) return;
            if (accept && !e.can_accept) return;
            string sid = MatchTracker.LocalSteamId;
            if (string.IsNullOrEmpty(sid) || string.IsNullOrEmpty(e.id)) return;

            string verb = accept ? "Accept" : "Discard";
            string players = e.player_names == null || e.player_names.Count == 0
                ? "this rejected report"
                : string.Join(" vs ", e.player_names.Select(n => AdminDisplay(n, 24)).ToArray());
            string question = accept
                ? $"Accept the rejected report for {players}?\n\nServer eligibility will be rechecked."
                : $"Discard the rejected report for {players}?\n\nThis cannot be accepted later.";
            CompetitiveUI.OpenConfirm(question, () =>
            {
                Action<bool, string> done = (ok, resp) =>
                {
                    string detail = ApiClient.ExtractJsonStringPublic(resp ?? "", "detail");
                    if (string.IsNullOrEmpty(detail)) detail = resp;
                    if (ok)
                    {
                        CompetitiveUI.ShowNotification(
                            accept ? "Report approved for recovery - an ordered replay is still required." : "Report dismissed for good.",
                            new Color(0.45f, 0.9f, 0.5f), 4f);
                        ApiClient.FetchAdminQuarantine(sid);
                    }
                    else
                    {
                        CompetitiveUI.ShowNotification(
                            $"{verb} failed: {AdminDisplay(string.IsNullOrEmpty(detail) ? "request failed" : detail, 180)}",
                            new Color(1f, 0.45f, 0.35f), 7f);
                    }
                };
                if (accept) ApiClient.AdminQuarantineAccept(sid, e.id, done);
                else ApiClient.AdminQuarantineDiscard(
                    sid, e.id, "Discarded from in-game admin panel.", done);
            });
        }

        private static void SetAdminRowText(Transform textTransform, string value)
        {
            if (textTransform == null) return;
            foreach (var c in textTransform.GetComponents<Component>())
                if (c.GetType().Name == "TextMeshProUGUI") { UIFactory.SetText(c, value); break; }
        }

        private static string FormatAdminQuarantineTime(string value)
        {
            if (DateTime.TryParse(value, System.Globalization.CultureInfo.InvariantCulture,
                System.Globalization.DateTimeStyles.AssumeUniversal | System.Globalization.DateTimeStyles.AdjustToUniversal,
                out DateTime parsed))
                return DateFmt.Short(parsed) + " " + parsed.ToString("HH:mm 'UTC'", System.Globalization.CultureInfo.InvariantCulture);
            return "time unavailable";
        }

        private static string AdminDisplay(string value, int max)
        {
            if (string.IsNullOrEmpty(value)) return "";
            var sb = new StringBuilder(value.Length);
            bool lastSpace = false;
            foreach (char c in value)
            {
                char a = c == '<' ? '[' : c == '>' ? ']' : c;
                if (a == '\r' || a == '\n' || a == '\t') a = ' ';
                // Flatten CONTROL characters only. Do NOT clamp to ASCII here:
                // learning #110 added a runtime TMP unicode fallback precisely so
                // Cyrillic/CJK/accented personas render instead of turning into
                // squares, and every other name surface in the menu shows them
                // correctly. Mapping >= 127 to '?' would render a 6-player lobby
                // as "??????? vs ?????????" in the ONE panel whose entire job is
                // letting an admin identify which players a report belongs to.
                if (a < 32) a = ' ';
                if (a == ' ')
                {
                    if (lastSpace) continue;
                    lastSpace = true;
                }
                else lastSpace = false;
                sb.Append(a);
            }
            return Trunc(sb.ToString().Trim(), max);
        }

        private static void SetButtonInteractable(GameObject button, bool interactable)
        {
            try
            {
                var component = button?.GetComponent(UIFactory.tButton);
                var property = UIFactory.tButton?.GetProperty(
                    "interactable", BindingFlags.Public | BindingFlags.Instance);
                property?.SetValue(component, interactable);
            }
            catch { }
        }

        private static GameObject BuildAdminFlagRow(Transform parent, int idx)
        {
            var row = UIFactory.CreatePanel($"AF{idx}", parent, new Color(0.18f, 0.13f, 0.13f, 0.85f));
            UIFactory.AddHLG(row, spacing: 6, padL: 6, padR: 6, padT: 4, padB: 4);
            UIFactory.AddLE(row, prefH: 38, flexH: 0);
            var txt = UIFactory.CreateText("AFT", row.transform, "", 13f, C_WHITE, UIFactory.AlignMidLeft, sizeDelta: new Vector2(420, 30));
            UIFactory.SetWordWrap(txt, false);
            // The flag line grew (steam ids + suspect + score), and an unwrapped
            // TMP overflows its rect and draws OVER the Details button that
            // follows it in this HLG. Take the row's spare width and ellipsize
            // instead of overflowing — full text lives in the Details viewer.
            {
                var txtComp = txt as Component;
                if (txtComp != null && UIFactory.tLE != null)
                {
                    var le = txtComp.gameObject.GetComponent(UIFactory.tLE)
                             ?? txtComp.gameObject.AddComponent(UIFactory.tLE);
                    UIFactory.tLE.GetProperty("flexibleWidth", BindingFlags.Public | BindingFlags.Instance)?.SetValue(le, 1f);
                    UIFactory.tLE.GetProperty("minWidth", BindingFlags.Public | BindingFlags.Instance)?.SetValue(le, 240f);
                }
                // Truncate (3), not Ellipsis (1) — ellipsis inserts U+2026,
                // absent from the static Gravity atlas -> box glyph (#47).
                UIFactory.SetOverflowMode(txt, 3);
            }
            // Decisions live in the evidence viewer so admins see the telemetry
            // before choosing Cheat or False positive.
            UIFactory.CreateButton($"AFDT{idx}", row.transform, "Details", 11f, C_WHITE,
                new Color(0.25f, 0.38f, 0.55f, 0.95f), () => { },
                sizeDelta: new Vector2(76, 26));
            row.SetActive(false);
            return row;
        }

        private static void FillAdminFlagRow(GameObject row, ApiClient.FlaggedMatchEntry e)
        {
            row.SetActive(true);
            // First child = text. The button onClicks are set below.
            var txt = row.transform.Find("AFT");
            if (txt != null)
            {
                string when = "";
                try { if (!string.IsNullOrEmpty(e.created_at)) when = DateTime.Parse(e.created_at).ToString("HH:mm"); } catch { }
                string verdict = e.restoration_required
                    ? "<color=#FFCC44>FALSE+ / MANUAL REPAIR</color>"
                    : e.auto_invalidated
                        ? "<color=#FF6666>auto-inv</color>"
                        : "<color=#DDAA44>advisory</color>";
                string mode = e.is_ranked ? "R" : "C";
                string duration = string.IsNullOrEmpty(e.duration_text)
                    ? (e.duration_seconds > 0 ? e.duration_seconds + "s" : "not recorded")
                    : e.duration_text;
                string line = $"[{when}] <b>{e.flag_reason}</b> {verdict}  "
                            + $"{Trunc(HomeSan(e.p1_name), 12)} vs {Trunc(HomeSan(e.p2_name), 12)}  "
                            + $"{mode}/{duration}  <color=#889>{e.game_code}</color>";
                // tTMP isn't accessible outside UIFactory. Iterate child components by reflected name.
                foreach (var c in txt.GetComponents<Component>())
                    if (c.GetType().Name == "TextMeshProUGUI") { UIFactory.SetText(c, line); break; }
            }
            var details = row.transform.Find("AFDT" + row.name.Substring(2));
            if (details != null) WireButton(details.gameObject, () => CompetitiveUI.OpenFlagEvidence(e));
        }

